local SystemModule, AutoLeveling, ClearWorld, MoveBlock, DiscordHook, ProxyCommands

local function isAnyMainTaskRunning(exceptName)
    local active = {
        PNB = PNB and PNB.State and PNB.State.running,
        Pabrik = Pabrik and Pabrik.State and Pabrik.State.running,
        DirtFarm = DirtFarm and DirtFarm.State and DirtFarm.State.running,
        ClearWorld = ClearWorld and ClearWorld.State and ClearWorld.State.running,
        MoveBlock = MoveBlock and MoveBlock.State and MoveBlock.State.running,
        AutoLeveling = AutoLeveling and AutoLeveling.State and AutoLeveling.State.running,
    }
    for k, on in pairs(active) do
        if k ~= exceptName and on == true then return true, k end
    end
    return false, nil
end

local function guardExclusiveStart(modName)
    local busy, holder = isAnyMainTaskRunning(modName)
    if busy then
        emitNotify("SYT", "SORRY YOUR TASK IS DO RIGHT NOW (" .. tostring(holder) .. ")")
        return false
    end
    return true
end

local function resolveConsoleUi(forceScan)
    if H._chatUiObj and type(H._chatUiObj.add) == "function" then return H._chatUiObj end
    local now = os.clock()
    if not forceScan and (now - (H._lastChatUiGcAt or 0)) < 5.0 then return nil end
    H._lastChatUiGcAt = now
    for _, v in ipairs(safeGetGC(true)) do
        if type(v) == "table" and type(rawget(v, "add")) == "function" and type(rawget(v, "setGems")) == "function" and type(rawget(v, "prefill")) == "function" then
            H._chatUiObj = v
            return v
        end
    end
    return nil
end

local function proxyConsole(msg, kind, allowSpans)
    local txt = tostring(msg or "")
    local chatUi = resolveConsoleUi(true)
    if chatUi then
        H._inProxyConsole = true
        local ok = pcall(chatUi.add, txt, kind or "system", allowSpans == true)
        H._inProxyConsole = false
        if ok then return true end
    end
    pcall(emitNotify, "Proxy", stripColorTags(txt))
    return true
end

local function buildStorageFileSupported()
    return type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
end

local function safeReadStorage(fname)
    if buildStorageFileSupported() then
        local okE, ex = pcall(isfile, fname)
        if okE and ex then
            local okR, dat = pcall(readfile, fname)
            if okR and type(dat) == "string" then return dat end
        end
    end
    local env = getEnv()
    return env and env["__SYT_STORE_" .. fname] or nil
end

local function safeWriteStorage(fname, val)
    local env = getEnv()
    if env then env["__SYT_STORE_" .. fname] = val end
    if buildStorageFileSupported() then
        pcall(writefile, fname, tostring(val))
    end
end

function Core.RegisterGlobalAutoRerun(forceRearm)
    local env = getEnv()
    if UIHooks and UIHooks.userDestroy or (env and env.__SYT_USER_CLOSED == true) then return false end
    local qot = (type(queue_on_teleport) == "function" and queue_on_teleport)
        or (type(syn) == "table" and type(syn.queue_on_teleport) == "function" and syn.queue_on_teleport)
        or (type(fluxus) == "table" and type(fluxus.queue_on_teleport) == "function" and fluxus.queue_on_teleport)
        or nil
    if not qot then return false end

    local jobKey = tostring(game.JobId or "")
    if jobKey == "" then jobKey = "LOCAL_" .. tostring(MY_SCRIPT_TOKEN) end
    if not forceRearm and env and env.__SYT_QOT_ARMED_JOB == jobKey then
        return true
    end
    if env then env.__SYT_QOT_ARMED_JOB = jobKey end

    local payload = [[task.spawn(function()
    local g = (type(getgenv)=="function" and getgenv()) or _G
    if type(g)=="table" and g.__SYT_USER_CLOSED then return end
    if type(isfile)=="function" and type(readfile)=="function" then
        local okF, ex = pcall(isfile, "syt_menu_closed.dat")
        if okF and ex then
            local okR, dat = pcall(readfile, "syt_menu_closed.dat")
            if okR and dat == "1" then return end
        end
    end
    if not game:IsLoaded() then pcall(function() game.Loaded:Wait() end) end
    task.wait(1.2)
    local plrs = game:GetService("Players")
    local wEnd = os.clock() + 5
    while not plrs.LocalPlayer and os.clock() < wEnd do task.wait(0.15) end
    if type(g)=="table" and g.__SYT_USER_CLOSED then return end
    if type(g)=="table" then g.__SYT_QOT_RERUN = true end
    -- [SAFE] Remote SYT_CN.lua download removed (unverified remote code, could re-add logger).
    -- Rerun after teleport now loads ONLY the local file "SYT_safe.lua" in the executor workspace.
    if type(isfile)=="function" and type(readfile)=="function" then
        local okC, exC = pcall(isfile, "SYT_safe.lua")
        if okC and exC then
            local okR, code = pcall(readfile, "SYT_safe.lua")
            if okR and type(code)=="string" and #code > 128 then
                local f = loadstring(code)
                if type(f)=="function" then f() end
            end
        end
    end
end)]]
    local okQ = pcall(qot, payload)
    return okQ == true
end

