-- Module 1: Immutable & Bedrock Protection Manager (CRITICAL SAFETY LAYER)
do
    local Safety = {}
    DF.Safety = Safety

    local BEDROCK_ID = 8
    local MAIN_DOOR_ID = 6
    local UNCERTAIN_BOTTOM_MARGIN = 6

    function Safety.isBedrockId(id)
        if type(id) ~= "number" or id == 0 then return false end
        if id == BEDROCK_ID then return true end
        local info = Core and Core.GetItemInfo and Core.GetItemInfo(id) or nil
        if not info then return false end
        local ln = string.lower(tostring(info.name or ""))
        if string.find(ln, "bedrock", 1, true) then
            return true
        end
        if type(info.hits) == "number" and info.hits < 0 and info.solid == true then
            return true
        end
        return false
    end

    function Safety.isImmutableId(id)
        if type(id) ~= "number" or id == 0 then return false end
        if id == BEDROCK_ID or id == MAIN_DOOR_ID then return true end
        if Safety.isBedrockId(id) then return true end
        if Core and Core.IsProtectedTile and Core.IsProtectedTile(id) then
            return true
        end
        local info = Core and Core.GetItemInfo and Core.GetItemInfo(id) or nil
        if not info then
            return true
        end
        local ln = string.lower(tostring(info.name or ""))
        if string.find(ln, "bedrock", 1, true) or string.find(ln, "main door", 1, true) then
            return true
        end
        if info.unbreakable == true then
            return true
        end
        if type(info.hits) == "number" and info.hits <= 0 then
            return true
        end
        if info.lock or info.area or info.door or info.entrance or info.vend or info.display or info.displayOne or info.worldKey or info.vip or info.combiner then
            return true
        end
        return false
    end

    function Safety.markImmutable(safetyState, w, x, y, reason)
        if x < 0 or x >= w or y < 0 then return end
        local idx = y * w + x
        safetyState.immutableSet[idx] = true
        if not safetyState.immutableReason[idx] then
            safetyState.immutableReason[idx] = reason or "IMMUTABLE"
        end
    end

    function Safety.buildFromSnapshot(snapshot)
        local CONF = DF.ENUMS.BEDROCK_CONFIDENCE
        local w = snapshot.w
        local h = snapshot.h
        local doorX = snapshot.doorX
        local doorY = snapshot.doorY

        local state = {
            w = w,
            h = h,
            immutableSet = {},
            immutableReason = {},
            bedrockCoords = {},
            bedrockCount = 0,
            rowBedrockCount = {},
            rowBedrockRatio = {},
            bedrockTopY = h,
            safeMaxWorkY = math.max(2, h - 1 - UNCERTAIN_BOTTOM_MARGIN),
            bedrockConfidence = CONF.LOW,
            lastValidatedAt = DF.Util.now(),
        }

        -- Pass 1: Scan ENTIRE world for bedrock and all immutable FG/BG tiles
        for y = 0, h - 1 do
            local bRow = 0
            for x = 0, w - 1 do
                local idx = y * w + x
                local fg = snapshot.fg[idx] or 0
                local bg = snapshot.bg[idx] or 0
                if fg ~= 0 and Safety.isBedrockId(fg) then
                    bRow = bRow + 1
                    state.bedrockCount = state.bedrockCount + 1
                    state.bedrockCoords[#state.bedrockCoords + 1] = { x = x, y = y, idx = idx }
                    Safety.markImmutable(state, w, x, y, "BEDROCK")
                elseif fg ~= 0 and Safety.isImmutableId(fg) then
                    Safety.markImmutable(state, w, x, y, "IMMUTABLE_FG")
                elseif bg ~= 0 and Safety.isImmutableId(bg) then
                    Safety.markImmutable(state, w, x, y, "IMMUTABLE_BG")
                elseif Core and Core.CanEditTile and not Core.CanEditTile(x, y) then
                    Safety.markImmutable(state, w, x, y, "NO_EDIT")
                end
            end
            state.rowBedrockCount[y] = bRow
            state.rowBedrockRatio[y] = (w > 0) and (bRow / w) or 0
        end

        -- Protect Main Door and bedrock anchor directly underneath it
        if doorX >= 0 and doorX < w and doorY >= 0 and doorY < h then
            Safety.markImmutable(state, w, doorX, doorY, "MAIN_DOOR")
            if doorY + 1 < h then
                local underDoorFg = snapshot.fg[(doorY + 1) * w + doorX] or 0
                if Safety.isBedrockId(underDoorFg) or Safety.isImmutableId(underDoorFg) then
                    Safety.markImmutable(state, w, doorX, doorY + 1, "DOOR_BEDROCK_ANCHOR")
                end
            end
        end

        -- Pass 2: Detect contiguous bottom bedrock boundary robustly (never stops prematurely on jagged rows)
        local bandTopY = nil
        local strongBottomRows = 0
        for y = h - 1, math.max(0, doorY + 2), -1 do
            local ratio = state.rowBedrockRatio[y] or 0
            if ratio >= 0.55 then
                bandTopY = y
                if ratio >= 0.65 then
                    strongBottomRows = strongBottomRows + 1
                end
            elseif bandTopY ~= nil then
                -- Check up to 2 jagged shelf rows right above the solid bedrock band
                if ratio >= 0.15 and (bandTopY - y) <= 2 then
                    bandTopY = y
                else
                    break
                end
            elseif y <= h - 3 then
                -- No bedrock in bottom 3 rows; keep scanning in case of non-standard bottom
                if ratio >= 0.20 then
                    bandTopY = y
                end
            end
        end

        if bandTopY ~= nil and strongBottomRows >= 1 then
            state.bedrockTopY = bandTopY
            state.bedrockConfidence = CONF.HIGH
            state.safeMaxWorkY = math.max(2, bandTopY - 1)
        elseif bandTopY ~= nil then
            state.bedrockTopY = bandTopY
            state.bedrockConfidence = CONF.MEDIUM
            state.safeMaxWorkY = math.max(2, bandTopY - 1)
        else
            -- Uncertain bedrock boundary: conservatively exclude bottom safety margin
            local highestLowerBedrock = nil
            for _, bc in ipairs(state.bedrockCoords) do
                if bc.y >= math.floor(h * 0.65) then
                    if not highestLowerBedrock or bc.y < highestLowerBedrock then
                        highestLowerBedrock = bc.y
                    end
                end
            end
            if highestLowerBedrock then
                state.bedrockTopY = highestLowerBedrock
                state.bedrockConfidence = CONF.MEDIUM
                state.safeMaxWorkY = math.max(2, highestLowerBedrock - 1)
            else
                state.bedrockTopY = math.max(doorY + 2, h - UNCERTAIN_BOTTOM_MARGIN)
                state.bedrockConfidence = CONF.LOW
                state.safeMaxWorkY = math.max(2, state.bedrockTopY - 1)
            end
        end

        -- Mark all tiles at or below bedrockTopY as strictly immutable
        for y = state.bedrockTopY, h - 1 do
            for x = 0, w - 1 do
                Safety.markImmutable(state, w, x, y, "BEDROCK_BOUNDARY")
            end
        end

        return state
    end

    function Safety.revalidateTile(ctx, x, y)
        if not ctx or not ctx.safety then return end
        local s = ctx.safety
        if x < 0 or x >= s.w or y < 0 or y >= s.h then return end
        local fg = Core.GetFG(x, y)
        local bg = Core.GetBG(x, y)
        if fg ~= 0 and Safety.isBedrockId(fg) then
            Safety.markImmutable(s, s.w, x, y, "LIVE_BEDROCK")
        elseif fg ~= 0 and Safety.isImmutableId(fg) then
            Safety.markImmutable(s, s.w, x, y, "LIVE_IMMUTABLE_FG")
        elseif bg ~= 0 and Safety.isImmutableId(bg) then
            Safety.markImmutable(s, s.w, x, y, "LIVE_IMMUTABLE_BG")
        elseif Core and Core.CanEditTile and not Core.CanEditTile(x, y) then
            Safety.markImmutable(s, s.w, x, y, "LIVE_NO_EDIT")
        end
    end

    -- Centralized single source of truth for tile immutability
    function Safety.isImmutableTile(ctx, x, y, checkBg)
        local gt = H and H.gt
        local w = (ctx and ctx.w) or (gt and gt.w) or 0
        local h = (ctx and ctx.h) or (gt and gt.h) or 0
        if type(x) ~= "number" or type(y) ~= "number" or w <= 0 or h <= 0 then
            return true, "INVALID_COORD"
        end
        x = math.floor(x)
        y = math.floor(y)
        if x < 0 or x >= w or y < 0 or y >= h then
            return true, "OUT_OF_BOUNDS"
        end
        local idx = y * w + x
        if ctx and ctx.safety then
            local s = ctx.safety
            if s.immutableSet[idx] then
                return true, s.immutableReason[idx] or "IMMUTABLE_SET"
            end
            if y >= s.bedrockTopY then
                return true, "BEDROCK_ZONE"
            end
            if s.bedrockConfidence == DF.ENUMS.BEDROCK_CONFIDENCE.LOW and y > s.safeMaxWorkY then
                return true, "UNCERTAIN_BEDROCK_MARGIN"
            end
        end
        local fg = Core and Core.GetFG and Core.GetFG(x, y) or 0
        if fg ~= 0 and Safety.isImmutableId(fg) then
            if ctx and ctx.safety then
                Safety.markImmutable(ctx.safety, w, x, y, Safety.isBedrockId(fg) and "LIVE_BEDROCK" or "LIVE_IMMUTABLE_FG")
            end
            return true, Safety.isBedrockId(fg) and "LIVE_BEDROCK" or "LIVE_IMMUTABLE_FG"
        end
        if checkBg then
            local bg = Core and Core.GetBG and Core.GetBG(x, y) or 0
            if bg ~= 0 and Safety.isImmutableId(bg) then
                if ctx and ctx.safety then
                    Safety.markImmutable(ctx.safety, w, x, y, "LIVE_IMMUTABLE_BG")
                end
                return true, "LIVE_IMMUTABLE_BG"
            end
        end
        if Core and Core.CanEditTile and not Core.CanEditTile(x, y) then
            return true, "NO_EDIT_ACCESS"
        end
        return false, nil
    end

    function Safety.canExecuteActionOn(ctx, x, y, actionKind, layer)
        local isImm, reason = Safety.isImmutableTile(ctx, x, y, layer == 2)
        if isImm then
            return false, reason
        end
        if ctx and ctx.format then
            if y < ctx.format.topY or y > ctx.format.maxWorkY then
                return false, "OUTSIDE_WORK_BAND"
            end
        end
        if actionKind == "place" and layer == 1 then
            local fg = Core.GetFG(x, y)
            if fg ~= 0 and Safety.isImmutableId(fg) then
                return false, "LIVE_IMMUTABLE_FG"
            end
        end
        return true, "OK"
    end
end

-- Module 2: World Scanner (Full World Snapshot & Dirty-Region Updates)
do
    local WorldScanner = {}
    DF.WorldScanner = WorldScanner

    function WorldScanner.resolveItemIds(snapshot)
        local dirtId = 2
        local foundDirt = Core and Core.FindItemByName and Core.FindItemByName("dirt") or nil
        if foundDirt and foundDirt.id then
            dirtId = foundDirt.id
        elseif snapshot then
            local counts = {}
            for y = math.floor(snapshot.h * 0.45), snapshot.h - 2 do
                for x = 2, snapshot.w - 3 do
                    local id = snapshot.fg[y * snapshot.w + x] or 0
                    if id > 0 and not DF.Safety.isImmutableId(id) then
                        local info = Core.GetItemInfo(id)
                        if info and info.solid and not info.deadly and not info.hurts then
                            counts[id] = (counts[id] or 0) + 1
                        end
                    end
                end
            end
            local bestId, bestN = 2, -1
            for id, cnt in pairs(counts) do
                if cnt > bestN then
                    bestId, bestN = id, cnt
                end
            end
            dirtId = bestId
        end

        local rockId = 10
        local foundRock = Core and Core.FindItemByName and Core.FindItemByName("rock") or nil
        if foundRock and foundRock.id then
            rockId = foundRock.id
        elseif H and type(H.ItemDB) == "table" then
            for id, info in pairs(H.ItemDB) do
                if type(id) == "number" and type(info) == "table" and info.solid and not info.background then
                    if string.lower(tostring(info.name or "")) == "rock" then
                        rockId = id
                        break
                    end
                end
            end
        end

        local dirtSeedId = dirtId + 1
        if H and type(H.ItemDB) == "table" then
            for id, info in pairs(H.ItemDB) do
                if type(id) == "number" and type(info) == "table" and info.kind == "seed" then
                    if info.seed == dirtId or string.lower(tostring(info.name or "")) == "dirt seed" then
                        dirtSeedId = id
                        break
                    end
                end
            end
        end

        local platformId = 102
        local foundPlat = Core and Core.FindItemByName and Core.FindItemByName("wooden platform") or nil
        if foundPlat and foundPlat.id then
            platformId = foundPlat.id
        elseif H and type(H.ItemDB) == "table" then
            for id, info in pairs(H.ItemDB) do
                if type(id) == "number" and type(info) == "table" and info.platform == true then
                    if string.lower(tostring(info.name or "")) == "wooden platform" then
                        platformId = id
                        break
                    end
                end
            end
        end

        return {
            dirtId = dirtId,
            rockId = rockId,
            dirtSeedId = dirtSeedId,
            platformId = platformId,
            bedrockId = 8,
            mainDoorId = 6,
        }
    end

    function WorldScanner.isPlatformItem(id, ids)
        if type(id) ~= "number" or id == 0 then return false end
        if ids and id == ids.platformId then return true end
        local info = Core and Core.GetItemInfo and Core.GetItemInfo(id) or nil
        return info ~= nil and info.platform == true and not info.background
    end

    function WorldScanner.scanFull(gt)
        gt = gt or (H and H.gt)
        if not gt then return nil end
        local w = math.max(4, tonumber(gt.w) or 100)
        local h = math.max(8, tonumber(gt.h) or 60)
        local worldName = cleanWorldName and cleanWorldName(gt.name or "") or tostring(gt.name or "")

        local sp = gt.spawn
        local doorX = (type(sp) == "table" and sp.x) and math.floor(sp.x) or math.floor(w / 2)
        local doorY = (type(sp) == "table" and sp.y) and math.floor(sp.y) or math.floor(h * 0.4)
        local doorFound = false

        local fg = {}
        local bg = {}
        local existingPlatforms = {}
        local lavaTiles = {}
        local nonZeroCount = 0
        local rowSolidCounts = {}
        local rowEmptyCounts = {}

        for y = 0, h - 1 do
            local solidCnt = 0
            local emptyCnt = 0
            for x = 0, w - 1 do
                local idx = y * w + x
                local fId = Core.GetFG(x, y)
                local bId = Core.GetBG(x, y)
                fg[idx] = fId
                bg[idx] = bId
                if fId ~= 0 or bId ~= 0 then
                    nonZeroCount = nonZeroCount + 1
                end
                if fId == 0 then
                    emptyCnt = emptyCnt + 1
                else
                    local info = Core.GetItemInfo(fId)
                    if not doorFound and (fId == 6 or (info and (info.door or info.entrance))) then
                        doorX, doorY = x, y
                        doorFound = true
                    end
                    if info then
                        if info.solid == true then
                            solidCnt = solidCnt + 1
                        end
                        if info.platform == true and not info.background then
                            existingPlatforms[#existingPlatforms + 1] = { x = x, y = y, idx = idx, id = fId }
                        end
                        if info.hurts == true or info.deadly == true then
                            lavaTiles[#lavaTiles + 1] = { x = x, y = y, idx = idx, id = fId }
                        end
                    end
                end
            end
            rowSolidCounts[y] = solidCnt
            rowEmptyCounts[y] = emptyCnt
        end

        local snapshot = {
            worldName = worldName,
            w = w,
            h = h,
            doorX = DF.Util.clamp(doorX, 0, w - 1),
            doorY = DF.Util.clamp(doorY, 2, h - 4),
            doorFound = doorFound,
            fg = fg,
            bg = bg,
            existingPlatforms = existingPlatforms,
            lavaTiles = lavaTiles,
            nonZeroCount = nonZeroCount,
            rowSolidCounts = rowSolidCounts,
            rowEmptyCounts = rowEmptyCounts,
            scannedAt = DF.Util.now(),
        }
        return snapshot
    end

    function WorldScanner.scanRegion(ctx, minX, maxX, minY, maxY)
        if not ctx or not ctx.snapshot then return {} end
        local snap = ctx.snapshot
        local w, h = snap.w, snap.h
        local x0 = DF.Util.clamp(math.floor(minX), 0, w - 1)
        local x1 = DF.Util.clamp(math.floor(maxX), 0, w - 1)
        local y0 = DF.Util.clamp(math.floor(minY), 0, h - 1)
        local y1 = DF.Util.clamp(math.floor(maxY), 0, h - 1)
        local changed = {}

        for y = y0, y1 do
            for x = x0, x1 do
                local idx = y * w + x
                local newFg = Core.GetFG(x, y)
                local newBg = Core.GetBG(x, y)
                local oldFg = snap.fg[idx] or 0
                local oldBg = snap.bg[idx] or 0
                DF.Safety.revalidateTile(ctx, x, y)
                if newFg ~= oldFg or newBg ~= oldBg then
                    snap.fg[idx] = newFg
                    snap.bg[idx] = newBg
                    changed[#changed + 1] = {
                        x = x,
                        y = y,
                        idx = idx,
                        oldFg = oldFg,
                        oldBg = oldBg,
                        newFg = newFg,
                        newBg = newBg,
                    }
                end
            end
        end
        return changed
    end
end

-- Module 3: World Format Detector (Full World DF Layout Recognition)
do
    local FormatDetector = {}
    DF.FormatDetector = FormatDetector

    function FormatDetector.detect(snapshot, safety, ids)
        local w = snapshot.w
        local h = snapshot.h
        local doorX = snapshot.doorX
        local doorY = snapshot.doorY
        local topY = 2
        local maxWorkY = DF.Util.clamp(safety.safeMaxWorkY, topY, h - 2)
        local groundY = DF.Util.clamp(doorY + 1, topY, maxWorkY)
        local hasShafts = (w >= 6)
        local centerGap = (DirtFarm.State.centerGap == true) and (w >= 12)
        local midX = math.floor(w / 2)

        local floorRows = {}
        local corridorRows = {}
        local isFloorRowMap = {}

        for y = topY, maxWorkY do
            if ((y - groundY) % 2) == 0 then
                isFloorRowMap[y] = true
                floorRows[#floorRows + 1] = y
            else
                isFloorRowMap[y] = false
                corridorRows[#corridorRows + 1] = y
            end
        end

        -- Detect Wooden Platform column layout across existing world platforms
        local innerLeftCnt, innerRightCnt = 0, 0
        local outerLeftCnt, outerRightCnt = 0, 0
        for _, pl in ipairs(snapshot.existingPlatforms) do
            if pl.y >= topY and pl.y <= maxWorkY and isFloorRowMap[pl.y] then
                if pl.x == 1 then innerLeftCnt = innerLeftCnt + 1 end
                if pl.x == w - 2 then innerRightCnt = innerRightCnt + 1 end
                if pl.x == 0 then outerLeftCnt = outerLeftCnt + 1 end
                if pl.x == w - 1 then outerRightCnt = outerRightCnt + 1 end
            end
        end

        local platformRequired = hasShafts and (DirtFarm.State.usePlatforms ~= false)
        local leftPlatCol = 1
        local rightPlatCol = w - 2
        local platformLayout = "INNER_SHAFT"

        if platformRequired then
            local innerTotal = innerLeftCnt + innerRightCnt
            local outerTotal = outerLeftCnt + outerRightCnt
            if outerTotal >= 3 and innerTotal == 0 then
                leftPlatCol = 0
                rightPlatCol = w - 1
                platformLayout = "OUTER_SHAFT"
            end
        else
            platformLayout = "NONE"
        end

        local platformSlotSet = {}
        local platformSlots = {}
        if platformRequired then
            for _, fy in ipairs(floorRows) do
                local cols = { leftPlatCol, rightPlatCol }
                for _, px in ipairs(cols) do
                    local idx = fy * w + px
                    if not safety.immutableSet[idx] then
                        platformSlotSet[idx] = true
                        platformSlots[#platformSlots + 1] = { x = px, y = fy, idx = idx }
                    end
                end
            end
        end

        -- Analyze existing world compliance (floors, corridors, platforms)
        local existingValidFloors = 0
        local existingValidCorridors = 0
        local existingValidPlatforms = 0
        for _, fy in ipairs(floorRows) do
            local okCount, totalFloor = 0, 0
            local minX = hasShafts and 2 or 0
            local maxX = hasShafts and (w - 3) or (w - 1)
            for x = minX, maxX do
                if not (centerGap and x == midX) then
                    local idx = fy * w + x
                    if not safety.immutableSet[idx] then
                        totalFloor = totalFloor + 1
                        local fid = snapshot.fg[idx] or 0
                        if fid == ids.dirtId or (DirtFarm.State.acceptRockOnFloor and fid == ids.rockId) then
                            okCount = okCount + 1
                        end
                    end
                end
            end
            if totalFloor > 0 and (okCount / totalFloor) >= 0.85 then
                existingValidFloors = existingValidFloors + 1
            end
        end
        for _, cy in ipairs(corridorRows) do
            local airCount, totalCor = 0, 0
            for x = 0, w - 1 do
                local idx = cy * w + x
                if not safety.immutableSet[idx] then
                    totalCor = totalCor + 1
                    if (snapshot.fg[idx] or 0) == 0 and (snapshot.bg[idx] or 0) == 0 then
                        airCount = airCount + 1
                    end
                end
            end
            if totalCor > 0 and (airCount / totalCor) >= 0.85 then
                existingValidCorridors = existingValidCorridors + 1
            end
        end
        for _, ps in ipairs(platformSlots) do
            local fid = snapshot.fg[ps.idx] or 0
            local bid = snapshot.bg[ps.idx] or 0
            if DF.WorldScanner.isPlatformItem(fid, ids) and bid == 0 then
                existingValidPlatforms = existingValidPlatforms + 1
            end
        end

        -- Door-based starting direction (leftDistance vs rightDistance with deterministic tie-break)
        local leftDistance = math.abs(doorX - 0)
        local rightDistance = math.abs((w - 1) - doorX)
        local startingSide
        if leftDistance < rightDistance then
            startingSide = "LEFT"
        elseif rightDistance < leftDistance then
            startingSide = "RIGHT"
        else
            startingSide = (DirtFarm.State.tieBreakSide == "RIGHT") and "RIGHT" or "LEFT"
        end

        -- Two-section boundaries (Bagan 1: Lower Area Cleanup | Bagan 2: Upper Area, Bottom-Up)
        local bagan1StartY = groundY
        local bagan1EndY = maxWorkY
        local bagan2StartY = topY
        local bagan2EndY = math.max(topY, doorY - 1)

        -- Serpentine zigzag direction map per row (alternating LEFT_TO_RIGHT / RIGHT_TO_LEFT)
        local rowDirections = {}
        local curDir = (startingSide == "LEFT") and 1 or -1
        for y = bagan1StartY, bagan1EndY do
            rowDirections[y] = curDir
            curDir = -curDir
        end
        local curDir2 = (startingSide == "LEFT") and 1 or -1
        for y = bagan2EndY, bagan2StartY, -1 do
            rowDirections[y] = curDir2
            curDir2 = -curDir2
        end

        local summary = string.format(
            "%dx%d | Door(%d,%d)->%s | B1:%d..%d B2:%d..%d | BedTop:%d(%s) | Plat:%d/%d(%s)",
            w, h, doorX, doorY, startingSide, bagan1StartY, bagan1EndY, bagan2StartY, bagan2EndY,
            safety.bedrockTopY, safety.bedrockConfidence,
            existingValidPlatforms, #platformSlots, platformLayout
        )

        return {
            w = w,
            h = h,
            topY = topY,
            maxWorkY = maxWorkY,
            doorX = doorX,
            doorY = doorY,
            groundY = groundY,
            midX = midX,
            hasShafts = hasShafts,
            centerGap = centerGap,
            minWorkX = hasShafts and 2 or 0,
            maxWorkX = hasShafts and (w - 3) or (w - 1),
            leftShaftCols = hasShafts and { 0, 1 } or {},
            rightShaftCols = hasShafts and { w - 2, w - 1 } or {},
            floorRows = floorRows,
            corridorRows = corridorRows,
            isFloorRowMap = isFloorRowMap,
            platformRequired = platformRequired,
            platformLayout = platformLayout,
            leftPlatCol = leftPlatCol,
            rightPlatCol = rightPlatCol,
            platformSlotSet = platformSlotSet,
            platformSlots = platformSlots,
            existingValidFloors = existingValidFloors,
            existingValidCorridors = existingValidCorridors,
            existingValidPlatforms = existingValidPlatforms,
            -- Conceptual DirtFarm V4 metadata (logicalY = y + 1, Door Direction, Bagan 1 & 2, Serpentine Zigzag)
            toLogicalY = function(y) return y + 1 end,
            getLogicalParity = function(y) return (((y + 1) % 2) == 1) and "ODD" or "EVEN" end,
            isEndpointX = function(x) return hasShafts and (x <= 1 or x >= w - 2) end,
            doorDirection = {
                startingSide = startingSide,
                leftDistance = leftDistance,
                rightDistance = rightDistance,
            },
            bagan1 = { startY = bagan1StartY, endY = bagan1EndY },
            bagan2 = { startY = bagan2StartY, endY = bagan2EndY, direction = "BOTTOM_UP" },
            rowDirections = rowDirections,
            summary = summary,
        }
    end
end

-- Module 4: Blueprint & Tile Requirement Engine (Single Source of Truth)
do
    local Blueprint = {}
    DF.Blueprint = Blueprint

    function Blueprint.desiredAt(ctx, x, y)
        local ROLE = DF.ENUMS.TILE_ROLE
        local fmt = ctx.format
        if x < 0 or x >= ctx.w or y < 0 or y >= ctx.h then
            return { desiredFg = nil, desiredBg = nil, role = ROLE.EXCLUDED }
        end
        if y < fmt.topY or y > fmt.maxWorkY then
            return { desiredFg = nil, desiredBg = nil, role = ROLE.EXCLUDED }
        end
        local isImm = DF.Safety.isImmutableTile(ctx, x, y, false)
        if isImm then
            return { desiredFg = nil, desiredBg = nil, role = ROLE.IMMUTABLE }
        end

        local idx = y * ctx.w + x
        -- Platform slot in side shafts
        if fmt.platformRequired and fmt.platformSlotSet[idx] then
            return {
                desiredFg = ctx.ids.platformId,
                desiredBg = 0,
                role = ROLE.PLATFORM,
            }
        end

        -- Remaining side shaft tiles -> open air + clean BG
        if fmt.hasShafts and (x <= 1 or x >= ctx.w - 2) then
            return { desiredFg = 0, desiredBg = 0, role = ROLE.SHAFT_AIR }
        end

        -- Optional center gap shaft
        if fmt.centerGap and x == fmt.midX then
            return { desiredFg = 0, desiredBg = 0, role = ROLE.SHAFT_AIR }
        end

        -- Door row is always open corridor
        if y == fmt.doorY then
            return { desiredFg = 0, desiredBg = 0, role = ROLE.CORRIDOR_AIR }
        end

        -- Alternating Dirt floor rows vs Air corridor rows across full world
        if fmt.isFloorRowMap[y] then
            return {
                desiredFg = ctx.ids.dirtId,
                desiredBg = nil,
                role = ROLE.DIRT_FLOOR,
            }
        end

        return { desiredFg = 0, desiredBg = 0, role = ROLE.CORRIDOR_AIR }
    end

    function Blueprint.wantBgZeroAt(ctx, x, y)
        local spec = Blueprint.desiredAt(ctx, x, y)
        return spec.desiredBg == 0
    end

    function Blueprint.isFgMatch(ctx, fg, spec)
        local ROLE = DF.ENUMS.TILE_ROLE
        if spec.desiredFg == nil then return true end
        if spec.role == ROLE.PLATFORM then
            return DF.WorldScanner.isPlatformItem(fg, ctx.ids)
        end
        if spec.role == ROLE.DIRT_FLOOR then
            if fg == ctx.ids.dirtId then return true end
            if DirtFarm.State.acceptRockOnFloor and fg == ctx.ids.rockId then
                return true
            end
            return false
        end
        return fg == spec.desiredFg
    end

    function Blueprint.evaluateTile(ctx, x, y, opts)
        opts = opts or {}
        local ST = DF.ENUMS.TILE_STATUS
        local LC = DF.ENUMS.TASK_LIFECYCLE
        local ROLE = DF.ENUMS.TILE_ROLE
        local fmt = ctx.format

        if x < 0 or x >= ctx.w or y < 0 or y >= ctx.h then
            return ST.EXCLUDED, nil, "OUT_OF_BOUNDS"
        end
        if y < fmt.topY or y > fmt.maxWorkY then
            return ST.EXCLUDED, nil, "OUTSIDE_WORK_BAND"
        end

        local isImm, immReason = DF.Safety.isImmutableTile(ctx, x, y, false)
        if isImm then
            return ST.IMMUTABLE, nil, immReason
        end

        local idx = y * ctx.w + x
        local spec = Blueprint.desiredAt(ctx, x, y)
        if spec.role == ROLE.EXCLUDED then
            return ST.EXCLUDED, spec, nil
        end
        if spec.role == ROLE.IMMUTABLE then
            return ST.IMMUTABLE, spec, "BLUEPRINT_IMMUTABLE"
        end

        local fg = Core.GetFG(x, y)
        local bg = Core.GetBG(x, y)

        -- Respect live task lifecycle unless caller explicitly asks for raw world blueprint diff
        if not opts.ignoreLifecycle and ctx.tasks then
            local rec = DF.TaskManager.get(ctx, idx)
            if rec then
                if rec.state == LC.VERIFYING then
                    return ST.VERIFYING, spec, rec.failReason
                elseif rec.state == LC.RESERVED or rec.state == LC.EXECUTING then
                    return ST.PENDING, spec, rec.failReason
                elseif rec.state == LC.FAILED then
                    return ST.FAILED, spec, rec.failReason
                elseif rec.state == LC.BLOCKED then
                    -- Unblock platform slot automatically if material is now available
                    if rec.failReason == "PLATFORM_NO_MATERIAL" and spec.role == ROLE.PLATFORM and Core.CountItem(ctx.ids.platformId) > 0 then
                        DF.TaskManager.resetToDiscovered(ctx, idx)
                    else
                        return ST.BLOCKED, spec, rec.failReason
                    end
                end
            end
        end

        -- Independent FG & BG evaluation
        local fgOk = Blueprint.isFgMatch(ctx, fg, spec)
        local bgProtected = (bg ~= 0) and DF.Safety.isImmutableId(bg)
        local bgOk = (spec.desiredBg == nil) or (bg == spec.desiredBg) or bgProtected

        if fgOk and bgOk then
            if ctx.tasks then
                local rec = DF.TaskManager.get(ctx, idx)
                if rec and rec.state == LC.COMPLETED then
                    return ST.COMPLETED, spec, nil
                end
            end
            return ST.CORRECT, spec, nil
        end

        -- Case 1: FG wrong and must become empty air
        if not fgOk and spec.desiredFg == 0 then
            return ST.NEED_BREAK_FG, spec, nil
        end

        -- Case 2: FG wrong and must become a placed item, but another block occupies FG
        if not fgOk and spec.desiredFg > 0 and fg ~= 0 then
            -- For platform slot with no material, still clear blocking solid FG so shaft stays traversable
            if spec.role == ROLE.PLATFORM and Core.CountItem(ctx.ids.platformId) <= 0 then
                return ST.NEED_BREAK_FG, spec, "CLEAR_SHAFT_BEFORE_PLATFORM"
            end
            return ST.NEED_REPLACE, spec, nil
        end

        -- Case 3: FG empty and must become a placed item
        if not fgOk and spec.desiredFg > 0 and fg == 0 then
            -- Break exposed Cave BG / non-protected BG on targeted tile BEFORE placing FG (never blindly place over Cave BG!)
            if (not bgOk and spec.desiredBg == 0) or (bg ~= 0 and not bgProtected) then
                return ST.NEED_BREAK_BG, spec, nil
            end
            if spec.role == ROLE.PLATFORM then
                if Core.CountItem(ctx.ids.platformId) <= 0 then
                    return ST.BLOCKED, spec, "PLATFORM_NO_MATERIAL"
                end
            end
            return ST.NEED_PLACE, spec, nil
        end

        -- Case 4: FG matches, only BG is dirty
        if fgOk and not bgOk then
            return ST.NEED_BREAK_BG, spec, nil
        end

        return ST.CORRECT, spec, nil
    end

    function Blueprint.isActionableStatus(status)
        local ST = DF.ENUMS.TILE_STATUS
        return status == ST.NEED_BREAK_FG
            or status == ST.NEED_BREAK_BG
            or status == ST.NEED_PLACE
            or status == ST.NEED_REPLACE
    end

    function Blueprint.isTileComplete(ctx, x, y)
        local ST = DF.ENUMS.TILE_STATUS
        local st, _, reason = Blueprint.evaluateTile(ctx, x, y)
        if st == ST.CORRECT or st == ST.COMPLETED or st == ST.IMMUTABLE or st == ST.EXCLUDED then
            return true
        end
        if st == ST.BLOCKED and reason == "PLATFORM_NO_MATERIAL" then
            return true
        end
        if st == ST.FAILED then
            return true
        end
        return false
    end
end

-- Module 5: Wooden Platform Detection & Status Manager (Integrated with Blueprint & Planner)
do
    local Platform = {}
    DF.Platform = Platform

    function Platform.evaluate(ctx)
        local PS = DF.ENUMS.PLATFORM_STATUS
        local ST = DF.ENUMS.TILE_STATUS
        local fmt = ctx.format
        if not fmt or not fmt.platformRequired or #fmt.platformSlots == 0 then
            ctx.platformStatus = PS.NOT_REQUIRED
            ctx.platformStats = {
                total = 0,
                existing = 0,
                missing = 0,
                needsRepair = 0,
                verifying = 0,
                material = Core.CountItem(ctx.ids.platformId),
            }
            DirtFarm.State.platformStatus = PS.NOT_REQUIRED
            return PS.NOT_REQUIRED, ctx.platformStats
        end

        local existing = 0
        local missing = 0
        local needsRepair = 0
        local verifying = 0
        local material = Core.CountItem(ctx.ids.platformId)

        for _, slot in ipairs(fmt.platformSlots) do
            local st = DF.Blueprint.evaluateTile(ctx, slot.x, slot.y)
            local fg = Core.GetFG(slot.x, slot.y)
            local bg = Core.GetBG(slot.x, slot.y)
            if st == ST.VERIFYING or st == ST.PENDING then
                verifying = verifying + 1
            elseif st == ST.CORRECT or st == ST.COMPLETED then
                existing = existing + 1
            elseif fg ~= 0 and not DF.WorldScanner.isPlatformItem(fg, ctx.ids) then
                needsRepair = needsRepair + 1
            elseif fg == 0 and bg ~= 0 then
                needsRepair = needsRepair + 1
            else
                missing = missing + 1
            end
        end

        local total = #fmt.platformSlots
        local status
        if verifying > 0 then
            status = PS.VERIFYING
        elseif existing >= total then
            status = PS.EXISTS
        elseif needsRepair > 0 and existing > 0 then
            status = PS.NEEDS_REPAIR
        elseif material <= 0 and (missing > 0 or needsRepair > 0) then
            status = PS.NO_MATERIAL
        elseif existing == 0 then
            status = PS.MISSING
        else
            status = PS.INCOMPLETE
        end

        ctx.platformStatus = status
        ctx.platformStats = {
            total = total,
            existing = existing,
            missing = missing,
            needsRepair = needsRepair,
            verifying = verifying,
            material = material,
        }
        DirtFarm.State.platformStatus = status
        return status, ctx.platformStats
    end
end

-- Module 6: Task Lifecycle & Reservation Manager (Anti Place-Break-Place Loop)
do
    local TaskManager = {}
    DF.TaskManager = TaskManager

    local MAX_RETRIES = 3
    local RETRY_COOLDOWNS = { 0.30, 0.65, 1.15 }

    function TaskManager.create()
        return {
            records = {},
            nextBatchId = 1,
            activeBatches = {},
        }
    end

    function TaskManager.get(ctx, idx)
        return ctx.tasks and ctx.tasks.records[idx] or nil
    end

    function TaskManager.ensure(ctx, x, y)
        local idx = y * ctx.w + x
        local rec = ctx.tasks.records[idx]
        if not rec then
            rec = {
                x = x,
                y = y,
                idx = idx,
                state = DF.ENUMS.TASK_LIFECYCLE.DISCOVERED,
                action = nil,
                layer = nil,
                desiredId = nil,
                retries = 0,
                maxRetries = MAX_RETRIES,
                lastAttemptAt = 0,
                nextRetryAt = 0,
                verifyUntil = 0,
                failReason = nil,
                batchId = nil,
                confirmedFg = nil,
                confirmedBg = nil,
            }
            ctx.tasks.records[idx] = rec
        end
        return rec
    end

    function TaskManager.resetToDiscovered(ctx, idx)
        local rec = ctx.tasks and ctx.tasks.records[idx]
        if not rec then return end
        rec.state = DF.ENUMS.TASK_LIFECYCLE.DISCOVERED
        rec.action = nil
        rec.layer = nil
        rec.desiredId = nil
        rec.batchId = nil
        rec.failReason = nil
        rec.nextRetryAt = 0
        rec.verifyUntil = 0
    end

    function TaskManager.canReserve(ctx, x, y, actionKind)
        local LC = DF.ENUMS.TASK_LIFECYCLE
        local isImm, reason = DF.Safety.isImmutableTile(ctx, x, y, false)
        if isImm then
            return false, reason
        end
        local idx = y * ctx.w + x
        local rec = TaskManager.get(ctx, idx)
        local now = DF.Util.now()
        if rec then
            if rec.state == LC.RESERVED or rec.state == LC.EXECUTING then
                return false, "ALREADY_RESERVED"
            end
            if rec.state == LC.VERIFYING then
                -- Never send an opposite action while previous verification is still pending
                if now < rec.verifyUntil then
                    return false, "VERIFYING_PENDING"
                end
            end
            if rec.state == LC.COMPLETED then
                -- Confirm world did not change away from completed state
                local fg = Core.GetFG(x, y)
                local bg = Core.GetBG(x, y)
                if fg == rec.confirmedFg and bg == rec.confirmedBg then
                    return false, "ALREADY_COMPLETED"
                end
                -- Genuine world change detected: invalidate cleanly
                TaskManager.resetToDiscovered(ctx, idx)
                rec.retries = 0
            elseif rec.state == LC.FAILED then
                return false, rec.failReason or "MAX_RETRIES_EXCEEDED"
            elseif rec.state == LC.BLOCKED then
                return false, rec.failReason or "BLOCKED"
            elseif rec.state == LC.RETRY_PENDING then
                if now < rec.nextRetryAt then
                    return false, "RETRY_BACKOFF"
                end
            end
        end
        -- Double check live blueprint requirement (never break a correct tile, never place on already-matched tile)
        local st, spec = DF.Blueprint.evaluateTile(ctx, x, y, { ignoreLifecycle = true })
        local ST = DF.ENUMS.TILE_STATUS
        if st == ST.CORRECT or st == ST.IMMUTABLE or st == ST.EXCLUDED then
            return false, "ALREADY_CORRECT"
        end
        if actionKind == "break" then
            if st ~= ST.NEED_BREAK_FG and st ~= ST.NEED_BREAK_BG and st ~= ST.NEED_REPLACE then
                return false, "NO_BREAK_NEEDED"
            end
        elseif actionKind == "place" then
            if st ~= ST.NEED_PLACE then
                return false, "NO_PLACE_NEEDED"
            end
            if spec and spec.desiredFg and Core.GetFG(x, y) == spec.desiredFg then
                return false, "ALREADY_PLACED"
            end
        end
        return true, "OK"
    end

    function TaskManager.reserveBatch(ctx, items)
        local LC = DF.ENUMS.TASK_LIFECYCLE
        local batchId = ctx.tasks.nextBatchId
        ctx.tasks.nextBatchId = batchId + 1
        local reserved = {}
        local seen = {}
        for _, item in ipairs(items) do
            local idx = item.y * ctx.w + item.x
            if not seen[idx] then
                local ok = TaskManager.canReserve(ctx, item.x, item.y, item.action)
                if ok then
                    seen[idx] = true
                    local rec = TaskManager.ensure(ctx, item.x, item.y)
                    rec.state = LC.RESERVED
                    rec.action = item.action
                    rec.layer = item.layer
                    rec.desiredId = item.desiredId
                    rec.batchId = batchId
                    rec.failReason = nil
                    reserved[#reserved + 1] = item
                end
            end
        end
        if #reserved > 0 then
            ctx.tasks.activeBatches[batchId] = reserved
        end
        return batchId, reserved
    end

    function TaskManager.markExecuting(ctx, x, y)
        local rec = TaskManager.ensure(ctx, x, y)
        rec.state = DF.ENUMS.TASK_LIFECYCLE.EXECUTING
        rec.lastAttemptAt = DF.Util.now()
    end

    function TaskManager.markVerifying(ctx, x, y, windowSec)
        local rec = TaskManager.ensure(ctx, x, y)
        rec.state = DF.ENUMS.TASK_LIFECYCLE.VERIFYING
        rec.verifyUntil = DF.Util.now() + (windowSec or 0.45)
    end

    function TaskManager.markCompleted(ctx, x, y)
        local rec = TaskManager.ensure(ctx, x, y)
        rec.state = DF.ENUMS.TASK_LIFECYCLE.COMPLETED
        rec.action = nil
        rec.batchId = nil
        rec.failReason = nil
        rec.verifyUntil = 0
        rec.confirmedFg = Core.GetFG(x, y)
        rec.confirmedBg = Core.GetBG(x, y)
    end

    function TaskManager.markStageAdvanced(ctx, x, y)
        -- Used when NEED_REPLACE finishes its break stage cleanly and must transition to NEED_PLACE (or NEED_BREAK_BG)
        local rec = TaskManager.ensure(ctx, x, y)
        rec.state = DF.ENUMS.TASK_LIFECYCLE.DISCOVERED
        rec.action = nil
        rec.batchId = nil
        rec.failReason = nil
        rec.verifyUntil = 0
        rec.retries = 0
    end

    function TaskManager.markBlocked(ctx, x, y, reason)
        local rec = TaskManager.ensure(ctx, x, y)
        rec.state = DF.ENUMS.TASK_LIFECYCLE.BLOCKED
        rec.action = nil
        rec.batchId = nil
        rec.failReason = reason or "BLOCKED"
        rec.verifyUntil = 0
    end

    function TaskManager.recordFailure(ctx, x, y, reason, hardBlock)
        local LC = DF.ENUMS.TASK_LIFECYCLE
        local rec = TaskManager.ensure(ctx, x, y)
        rec.batchId = nil
        rec.failReason = reason or "UNKNOWN_FAIL"
        rec.verifyUntil = 0
        if hardBlock then
            rec.state = LC.BLOCKED
            return rec.state
        end
        rec.retries = (rec.retries or 0) + 1
        if rec.retries >= (rec.maxRetries or MAX_RETRIES) then
            rec.state = LC.FAILED
        else
            rec.state = LC.RETRY_PENDING
            local cd = RETRY_COOLDOWNS[rec.retries] or 1.2
            rec.nextRetryAt = DF.Util.now() + cd
        end
        return rec.state
    end

    function TaskManager.releaseBatch(ctx, batchId)
        if not ctx or not ctx.tasks then return end
        local list = ctx.tasks.activeBatches[batchId]
        if list then
            local LC = DF.ENUMS.TASK_LIFECYCLE
            for _, item in ipairs(list) do
                local idx = item.y * ctx.w + item.x
                local rec = ctx.tasks.records[idx]
                if rec and rec.batchId == batchId and (rec.state == LC.RESERVED or rec.state == LC.EXECUTING) then
                    rec.state = LC.DISCOVERED
                    rec.batchId = nil
                    rec.action = nil
                end
            end
            ctx.tasks.activeBatches[batchId] = nil
        end
    end

    function TaskManager.invalidateIfWorldChanged(ctx, changedList)
        if not ctx or not ctx.tasks or not changedList then return end
        local LC = DF.ENUMS.TASK_LIFECYCLE
        for _, ch in ipairs(changedList) do
            local rec = ctx.tasks.records[ch.idx]
            if rec then
                if rec.state == LC.COMPLETED then
                    if ch.newFg ~= rec.confirmedFg or ch.newBg ~= rec.confirmedBg then
                        TaskManager.resetToDiscovered(ctx, ch.idx)
                        rec.retries = 0
                    end
                elseif rec.state == LC.FAILED or rec.state == LC.BLOCKED then
                    if rec.failReason ~= "IMMUTABLE" and rec.failReason ~= "LIVE_BEDROCK" then
                        TaskManager.resetToDiscovered(ctx, ch.idx)
                        rec.retries = 0
                    end
                end
            end
        end
    end

    function TaskManager.clearAll(ctx)
        if not ctx or not ctx.tasks then return end
        ctx.tasks.records = {}
        ctx.tasks.activeBatches = {}
    end
end

-- Module 7: Difference Analyzer & Incremental Progress Tracker
do
    local DiffAnalyzer = {}
    DF.DiffAnalyzer = DiffAnalyzer

    function DiffAnalyzer.create()
        return {
            workMap = {},
            rowWorkCount = {},
            remainingCount = 0,
            initialCount = 0,
            confirmedCompleted = 0,
            batchesSinceReconcile = 0,
            lastReconcileAt = 0,
        }
    end

    function DiffAnalyzer._setTileWork(diff, w, x, y, newStatus)
        local idx = y * w + x
        local wasActionable = diff.workMap[idx] ~= nil
        local isActionable = DF.Blueprint.isActionableStatus(newStatus)
        if wasActionable and not isActionable then
            diff.workMap[idx] = nil
            diff.remainingCount = math.max(0, diff.remainingCount - 1)
            diff.rowWorkCount[y] = math.max(0, (diff.rowWorkCount[y] or 0) - 1)
        elseif not wasActionable and isActionable then
            diff.workMap[idx] = newStatus
            diff.remainingCount = diff.remainingCount + 1
            diff.rowWorkCount[y] = (diff.rowWorkCount[y] or 0) + 1
        elseif isActionable then
            diff.workMap[idx] = newStatus
        end
    end

    local function resolveHitEstimate(tileId)
        if type(tileId) ~= "number" or tileId == 0 then return 0, true end
        local info = Core and Core.GetItemInfo and Core.GetItemInfo(tileId) or nil
        if info and type(info.hits) == "number" and info.hits > 0 then
            return math.floor(info.hits), true
        end
        return "UNKNOWN", false
    end

    local function safePct(done, total)
        if not total or total <= 0 then return 100 end
        return DF.Util.clamp(math.floor((done / total) * 100 + 0.5), 0, 100)
    end

    function DiffAnalyzer.isBagan1Complete(ctx)
        if not ctx or not ctx.diff or not ctx.format then return true end
        local b1 = ctx.format.bagan1
        for y = b1.startY, b1.endY do
            if (ctx.diff.rowWorkCount[y] or 0) > 0 then
                return false
            end
        end
        return true
    end

    function DiffAnalyzer.syncProgress(ctx)
        local diff = ctx.diff
        local fmt = ctx.format
        local b1Rem, b2Rem = 0, 0
        for y = fmt.bagan1.startY, fmt.bagan1.endY do
            b1Rem = b1Rem + (diff.rowWorkCount[y] or 0)
        end
        for y = fmt.bagan2.startY, fmt.bagan2.endY do
            b2Rem = b2Rem + (diff.rowWorkCount[y] or 0)
        end

        local b1Init = math.max(diff.bagan1Initial or 0, b1Rem)
        local b2Init = math.max(diff.bagan2Initial or 0, b2Rem)
        local b1Pct = safePct(math.max(0, b1Init - b1Rem), b1Init)
        local b2Pct = (b1Rem > 0) and 0 or safePct(math.max(0, b2Init - b2Rem), b2Init)

        local total = math.max(diff.initialCount, diff.remainingCount + diff.confirmedCompleted)
        local tilePct = safePct(math.max(0, total - diff.remainingCount), total)
        local hitTotal = diff.initialKnownHits or 0
        local hitDone = math.max(0, hitTotal - (diff.remainingKnownHits or 0))
        local workPct = (hitTotal > 0) and safePct(hitDone, hitTotal) or tilePct

        ctx.activeSection = (b1Rem > 0) and "BAGAN_1" or "BAGAN_2"
        ctx.bagan1Status = (b1Rem > 0) and "RUNNING" or "COMPLETED"
        ctx.bagan2Status = (b1Rem > 0) and "BLOCKED_BY_BAGAN_1" or ((b2Rem > 0) and "RUNNING" or "COMPLETED")

        DirtFarm.State.progress = tilePct
        DirtFarm.State.tileProgressPct = tilePct
        DirtFarm.State.estimatedWorkProgressPct = workPct
        DirtFarm.State.bagan1ProgressPct = b1Pct
        DirtFarm.State.bagan2ProgressPct = b2Pct
        DirtFarm.State.activeSection = ctx.activeSection
        DirtFarm.State.remainingTasks = diff.remainingCount
        DirtFarm.State.completedTasks = diff.confirmedCompleted
        DirtFarm.State.totalTasks = total
        DirtFarm.State.unknownHitUnits = diff.unknownHitUnits or 0
        DirtFarm.State.lavaRecommendations = diff.lavaRecommendations or 0
        return tilePct
    end

    function DiffAnalyzer.buildInitial(ctx)
        local diff = DiffAnalyzer.create()
        diff.bagan1Initial = 0
        diff.bagan2Initial = 0
        diff.initialKnownHits = 0
        diff.remainingKnownHits = 0
        diff.unknownHitUnits = 0
        diff.lavaRecommendations = 0
        diff.fgEligible = 0
        diff.bgEligible = 0
        ctx.diff = diff
        local fmt = ctx.format
        local ST = DF.ENUMS.TILE_STATUS
        for y = fmt.topY, fmt.maxWorkY do
            diff.rowWorkCount[y] = 0
            local inB1 = (y >= fmt.bagan1.startY and y <= fmt.bagan1.endY)
            for x = 0, ctx.w - 1 do
                local st = DF.Blueprint.evaluateTile(ctx, x, y)
                if DF.Blueprint.isActionableStatus(st) then
                    local idx = y * ctx.w + x
                    diff.workMap[idx] = st
                    diff.remainingCount = diff.remainingCount + 1
                    diff.rowWorkCount[y] = diff.rowWorkCount[y] + 1
                    if inB1 then diff.bagan1Initial = diff.bagan1Initial + 1
                    else diff.bagan2Initial = diff.bagan2Initial + 1 end
                    local fg = Core.GetFG(x, y)
                    local bg = Core.GetBG(x, y)
                    if st == ST.NEED_BREAK_FG or st == ST.NEED_REPLACE or st == ST.NEED_PLACE then
                        diff.fgEligible = diff.fgEligible + 1
                        local hCnt, known = resolveHitEstimate(fg ~= 0 and fg or ctx.ids.dirtId)
                        if known then diff.initialKnownHits = diff.initialKnownHits + hCnt
                        else diff.unknownHitUnits = diff.unknownHitUnits + 1 end
                        if st == ST.NEED_REPLACE and fg == 4 then
                            diff.lavaRecommendations = diff.lavaRecommendations + 1
                        end
                    elseif st == ST.NEED_BREAK_BG then
                        diff.bgEligible = diff.bgEligible + 1
                        local hCnt, known = resolveHitEstimate(bg)
                        if known then diff.initialKnownHits = diff.initialKnownHits + hCnt
                        else diff.unknownHitUnits = diff.unknownHitUnits + 1 end
                    end
                end
            end
        end
        diff.remainingKnownHits = diff.initialKnownHits
        diff.initialCount = diff.remainingCount
        diff.lastReconcileAt = DF.Util.now()
        DiffAnalyzer.syncProgress(ctx)
        return diff
    end

    function DiffAnalyzer.updateRegion(ctx, minX, maxX, minY, maxY)
        local fmt = ctx.format
        local x0 = DF.Util.clamp(math.floor(minX), 0, ctx.w - 1)
        local x1 = DF.Util.clamp(math.floor(maxX), 0, ctx.w - 1)
        local y0 = DF.Util.clamp(math.floor(minY), fmt.topY, fmt.maxWorkY)
        local y1 = DF.Util.clamp(math.floor(maxY), fmt.topY, fmt.maxWorkY)

        local changed = DF.WorldScanner.scanRegion(ctx, x0, x1, y0, y1)
        if #changed > 0 then
            DF.TaskManager.invalidateIfWorldChanged(ctx, changed)
        end

        for y = y0, y1 do
            for x = x0, x1 do
                local st = DF.Blueprint.evaluateTile(ctx, x, y)
                DiffAnalyzer._setTileWork(ctx.diff, ctx.w, x, y, st)
            end
        end

        DF.Platform.evaluate(ctx)
        DiffAnalyzer.syncProgress(ctx)
        return changed
    end

    function DiffAnalyzer.reconcileAll(ctx)
        local fmt = ctx.format
        local changed = DF.WorldScanner.scanRegion(ctx, 0, ctx.w - 1, fmt.topY, fmt.maxWorkY)
        if #changed > 0 then
            DF.TaskManager.invalidateIfWorldChanged(ctx, changed)
        end
        local diff = ctx.diff
        diff.workMap = {}
        diff.remainingCount = 0
        for y = fmt.topY, fmt.maxWorkY do
            diff.rowWorkCount[y] = 0
            for x = 0, ctx.w - 1 do
                local st = DF.Blueprint.evaluateTile(ctx, x, y)
                if DF.Blueprint.isActionableStatus(st) then
                    local idx = y * ctx.w + x
                    diff.workMap[idx] = st
                    diff.remainingCount = diff.remainingCount + 1
                    diff.rowWorkCount[y] = diff.rowWorkCount[y] + 1
                end
            end
        end
        diff.batchesSinceReconcile = 0
        diff.lastReconcileAt = DF.Util.now()
        DF.Platform.evaluate(ctx)
        DiffAnalyzer.syncProgress(ctx)
        return diff.remainingCount
    end

    function DiffAnalyzer.getRowWorkCount(ctx, y)
        if not ctx or not ctx.diff then return 0 end
        return ctx.diff.rowWorkCount[y] or 0
    end

    function DiffAnalyzer.bandHasWork(ctx, yMin, yMax)
        local fmt = ctx.format
        local lo = math.max(fmt.topY, yMin)
        local hi = math.min(fmt.maxWorkY, yMax)
        for y = lo, hi do
            if (ctx.diff.rowWorkCount[y] or 0) > 0 then
                return true
            end
        end
        return false
    end
end

-- Module 8: Smart Collect & Inventory Manager
do
    local Inventory = {}
    DF.Inventory = Inventory

    function Inventory.countDirt(ctx)
        return Core.CountItem(ctx.ids.dirtId)
    end

    function Inventory.countPlatform(ctx)
        return Core.CountItem(ctx.ids.platformId)
    end

    function Inventory.countDirtSeed(ctx)
        return Core.CountItem(ctx.ids.dirtSeedId)
    end

    function Inventory.hasFreeSpace(id)
        if Core.GetItemRoom then
            return Core.GetItemRoom(id) > 0
        end
        return Core.CountItem(id) < 200
    end

    function Inventory.checkMaterialForBatch(ctx, batchItems)
        local needDirt = 0
        local needPlat = 0
        for _, it in ipairs(batchItems) do
            if it.action == "place" then
                if it.desiredId == ctx.ids.dirtId then
                    needDirt = needDirt + 1
                elseif it.desiredId == ctx.ids.platformId then
                    needPlat = needPlat + 1
                end
            end
        end
        local haveDirt = Inventory.countDirt(ctx)
        local havePlat = Inventory.countPlatform(ctx)
        return {
            okDirt = (haveDirt >= needDirt),
            okPlatform = (havePlat >= needPlat),
            needDirt = needDirt,
            needPlat = needPlat,
            haveDirt = haveDirt,
            havePlat = havePlat,
        }
    end

    -- Area-based / Need-based collect (avoids wasteful detours & per-tile dropList spam)
    function Inventory.collectSmart(ctx, aliveFn, opts)
        opts = opts or {}
        if not DirtFarm.State.autoCollect and not opts.force then return 0 end
        local gt = H and H.gt
        if not gt or type(gt.dropList) ~= "function" then return 0 end

        local now = DF.Util.now()
        if not opts.force and ctx and ctx.lastCollectAt and (now - ctx.lastCollectAt) < (opts.minInterval or 0.55) then
            return 0
        end

        local pos = Core.ReadPos()
        local maxR = opts.radius or 4.15
        local needDirt = ctx and (Inventory.countDirt(ctx) < 80) or false
        local okD, drops = pcall(gt.dropList)
        if not okD or type(drops) ~= "table" or #drops == 0 then
            if ctx then ctx.lastCollectAt = now end
            return 0
        end

        local usefulNear = 0
        for _, d in ipairs(drops) do
            if d and d.x and d.y and d.id then
                local dx = d.x - pos.x
                local dy = d.y - pos.y
                local dist = math.sqrt(dx * dx + dy * dy)
                if dist <= maxR then
                    local wantItem = true
                    if opts.filterId and d.id ~= opts.filterId then
                        wantItem = false
                    elseif not Inventory.hasFreeSpace(d.id) then
                        wantItem = false
                    elseif ctx and not opts.force and not needDirt and d.id == ctx.ids.dirtSeedId and Inventory.countDirtSeed(ctx) >= 180 then
                        wantItem = false
                    end
                    if wantItem then
                        usefulNear = usefulNear + 1
                        break
                    end
                end
            end
        end

        if ctx then ctx.lastCollectAt = now end
        if usefulNear == 0 then return 0 end

        local collectFn = Packets and Packets.Collect
        if type(collectFn) ~= "function" then return 0 end
        local collected = collectFn({
            radius = maxR,
            filterId = opts.filterId,
            stepMoveIfFar = false,
            preferWalk = false,
            collectDelay = math.min(0.025, DirtFarm.State.collectDelay or 0.025),
            shouldContinue = aliveFn,
        })
        return collected or 0
    end

    function Inventory.autoDropStash(ctx, aliveFn)
        local seedId = ctx.ids.dirtSeedId
        if not seedId or seedId <= 0 then return false end
        local cnt = Core.CountItem(seedId)
        if cnt < 180 then return false end
        if not (Packets and Packets.Drop) then return false end
        local pos = Core.ReadPos()
        local dropCount = math.min(cnt - 20, 160)
        if dropCount <= 0 then return false end
        setDfStatus(string.format("Auto-Drop %d Dirt Seed di (%d,%d)...", dropCount, pos.tx or 0, pos.ty or 0))
        local okDrop = Packets.Drop(seedId, dropCount, { shouldContinue = aliveFn })
        return okDrop == true
    end

    function Inventory.farmDirtIfLow(ctx, aliveFn, minDirtNeeded)
        minDirtNeeded = minDirtNeeded or 20
        local dirtId = ctx.ids.dirtId
        local seedId = ctx.ids.dirtSeedId
        if Core.CountItem(dirtId) >= minDirtNeeded then return true end

        -- Step 1: Collect nearby drops first (maybe Dirt is lying on the ground)
        Inventory.collectSmart(ctx, aliveFn, { force = true, radius = 4.6, filterId = dirtId })
        if Core.CountItem(dirtId) >= minDirtNeeded then return true end

        -- Step 2: Check if Dirt Seeds are available to plant safely on a valid Dirt floor
        local seedCount = Core.CountItem(seedId)
        if seedCount <= 0 then
            Inventory.collectSmart(ctx, aliveFn, { force = true, radius = 4.6, filterId = seedId })
            seedCount = Core.CountItem(seedId)
        end
        if seedCount <= 0 then return false end

        local pos = Core.ReadPos()
        local standFloorY = math.floor(pos.y + 0.5)
        local plantY = standFloorY - 1
        local fmt = ctx.format
        if plantY < fmt.topY or plantY > fmt.maxWorkY then return false end

        -- Gather up to 8 safe, non-immutable plantable spots near current X
        local spots = {}
        local minX = DF.Util.clamp(math.floor(pos.x) - 4, fmt.minWorkX, fmt.maxWorkX)
        local maxX = DF.Util.clamp(math.floor(pos.x) + 4, fmt.minWorkX, fmt.maxWorkX)
        for px = minX, maxX do
            if not DF.Safety.isImmutableTile(ctx, px, plantY, false)
                and Core.GetFG(px, plantY) == 0
                and DF.MoveController.isStandable(px, standFloorY)
                and (not Core.IsPlantable or Core.IsPlantable(px, plantY)) then
                spots[#spots + 1] = { x = px, y = plantY }
                if #spots >= math.min(8, seedCount) then break end
            end
        end
        if #spots == 0 then return false end

        setDfStatus("Dirt habis -> Tanam & Harvest Dirt Seed...")
        local planted = {}
        for _, sp in ipairs(spots) do
            if not aliveFn() or Core.CountItem(seedId) <= 0 then break end
            if DF.MoveController.moveToStand(ctx, sp.x, standFloorY, aliveFn, { maxSec = 2.0 }) then
                if not DF.Safety.isImmutableTile(ctx, sp.x, sp.y, false) and Core.GetFG(sp.x, sp.y) == 0 then
                    local okP = Packets.PlaceVerified(sp.x, sp.y, seedId, 1, {
                        showHand = DirtFarm.State.showHand,
                        verifyTimeout = 0.30,
                        optimisticFast = false,
                        shouldContinue = aliveFn,
                    })
                    if okP then
                        planted[#planted + 1] = sp
                    end
                end
            end
        end
        if #planted == 0 then return false end

        -- Wait cleanly for Dirt Trees to grow (Dirt Tree ~31s, poll ready state)
        local growDeadline = DF.Util.now() + 36.0
        while aliveFn() and DF.Util.now() < growDeadline do
            local readyCount = 0
            for _, sp in ipairs(planted) do
                if Core.IsTreeRipe and Core.IsTreeRipe(sp.x, sp.y) then
                    readyCount = readyCount + 1
                elseif Core.GetFG(sp.x, sp.y) == 0 then
                    readyCount = readyCount + 1
                end
            end
            if readyCount >= #planted then break end
            setDfStatus(string.format("Menunggu Dirt Tree siap (%d/%d)...", readyCount, #planted))
            DF.Util.wait(0.8)
        end

        -- Harvest all planted trees (strictly immutable-checked)
        for _, sp in ipairs(planted) do
            if not aliveFn() then break end
            if not DF.Safety.isImmutableTile(ctx, sp.x, sp.y, false) and Core.GetFG(sp.x, sp.y) ~= 0 then
                DF.MoveController.moveToStand(ctx, sp.x, standFloorY, aliveFn, { maxSec = 2.0 })
                Packets.BreakVerified({ { tx = sp.x, ty = sp.y, layer = 1 } }, {
                    threads = 1,
                    layer = 1,
                    hitDelay = math.max(0.16, DirtFarm.State.breakDelay or 0.16),
                    verifyTimeout = 0.28,
                    showHand = DirtFarm.State.showHand,
                    showVisual = true,
                    autoRange = false,
                    shouldContinue = aliveFn,
                })
                Inventory.collectSmart(ctx, aliveFn, { force = true, radius = 4.6 })
            end
        end

        DF.DiffAnalyzer.updateRegion(ctx, minX - 1, maxX + 1, plantY - 1, standFloorY)
        return Core.CountItem(dirtId) >= 1
    end
end

-- Module 9: Action Executor & 3-Stage Smart Verification Manager
do
    local Executor = {}
    DF.Executor = Executor

    local function serverEchoTimeout()
        if H and H.serverTileEchoSeen then
            return DF.Util.clamp((H.serverEchoRtt or 0.22) + 0.18, 0.24, 0.65)
        end
        return 0.28
    end

    local function readTileAck(w, x, y, layer)
        if not (H and H.serverTileEchoSeen and type(H.tileAck) == "table") then
            return nil
        end
        local key = ((layer == 2) and "bg" or "fg") .. ":" .. (y * w + x)
        return H.tileAck[key]
    end

    -- Stage 2: World State Verification (PENDING / CONFIRMED / FAILED / UNKNOWN)
    function Executor.verifyTileWorldState(ctx, item, sentAt, aliveFn)
        local VS = DF.ENUMS.VERIFY_STATUS
        local w = ctx.w
        local tx, ty, layer = item.x, item.y, item.layer
        local expectedVal = (item.action == "break") and 0 or item.desiredId
        local timeout = serverEchoTimeout()
        local deadline = DF.Util.now() + timeout

        while DF.Util.now() <= deadline do
            if aliveFn and not aliveFn() then
                return VS.UNKNOWN, "CANCELLED"
            end
            if Core.ReconcileTile then
                Core.ReconcileTile(tx, ty, layer)
            end
            local liveVal = Core.GetLayerTile(tx, ty, layer)
            local ack = readTileAck(w, tx, ty, layer)

            if H and H.serverTileEchoSeen then
                if ack and ack.t >= (sentAt - 0.02) then
                    if ack.id == expectedVal then
                        if liveVal ~= expectedVal and Core.MirrorLocalTile then
                            Core.MirrorLocalTile(layer, tx, ty, expectedVal, false)
                        end
                        return VS.CONFIRMED, "SERVER_ACK_CONFIRMED"
                    else
                        -- Server explicitly sent a different tile ID (reject/revert)
                        if liveVal ~= ack.id and Core.MirrorLocalTile then
                            Core.MirrorLocalTile(layer, tx, ty, ack.id, false)
                        end
                        return VS.FAILED, "SERVER_MISMATCH"
                    end
                end
            else
                if liveVal == expectedVal then
                    return VS.CONFIRMED, "WORLD_STATE_MATCHED"
                end
            end
            DF.Util.wait(0.025)
        end

        -- Post-window check
        if Core.ReconcileTile then
            Core.ReconcileTile(tx, ty, layer)
        end
        local finalVal = Core.GetLayerTile(tx, ty, layer)
        if finalVal == expectedVal then
            if H and H.serverTileEchoSeen then
                -- Client reflects expected value, but server echo has not arrived yet -> PENDING (do NOT fire opposite action!)
                return VS.PENDING, "AWAITING_LATE_ECHO"
            end
            return VS.CONFIRMED, "WORLD_STATE_MATCHED"
        end
        return VS.FAILED, "VERIFY_TIMEOUT"
    end

    -- Stage 3: Blueprint Completion Verification
    function Executor.finalizeTileVerification(ctx, item, vStatus, vReason)
        local VS = DF.ENUMS.VERIFY_STATUS
        local ST = DF.ENUMS.TILE_STATUS
        local x, y = item.x, item.y

        if vStatus == VS.PENDING then
            DF.TaskManager.markVerifying(ctx, x, y, 0.45)
            return false, vStatus, vReason
        end

        if vStatus == VS.CONFIRMED then
            local postSt = DF.Blueprint.evaluateTile(ctx, x, y, { ignoreLifecycle = true })
            if postSt == ST.CORRECT or postSt == ST.IMMUTABLE or postSt == ST.EXCLUDED then
                DF.TaskManager.markCompleted(ctx, x, y)
                ctx.diff.confirmedCompleted = ctx.diff.confirmedCompleted + 1
                return true, VS.CONFIRMED, "BLUEPRINT_COMPLETED"
            elseif item.action == "break" and (postSt == ST.NEED_PLACE or postSt == ST.NEED_BREAK_BG) then
                -- Multi-step tile (NEED_REPLACE or FG+BG clear) cleanly finished Stage 1 -> advance to next stage
                DF.TaskManager.markStageAdvanced(ctx, x, y)
                return true, VS.CONFIRMED, "STAGE_ADVANCED"
            else
                DF.TaskManager.recordFailure(ctx, x, y, "POST_CHECK_MISMATCH", false)
                return false, VS.FAILED, "POST_CHECK_MISMATCH"
            end
        end

        -- FAILED or UNKNOWN
        local hardBlock = (vReason == "IMMUTABLE_REJECTED" or vReason == "NO_EDIT_ACCESS")
        DF.TaskManager.recordFailure(ctx, x, y, vReason or "ACTION_FAILED", hardBlock)
        return false, vStatus, vReason
    end

    -- Execute a reserved, duplicate-free batch of BREAK or PLACE items with strict immutable guard
    function Executor.executeBatch(ctx, batchItems, aliveFn)
        if not batchItems or #batchItems == 0 then
            return { okCount = 0, failCount = 0, pendingCount = 0 }
        end
        local VS = DF.ENUMS.VERIFY_STATUS

        -- Reserve entire batch atomically (prevents duplicate tasks & opposite actions)
        local batchId, reserved = DF.TaskManager.reserveBatch(ctx, batchItems)
        if #reserved == 0 then
            return { okCount = 0, failCount = 0, pendingCount = 0 }
        end

        local okCount = 0
        local failCount = 0
        local pendingCount = 0
        local minX, maxX = ctx.w - 1, 0
        local minY, maxY = ctx.h - 1, 0

        local breakList = {}
        local placeList = {}

        for _, it in ipairs(reserved) do
            minX = math.min(minX, it.x)
            maxX = math.max(maxX, it.x)
            minY = math.min(minY, it.y)
            maxY = math.max(maxY, it.y)

            -- Hard safety gate right before any packet execution
            local safeOk, safeReason = DF.Safety.canExecuteActionOn(ctx, it.x, it.y, it.action, it.layer)
            if not safeOk then
                DF.TaskManager.recordFailure(ctx, it.x, it.y, safeReason or "IMMUTABLE_REJECTED", true)
                failCount = failCount + 1
            elseif not Core.IsInActionReach(it.x, it.y, (it.action == "break") and "break" or "build") then
                DF.TaskManager.recordFailure(ctx, it.x, it.y, "OUT_OF_REACH", false)
                failCount = failCount + 1
            else
                if it.action == "break" then
                    if Core.GetLayerTile(it.x, it.y, it.layer) ~= 0 then
                        breakList[#breakList + 1] = it
                    else
                        Executor.finalizeTileVerification(ctx, it, VS.CONFIRMED, "ALREADY_EMPTY")
                        okCount = okCount + 1
                    end
                elseif it.action == "place" then
                    local info = Core.GetItemInfo(it.desiredId)
                    if Core.GetLayerTile(it.x, it.y, it.layer) == it.desiredId then
                        Executor.finalizeTileVerification(ctx, it, VS.CONFIRMED, "ALREADY_MATCHED")
                        okCount = okCount + 1
                    elseif Core.GetLayerTile(it.x, it.y, it.layer) ~= 0 then
                        DF.TaskManager.markStageAdvanced(ctx, it.x, it.y)
                        failCount = failCount + 1
                    elseif Core.CountItem(it.desiredId) <= 0 then
                        local reason = (it.desiredId == ctx.ids.platformId) and "PLATFORM_NO_MATERIAL" or "NO_MATERIAL"
                        DF.TaskManager.markBlocked(ctx, it.x, it.y, reason)
                        failCount = failCount + 1
                    elseif Core.CanPlaceBodyOk and not Core.CanPlaceBodyOk(it.x, it.y, info) then
                        DF.TaskManager.recordFailure(ctx, it.x, it.y, "BODY_OVERLAP", false)
                        failCount = failCount + 1
                    else
                        placeList[#placeList + 1] = it
                    end
                end
            end
        end

        -- Stage 1A: Execute Break Batch SEQUENTIALLY (threads = 1, strictVerify = true, FG FIRST then BG!)
        -- Menghilangkan punch collision antar thread, fake local-mirror vanish, miss Rock (10 hit), dan Cave BG kelewat.
        if #breakList > 0 and aliveFn() then
            DF.Util.coolAntiKick()
            DF.Util.forceWalkSpeedWindow(1.5)
            local fgItems, bgItems = {}, {}
            for _, it in ipairs(breakList) do
                if it.layer == 2 then
                    bgItems[#bgItems + 1] = it
                else
                    fgItems[#fgItems + 1] = it
                end
            end
            local hitDelay = math.max(0.194, tonumber(DirtFarm.State.breakDelay) or 0.194)
            local verTo = math.max(0.18, serverEchoTimeout())

            local function runBreakPhase(phaseItems, phaseLayer)
                if #phaseItems == 0 or not aliveFn() then return end
                local targets = {}
                local safeList = {}
                local sentAt = DF.Util.now()
                for _, it in ipairs(phaseItems) do
                    if phaseLayer == 2 and Core.GetFG(it.x, it.y) ~= 0 then
                        DF.TaskManager.markStageAdvanced(ctx, it.x, it.y)
                        failCount = failCount + 1
                    else
                        local okLive, liveReason = DF.Safety.canExecuteActionOn(ctx, it.x, it.y, "break", phaseLayer)
                        if okLive and Core.IsInActionReach(it.x, it.y, "break") then
                            DF.TaskManager.markExecuting(ctx, it.x, it.y)
                            safeList[#safeList + 1] = it
                            targets[#targets + 1] = { tx = it.x, ty = it.y, layer = phaseLayer }
                        elseif not okLive then
                            DF.TaskManager.recordFailure(ctx, it.x, it.y, liveReason or "IMMUTABLE_REJECTED", true)
                            failCount = failCount + 1
                        else
                            DF.TaskManager.recordFailure(ctx, it.x, it.y, "OUT_OF_REACH", false)
                            failCount = failCount + 1
                        end
                    end
                end
                if #targets == 0 then return end
                Packets.BreakVerified(targets, {
                    threads = 1,
                    layer = phaseLayer,
                    oneHit = DirtFarm.State.oneHit == true,
                    hitDelay = hitDelay,
                    verifyTimeout = verTo,
                    showHand = DirtFarm.State.showHand ~= false,
                    showVisual = true,
                    noLocalMirror = true,
                    strictVerify = true,
                    autoRange = false,
                    shouldContinue = aliveFn,
                })
                for _, it in ipairs(safeList) do
                    DF.TaskManager.markVerifying(ctx, it.x, it.y, verTo)
                    local vSt, vReason = Executor.verifyTileWorldState(ctx, it, sentAt, aliveFn)
                    local doneOk = Executor.finalizeTileVerification(ctx, it, vSt, vReason)
                    if doneOk then
                        if Core.ClearVisualCrack then pcall(Core.ClearVisualCrack, it.x, it.y) end
                        okCount = okCount + 1
                        -- Bila FG baru saja hancur dan Cave BG di tile yang sama ikut perlu dibreak, langsung antrikan ke fase BG!
                        if phaseLayer == 1 and Core.GetFG(it.x, it.y) == 0 and Core.GetBG(it.x, it.y) ~= 0 then
                            local nextSt = DF.Blueprint.evaluateTile(ctx, it.x, it.y, { ignoreLifecycle = true })
                            if nextSt == DF.ENUMS.TILE_STATUS.NEED_BREAK_BG and Core.IsInActionReach(it.x, it.y, "break") then
                                local dup = false
                                for _, bIt in ipairs(bgItems) do
                                    if bIt.x == it.x and bIt.y == it.y then dup = true; break end
                                end
                                if not dup then
                                    bgItems[#bgItems + 1] = { x = it.x, y = it.y, action = "break", layer = 2, role = it.role }
                                end
                            end
                        end
                    elseif vSt == VS.PENDING then
                        pendingCount = pendingCount + 1
                    else
                        failCount = failCount + 1
                    end
                end
            end

            runBreakPhase(fgItems, 1)
            runBreakPhase(bgItems, 2)
        end

        -- Stage 1B: Execute Place Batch (never optimisticFast blind mirror; waits for genuine world verification)
        if #placeList > 0 and aliveFn() then
            local placeGap = math.max(0.11, tonumber(DirtFarm.State.placeDelay) or 0.12)
            for _, it in ipairs(placeList) do
                if not aliveFn() then break end
                DF.Util.coolAntiKick()
                DF.Util.forceWalkSpeedWindow(1.0)

                -- Final live check before sending place packet
                local safeOk, safeReason = DF.Safety.canExecuteActionOn(ctx, it.x, it.y, "place", it.layer)
                if not safeOk then
                    DF.TaskManager.recordFailure(ctx, it.x, it.y, safeReason or "IMMUTABLE_REJECTED", true)
                    failCount = failCount + 1
                elseif Core.CountItem(it.desiredId) <= 0 then
                    local reason = (it.desiredId == ctx.ids.platformId) and "PLATFORM_NO_MATERIAL" or "NO_MATERIAL"
                    DF.TaskManager.markBlocked(ctx, it.x, it.y, reason)
                    failCount = failCount + 1
                else
                    DF.TaskManager.markExecuting(ctx, it.x, it.y)
                    local sentAt = DF.Util.now()
                    local okP, msgP = Packets.PlaceVerified(it.x, it.y, it.desiredId, it.layer, {
                        showHand = DirtFarm.State.showHand ~= false,
                        delay = 0,
                        placeGap = placeGap,
                        noLocalMirror = false,
                        optimisticFast = false,
                        verifyTimeout = serverEchoTimeout(),
                        retries = 1,
                        shouldContinue = aliveFn,
                    })
                    DF.TaskManager.markVerifying(ctx, it.x, it.y, serverEchoTimeout())
                    if msgP == "placing_too_fast" then
                        DF.Util.wait(0.24)
                    end
                    local vSt, vReason = Executor.verifyTileWorldState(ctx, it, sentAt, aliveFn)
                    if not okP and vSt ~= VS.CONFIRMED then
                        vSt = VS.FAILED
                        vReason = tostring(msgP or vReason or "PLACE_REJECTED")
                    end
                    local doneOk = Executor.finalizeTileVerification(ctx, it, vSt, vReason)
                    if doneOk then
                        okCount = okCount + 1
                    elseif vSt == VS.PENDING then
                        pendingCount = pendingCount + 1
                    else
                        failCount = failCount + 1
                    end
                end
            end
        end

        DF.TaskManager.releaseBatch(ctx, batchId)

        -- Local dirty-region update (no full world rescan!)
        if minX <= maxX and minY <= maxY then
            DF.DiffAnalyzer.updateRegion(ctx, minX - 1, maxX + 1, minY - 1, maxY + 1)
            ctx.diff.batchesSinceReconcile = ctx.diff.batchesSinceReconcile + 1
        end

        return {
            okCount = okCount,
            failCount = failCount,
            pendingCount = pendingCount,
        }
    end
end

-- Module 10: Unified Movement Controller (Single Owner of Movement Decisions)
do
    local MoveController = {}
    DF.MoveController = MoveController

    function MoveController.isHazard(info)
        local godMode = SYT_Logic and SYT_Logic.Misc and SYT_Logic.Misc.State and SYT_Logic.Misc.State.godMode == true
        return info ~= nil and (info.deadly == true or info.hurts == true) and not godMode
    end

    function MoveController.isStandable(tx, ty)
        local gt = H and H.gt
        if not gt or tx < 0 or tx >= gt.w or ty >= gt.h then return true end
        if ty < 0 then return false end
        if Core.IsSolid(tx, ty) then
            local id = Core.GetFG(tx, ty)
            if id ~= 0 and MoveController.isHazard(Core.GetItemInfo(id)) then
                return false
            end
            return true
        end
        local id = Core.GetFG(tx, ty)
        if id == 0 then return false end
        local info = Core.GetItemInfo(id)
        return info ~= nil and info.platform == true and not info.background
    end

    function MoveController.isPassable(tx, ty)
        local gt = H and H.gt
        if not gt or tx < 0 or tx >= gt.w or ty < 0 or ty >= gt.h then return false end
        if Core.IsSolid(tx, ty) then return false end
        local id = Core.GetFG(tx, ty)
        if id ~= 0 and MoveController.isHazard(Core.GetItemInfo(id)) then
            return false
        end
        return true
    end

    function MoveController.safeReachDist(tx, ty, pos, kind)
        pos = pos or Core.ReadPos()
        local r = (Core.GetActionRange and Core.GetActionRange(kind or "break")) or 2.15
        r = math.min(r, 2.15)
        local dx = math.abs((tx + 0.5) - pos.x)
        local dy = math.abs((ty + 0.5) - (pos.y - 0.475))
        return dx <= r and dy <= r
    end

    function MoveController.settleGrounded(aliveFn, maxSec)
        local dl = DF.Util.now() + (maxSec or 0.35)
        Core.ClearManualInput()
        while DF.Util.now() < dl do
            if aliveFn and not aliveFn() then return false end
            local p = Core.ReadPos()
            if p.grounded then return true end
            DF.Util.wait(0.02)
        end
        return Core.ReadPos().grounded == true
    end

    function MoveController.manualJumpTo(destX, destFloorY, aliveFn, maxSec)
        local targetX = destX + 0.5
        local dl = DF.Util.now() + (maxSec or 1.25)
        while DF.Util.now() < dl do
            if aliveFn and not aliveFn() then
                Core.ClearManualInput()
                return false
            end
            DF.Util.forceWalkSpeedWindow(0.8)
            local p = Core.ReadPos()
            if p.grounded and math.abs(p.y - destFloorY) <= 0.35 and math.abs(p.x - targetX) <= 0.55 then
                Core.ClearManualInput()
                return true
            end
            local dir = (targetX > p.x + 0.08) and 1 or ((targetX < p.x - 0.08) and -1 or 0)
            local wantJump = p.grounded and (p.y > destFloorY + 0.25 or math.abs(targetX - p.x) > 0.65)
            Core.SetManualInput(dir, wantJump)
            DF.Util.wait(0.016)
        end
        Core.ClearManualInput()
        local pf = Core.ReadPos()
        return math.abs(pf.x - targetX) <= 0.85 and math.abs(pf.y - destFloorY) <= 0.55
    end

    function MoveController.dropIntoCol(colX, targetFloorY, aliveFn, maxSec)
        local targetX = colX + 0.5
        local dl = DF.Util.now() + (maxSec or 1.5)
        while DF.Util.now() < dl do
            if aliveFn and not aliveFn() then
                Core.ClearManualInput()
                return false
            end
            DF.Util.forceWalkSpeedWindow(0.8)
            local p = Core.ReadPos()
            if math.floor(p.y + 0.5) >= targetFloorY and p.grounded then
                Core.ClearManualInput()
                return true
            end
            local dir = 0
            if p.x < targetX - 0.14 then dir = 1
            elseif p.x > targetX + 0.14 then dir = -1 end
            Core.SetManualInput(dir, false)
            DF.Util.wait(0.016)
        end
        Core.ClearManualInput()
        return math.floor(Core.ReadPos().y + 0.5) >= targetFloorY
    end

    -- Smooth horizontal walk on floorY with auto-jump over small gaps and 1-tile step-ups.
    -- Strictly NEVER breaks or places immutable/bedrock tiles mid-walk.
    function MoveController.stepWalkToX(goalX, floorY, maxSec, aliveFn, ctx)
        local gt = H and H.gt
        if not gt then return false end
        -- Clamp ke batas fisik hitbox player agar tidak mentok dinding ujung world lalu stuck delay!
        local gx = DF.Util.clamp(goalX, 0.55, gt.w - 0.55)
        local nearEdge = (gx <= 1.25 or gx >= gt.w - 1.25)
        local tolX = nearEdge and 0.42 or 0.28
        local dl = DF.Util.now() + (maxSec or 3.0)
        local lastX = Core.ReadPos().x
        local stuckSince = DF.Util.now()

        while DF.Util.now() < dl do
            if aliveFn and not aliveFn() then
                Core.ClearManualInput()
                return false
            end
            DF.Util.forceWalkSpeedWindow(0.8)
            local p = Core.ReadPos()
            local dist = gx - p.x
            if math.abs(dist) <= tolX and (not floorY or math.abs(p.y - floorY) <= 0.65) then
                Core.ClearManualInput()
                return true
            end

            local dir = (dist > 0) and 1 or -1
            local curCol = DF.Util.clamp(math.floor(p.x), 0, gt.w - 1)
            local curFloor = floorY or math.floor(p.y + 0.5)
            local bodyY = curFloor - 1
            local aheadCol = DF.Util.clamp(curCol + dir, 0, gt.w - 1)

            -- Bila sudah di ujung world (kolom 0 / w-1) dan arah masih mendorong ke dinding border, langsung selesai & turn!
            if ((curCol == 0 and dir < 0) or (curCol == gt.w - 1 and dir > 0)) and math.abs(dist) <= 0.75 then
                Core.ClearManualInput()
                return true
            end

            local wantJump = false
            -- Gap jump over 1..3 missing floor tiles
            if p.grounded and aheadCol ~= curCol and not MoveController.isStandable(aheadCol, curFloor) then
                for look = 1, 3 do
                    local lx = curCol + dir * look
                    if lx >= 0 and lx < gt.w and MoveController.isStandable(lx, curFloor) then
                        wantJump = true
                        break
                    end
                end
            end

            -- 1-tile solid obstacle ahead with clear headroom -> step-up jump
            if p.grounded and aheadCol ~= curCol and Core.IsSolid(aheadCol, bodyY) then
                if MoveController.isPassable(aheadCol, bodyY - 1) and MoveController.isPassable(curCol, bodyY - 1) then
                    wantJump = true
                elseif ctx then
                    -- Clear non-immutable obstacle blocking corridor through safety-checked executor
                    local isImm = DF.Safety.isImmutableTile(ctx, aheadCol, bodyY, false)
                    if not isImm and Core.IsInActionReach(aheadCol, bodyY, "break") then
                        Core.ClearManualInput()
                        DF.Executor.executeBatch(ctx, {
                            { x = aheadCol, y = bodyY, action = "break", layer = 1 }
                        }, aliveFn)
                    else
                        Core.ClearManualInput()
                        return false
                    end
                else
                    Core.ClearManualInput()
                    return false
                end
            end

            -- Check genuine horizontal stall (cepat lepas agar tidak stuck lama di ujung world!)
            if math.abs(p.x - lastX) > 0.10 then
                lastX = p.x
                stuckSince = DF.Util.now()
            else
                local stalledSec = DF.Util.now() - stuckSince
                if nearEdge and stalledSec >= 0.18 and math.abs(dist) <= 0.95 then
                    Core.ClearManualInput()
                    return true
                elseif stalledSec > 0.40 then
                    Core.ClearManualInput()
                    return false
                end
            end

            Core.SetManualInput(dir, wantJump)
            DF.Util.wait(0.016)
        end

        Core.ClearManualInput()
        local pf = Core.ReadPos()
        return math.abs(pf.x - gx) <= (nearEdge and 0.95 or 0.65) and (not floorY or math.abs(pf.y - floorY) <= 0.75)
    end

    -- Platformer BFS/Dijkstra reachability map for isolated/complex navigation
    function MoveController.computePlatformerReach(ctx, startTx, startFloorY)
        local w, h = ctx.w, ctx.h
        local dist = {}
        local parent = {}
        local moveKind = {}
        local q = {}
        local head, tail = 1, 1

        local sKey = startFloorY * w + startTx
        dist[sKey] = 0
        q[1] = sKey

        local function push(nx, ny, cost, fromKey, kind)
            if nx < 0 or nx >= w or ny < 1 or ny >= h then return end
            if not MoveController.isStandable(nx, ny) then return end
            if not MoveController.isPassable(nx, ny - 1) then return end
            local k = ny * w + nx
            if dist[k] == nil or cost < dist[k] then
                dist[k] = cost
                parent[k] = fromKey
                moveKind[k] = kind
                tail = tail + 1
                q[tail] = k
            end
        end

        while head <= tail do
            local cur = q[head]
            head = head + 1
            local cy = math.floor(cur / w)
            local cx = cur - cy * w
            local cd = dist[cur]

            -- Walk left/right
            for _, dx in ipairs({ -1, 1 }) do
                local nx = cx + dx
                if nx >= 0 and nx < w then
                    if MoveController.isPassable(nx, cy - 1) then
                        if MoveController.isStandable(nx, cy) then
                            push(nx, cy, cd + 1, cur, "walk")
                        else
                            -- Drop down shaft/ledge
                            for fy = cy + 1, h - 1 do
                                if not MoveController.isPassable(nx, fy - 1) then break end
                                if MoveController.isStandable(nx, fy) then
                                    push(nx, fy, cd + 1 + (fy - cy) * 0.6, cur, "drop")
                                    break
                                end
                            end
                            -- Jump gap 2..3 tiles across
                            for gap = 2, 3 do
                                local gx = cx + dx * gap
                                if gx >= 0 and gx < w and MoveController.isPassable(gx, cy - 1) and MoveController.isStandable(gx, cy) then
                                    push(gx, cy, cd + gap + 0.5, cur, "jump")
                                    break
                                end
                            end
                        end
                    end
                    -- Jump up 1..2 tiles onto ledge/platform
                    for dy = 1, 2 do
                        local ny = cy - dy
                        if ny >= 2 and MoveController.isPassable(cx, ny - 1) and MoveController.isPassable(nx, ny - 1) and MoveController.isStandable(nx, ny) then
                            push(nx, ny, cd + 2.2, cur, "jump_up")
                        end
                    end
                end
            end

            -- Straight-up platform jump (Wooden Platform ladder!)
            for dy = 1, 2 do
                local ny = cy - dy
                if ny >= 2 and MoveController.isPassable(cx, ny - 1) and MoveController.isStandable(cx, ny) then
                    local fid = Core.GetFG(cx, ny)
                    local info = fid ~= 0 and Core.GetItemInfo(fid) or nil
                    if info and info.platform == true then
                        push(cx, ny, cd + 1.5, cur, "plat_up")
                    end
                end
            end
        end

        return { dist = dist, parent = parent, moveKind = moveKind, w = w }
    end

    function MoveController.walkNavPath(ctx, nav, goalTx, goalFloorY, aliveFn)
        local gKey = goalFloorY * ctx.w + goalTx
        if not nav.dist[gKey] then return false end
        local path = {}
        local k = gKey
        while k do
            local py = math.floor(k / ctx.w)
            local px = k - py * ctx.w
            path[#path + 1] = { x = px, floorY = py, kind = nav.moveKind[k] }
            k = nav.parent[k]
        end
        -- Reverse path (skip start node)
        for i = #path - 1, 1, -1 do
            if not aliveFn() then
                Core.ClearManualInput()
                return false
            end
            local step = path[i]
            if step.kind == "walk" then
                MoveController.stepWalkToX(step.x + 0.5, step.floorY, 1.4, aliveFn, ctx)
            elseif step.kind == "drop" then
                MoveController.dropIntoCol(step.x, step.floorY, aliveFn, 1.8)
            else
                MoveController.manualJumpTo(step.x, step.floorY, aliveFn, 1.3)
            end
        end
        return math.abs(Core.ReadPos().x - (goalTx + 0.5)) <= 1.1 and math.abs(Core.ReadPos().y - goalFloorY) <= 0.85
    end

    -- Climb side shaft using existing Wooden Platforms first; falls back to tracked temporary Dirt only if PLATFORM_NO_MATERIAL
    function MoveController.climbShaftToFloor(ctx, targetFloorY, aliveFn)
        local fmt = ctx.format
        if not fmt.hasShafts then return false end
        local pos = Core.ReadPos()
        local curFloor = math.floor(pos.y + 0.5)
        if curFloor <= targetFloorY then return true end

        -- Pick nearest side shaft (left or right)
        local useLeft = (pos.x <= ctx.w * 0.5)
        local platCol = useLeft and fmt.leftPlatCol or fmt.rightPlatCol
        local openCol = useLeft and (platCol == 1 and 0 or 1) or (platCol == ctx.w - 2 and (ctx.w - 1) or (ctx.w - 2))

        MoveController.stepWalkToX(platCol + 0.5, curFloor, 3.0, aliveFn, ctx)

        local guard = 0
        while aliveFn() and guard < 36 do
            guard = guard + 1
            local p = Core.ReadPos()
            curFloor = math.floor(p.y + 0.5)
            if curFloor <= targetFloorY then
                return true
            end
            local nextFloor = math.max(targetFloorY, curFloor - 2)

            -- Clear any blocking non-immutable air tile above head in shaft
            local toBreak = {}
            for _, sy in ipairs({ curFloor - 2, curFloor - 3 }) do
                if sy >= fmt.topY then
                    for _, sx in ipairs({ platCol, openCol }) do
                        local fg = Core.GetFG(sx, sy)
                        if fg ~= 0 and not DF.WorldScanner.isPlatformItem(fg, ctx.ids) and not DF.Safety.isImmutableTile(ctx, sx, sy, false) then
                            if Core.IsInActionReach(sx, sy, "break") then
                                toBreak[#toBreak + 1] = { x = sx, y = sy, action = "break", layer = 1 }
                            end
                        end
                    end
                end
            end
            if #toBreak > 0 then
                DF.Executor.executeBatch(ctx, toBreak, aliveFn)
            end

            -- Prefer Wooden Platform at (platCol, nextFloor)
            if MoveController.isStandable(platCol, nextFloor) then
                MoveController.manualJumpTo(platCol, nextFloor, aliveFn, 1.3)
            elseif fmt.platformRequired and Core.CountItem(ctx.ids.platformId) > 0 and not DF.Safety.isImmutableTile(ctx, platCol, nextFloor, false) then
                -- Place the permanent Blueprint Wooden Platform right on the shaft slot!
                DF.Executor.executeBatch(ctx, {
                    { x = platCol, y = nextFloor, action = "place", layer = 1, desiredId = ctx.ids.platformId }
                }, aliveFn)
                if MoveController.isStandable(platCol, nextFloor) then
                    MoveController.manualJumpTo(platCol, nextFloor, aliveFn, 1.3)
                end
            elseif Core.CountItem(ctx.ids.dirtId) > 0 and DF.Safety.canExecuteActionOn(ctx, openCol, nextFloor, "place", 1) and Core.GetFG(openCol, nextFloor) == 0 then
                -- Fallback only when PLATFORM_NO_MATERIAL: temporary Dirt step on openCol, then clean after climbing
                local okTmp = Packets.PlaceVerified(openCol, nextFloor, ctx.ids.dirtId, 1, {
                    showHand = DirtFarm.State.showHand ~= false,
                    optimisticFast = false,
                    verifyTimeout = 0.30,
                    shouldContinue = aliveFn,
                })
                if okTmp then
                    MoveController.manualJumpTo(openCol, nextFloor, aliveFn, 1.3)
                    -- Step onto platCol or inner floor before breaking temporary dirt
                    local stepOutX = useLeft and 2 or (ctx.w - 3)
                    if MoveController.isStandable(stepOutX, nextFloor) then
                        MoveController.stepWalkToX(stepOutX + 0.5, nextFloor, 1.4, aliveFn, ctx)
                        if DF.Safety.canExecuteActionOn(ctx, openCol, nextFloor, "break", 1) then
                            Packets.BreakVerified({ { tx = openCol, ty = nextFloor, layer = 1 } }, {
                                threads = 1, layer = 1, hitDelay = 0.16, verifyTimeout = 0.28, autoRange = false, shouldContinue = aliveFn
                            })
                        end
                    end
                else
                    break
                end
            else
                break
            end
        end

        return math.floor(Core.ReadPos().y + 0.5) <= targetFloorY + 1
    end

    function MoveController.respawnToDoor(ctx, aliveFn)
        if aliveFn and not aliveFn() then return false end
        local fmt = ctx and ctx.format
        if not fmt then return false end
        local p0 = Core.ReadPos()
        if math.abs((p0.tx or math.floor(p0.x)) - fmt.doorX) <= 3 and math.abs((p0.ty or math.floor(p0.y)) - fmt.doorY) <= 1 then
            return true
        end
        Core.ClearManualInput()
        if Core.AllowMoveToWindow then Core.AllowMoveToWindow(4.0) end
        local fnResp = (H and (H.origGtRespawn or H.origRespawnFn)) or (H and H.gt and rawget(H.gt, "respawn"))
        if type(fnResp) == "function" then
            pcall(fnResp)
            local dl = DF.Util.now() + 1.15
            while DF.Util.now() < dl do
                if aliveFn and not aliveFn() then return false end
                local cur = Core.ReadPos()
                if math.abs((cur.ty or math.floor(cur.y)) - fmt.doorY) <= 2 and math.abs((cur.tx or math.floor(cur.x)) - fmt.doorX) <= 4 then
                    if H then H.stopMoveUntil = 0 end
                    MoveController.settleGrounded(aliveFn, 0.30)
                    return true
                end
                DF.Util.wait(0.08)
            end
        end
        if Core.AllowMoveToWindow then Core.AllowMoveToWindow(4.0) end
        if Packets and type(Packets.SendChat) == "function" then
            pcall(Packets.SendChat, { message = "/respawn" })
            local dlChat = DF.Util.now() + 1.85
            while DF.Util.now() < dlChat do
                if aliveFn and not aliveFn() then return false end
                local cur = Core.ReadPos()
                if math.abs((cur.ty or math.floor(cur.y)) - fmt.doorY) <= 2 and math.abs((cur.tx or math.floor(cur.x)) - fmt.doorX) <= 4 then
                    if H then H.stopMoveUntil = 0 end
                    MoveController.settleGrounded(aliveFn, 0.30)
                    return true
                end
                DF.Util.wait(0.08)
            end
        end
        MoveController.settleGrounded(aliveFn, 0.25)
        local pf = Core.ReadPos()
        return math.abs((pf.ty or math.floor(pf.y)) - fmt.doorY) <= 2
    end

    -- Unified Move Controller Entry Point
    function MoveController.moveToStand(ctx, standX, standFloorY, aliveFn, opts)
        opts = opts or {}
        if not aliveFn() then return false end
        local pos = Core.ReadPos()
        local curFloor = math.floor(pos.y + 0.5)

        -- Already standing safely at target stand tile (termasuk posisi tepi ujung world agar langsung eksekusi & turn)
        local atEdgeOk = (standX <= 1 and pos.x <= 1.35) or (standX >= ctx.w - 2 and pos.x >= ctx.w - 1.35)
        if pos.grounded and (math.abs(pos.x - (standX + 0.5)) <= 0.55 or atEdgeOk) and math.abs(pos.y - standFloorY) <= 0.50 then
            return true
        end

        -- Case 1: Same horizontal floor -> smooth direct walk
        if math.abs(curFloor - standFloorY) <= 1 and math.abs(pos.y - standFloorY) <= 0.75 then
            if MoveController.stepWalkToX(standX + 0.5, standFloorY, opts.maxSec or 4.0, aliveFn, ctx) then
                return true
            end
        end

        -- Case 2: Smart Respawn Shortcut when deep underground and target is at/above Main Door
        local fmt = ctx.format
        if curFloor > fmt.doorY + 4 and standFloorY <= fmt.doorY + 1 then
            setDfStatus("Respawn cerdas ke Main Door untuk area atas...")
            if MoveController.respawnToDoor(ctx, aliveFn) then
                pos = Core.ReadPos()
                curFloor = math.floor(pos.y + 0.5)
                if math.abs(curFloor - standFloorY) <= 1 then
                    if MoveController.stepWalkToX(standX + 0.5, standFloorY, 4.0, aliveFn, ctx) then
                        return true
                    end
                end
            end
        end

        -- Case 3: Descending via nearest side shaft
        if standFloorY > curFloor and fmt.hasShafts then
            local useLeft = (pos.x <= ctx.w * 0.5)
            local dropCol = useLeft and (fmt.leftPlatCol == 1 and 0 or 1) or (fmt.rightPlatCol == ctx.w - 2 and (ctx.w - 1) or (ctx.w - 2))
            if MoveController.stepWalkToX(dropCol + 0.5, curFloor, 3.5, aliveFn, ctx) then
                -- Clear blocking shaft tiles above drop path (strictly non-immutable)
                local blockBreaks = {}
                for dy = curFloor, math.min(standFloorY - 1, curFloor + 2) do
                    if not DF.Safety.isImmutableTile(ctx, dropCol, dy, false) and Core.GetFG(dropCol, dy) ~= 0 then
                        if Core.IsInActionReach(dropCol, dy, "break") then
                            blockBreaks[#blockBreaks + 1] = { x = dropCol, y = dy, action = "break", layer = 1 }
                        end
                    end
                end
                if #blockBreaks > 0 then
                    DF.Executor.executeBatch(ctx, blockBreaks, aliveFn)
                end
                MoveController.dropIntoCol(dropCol, standFloorY, aliveFn, 2.2)
                if math.abs(Core.ReadPos().y - standFloorY) <= 0.85 then
                    if MoveController.stepWalkToX(standX + 0.5, standFloorY, 4.0, aliveFn, ctx) then
                        return true
                    end
                end
            end
        end

        -- Case 4: Ascending via nearest side shaft (Wooden Platforms first)
        if standFloorY < curFloor and fmt.hasShafts then
            if MoveController.climbShaftToFloor(ctx, standFloorY, aliveFn) then
                if MoveController.stepWalkToX(standX + 0.5, standFloorY, 4.0, aliveFn, ctx) then
                    return true
                end
            end
        end

        -- Case 5: Full platformer graph pathfinding fallback
        pos = Core.ReadPos()
        local nav = MoveController.computePlatformerReach(ctx, DF.Util.clamp(math.floor(pos.x), 0, ctx.w - 1), math.floor(pos.y + 0.5))
        if nav.dist[standFloorY * ctx.w + standX] then
            if MoveController.walkNavPath(ctx, nav, standX, standFloorY, aliveFn) then
                return true
            end
        end

        -- Case 6: Core WalkPathTo final fallback
        if Packets and type(Packets.WalkPathTo) == "function" then
            Packets.WalkPathTo(standX, math.max(0, standFloorY - 1), 6.9, aliveFn, { fastWalk = false, noSnap = true })
            local pf = Core.ReadPos()
            return math.abs(pf.x - (standX + 0.5)) <= 1.25 and math.abs(pf.y - standFloorY) <= 1.0
        end

        return false
    end

    -- Minimal recovery: ONLY acts if character is genuinely off-floor / trapped / on hazard
    function MoveController.recoverOnlyIfUnsafe(ctx, aliveFn)
        local p = Core.ReadPos()
        local cx = DF.Util.clamp(math.floor(p.x), 0, ctx.w - 1)
        local cy = math.floor(p.y + 0.5)
        if p.grounded and MoveController.isStandable(cx, cy) and MoveController.isPassable(cx, cy - 1) then
            return true
        end
        MoveController.settleGrounded(aliveFn, 0.5)
        p = Core.ReadPos()
        cx = DF.Util.clamp(math.floor(p.x), 0, ctx.w - 1)
        cy = math.floor(p.y + 0.5)
        if p.grounded and MoveController.isStandable(cx, cy) then
            return true
        end
        -- Try stepping 1 tile left or right onto a standable neighbor
        for _, dx in ipairs({ -1, 1 }) do
            local nx = cx + dx
            if nx >= 0 and nx < ctx.w and MoveController.isStandable(nx, cy) and MoveController.isPassable(nx, cy - 1) then
                return MoveController.manualJumpTo(nx, cy, aliveFn, 1.0)
            end
        end
        -- Last resort if genuinely trapped in void/pit: respawn to Main Door
        return MoveController.respawnToDoor(ctx, aliveFn)
    end
end

-- Module 11: Intelligent Reach-Aware Batch Task Planner (1 2 3   1 2 3 / 1 2   1 2)
do
    local BatchPlanner = {}
    DF.BatchPlanner = BatchPlanner

    local MAX_BATCH_SIZE = 6

    local function buildActionItem(ctx, x, y, st, spec)
        local ST = DF.ENUMS.TILE_STATUS
        if st == ST.NEED_BREAK_FG or st == ST.NEED_REPLACE then
            return { x = x, y = y, action = "break", layer = 1, status = st, role = spec.role }
        elseif st == ST.NEED_BREAK_BG then
            return { x = x, y = y, action = "break", layer = 2, status = st, role = spec.role }
        elseif st == ST.NEED_PLACE then
            return { x = x, y = y, action = "place", layer = 1, desiredId = spec.desiredFg, status = st, role = spec.role }
        end
        return nil
    end

    -- Collect all safe, unreserved, non-immutable actionable tiles reachable from a given stand position (standX, standFloorY)
    function BatchPlanner.collectBatchAtStand(ctx, standX, standFloorY, travelDir)
        local ST = DF.ENUMS.TILE_STATUS
        local ROLE = DF.ENUMS.TILE_ROLE
        local fmt = ctx.format
        local virtualPos = {
            x = standX + 0.5,
            y = standFloorY,
            tx = standX,
            ty = standFloorY - 1,
            grounded = true,
        }

        local range = math.floor(math.min(2.35, (Core.GetActionRange and Core.GetActionRange("break")) or 2.35))
        local minX = DF.Util.clamp(standX - range, 0, ctx.w - 1)
        local maxX = DF.Util.clamp(standX + range, 0, ctx.w - 1)
        local minY = DF.Util.clamp(standFloorY - 1 - range, fmt.topY, fmt.maxWorkY)
        local maxY = DF.Util.clamp(standFloorY - 1 + range, fmt.topY, fmt.maxWorkY)
        local bagan1Done = DF.DiffAnalyzer.isBagan1Complete(ctx)
        if not bagan1Done then
            minY = math.max(minY, fmt.bagan1.startY)
        end

        local breakItems = {}
        local placeItems = {}
        local seen = {}

        local xStart = (travelDir >= 0) and minX or maxX
        local xEnd = (travelDir >= 0) and maxX or minX
        local xStep = (travelDir >= 0) and 1 or -1

        for y = minY, maxY do
            for x = xStart, xEnd, xStep do
                local idx = y * ctx.w + x
                if not seen[idx] then
                    local st, spec = DF.Blueprint.evaluateTile(ctx, x, y)
                    if DF.Blueprint.isActionableStatus(st) then
                        local item = buildActionItem(ctx, x, y, st, spec)
                        if item then
                            local kind = (item.action == "break") and "break" or "build"
                            if DF.MoveController.safeReachDist(x, y, virtualPos, kind)
                                and Core.IsInActionReach(x, y, kind, virtualPos) then
                                local okRes = DF.TaskManager.canReserve(ctx, x, y, item.action)
                                if okRes then
                                    if item.action == "break" then
                                        -- Do not break the tile we are standing directly on unless it's a hazard
                                        local isStandingFoot = (x == standX and y == standFloorY and item.layer == 1)
                                        local fgInfo = Core.GetItemInfo(Core.GetFG(x, y))
                                        if not isStandingFoot or DF.MoveController.isHazard(fgInfo) then
                                            seen[idx] = true
                                            item.priority = DF.MoveController.isHazard(fgInfo) and 1
                                                or (item.layer == 1 and 2 or 3)
                                            breakItems[#breakItems + 1] = item
                                        end
                                    elseif item.action == "place" then
                                        local pInfo = Core.GetItemInfo(item.desiredId)
                                        if not Core.CanPlaceBodyOk or Core.CanPlaceBodyOk(x, y, pInfo, virtualPos) then
                                            local allowMat = (spec.role ~= ROLE.PLATFORM) or (Core.CountItem(item.desiredId) > 0)
                                            if allowMat then
                                                seen[idx] = true
                                                item.priority = (spec.role == ROLE.PLATFORM) and 1 or 2
                                                placeItems[#placeItems + 1] = item
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end

        -- Prioritize cohesive break batch first (clears space before placing), then place batch
        local chosen = (#breakItems > 0) and breakItems or placeItems
        table.sort(chosen, function(a, b)
            if a.priority ~= b.priority then return a.priority < b.priority end
            if a.y ~= b.y then return a.y < b.y end
            if travelDir >= 0 then return a.x < b.x else return a.x > b.x end
        end)

        local trimmed = {}
        for i = 1, math.min(#chosen, MAX_BATCH_SIZE) do
            trimmed[i] = chosen[i]
        end
        return trimmed
    end

    -- Score candidate stand tiles along a floor row to produce optimal 1 2 3   1 2 3 / 1 2   1 2 jumps
    function BatchPlanner.findBestClusterOnFloor(ctx, standFloorY, curX, travelDir)
        local fmt = ctx.format
        local bandMinY = math.max(fmt.topY, standFloorY - 3)
        local bandMaxY = math.min(fmt.maxWorkY, standFloorY + 1)
        if not DF.DiffAnalyzer.bandHasWork(ctx, bandMinY, bandMaxY) then
            return nil
        end

        local best = nil
        local bestScore = -1e9

        -- Scan actionable X coordinates in this band to generate candidate stand tiles (no O(W^2) waste)
        local candStandX = {}
        local range = math.floor(math.min(2.35, (Core.GetActionRange and Core.GetActionRange("break")) or 2.35))
        for y = bandMinY, bandMaxY do
            if (ctx.diff.rowWorkCount[y] or 0) > 0 then
                for x = 0, ctx.w - 1 do
                    if ctx.diff.workMap[y * ctx.w + x] then
                        for sx = math.max(0, x - range), math.min(ctx.w - 1, x + range) do
                            candStandX[sx] = true
                        end
                    end
                end
            end
        end

        for sx, _ in pairs(candStandX) do
            if DF.MoveController.isStandable(sx, standFloorY) and DF.MoveController.isPassable(sx, standFloorY - 1) then
                local items = BatchPlanner.collectBatchAtStand(ctx, sx, standFloorY, travelDir)
                if #items > 0 then
                    local distX = math.abs(sx - curX)
                    -- Endpoint priority bonus (x=0,1 and x=w-2,w-1 prioritized cleanly before interior)
                    local hasEndpointItem = false
                    for _, it in ipairs(items) do
                        if fmt.isEndpointX and fmt.isEndpointX(it.x) then hasEndpointItem = true; break end
                    end
                    local endpointBonus = hasEndpointItem and 9.0 or 0.0
                    -- Strong bonus for staying in current serpentine travelDir (zero ping-pong!)
                    local wrongDir = (travelDir > 0 and sx < curX - 1) or (travelDir < 0 and sx > curX + 1)
                    local dirPenalty = wrongDir and 14.0 or 0.0
                    -- Reward larger cohesive batches (1 2 3), endpoint priority, and lower travel distance
                    local score = (#items * 6.0) + endpointBonus - (distX * 0.85) - dirPenalty
                    if score > bestScore then
                        bestScore = score
                        best = {
                            standX = sx,
                            standFloorY = standFloorY,
                            items = items,
                            score = score,
                            travelDir = wrongDir and -travelDir or travelDir,
                        }
                    end
                end
            end
        end

        return best
    end

    -- Strict Two-Section Row Selector: completes BAGAN 1 (Lower Area) 100% before unlocking BAGAN 2 (Upper Area, Bottom-Up)
    function BatchPlanner.selectNextFloorRow(ctx, curFloorY)
        local fmt = ctx.format
        local bagan1Done = DF.DiffAnalyzer.isBagan1Complete(ctx)
        local candidates = {}

        if not bagan1Done then
            -- BAGAN 1 ONLY (strictly blocks Bagan 2 placement until Bagan 1 completes!)
            for _, fy in ipairs(fmt.floorRows) do
                if fy >= fmt.bagan1.startY and fy <= fmt.bagan1.endY and DF.DiffAnalyzer.bandHasWork(ctx, math.max(fmt.bagan1.startY, fy - 2), fy) then
                    candidates[#candidates + 1] = fy
                end
            end
            if fmt.maxWorkY + 1 < ctx.h and DF.DiffAnalyzer.bandHasWork(ctx, math.max(fmt.bagan1.startY, fmt.maxWorkY - 2), fmt.maxWorkY) then
                candidates[#candidates + 1] = fmt.maxWorkY + 1
            end
        else
            -- BAGAN 2 UNLOCKED: bottom-up from lower part of Bagan 2 (doorY - 1) upward to topY
            for _, fy in ipairs(fmt.floorRows) do
                if fy <= fmt.bagan2.endY + 1 and DF.DiffAnalyzer.bandHasWork(ctx, math.max(fmt.topY, fy - 2), math.min(fmt.bagan2.endY, fy)) then
                    candidates[#candidates + 1] = fy
                end
            end
        end

        if #candidates == 0 then return nil end

        local bestRow = nil
        local bestCost = 1e9
        for _, fy in ipairs(candidates) do
            local cost
            if not bagan1Done then
                cost = (fy >= curFloorY) and (fy - curFloorY) or (200 + (curFloorY - fy))
            else
                -- Bottom-up in Bagan 2 (prefer starting at highest Y / lowest part of Bagan 2)
                cost = (fy <= curFloorY) and (curFloorY - fy) or (150 + (fy - curFloorY))
            end
            if cost < bestCost then
                bestCost = cost
                bestRow = fy
            end
        end
        return bestRow
    end

    -- Safe Tunnel Blocker: ONLY targets non-immutable, non-bedrock, non-platform tiles blocking access to remaining work
    function BatchPlanner.findSafeTunnelCluster(ctx, curTx, curFloorY)
        local nav = DF.MoveController.computePlatformerReach(ctx, curTx, curFloorY)
        local fmt = ctx.format
        local best = nil
        local bestDist = 1e9

        for idx, _ in pairs(ctx.diff.workMap) do
            local tx, ty = DF.Util.fromIdx(ctx.w, idx)
            -- Search reachable stand tiles adjacent to a non-immutable solid blocker near (tx, ty)
            for sy = math.max(fmt.topY, ty - 2), math.min(fmt.maxWorkY + 1, ty + 2) do
                for sx = math.max(0, tx - 3), math.min(ctx.w - 1, tx + 3) do
                    local d = nav.dist[sy * ctx.w + sx]
                    if d and d < bestDist then
                        -- Check if standing at (sx, sy) directly reaches actionable work
                        local direct = BatchPlanner.collectBatchAtStand(ctx, sx, sy, ctx.travelDir or 1)
                        if #direct > 0 then
                            bestDist = d
                            best = { standX = sx, standFloorY = sy, items = direct, nav = nav }
                        else
                            -- Check for a safe breakable tunnel blocker between (sx, sy-1) and (tx, ty)
                            local stepX = (tx > sx) and 1 or ((tx < sx) and -1 or 0)
                            local stepY = (ty > sy - 1) and 1 or ((ty < sy - 1) and -1 or 0)
                            local bx = DF.Util.clamp(sx + stepX, 0, ctx.w - 1)
                            local by = DF.Util.clamp((sy - 1) + stepY, fmt.topY, fmt.maxWorkY)
                            local fg = Core.GetFG(bx, by)
                            if fg ~= 0
                                and not DF.Safety.isImmutableTile(ctx, bx, by, false)
                                and not DF.WorldScanner.isPlatformItem(fg, ctx.ids)
                                and Core.IsInActionReach(bx, by, "break", { x = sx + 0.5, y = sy, grounded = true }) then
                                bestDist = d + 10
                                best = {
                                    standX = sx,
                                    standFloorY = sy,
                                    items = { { x = bx, y = by, action = "break", layer = 1, isTunnel = true } },
                                    nav = nav,
                                }
                            end
                        end
                    end
                end
            end
        end
        return best
    end

    -- Master Batch Planner Entry Point
    function BatchPlanner.planNextBatch(ctx)
        local pos = Core.ReadPos()
        local curTx = DF.Util.clamp(math.floor(pos.x), 0, ctx.w - 1)
        local curFloorY = DF.Util.clamp(math.floor(pos.y + 0.5), 2, ctx.h - 1)
        local travelDir = ctx.travelDir or ((curTx <= ctx.w * 0.5) and 1 or -1)

        -- Priority 1: Zero-travel in-reach batch from current stand position
        if pos.grounded then
            local inReach = BatchPlanner.collectBatchAtStand(ctx, curTx, curFloorY, travelDir)
            if #inReach > 0 then
                return {
                    standX = curTx,
                    standFloorY = curFloorY,
                    items = inReach,
                    inPlace = true,
                    travelDir = travelDir,
                }
            end
        end

        -- Priority 2: Best cluster on current floor row (finishes corridor in current direction)
        local sameFloor = BatchPlanner.findBestClusterOnFloor(ctx, curFloorY, curTx, travelDir)
        if sameFloor then
            ctx.travelDir = sameFloor.travelDir
            return sameFloor
        end

        -- Priority 3: Next corridor row with lowest traversal cost (langsung balik arah ke dalam dari sisi ujung!)
        local nextFloor = BatchPlanner.selectNextFloorRow(ctx, curFloorY)
        if nextFloor then
            local turnDir = (curTx <= ctx.w * 0.5) and 1 or -1
            local cluster = BatchPlanner.findBestClusterOnFloor(ctx, nextFloor, curTx, turnDir)
            if cluster then
                ctx.travelDir = cluster.travelDir or turnDir
                return cluster
            end
        end

        -- Priority 4: Global platformer-reachable cluster or safe non-immutable tunnel fallback
        return BatchPlanner.findSafeTunnelCluster(ctx, curTx, curFloorY)
    end
end

-- Module 12: Session Orchestrator & Public API
do
    local Session = {}
    DF.Session = Session

    function Session.createContext(gt)
        local snap = DF.WorldScanner.scanFull(gt)
        if not snap then return nil end
        local ids = DF.WorldScanner.resolveItemIds(snap)
        local safety = DF.Safety.buildFromSnapshot(snap)
        local fmt = DF.FormatDetector.detect(snap, safety, ids)
        local ctx = {
            worldName = snap.worldName,
            w = snap.w,
            h = snap.h,
            snapshot = snap,
            ids = ids,
            safety = safety,
            format = fmt,
            tasks = DF.TaskManager.create(),
            diff = nil,
            platformStatus = DF.ENUMS.PLATFORM_STATUS.NOT_REQUIRED,
            platformStats = nil,
            -- Deterministic Door-Based Starting Direction
            travelDir = (fmt.doorDirection and fmt.doorDirection.startingSide == "RIGHT") and -1 or 1,
            activeSection = "BAGAN_1",
            bagan1Status = "RUNNING",
            bagan2Status = "BLOCKED_BY_BAGAN_1",
            lastCollectAt = 0,
            isImmutableTile = function(x, y, checkBg)
                return DF.Safety.isImmutableTile(nil, x, y, checkBg)
            end,
        }
        ctx.isImmutableTile = function(x, y, checkBg)
            return DF.Safety.isImmutableTile(ctx, x, y, checkBg)
        end
        DF.DiffAnalyzer.buildInitial(ctx)
        DF.Platform.evaluate(ctx)

        DirtFarm.State.bedrockConfidence = safety.bedrockConfidence
        DirtFarm.State.bedrockTopY = safety.bedrockTopY
        DirtFarm.State.formatSummary = fmt.summary
        return ctx
    end

    function Session.runWorld(ctx, aliveFn)
        local CONF = DF.ENUMS.BEDROCK_CONFIDENCE
        -- Safety guard: if world tiles have not loaded properly, wait and rescan before touching anything
        if ctx.snapshot.nonZeroCount < 10 then
            setDfStatus("Menunggu tile world selesai dimuat...")
            DF.Util.wait(0.8)
            return "RETRY_LOAD"
        end
        if ctx.safety.bedrockConfidence == CONF.LOW then
            setDfStatus(string.format("[%s] Bedrock tidak terdeteksi penuh -> area aman dibatasi y<=%d", ctx.worldName, ctx.format.maxWorkY))
        end

        local idleCycles = 0
        while aliveFn() do
            if Misc and Misc.State and Misc.State.seems and evaluateSeems and evaluateSeems() then
                Core.ClearManualInput()
                setDfStatus("Paused (Seems)")
                DF.Util.wait(0.5)
                break
            end

            -- Detect live world change / resize -> full re-scan & bedrock re-validation
            local gt = H and H.gt
            if not gt or (cleanWorldName and cleanWorldName(gt.name or "") ~= ctx.worldName) or gt.w ~= ctx.w or gt.h ~= ctx.h then
                return "WORLD_CHANGED"
            end

            -- Periodic consistency scan every 25 batches
            if ctx.diff.batchesSinceReconcile >= 25 then
                DF.DiffAnalyzer.reconcileAll(ctx)
            end

            -- Check completion (confirm with full consistency scan before declaring done)
            if ctx.diff.remainingCount <= 0 then
                local remCheck = DF.DiffAnalyzer.reconcileAll(ctx)
                if remCheck <= 0 then
                    DirtFarm.State.progress = 100
                    return "WORLD_COMPLETE"
                end
            end

            -- Recover ONLY if genuinely unsafe / stuck off-floor
            DF.MoveController.recoverOnlyIfUnsafe(ctx, aliveFn)

            -- Plan next optimal batch
            local plan = DF.BatchPlanner.planNextBatch(ctx)
            if not plan or not plan.items or #plan.items == 0 then
                idleCycles = idleCycles + 1
                if idleCycles >= 2 then
                    local remCheck = DF.DiffAnalyzer.reconcileAll(ctx)
                    if remCheck <= 0 then
                        DirtFarm.State.progress = 100
                        return "WORLD_COMPLETE"
                    end
                    if idleCycles >= 4 then
                        -- Remaining tiles are permanently blocked/unreachable/no-material
                        return "WORLD_COMPLETE"
                    end
                end
                DF.Util.wait(0.25)
            else
                idleCycles = 0

                -- Check material requirements BEFORE walking to place
                local mat = DF.Inventory.checkMaterialForBatch(ctx, plan.items)
                if not mat.okDirt then
                    local farmed = DF.Inventory.farmDirtIfLow(ctx, aliveFn, math.max(16, mat.needDirt))
                    if not farmed and DF.Inventory.countDirt(ctx) <= 0 then
                        setDfStatus(string.format("[%s] Dirt habis & tidak ada Dirt Seed!", ctx.worldName))
                        DF.Util.wait(0.8)
                    end
                end

                local pct = DF.DiffAnalyzer.syncProgress(ctx)
                local secTag = (ctx.activeSection == "BAGAN_1") and "B1" or "B2"
                setDfStatus(string.format(
                    "[%s] %s %d%% (W:%d%%) | Rem:%d | Plat:%s | Batch:%d",
                    ctx.worldName, secTag, pct, DirtFarm.State.estimatedWorkProgressPct or pct,
                    ctx.diff.remainingCount, ctx.platformStatus, #plan.items
                ))

                -- Move via single unified Movement Controller
                local arrived = true
                if not plan.inPlace then
                    if plan.nav then
                        arrived = DF.MoveController.walkNavPath(ctx, plan.nav, plan.standX, plan.standFloorY, aliveFn)
                    else
                        arrived = DF.MoveController.moveToStand(ctx, plan.standX, plan.standFloorY, aliveFn)
                    end
                end

                if arrived and aliveFn() then
                    DF.Executor.executeBatch(ctx, plan.items, aliveFn)
                    -- Need/area-based collect after batch + auto-drop seed overflow
                    DF.Inventory.collectSmart(ctx, aliveFn, { minInterval = 0.60 })
                    DF.Inventory.autoDropStash(ctx, aliveFn)
                else
                    -- Move failed: back off affected tiles mildly instead of spinning infinitely
                    for _, it in ipairs(plan.items) do
                        DF.TaskManager.recordFailure(ctx, it.x, it.y, "MOVE_FAILED", false)
                    end
                    DF.Util.wait(0.15)
                end
            end

            DF.Util.wait(0.02)
        end

        return "STOPPED"
    end
end

-- Backward-compatible DirtFarm._impl exports (used by ClearWorld, Pabrik, and test harnesses)
do
    local impl = DirtFarm._impl
    impl.ENUMS = DF.ENUMS
    impl.Safety = DF.Safety
    impl.WorldScanner = DF.WorldScanner
    impl.FormatDetector = DF.FormatDetector
    impl.Blueprint = DF.Blueprint
    impl.Platform = DF.Platform
    impl.TaskManager = DF.TaskManager
    impl.DiffAnalyzer = DF.DiffAnalyzer
    impl.Inventory = DF.Inventory
    impl.Executor = DF.Executor
    impl.MoveController = DF.MoveController
    impl.BatchPlanner = DF.BatchPlanner
    impl.Session = DF.Session

    -- Centralized immutable tile checker exposed directly
    function impl.isImmutableTile(x, y, ctx, checkBg)
        return DF.Safety.isImmutableTile(ctx, x, y, checkBg)
    end

    -- Shims required by 3_SC_CLEAR_WORLD.lua & 2_SC_PABRIK_LOGIC.lua
    function impl.dfIsHazard(info)
        return DF.MoveController.isHazard(info)
    end

    function impl.dfIsStandable(tx, ty)
        return DF.MoveController.isStandable(tx, ty)
    end

    function impl.dfSettleGrounded(aliveFn, maxSec)
        return DF.MoveController.settleGrounded(aliveFn, maxSec)
    end

    function impl.dfDropIntoCol(colX, targetFloorY, aliveFn, maxSec)
        return DF.MoveController.dropIntoCol(colX, targetFloorY, aliveFn, maxSec)
    end

    function impl.dfStepWalkToX(goalX, floorY, maxSec, aliveFn, bp)
        return DF.MoveController.stepWalkToX(goalX, floorY, maxSec, aliveFn, bp and bp._ctx or nil)
    end

    function impl.dfQuickCollectNear(aliveFn, filterId, force)
