            minInterval = 0,
        })
    end
end

function DirtFarm.Stop(keepSaved)
    if Core and Core.ClearManualInput then Core.ClearManualInput() end
    if H then H.dfSpeedForceUntil = 0 end
    DirtFarm.State.running = false
    DirtFarm.State.switchingWorld = false
    DirtFarm.State.sessionToken = (DirtFarm.State.sessionToken or 0) + 1
    if DirtFarm._activeCtx then
        DF.TaskManager.clearAll(DirtFarm._activeCtx)
        DirtFarm._activeCtx = nil
    end
    if DirtFarm.State.thread then
        if task and task.cancel then pcall(task.cancel, DirtFarm.State.thread) end
        DirtFarm.State.thread = nil
    end
    if not keepSaved then
        local env = (type(getEnv) == "function") and getEnv() or _G
        local ed = env.__SYT_ENV_DATA
        if type(ed) == "table" and ed.rotSession and ed.rotSession.mode == "DirtFarm" then
            ed.rotSession = nil
        end
        if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("DfRunToggle", false) end
    end
    if type(DirtFarm.State.status) ~= "string" or string.sub(DirtFarm.State.status, 1, 9) ~= "DF Error:" then
        setDfStatus("Stopped")
    end
    if UIHooks and UIHooks.updateButtons then UIHooks.updateButtons() end
    if SYT_Logic and SYT_Logic.DiscordHook and SYT_Logic.DiscordHook.NotifyStateChanged then pcall(SYT_Logic.DiscordHook.NotifyStateChanged) end
    return false
end

function DirtFarm.Start()
    if DirtFarm.State.running then return true end
    if type(guardExclusiveStart) == "function" and not guardExclusiveStart("DirtFarm") then
        if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("DfRunToggle", false) end
        return false
    end
    if Core and Core.EnsureInit then Core.EnsureInit() end
    if Core and Core.EnsureManualInputHook then Core.EnsureManualInputHook() end
    if Core and Core.SyncOneHitHook then Core.SyncOneHitHook() end
    if SystemModule and SystemModule.State then SystemModule.State.frozenByJoin = false end

    local S = DirtFarm.State
    S.running = true
    S.switchingWorld = false
    S.progress = 0
    S.sessionToken = (S.sessionToken or 0) + 1
    local tok = S.sessionToken
    local function alive()
        return S.running and S.sessionToken == tok
    end

    if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("DfRunToggle", true) end
    if UIHooks and UIHooks.updateButtons then UIHooks.updateButtons() end
    setDfStatus("Initializing Dirt Farm Intelligence...")

    S.thread = task.spawn(function()
        local dfErr = nil
        local okRun, resErr = xpcall(function()
            while alive() do
                local gt = H and H.gt
                if not gt or (gt.name or "") == "" then
                    setDfStatus("Menunggu masuk world...")
                    DF.Util.wait(0.5)
                else
                    local curW = cleanWorldName and cleanWorldName(gt.name) or tostring(gt.name)
                    local rotQ = S.rotationWorlds or {}
                    local readyWorld = true

                    -- Multi-world rotation queue synchronization
                    if #rotQ > 0 then
                        local inQ = false
                        for _, wName in ipairs(rotQ) do
                            if wName == curW then inQ = true; break end
                        end
                        if not inQ then
                            local targetW = rotQ[1]
                            if targetW and targetW ~= "" and targetW ~= curW then
                                readyWorld = false
                                local env = (type(getEnv) == "function") and getEnv() or _G
                                local ed = env.__SYT_ENV_DATA or {}
                                env.__SYT_ENV_DATA = ed
                                ed.rotSession = {
                                    mode = "DirtFarm",
                                    targetWorld = targetW,
                                    worlds = DirtFarm._syncEnvQueue(rotQ),
                                    active = true,
                                    updatedAt = DF.Util.now(),
                                }
                                S.switchingWorld = true
                                setDfStatus("Masuk antrian world: " .. targetW)
                                local okWarp = Packets and Packets.EnterWorldDoor and Packets.EnterWorldDoor(targetW, alive)
                                S.switchingWorld = false
                                if not alive() then break end
                                if not okWarp then
                                    setDfStatus("Gagal masuk " .. targetW .. ", retry...")
                                    DF.Util.wait(1.6)
                                end
                            end
                        end
                    end

                    if readyWorld and alive() then
                        local ctx = DF.Session.createContext(gt)
                        DirtFarm._activeCtx = ctx
                        if ctx then
                            local outcome = DF.Session.runWorld(ctx, alive)
                            if outcome == "WORLD_COMPLETE" then
                                local nextW = nil
                                if #rotQ > 0 then
                                    for i = #rotQ, 1, -1 do
                                        if rotQ[i] == curW then table.remove(rotQ, i) end
                                    end
                                    S.rotationText = table.concat(rotQ, ", ")
                                    DirtFarm._syncEnvQueue(rotQ)
                                    if UIHooks and UIHooks.refreshDfList then UIHooks.refreshDfList() end
                                    nextW = rotQ[1]
                                end
                                if nextW and nextW ~= curW then
                                    S.switchingWorld = true
                                    setDfStatus("World DF selesai -> Next: " .. nextW)
                                    Packets.EnterWorldDoor(nextW, alive)
                                    S.switchingWorld = false
                                else
                                    setDfStatus("Dirt Farm Selesai: " .. curW .. " (100%)")
                                    if emitNotify then
                                        emitNotify("Dirt Farm", "World " .. curW .. " selesai 100%!")
                                    end
                                    S.running = false
                                    break
                                end
                            elseif outcome == "STOPPED" then
                                break
                            end
                        else
                            DF.Util.wait(0.4)
                        end
                    end
                end
                DF.Util.wait(0.05)
            end
        end, function(err)
            dfErr = tostring(err or "unknown error")
            return debug.traceback(dfErr, 2)
        end)

        if not okRun and dfErr then
            local raw = tostring(dfErr):match("([^\r\n]+)") or "Runtime error"
            setDfStatus("DF Error: " .. raw:sub(1, 56))
            if warn then warn("[SYT DirtFarm Error]: " .. tostring(resErr)) end
        end

        if Core and Core.ClearManualInput then Core.ClearManualInput() end
        if H then H.dfSpeedForceUntil = 0 end
        S.switchingWorld = false
        if DirtFarm._activeCtx then
            DF.TaskManager.clearAll(DirtFarm._activeCtx)
            DirtFarm._activeCtx = nil
        end
        if S.sessionToken == tok then
            S.running = false
            S.thread = nil
            if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("DfRunToggle", false) end
            if UIHooks and UIHooks.updateButtons then UIHooks.updateButtons() end
        end
    end)

    return true
end

function DirtFarm.GetProgressReport()
    local S = DirtFarm.State
    local ctx = DirtFarm._activeCtx
    return {
        world = ctx and ctx.worldName or "",
        width = ctx and ctx.w or 0,
        height = ctx and ctx.h or 0,
        activeSection = S.activeSection or "BAGAN_1",
        bagan1ProgressPct = S.bagan1ProgressPct or 0,
        bagan2ProgressPct = S.bagan2ProgressPct or 0,
        tileProgressPct = S.tileProgressPct or S.progress or 0,
        estimatedWorkProgressPct = S.estimatedWorkProgressPct or S.progress or 0,
        completedTasks = S.completedTasks or 0,
        remainingTasks = S.remainingTasks or 0,
        totalTasks = S.totalTasks or 0,
        unknownHitUnits = S.unknownHitUnits or 0,
        lavaRecommendations = S.lavaRecommendations or 0,
        platformStatus = S.platformStatus or "PLATFORM_NOT_REQUIRED",
        bedrockConfidence = S.bedrockConfidence or "UNKNOWN",
        cv = S.cvMetric,
        status = S.running and "RUNNING" or "IDLE",
    }
end

function DirtFarm.GetAsciiTraversal()
    local ctx = DirtFarm._activeCtx
    if not ctx or not ctx.format then return "No active DirtFarm world context." end
    local fmt = ctx.format
    local dd = fmt.doorDirection
    local lines = {
        string.format("WORLD %dx%d | Door=(%d,%d) | LDist=%d RDist=%d -> START=%s",
            ctx.w, ctx.h, fmt.doorX, fmt.doorY, dd.leftDistance, dd.rightDistance, dd.startingSide),
        string.format("BAGAN 1 (Lower y=%d..%d, %d%%) | BAGAN 2 (Upper y=%d..%d, %d%%, %s)",
            fmt.bagan1.startY, fmt.bagan1.endY, DirtFarm.State.bagan1ProgressPct or 0,
            fmt.bagan2.startY, fmt.bagan2.endY, DirtFarm.State.bagan2ProgressPct or 0,
            ctx.bagan2Status or "BLOCKED_BY_BAGAN_1"),
    }
    return table.concat(lines, "\n")
end

function DirtFarm.Toggle()
    if DirtFarm.State.running then
        return DirtFarm.Stop()
    end
    return DirtFarm.Start()
end
end

-- [3] INTELLIGENT CLEAR WORLD SYSTEM (Refactored V3)
do
ClearWorld = {
    State = {
        running = false,
        sessionToken = 0,
        thread = nil,
        status = "Idle",
        worldInput = "",
        worldList = {},
        worldIdx = 1,
        switchingWorld = false,
        halfWorldMode = false,
        noCollect = false,
        progress = 0,
        _worldLockedOrEmpty = false,
        phase = "IDLE",
        moveState = "IDLE",
        bedrockConfidence = "UNKNOWN",
        dashboard = {
            world = {},
            progress = {},
            character = {},
            currentTask = {},
            logs = {},
        },
    },
    _sys = {},
    _activeCtx = nil,
}
SYT_Logic.ClearWorld = ClearWorld

local CW = ClearWorld._sys

local function setCwStatus(msg)
    ClearWorld.State.status = msg
    if UI then pcall(UI.SetValue, UI, "CwStatusDisplay", msg) end
    if UIHooks and UIHooks.updateButtons then UIHooks.updateButtons() end
end

function ClearWorld._syncEnvQueue(worlds)
    local env = (type(getEnv) == "function") and getEnv() or _G
    local ed = env.__SYT_ENV_DATA or {}
    env.__SYT_ENV_DATA = ed
    local copy = {}
    for i, w in ipairs(worlds or ClearWorld.State.worldList or {}) do
        copy[i] = w
    end
    ed.cwQueue = copy
    return copy
end

function ClearWorld.AddWorld(raw)
    local w = (type(sanitizeWorldSpec) == "function") and sanitizeWorldSpec(raw, false)
        or string.upper((tostring(raw or ""):gsub("^%s*(.-)%s*$", "%1")))
    if w == "" then return false, ClearWorld.State.worldList end
    for _, existing in ipairs(ClearWorld.State.worldList) do
        if existing == w then return false, ClearWorld.State.worldList end
    end
    table.insert(ClearWorld.State.worldList, w)
    ClearWorld._syncEnvQueue(ClearWorld.State.worldList)
    if UIHooks and UIHooks.refreshCwList then UIHooks.refreshCwList() end
    return true, ClearWorld.State.worldList
end

function ClearWorld.RemoveWorldAt(idx)
    if idx >= 1 and idx <= #ClearWorld.State.worldList then
        table.remove(ClearWorld.State.worldList, idx)
        ClearWorld._syncEnvQueue(ClearWorld.State.worldList)
        if UIHooks and UIHooks.refreshCwList then UIHooks.refreshCwList() end
    end
end

-- Module 0: Shared Enums & Low-Level Utilities
do
    CW.ENUMS = {
        TARGET_STATUS = {
            DISCOVERED = "DISCOVERED",
            VALIDATING = "VALIDATING",
            READY = "READY",
            RESERVED = "RESERVED",
            EXECUTING = "EXECUTING",
            VERIFYING = "VERIFYING",
            COMPLETED = "COMPLETED",
            BLOCKED = "BLOCKED",
            RETRY_PENDING = "RETRY_PENDING",
            SKIPPED = "SKIPPED",
            FAILED = "FAILED",
        },
        SKIP_REASON = {
            TEMPORARY_BLOCKED = "TEMPORARY_BLOCKED",
            UNREACHABLE = "UNREACHABLE",
            PROTECTED = "PROTECTED",
            NOT_EDITABLE = "NOT_EDITABLE",
            FAILED = "FAILED",
            COMPLETED = "COMPLETED",
        },
        MOVE_STATE = {
            IDLE = "IDLE",
            PLANNING = "PLANNING",
            MOVING = "MOVING",
            JUMPING = "JUMPING",
            DESCENDING = "DESCENDING",
            VERIFYING_POSITION = "VERIFYING_POSITION",
            BLOCKED = "BLOCKED",
            RECOVERING = "RECOVERING",
        },
        PHASE = {
            IDLE = "IDLE",
            HYDRATING = "HYDRATING",
            SCANNING = "SCANNING",
            PHASE_1A_HILL = "PHASE_1A_HILL",
            PHASE_1B_SURFACE = "PHASE_1B_SURFACE",
            PHASE_2_UNDERGROUND = "PHASE_2_UNDERGROUND",
            PHASE_3_LEFTOVER = "PHASE_3_LEFTOVER",
            RECONCILING = "RECONCILING",
            COMPLETE = "COMPLETE",
        },
        BEDROCK_CONFIDENCE = {
            HIGH = "HIGH",
            MEDIUM = "MEDIUM",
            LOW = "LOW",
        },
    }

    CW.Util = {}

    function CW.Util.now()
        return os.clock()
    end

    function CW.Util.wait(sec)
        if task and type(task.wait) == "function" then
            return task.wait(sec)
        end
        return sec
    end

    function CW.Util.clamp(v, lo, hi)
        if v < lo then return lo end
        if v > hi then return hi end
        return v
    end

    function CW.Util.cleanWorld(name)
        if type(cleanWorldName) == "function" then return cleanWorldName(name) end
        return string.upper((tostring(name or ""):gsub("^%s*(.-)%s*$", "%1")))
    end

    function CW.Util.coordIdx(w, x, y)
        return y * w + x
    end

    function CW.Util.targetKey(x, y, layer)
        return tostring(x) .. "," .. tostring(y) .. ":" .. tostring(layer or 1)
    end

    function CW.Util.coolAntiKick()
        if H and H.fwLastBlockAt and (CW.Util.now() - H.fwLastBlockAt) < 0.45 then
            CW.Util.wait(0.32)
            return true
        end
        return false
    end

    function CW.Util.forceWalkSpeed(sec)
        if H then H.dfSpeedForceUntil = CW.Util.now() + (sec or 1.0) end
    end

    function CW.Util.getEnvTable()
        if type(getEnv) == "function" then
            local ok, e = pcall(getEnv)
            if ok and type(e) == "table" then return e end
        end
        return _G
    end
end

-- Module 1: Dashboard & Structured Event Logger
do
    local Logger = {}
    CW.Logger = Logger

    local MAX_LOGS = 120

    function Logger.init(ctx)
        ctx.logs = ctx.logs or {}
        ctx.phase = CW.ENUMS.PHASE.IDLE
        ctx.moveState = CW.ENUMS.MOVE_STATE.IDLE
        ctx.currentTask = { x = -1, y = -1, layer = 1, itemId = 0, status = "IDLE", retries = 0 }
    end

    function Logger.log(ctx, tag, msg)
        local line = string.format("[%s] %s", tostring(tag or "INFO"), tostring(msg or ""))
        if ctx and ctx.logs then
            ctx.logs[#ctx.logs + 1] = line
            if #ctx.logs > MAX_LOGS then
                table.remove(ctx.logs, 1)
            end
            ClearWorld.State.dashboard.logs = ctx.logs
        end
        return line
    end

    function Logger.setPhase(ctx, phaseName)
        if not ctx then return end
        ctx.phase = phaseName
        ClearWorld.State.phase = phaseName
        Logger.syncDashboard(ctx)
    end

    function Logger.setMoveState(ctx, mState, targetStr)
        if not ctx then return end
        ctx.moveState = mState
        ctx.moveTarget = targetStr or ctx.moveTarget or "-"
        ClearWorld.State.moveState = mState
        Logger.syncDashboard(ctx)
    end

    function Logger.setCurrentTask(ctx, tx, ty, layer, itemId, status, retries)
        if not ctx then return end
        ctx.currentTask = {
            x = tx or -1,
            y = ty or -1,
            layer = layer or 1,
            itemId = itemId or 0,
            status = status or "IDLE",
            retries = retries or 0,
        }
        Logger.syncDashboard(ctx)
    end

    function Logger.syncDashboard(ctx)
        if not ctx then return end
        local p = (Core and Core.ReadPos) and Core.ReadPos() or { x = 0, y = 0, tx = 0, ty = 0 }
        local prog = ctx.progress or {}
        ClearWorld.State.dashboard = {
            world = {
                currentWorld = ctx.worldName or "",
                queue = ClearWorld.State.worldList or {},
                width = ctx.w or 0,
                height = ctx.h or 0,
                phase = ctx.phase or CW.ENUMS.PHASE.IDLE,
                currentFloor = math.floor((p.y or 0) + 0.5),
                maxY = ctx.maxY or 0,
                halfWorldMode = ctx.halfWorldMode == true,
                noCollect = ctx.noCollect == true,
            },
            progress = {
                initialTarget = prog.initialTargets or 0,
                completed = prog.completedCount or 0,
                remaining = prog.remainingCount or 0,
                blocked = prog.blockedCount or 0,
                skipped = prog.skippedCount or 0,
                failed = prog.failedCount or 0,
                percentage = ClearWorld.State.progress or 0,
            },
            character = {
                x = p.tx or math.floor(p.x or 0),
                y = p.ty or math.floor(p.y or 0),
                floorY = math.floor((p.y or 0) + 0.5),
                moveState = ctx.moveState or CW.ENUMS.MOVE_STATE.IDLE,
                currentTarget = ctx.moveTarget or "-",
                actionReach = (Core and Core.GetActionRange) and Core.GetActionRange("break") or 2.35,
            },
            currentTask = ctx.currentTask or {},
            logs = ctx.logs or {},
        }
    end
end

-- Module 2: Centralized Immutable & Bedrock Protection Safety Manager
do
    local Safety = {}
    CW.Safety = Safety

    local BEDROCK_ID = 8
    local MAIN_DOOR_ID = 6
    local UNCERTAIN_BOTTOM_MARGIN = 6

    function Safety.isBedrockId(id)
        if type(id) ~= "number" or id == 0 then return false end
        if id == BEDROCK_ID then return true end
        local info = Core and Core.GetItemInfo and Core.GetItemInfo(id) or nil
        if not info then return false end
        local ln = string.lower(tostring(info.name or ""))
        if string.find(ln, "bedrock", 1, true) then return true end
        if type(info.hits) == "number" and info.hits < 0 and info.solid == true then return true end
        return false
    end

    function Safety.isImmutableId(id)
        if type(id) ~= "number" or id == 0 then return false end
        if id == BEDROCK_ID or id == MAIN_DOOR_ID then return true end
        if Safety.isBedrockId(id) then return true end
        if Core and Core.IsProtectedTile and Core.IsProtectedTile(id) then return true end
        local info = Core and Core.GetItemInfo and Core.GetItemInfo(id) or nil
        if not info then return true end
        local ln = string.lower(tostring(info.name or ""))
        if string.find(ln, "bedrock", 1, true) or string.find(ln, "main door", 1, true) then return true end
        if info.unbreakable == true then return true end
        if type(info.hits) == "number" and info.hits <= 0 then return true end
        if info.lock or info.area or info.door or info.entrance or info.vend or info.display or info.displayOne or info.worldKey or info.vip or info.combiner then
            return true
        end
        return false
    end

    function Safety.isHazardInfo(info)
        local godMode = SYT_Logic and SYT_Logic.Misc and SYT_Logic.Misc.State and SYT_Logic.Misc.State.godMode == true
        return info ~= nil and (info.deadly == true or info.hurts == true) and not godMode
    end

    function Safety.isHazardAt(tx, ty)
        local gt = H and H.gt
        if not gt or tx < 0 or tx >= gt.w or ty < 0 or ty >= gt.h then return false end
        local fid = Core.GetFG(tx, ty)
        if fid == 0 then return false end
        return Safety.isHazardInfo(Core.GetItemInfo(fid))
    end

    function Safety.detectBedrockBoundary(w, h)
        local CONF = CW.ENUMS.BEDROCK_CONFIDENCE
        local immutableSet = {}
        local rowBedrockRatio = {}
        local bedrockCoords = {}

        for y = 0, h - 1 do
            local bCnt = 0
            for x = 0, w - 1 do
                local fg = Core.GetFG(x, y)
                local bg = Core.GetBG(x, y)
                local idx = y * w + x
                if fg ~= 0 and Safety.isBedrockId(fg) then
                    bCnt = bCnt + 1
                    bedrockCoords[#bedrockCoords + 1] = { x = x, y = y }
                    immutableSet[idx] = "BEDROCK"
                elseif fg ~= 0 and Safety.isImmutableId(fg) then
                    immutableSet[idx] = "IMMUTABLE_FG"
                elseif bg ~= 0 and Safety.isImmutableId(bg) then
                    immutableSet[idx] = "IMMUTABLE_BG"
                end
            end
            rowBedrockRatio[y] = (w > 0) and (bCnt / w) or 0
        end

        local bandTopY = nil
        local strongRows = 0
        for y = h - 1, 2, -1 do
            local ratio = rowBedrockRatio[y] or 0
            if ratio >= 0.55 then
                bandTopY = y
                if ratio >= 0.65 then strongRows = strongRows + 1 end
            elseif bandTopY ~= nil then
                -- Pull boundary above jagged bedrock shelf right above main band
                if ratio >= 0.15 and (bandTopY - y) <= 2 then
                    bandTopY = y
                else
                    break
                end
            elseif y <= h - 3 and ratio >= 0.20 then
                bandTopY = y
            end
        end

        local confidence, safeMaxY, bedrockTopY
        if bandTopY ~= nil and strongRows >= 1 then
            confidence = CONF.HIGH
            bedrockTopY = bandTopY
            safeMaxY = math.max(2, bandTopY - 1)
        elseif bandTopY ~= nil then
            confidence = CONF.MEDIUM
            bedrockTopY = bandTopY
            safeMaxY = math.max(2, bandTopY - 1)
        else
            local highLower = nil
            for _, bc in ipairs(bedrockCoords) do
                if bc.y >= math.floor(h * 0.65) and (not highLower or bc.y < highLower) then
                    highLower = bc.y
                end
            end
            if highLower then
                confidence = CONF.MEDIUM
                bedrockTopY = highLower
                safeMaxY = math.max(2, highLower - 1)
            else
                confidence = CONF.LOW
                bedrockTopY = math.max(3, h - UNCERTAIN_BOTTOM_MARGIN)
                safeMaxY = math.max(2, bedrockTopY - 1)
            end
        end

        -- Permanently protect every tile at or below bedrockTopY
        for y = bedrockTopY, h - 1 do
            for x = 0, w - 1 do
                immutableSet[y * w + x] = immutableSet[y * w + x] or "BEDROCK_BOUNDARY"
            end
        end

        return {
            immutableSet = immutableSet,
            bedrockTopY = bedrockTopY,
            safeMaxY = safeMaxY,
            confidence = confidence,
            bedrockCount = #bedrockCoords,
        }
    end

    -- Centralized single validation gate for ALL scanners, planners, and break executors
    function Safety.isValidClearTarget(ctx, x, y, layer, opts)
        opts = opts or {}
        local gt = H and H.gt
        local w = (ctx and ctx.w) or (gt and gt.w) or 0
        local h = (ctx and ctx.h) or (gt and gt.h) or 0
        local maxY = (ctx and ctx.maxY) or (h - 1)
        layer = layer or 1

        if type(x) ~= "number" or type(y) ~= "number" or w <= 0 or h <= 0 then
            return false, "INVALID_COORD"
        end
        x, y = math.floor(x), math.floor(y)
        if x < 0 or x >= w or y < 0 or y > maxY or y >= h then
            return false, "OUT_OF_WORK_BOUNDS"
        end

        -- Check cached immutable set & bedrock boundary
        if ctx and ctx.safety then
            if y >= ctx.safety.bedrockTopY then
                return false, "BEDROCK_BOUNDARY"
            end
            local immRsn = ctx.safety.immutableSet[y * w + x]
            if immRsn then
                return false, immRsn
            end
        end

        -- Live re-check: NEVER break FG or BG on a Bedrock/Door/Protected coordinate
        local fgId = Core.GetFG(x, y)
        if fgId ~= 0 and Safety.isImmutableId(fgId) then
            if ctx and ctx.safety then
                ctx.safety.immutableSet[y * w + x] = Safety.isBedrockId(fgId) and "LIVE_BEDROCK" or "LIVE_IMMUTABLE_FG"
            end
            return false, Safety.isBedrockId(fgId) and "LIVE_BEDROCK" or "LIVE_IMMUTABLE_FG"
        end

        local tid = (layer == 2) and Core.GetBG(x, y) or fgId
        if tid == 0 then
            return false, "ALREADY_EMPTY"
        end
        if Safety.isImmutableId(tid) then
            return false, "PROTECTED_LAYER"
        end
        if Core.CanEditTile and not Core.CanEditTile(x, y) then
            return false, "NOT_EDITABLE"
        end

        -- Check skip/reservation state unless ignored by scanner
        if ctx and not opts.ignoreSkip and ctx.skip then
            local sr = CW.SkipManager.getReason(ctx, x, y, layer)
            if sr then
                return false, sr
            end
        end
        if ctx and not opts.ignoreReservation and ctx.reservedTargets then
            if ctx.reservedTargets[CW.Util.targetKey(x, y, layer)] then
                return false, "ALREADY_RESERVED"
            end
        end

        return true, "OK"
    end
end

-- Module 3: Categorized Skip & Recheck Manager (Replaces flat permanent skipMap)
do
    local SkipManager = {}
    CW.SkipManager = SkipManager

    function SkipManager.create()
        return {
            entries = {},
        }
    end

    function SkipManager.mark(ctx, x, y, layer, reason)
        local key = CW.Util.targetKey(x, y, layer)
        local prev = ctx.skip.entries[key]
        ctx.skip.entries[key] = {
            x = x,
            y = y,
            layer = layer,
            reason = reason,
            markedAt = CW.Util.now(),
            rechecks = prev and prev.rechecks or 0,
        }
    end

    function SkipManager.getReason(ctx, x, y, layer)
        local e = ctx.skip and ctx.skip.entries[CW.Util.targetKey(x, y, layer)]
        return e and e.reason or nil
    end

    function SkipManager.clear(ctx, x, y, layer)
        if ctx and ctx.skip then
            ctx.skip.entries[CW.Util.targetKey(x, y, layer)] = nil
        end
    end

    -- Re-enables TEMPORARY_BLOCKED and UNREACHABLE targets when terrain opens up (never retries PROTECTED/NOT_EDITABLE/COMPLETED)
    function SkipManager.recheckRecoverable(ctx)
        local SR = CW.ENUMS.SKIP_REASON
        local reopened = 0
        for key, e in pairs(ctx.skip.entries) do
            if (e.reason == SR.TEMPORARY_BLOCKED or e.reason == SR.UNREACHABLE) and (e.rechecks or 0) < 2 then
                e.rechecks = (e.rechecks or 0) + 1
                ctx.skip.entries[key] = nil
                reopened = reopened + 1
            end
        end
        return reopened
    end
end

-- Module 4: World Scanner & Incremental Accurate Progress Manager (Independent FG & BG)
do
    local WorldScanner = {}
    CW.WorldScanner = WorldScanner

    function WorldScanner.waitForWorldHydration(targetWorld, aliveFn, maxSec)
        local dl = CW.Util.now() + (maxSec or 7.5)
        while aliveFn() and CW.Util.now() < dl do
            local gt = H and H.gt
            if gt and (gt.w or 0) > 0 and (gt.h or 0) > 0 and type(gt.fg) == "table" then
                local curW = CW.Util.cleanWorld(gt.name)
                if not targetWorld or targetWorld == "" or curW == targetWorld then
                    local loadedTiles = 0
                    for yy = 0, gt.h - 1, 2 do
                        local r = gt.fg[yy]
                        if type(r) == "table" then
                            for xx = 0, gt.w - 1, 4 do
                                if (r[xx] or 0) ~= 0 then loadedTiles = loadedTiles + 1 end
                            end
                        end
                        if loadedTiles >= 12 then break end
                    end
                    local p = Core.ReadPos()
                    if loadedTiles >= 12 and p and type(p.x) == "number" then
                        CW.Util.wait(0.25)
                        return true
                    end
                end
            end
            CW.Util.wait(0.18)
        end
        local gt = H and H.gt
        return gt ~= nil and (gt.w or 0) > 0 and (gt.h or 0) > 0 and type(gt.fg) == "table"
    end

    function WorldScanner.computeHalfWorldMaxY(w, safeMaxY, safety)
        local firstDirtyY, lastDirtyY = nil, nil
        for y = 0, safeMaxY do
            local rowDirty = false
            for x = 0, w - 1 do
                if not safety.immutableSet[y * w + x] then
                    local fgId = Core.GetFG(x, y)
                    local bgId = Core.GetBG(x, y)
                    if (fgId ~= 0 and not CW.Safety.isImmutableId(fgId) and Core.CanEditTile(x, y))
                        or (bgId ~= 0 and not CW.Safety.isImmutableId(bgId) and Core.CanEditTile(x, y)) then
                        rowDirty = true
                        break
                    end
                end
            end
            if rowDirty then
                if not firstDirtyY then firstDirtyY = y end
                lastDirtyY = y
            end
        end
        if firstDirtyY and lastDirtyY then
            local halfSpan = math.max(6, math.floor((lastDirtyY - firstDirtyY + 1) * 0.5))
            return CW.Util.clamp(firstDirtyY + halfSpan - 1, firstDirtyY + 1, safeMaxY), true
        end
        return math.max(3, math.floor(safeMaxY * 0.5)), false
    end

    function WorldScanner.syncProgress(ctx)
        local pr = ctx.progress
        local denom = math.max(1, pr.initialTargets)
        -- Progress strictly reflects VERIFIED COMPLETED targets (never skipped/blocked/failed!)
        local pct = (pr.initialTargets > 0)
            and CW.Util.clamp(math.floor((pr.completedCount / denom) * 100), 0, 100)
            or 100
        ClearWorld.State.progress = pct
        CW.Logger.syncDashboard(ctx)
        return pct
    end

    function WorldScanner.scanFull(ctx)
        local TS = CW.ENUMS.TARGET_STATUS
        local gt = H and H.gt
        if not gt or (gt.w or 0) <= 0 or (gt.h or 0) <= 0 then return false end

        local w, h = gt.w, gt.h
        ctx.w = w
        ctx.h = h
        ctx.worldName = CW.Util.cleanWorld(gt.name)
        ctx.safety = CW.Safety.detectBedrockBoundary(w, h)
        ClearWorld.State.bedrockConfidence = ctx.safety.confidence

        local maxY = ctx.safety.safeMaxY
        if ctx.halfWorldMode then
            maxY = WorldScanner.computeHalfWorldMaxY(w, ctx.safety.safeMaxY, ctx.safety)
        end
        ctx.maxY = maxY

        ctx.targets = {}
        ctx.rowRemaining = {}
        ctx.colRowDirty = {}

        local total = 0
        for y = 0, maxY do
            ctx.rowRemaining[y] = 0
            for x = 0, w - 1 do
                -- Independently inspect FG (layer 1) and BG (layer 2)
                for layer = 1, 2 do
                    local ok = CW.Safety.isValidClearTarget(ctx, x, y, layer, { ignoreSkip = true, ignoreReservation = true })
                    if ok then
                        local tKey = CW.Util.targetKey(x, y, layer)
                        local tid = Core.GetLayerTile(x, y, layer)
                        ctx.targets[tKey] = {
                            x = x,
                            y = y,
                            layer = layer,
                            key = tKey,
                            itemId = tid,
                            status = TS.DISCOVERED,
                            retries = 0,
                            isHazard = (layer == 1) and CW.Safety.isHazardInfo(Core.GetItemInfo(tid)) or false,
                            lastVerifiedAt = CW.Util.now(),
                        }
                        total = total + 1
                        ctx.rowRemaining[y] = ctx.rowRemaining[y] + 1
                        ctx.colRowDirty[y * w + x] = (ctx.colRowDirty[y * w + x] or 0) + 1
                    end
                end
            end
        end

        ctx.progress = {
            initialTargets = total,
            completedCount = 0,
            remainingCount = total,
            blockedCount = 0,
            skippedCount = 0,
            failedCount = 0,
            breaksSinceReconcile = 0,
        }
        WorldScanner.syncProgress(ctx)
        CW.Logger.log(ctx, "SCAN", string.format("World %s (%dx%d) | BedrockTop:%d(%s) | MaxY:%d | Targets:%d (FG+BG)",
            ctx.worldName, w, h, ctx.safety.bedrockTopY, ctx.safety.confidence, maxY, total))
        return true
    end

    -- O(1) incremental update for a single (x, y, layer) target
    function WorldScanner.markTargetResult(ctx, x, y, layer, newStatus, skipReason)
        local TS = CW.ENUMS.TARGET_STATUS
        local tKey = CW.Util.targetKey(x, y, layer)
        local rec = ctx.targets[tKey]
        local pr = ctx.progress
        local cIdx = y * ctx.w + x

        if rec then
            local wasActive = (rec.status == TS.DISCOVERED or rec.status == TS.READY or rec.status == TS.RESERVED
                or rec.status == TS.EXECUTING or rec.status == TS.VERIFYING or rec.status == TS.RETRY_PENDING)
            local nowDone = (newStatus == TS.COMPLETED or newStatus == TS.BLOCKED or newStatus == TS.SKIPPED or newStatus == TS.FAILED)
            rec.status = newStatus
            rec.lastVerifiedAt = CW.Util.now()

            if wasActive and nowDone then
                pr.remainingCount = math.max(0, pr.remainingCount - 1)
                ctx.rowRemaining[y] = math.max(0, (ctx.rowRemaining[y] or 0) - 1)
                ctx.colRowDirty[cIdx] = math.max(0, (ctx.colRowDirty[cIdx] or 0) - 1)
                if newStatus == TS.COMPLETED then
                    pr.completedCount = pr.completedCount + 1
                    pr.breaksSinceReconcile = pr.breaksSinceReconcile + 1
                elseif newStatus == TS.BLOCKED then
                    pr.blockedCount = pr.blockedCount + 1
                elseif newStatus == TS.SKIPPED then
                    pr.skippedCount = pr.skippedCount + 1
                elseif newStatus == TS.FAILED then
                    pr.failedCount = pr.failedCount + 1
                end
            end
        elseif newStatus == TS.COMPLETED then
            pr.completedCount = pr.completedCount + 1
            pr.breaksSinceReconcile = pr.breaksSinceReconcile + 1
        end

        if skipReason then
            CW.SkipManager.mark(ctx, x, y, layer, skipReason)
        end
        WorldScanner.syncProgress(ctx)
    end

    -- Periodic or end-of-phase reconciliation against live world state
    function WorldScanner.reconcile(ctx)
        local TS = CW.ENUMS.TARGET_STATUS
        local pr = ctx.progress
        local liveRemaining = 0

        for y = 0, ctx.maxY do
            ctx.rowRemaining[y] = 0
            for x = 0, ctx.w - 1 do
                local cIdx = y * ctx.w + x
                local cellDirty = 0
                for layer = 1, 2 do
                    local tKey = CW.Util.targetKey(x, y, layer)
                    local rec = ctx.targets[tKey]
                    local okLive = CW.Safety.isValidClearTarget(ctx, x, y, layer, { ignoreReservation = true })
                    if okLive then
                        if not rec then
                            local tid = Core.GetLayerTile(x, y, layer)
                            rec = {
                                x = x, y = y, layer = layer, key = tKey, itemId = tid,
                                status = TS.DISCOVERED, retries = 0,
                                isHazard = (layer == 1) and CW.Safety.isHazardInfo(Core.GetItemInfo(tid)) or false,
                                lastVerifiedAt = CW.Util.now(),
                            }
                            ctx.targets[tKey] = rec
                            pr.initialTargets = pr.initialTargets + 1
                        else
                            rec.status = TS.DISCOVERED
                            rec.itemId = Core.GetLayerTile(x, y, layer)
                            rec.lastVerifiedAt = CW.Util.now()
                        end
                        liveRemaining = liveRemaining + 1
                        ctx.rowRemaining[y] = ctx.rowRemaining[y] + 1
                        cellDirty = cellDirty + 1
                    elseif rec and rec.status ~= TS.COMPLETED and Core.GetLayerTile(x, y, layer) == 0 then
                        rec.status = TS.COMPLETED
                        pr.completedCount = pr.completedCount + 1
                    end
                end
                ctx.colRowDirty[cIdx] = cellDirty
            end
        end

        pr.remainingCount = liveRemaining
        pr.breaksSinceReconcile = 0
        WorldScanner.syncProgress(ctx)
        return liveRemaining
    end

    function WorldScanner.bandHasWork(ctx, yList)
        for _, ry in ipairs(yList) do
            if ry >= 0 and ry <= ctx.maxY and (ctx.rowRemaining[ry] or 0) > 0 then
                return true
            end
        end
        return false
    end

    function WorldScanner.colBandNeedsWork(ctx, tx, yList)
        local w = ctx.w
        for _, ry in ipairs(yList) do
            if ry >= 0 and ry <= ctx.maxY and (ctx.colRowDirty[ry * w + tx] or 0) > 0 then
                return true
            end
        end
        return false
    end
end

-- Module 5: Unified Break Executor, Verification & Smart Collect
do
    local BreakExecutor = {}
    CW.BreakExecutor = BreakExecutor

    local MAX_RETRIES = 3

    local function verifyLayerEmpty(ctx, tx, ty, layer, sentAt, aliveFn)
        local w = ctx and ctx.w or (H and H.gt and H.gt.w) or 100
        local timeout = (H and H.serverTileEchoSeen)
            and CW.Util.clamp((H.serverEchoRtt or 0.22) + 0.16, 0.22, 0.55)
            or 0.24
        local dl = CW.Util.now() + timeout

        while CW.Util.now() <= dl do
            if aliveFn and not aliveFn() then return false, "CANCELLED" end
            if Core.ReconcileTile then Core.ReconcileTile(tx, ty, layer) end
            if Core.GetLayerTile(tx, ty, layer) == 0 then
                return true, "CLEARED"
            end
            if H and H.serverTileEchoSeen and type(H.tileAck) == "table" then
                local ack = H.tileAck[((layer == 2) and "bg" or "fg") .. ":" .. (ty * w + tx)]
                if ack and ack.t >= (sentAt - 0.02) and ack.id == 0 then
                    if Core.MirrorLocalTile then Core.MirrorLocalTile(layer, tx, ty, 0, false) end
                    return true, "SERVER_ACK_CLEARED"
                end
            end
            CW.Util.wait(0.022)
        end
        if Core.ReconcileTile then Core.ReconcileTile(tx, ty, layer) end
        if Core.GetLayerTile(tx, ty, layer) == 0 then
            return true, "CLEARED"
        end
        return false, "VERIFY_TIMEOUT"
    end

    -- Respects noCollect strictly: when noCollect == true, NEVER invokes any collect helper!
    function BreakExecutor.maybeCollect(ctx, aliveFn, force)
        if ctx.noCollect == true then return 0 end
        local now = CW.Util.now()
        if not force and ctx.lastCollectAt and (now - ctx.lastCollectAt) < 0.55 then
            return 0
        end
        ctx.lastCollectAt = now
        local impl = DirtFarm and DirtFarm._impl
        if impl and impl.dfQuickCollectNear then
            return impl.dfQuickCollectNear(aliveFn, nil, true) or 0
        end
        if Packets and Packets.Collect then
            return Packets.Collect({
                radius = 4.2,
                stepMoveIfFar = false,
                preferWalk = true,
                collectDelay = 0.02,
                shouldContinue = aliveFn,
            }) or 0
        end
        return 0
    end

    -- Unified verified break for reachable targets: STRICT FG (layer 1) FIRST, THEN BG/Cave BG (layer 2), SEQUENTIAL (threads=1, strictVerify=true)
    function BreakExecutor.breakBatch(ctx, targetList, hitGap, aliveFn)
        local TS = CW.ENUMS.TARGET_STATUS
        local SR = CW.ENUMS.SKIP_REASON
        if not targetList or #targetList == 0 then return 0, 0 end
        local safeHitGap = math.max(0.194, tonumber(hitGap) or 0.194)

        -- Pre-break validation & reservation, dipisah tegas antara FG (layer 1) dan BG (layer 2)
        local fgBatch, bgBatch = {}, {}
        local allValid = {}
        local seen = {}
        for _, t in ipairs(targetList) do
            local tx, ty, lyr = t.x or t.tx, t.y or t.ty, t.layer or 1
            local tKey = CW.Util.targetKey(tx, ty, lyr)
            if not seen[tKey] then
                local okValid, vRsn = CW.Safety.isValidClearTarget(ctx, tx, ty, lyr)
                if okValid and Core.IsInActionReach(tx, ty, "break") then
                    seen[tKey] = true
                    ctx.reservedTargets[tKey] = true
                    local rec = { x = tx, y = ty, layer = lyr, key = tKey }
                    allValid[#allValid + 1] = rec
                    if lyr == 2 then
                        bgBatch[#bgBatch + 1] = rec
                    else
                        fgBatch[#fgBatch + 1] = rec
                    end
                elseif vRsn == "ALREADY_EMPTY" then
                    CW.WorldScanner.markTargetResult(ctx, tx, ty, lyr, TS.COMPLETED, SR.COMPLETED)
                elseif vRsn == "NOT_EDITABLE" then
                    CW.WorldScanner.markTargetResult(ctx, tx, ty, lyr, TS.BLOCKED, SR.NOT_EDITABLE)
                elseif vRsn == "LIVE_BEDROCK" or vRsn == "BEDROCK_BOUNDARY" or vRsn == "PROTECTED_LAYER" then
                    CW.WorldScanner.markTargetResult(ctx, tx, ty, lyr, TS.BLOCKED, SR.PROTECTED)
                end
            end
        end

        if #allValid == 0 then return 0, 0 end

        local okTotal, failTotal = 0, 0

        local function runPhase(phaseBatch, phaseLayer)
            if #phaseBatch == 0 then return end
            for attempt = 1, MAX_RETRIES do
                if not aliveFn() then break end
                local pktTargets = {}
                local activeItems = {}
                for _, it in ipairs(phaseBatch) do
                    if not it.done then
                        if Core.GetLayerTile(it.x, it.y, phaseLayer) == 0 then
                            it.done = true
                            okTotal = okTotal + 1
                            CW.WorldScanner.markTargetResult(ctx, it.x, it.y, phaseLayer, TS.COMPLETED, SR.COMPLETED)
                        elseif phaseLayer == 2 and Core.GetFG(it.x, it.y) ~= 0 then
                            -- Jangan pukul Cave BG bila FG di tile tersebut masih ada!
                            it.retries = attempt
                        else
                            local okLive = CW.Safety.isValidClearTarget(ctx, it.x, it.y, phaseLayer, { ignoreReservation = true })
                            if okLive and Core.IsInActionReach(it.x, it.y, "break") then
                                pktTargets[#pktTargets + 1] = { tx = it.x, ty = it.y, layer = phaseLayer }
                                activeItems[#activeItems + 1] = it
                            end
                        end
                    end
                end
                if #pktTargets == 0 then break end

                CW.Util.coolAntiKick()
                CW.Util.forceWalkSpeed(1.0)
                local first = activeItems[1]
                CW.Logger.setCurrentTask(ctx, first.x, first.y, phaseLayer, Core.GetLayerTile(first.x, first.y, phaseLayer), "EXECUTING", attempt - 1)
                local sentAt = CW.Util.now()

                -- Sequential threads=1 + strictVerify=true + noLocalMirror=true agar ZERO collision & ZERO Rock/Cave BG kelewat!
                Packets.BreakVerified(pktTargets, {
                    threads = 1,
                    layer = phaseLayer,
                    oneHit = false,
                    hitDelay = safeHitGap,
                    verifyTimeout = 0.22,
                    showHand = true,
                    showVisual = true,
                    noLocalMirror = true,
                    strictVerify = true,
                    autoRange = false,
                    shouldContinue = aliveFn,
                })

                for _, it in ipairs(activeItems) do
                    CW.Logger.setCurrentTask(ctx, it.x, it.y, phaseLayer, Core.GetLayerTile(it.x, it.y, phaseLayer), "VERIFYING", attempt)
                    local okClr = verifyLayerEmpty(ctx, it.x, it.y, phaseLayer, sentAt, aliveFn)
                    if okClr then
                        it.done = true
                        okTotal = okTotal + 1
                        if Core.ClearVisualCrack then pcall(Core.ClearVisualCrack, it.x, it.y) end
                        CW.WorldScanner.markTargetResult(ctx, it.x, it.y, phaseLayer, TS.COMPLETED, SR.COMPLETED)
                    else
                        it.retries = attempt
                    end
                end
            end
        end

        -- Fase 1: Hancurkan semua FG (Dirt, Rock 10-hit, Lava, dll) sampai 100% terverifikasi == 0
        runPhase(fgBatch, 1)
        -- Fase 2: Baru hancurkan semua BG (Cave BG) pada tile yang FG-nya sudah benar-benar kosong!
        runPhase(bgBatch, 2)

        -- Release reservations & classify failures cleanly
        for _, it in ipairs(allValid) do
            ctx.reservedTargets[it.key] = nil
            if not it.done then
                failTotal = failTotal + 1
                if Core.CanEditTile and not Core.CanEditTile(it.x, it.y) then
                    CW.WorldScanner.markTargetResult(ctx, it.x, it.y, it.layer, TS.BLOCKED, SR.NOT_EDITABLE)
                elseif not Core.IsInActionReach(it.x, it.y, "break") then
                    CW.WorldScanner.markTargetResult(ctx, it.x, it.y, it.layer, TS.SKIPPED, SR.UNREACHABLE)
                else
                    CW.WorldScanner.markTargetResult(ctx, it.x, it.y, it.layer, TS.FAILED, SR.FAILED)
                end
            end
        end

        if okTotal > 0 then
            BreakExecutor.maybeCollect(ctx, aliveFn, false)
        end
        return okTotal, failTotal
    end

    -- Clears Lava/Deadly tile safely from adjacent tile & VERIFIES hazard is gone before returning true
    function BreakExecutor.clearHazardSafely(ctx, hx, hy, aliveFn)
        if not CW.Safety.isHazardAt(hx, hy) then return true end
        local okValid = CW.Safety.isValidClearTarget(ctx, hx, hy, 1)
        if not okValid then
            CW.Logger.log(ctx, "SAFETY", string.format("Hazard at (%d,%d) cannot be edited -> path BLOCKED", hx, hy))
            return false
        end
        if not Core.IsInActionReach(hx, hy, "break") then
            local okMove = CW.MoveController.moveIntoBreakReach(ctx, hx, hy, aliveFn)
            if not okMove then return false end
        end
        BreakExecutor.breakBatch(ctx, { { x = hx, y = hy, layer = 1 } }, 0.194, aliveFn)
        -- Strictly verify hazard is ACTUALLY gone
        return not CW.Safety.isHazardAt(hx, hy)
    end
end

-- Module 6: Unified Movement Controller (Single Owner of Movement, Route Cache & Hazard Guards)
do
    local MoveController = {}
    CW.MoveController = MoveController

    function MoveController.init(ctx)
        ctx.moveCache = { key = nil, fromX = nil, fromY = nil, cands = nil, at = 0 }
    end

    local function dfImpl()
        return DirtFarm and DirtFarm._impl or nil
    end

    function MoveController.isStandable(tx, ty)
        local gt = H and H.gt
        if not gt or tx < 0 or tx >= gt.w or ty >= gt.h then return true end
        if ty < 0 then return false end
        if CW.Safety.isHazardAt(tx, ty) then return false end
        local impl = dfImpl()
        if impl and impl.dfIsStandable then
            return impl.dfIsStandable(tx, ty)
        end
        if Core.IsSolid(tx, ty) then return true end
        local id = Core.GetFG(tx, ty)
        if id == 0 then return false end
        local info = Core.GetItemInfo(id)
        return info ~= nil and info.platform == true and not info.background
    end

    function MoveController.walkFloorX(ctx, goalX, floorY, maxSec, aliveFn)
        local MS = CW.ENUMS.MOVE_STATE
        local w = ctx and ctx.w or (H and H.gt and H.gt.w) or 100
        local gx = CW.Util.clamp(goalX, 0.55, w - 0.55)
        local nearEdge = (gx <= 1.25 or gx >= w - 1.25)
        local cur = Core.ReadPos()
        if cur.grounded and math.abs(cur.x - gx) <= (nearEdge and 0.65 or 0.35) and math.abs(cur.y - floorY) <= 0.50 then
            CW.Logger.setMoveState(ctx, MS.IDLE)
            return true
        end
        CW.Logger.setMoveState(ctx, MS.MOVING, string.format("X=%.1f Y=%d", gx, floorY))
        local impl = dfImpl()
        if impl and impl.dfStepWalkToX then
            local ok = impl.dfStepWalkToX(gx, floorY, maxSec or 2.8, aliveFn, nil)
            CW.Logger.setMoveState(ctx, ok and MS.IDLE or MS.BLOCKED)
            return ok
        end
        local h = ctx and ctx.h or (H and H.gt and H.gt.h) or 60
        local okW = Packets.WalkPathTo(CW.Util.clamp(math.floor(gx), 0, w - 1), CW.Util.clamp((floorY or 1) - 1, 0, h - 1), 6.9, aliveFn, { fastWalk = false, noSnap = true })
        CW.Logger.setMoveState(ctx, okW and MS.IDLE or MS.BLOCKED)
        return okW
    end

    function MoveController.jumpGapToX(ctx, destTileX, destFloorY, aliveFn)
        local MS = CW.ENUMS.MOVE_STATE
        CW.Logger.setMoveState(ctx, MS.JUMPING, string.format("(%d,%d)", destTileX, destFloorY))
        local dir = (destTileX >= Core.ReadPos().tx) and 1 or -1
        local targetX = destTileX + 0.5
        local dl = CW.Util.now() + 1.4
        while CW.Util.now() < dl do
            if not aliveFn() then Core.ClearManualInput(); return false end
            CW.Util.forceWalkSpeed(0.8)
            local p = Core.ReadPos()
            if p.grounded and math.abs(p.y - destFloorY) <= 0.30 and math.abs(p.x - targetX) <= 0.65 then
                Core.ClearManualInput()
                CW.Logger.setMoveState(ctx, MS.IDLE)
                return true
            end
            local needJump = p.grounded and ((dir > 0 and p.x < targetX - 0.5) or (dir < 0 and p.x > targetX + 0.5))
            Core.SetManualInput(dir, needJump)
            CW.Util.wait(0.016)
        end
        Core.ClearManualInput()
        local pf = Core.ReadPos()
        local ok = math.abs(pf.x - targetX) <= 0.85 and math.abs(pf.y - destFloorY) <= 0.55
        CW.Logger.setMoveState(ctx, ok and MS.IDLE or MS.BLOCKED)
        return ok
    end

    function MoveController.moveIntoBreakReach(ctx, bx, by, aliveFn)
        local MS = CW.ENUMS.MOVE_STATE
        if Core.IsInActionReach(bx, by, "break") then return true end
        CW.Logger.setMoveState(ctx, MS.PLANNING, string.format("Reach(%d,%d)", bx, by))

        -- Cached candidate stand lookup (avoids repeated pathfinding from unchanged position)
        local cur = Core.ReadPos()
        local mc = ctx and ctx.moveCache
        local cKey = tostring(bx) .. "," .. tostring(by)
        local cands
        if mc and mc.key == cKey and mc.fromX == cur.tx and mc.fromY == cur.ty and (CW.Util.now() - mc.at) < 1.5 and mc.cands then
            cands = mc.cands
        else
            cands = Packets.FindStandCandidates(bx, by, 2) or {}
            if mc then
                mc.key = cKey
                mc.fromX = cur.tx
                mc.fromY = cur.ty
                mc.cands = cands
                mc.at = CW.Util.now()
            end
        end

        CW.Logger.setMoveState(ctx, MS.MOVING, string.format("(%d,%d)", bx, by))
        if cands[1] then
            Packets.WalkPathTo(cands[1].x, cands[1].y, 6.9, aliveFn, { fastWalk = false, noSnap = true, customPath = cands[1].path })
            if Core.IsInActionReach(bx, by, "break") then
                CW.Logger.setMoveState(ctx, MS.IDLE)
                return true
            end
        end

        if Packets.MoveWalkNear then
            Packets.MoveWalkNear(bx, by, 2, aliveFn, 7.1, "break")
        end

        CW.Logger.setMoveState(ctx, MS.VERIFYING_POSITION)
        local inReach = Core.IsInActionReach(bx, by, "break")
        CW.Logger.setMoveState(ctx, inReach and MS.IDLE or MS.BLOCKED)
        return inReach
    end

    -- Safe descent along world edge with verified lava clearance and post-drop floor verification
    function MoveController.descendEdgeToFloor(ctx, edgeCol, innerCol, fromFloorY, toFloorY, aliveFn)
        local MS = CW.ENUMS.MOVE_STATE
        if math.floor(Core.ReadPos().y + 0.5) >= toFloorY then return true end
        CW.Logger.setMoveState(ctx, MS.DESCENDING, string.format("Edge %d -> Y=%d", edgeCol, toFloorY))

        MoveController.walkFloorX(ctx, innerCol + 0.5, fromFloorY, 2.2, aliveFn)

        -- Clear shaft descent path (strictly respecting maxY & Safety)
        for ty = math.max(0, fromFloorY - 2), math.min(ctx.maxY, toFloorY - 1) do
            if not aliveFn() then return false end
            local batch = {}
            for _, cx in ipairs({ edgeCol, innerCol }) do
                for layer = 1, 2 do
                    if CW.Safety.isValidClearTarget(ctx, cx, ty, layer) and Core.IsInActionReach(cx, ty, "break") then
                        batch[#batch + 1] = { x = cx, y = ty, layer = layer }
                    end
                end
            end
            if #batch > 0 then
                CW.BreakExecutor.breakBatch(ctx, batch, 0.194, aliveFn)
            end
        end

        -- Verify destination floor tiles are NOT Lava before dropping
        if toFloorY <= ctx.maxY then
            if CW.Safety.isHazardAt(edgeCol, toFloorY) then
                if not CW.BreakExecutor.clearHazardSafely(ctx, edgeCol, toFloorY, aliveFn) then
                    CW.Logger.setMoveState(ctx, MS.BLOCKED, "Hazard at descent floor")
                    return false
                end
            end
            if CW.Safety.isHazardAt(innerCol, toFloorY) then
                if not CW.BreakExecutor.clearHazardSafely(ctx, innerCol, toFloorY, aliveFn) then
                    CW.Logger.setMoveState(ctx, MS.BLOCKED, "Hazard at inner descent floor")
                    return false
                end
            end
        end

        local impl = dfImpl()
        for _ = 1, 2 do
            if not aliveFn() then return false end
            local p = Core.ReadPos()
            local curY = math.floor(p.y + 0.5)
            if curY >= toFloorY and p.grounded then break end
            local dropX = MoveController.isStandable(edgeCol, toFloorY) and edgeCol or innerCol
            -- Break seluruh FG lalu BG di jalur turun (termasuk tepat di bawah kaki bila masih solid!)
            local clr = {}
            for ry = math.max(0, curY - 1), math.min(ctx.maxY, toFloorY - 1) do
                for layer = 1, 2 do
                    if CW.Safety.isValidClearTarget(ctx, dropX, ry, layer) and Core.IsInActionReach(dropX, ry, "break") then
                        clr[#clr + 1] = { x = dropX, y = ry, layer = layer }
                    end
                end
            end
            if #clr > 0 then CW.BreakExecutor.breakBatch(ctx, clr, 0.194, aliveFn) end

            if impl and impl.dfDropIntoCol then
                impl.dfDropIntoCol(dropX, toFloorY, aliveFn, 0.90)
            else
                Packets.WalkPathTo(dropX, math.max(0, toFloorY - 1), 6.9, aliveFn, { fastWalk = false, noSnap = true })
            end
            if math.floor(Core.ReadPos().y + 0.5) >= toFloorY then break end
        end

        -- Verify landing tanpa wall-jam walkFloorX ke tepi border agar langsung TURN ke baris berikutnya!
        CW.Logger.setMoveState(ctx, MS.VERIFYING_POSITION)
        local landed = math.abs(Core.ReadPos().y - toFloorY) <= 0.85
        CW.Logger.setMoveState(ctx, landed and MS.IDLE or MS.BLOCKED)
        return landed
    end
end

-- Module 7: 3-Phase Intelligent Clearing Planner & Scheduler
do
    local Planner = {}
    CW.Planner = Planner

    local function shouldAbortForAutoLevelOrSeems(ctx, opts)
        if Misc and Misc.State and Misc.State.seems then
            if opts.fromAutoLevel then
                for _, p in ipairs(Core.GetInWorldPlayers(false)) do
                    if p.isStaff and evaluateSeems and evaluateSeems() then return true, "STAFF_SEEMS" end
                end
            elseif evaluateSeems and evaluateSeems() then
                return true, "SEEMS"
            end
        end
        if opts.fromAutoLevel and #Core.GetInWorldPlayers(false) > 0 then
            setCwStatus("Player lain terdeteksi saat AutoLevel -> Ganti world")
            Core.ClearManualInput()
            return true, "AUTOLEVEL_PLAYER"
        end
        return false, nil
    end

    -- Horizontal Band Sweep: O(1) dirty column skipping, hazard-first safety, reachable batching
    function Planner.sweepHorizontalBand(ctx, standY, xFrom, xTo, yBands, opts, aliveFn)
        local dir = (xTo >= xFrom) and 1 or -1
        local tx = xFrom

        while (dir > 0 and tx <= xTo) or (dir < 0 and tx >= xTo) do
            if not aliveFn() then Core.ClearManualInput(); return false end
            local abort = shouldAbortForAutoLevelOrSeems(ctx, opts)
            if abort then Core.ClearManualInput(); return false end
            CW.Util.forceWalkSpeed(1.0)

            -- Periodic reconciliation every 30 verified breaks
            if ctx.progress.breaksSinceReconcile >= 30 then
                CW.WorldScanner.reconcile(ctx)
            end

            -- O(1) scan ahead to sprint straight across already-clean standable columns
            local workX = tx
            while (dir > 0 and workX <= xTo) or (dir < 0 and workX >= xTo) do
                local colDirty = CW.WorldScanner.colBandNeedsWork(ctx, workX, yBands)
                local floorHazard = (standY <= ctx.maxY) and CW.Safety.isHazardAt(workX, standY)
                if workX == xTo or colDirty or floorHazard or not CW.MoveController.isStandable(workX, standY) then
                    break
                end
                workX = workX + dir
            end

            local sprintDone = false
            local sprintTo = workX - dir
            if (dir > 0 and sprintTo >= tx) or (dir < 0 and sprintTo <= tx) then
                local endClean = (workX == xTo) and not CW.WorldScanner.colBandNeedsWork(ctx, workX, yBands) and CW.MoveController.isStandable(workX, standY)
                local targetSprint = endClean and workX or sprintTo
                CW.MoveController.walkFloorX(ctx, targetSprint + 0.5, standY, math.max(1.4, math.abs(targetSprint - tx) * 0.25 + 1.2), aliveFn)
                if targetSprint == workX then
                    tx = workX + dir
                    sprintDone = true
                end
            end

            if not sprintDone then
                local pct = CW.WorldScanner.syncProgress(ctx)
                setCwStatus(string.format("[%s] %s y=%d x=%d (%d%%)", ctx.worldName, ctx.phase, standY - 1, workX, pct))

                -- Re-align onto standY if dropped slightly
                local p = Core.ReadPos()
                if math.abs(p.y - standY) > 0.70 and p.grounded and p.y > standY + 0.7 and p.y <= standY + 2.5 and CW.MoveController.isStandable(workX, standY) then
                    CW.MoveController.jumpGapToX(ctx, workX, standY, aliveFn)
                end

                if math.abs((workX + 0.5) - Core.ReadPos().x) > 1.65 then
                    local movedClose = false
                    for stepBack = 1, 2 do
                        local standPre = workX - stepBack * dir
                        if standPre >= 0 and standPre < ctx.w and CW.MoveController.isStandable(standPre, standY) then
                            CW.MoveController.walkFloorX(ctx, standPre + 0.5, standY, 1.2, aliveFn)
                            movedClose = true
                            break
                        end
                    end
                    if not movedClose then
                        -- Cari tile dirty pertama di kolom workX dan dekati agar kolom tidak terlewat
                        for _, ry in ipairs(yBands) do
                            if ry >= 0 and ry <= ctx.maxY and (CW.Safety.isValidClearTarget(ctx, workX, ry, 1) or CW.Safety.isValidClearTarget(ctx, workX, ry, 2)) then
                                CW.MoveController.moveIntoBreakReach(ctx, workX, ry, aliveFn)
                                break
                            end
                        end
                    end
                end

                -- 1) Hazard-First: clear Lava/Deadly tile at (workX, standY) BEFORE stepping onto it & verify cleared
                if standY <= ctx.maxY and CW.Safety.isHazardAt(workX, standY) then
                    local hazOk = CW.BreakExecutor.clearHazardSafely(ctx, workX, standY, aliveFn)
                    if not hazOk then
                        CW.SkipManager.mark(ctx, workX, standY, 1, CW.ENUMS.SKIP_REASON.TEMPORARY_BLOCKED)
                    end
                end

                -- 2) Multi-pass verified clear untuk kolom workX (+ aheadX dalam jangkauan):
                -- Pastikan FG (Rock/Dirt/Lava) DAN BG (Cave BG) di kolom workX benar-benar habis sebelum maju!
                for colPass = 1, 3 do
                    if not aliveFn() then break end
                    local batch = {}
                    local cols = { workX }
                    local aheadX = workX + dir
                    if (dir > 0 and aheadX <= xTo) or (dir < 0 and aheadX >= xTo) then
                        cols[2] = aheadX
                    end
                    for _, cx in ipairs(cols) do
                        for _, ry in ipairs(yBands) do
                            if ry >= 0 and ry <= ctx.maxY then
                                for layer = 1, 2 do
                                    if CW.Safety.isValidClearTarget(ctx, cx, ry, layer) and Core.IsInActionReach(cx, ry, "break") then
                                        batch[#batch + 1] = { x = cx, y = ry, layer = layer }
                                    end
                                end
                            end
                        end
                    end
                    if #batch == 0 then break end
                    local okCnt = CW.BreakExecutor.breakBatch(ctx, batch, 0.194, aliveFn)
                    -- Cek apakah masih ada target reachable tersisa di workX (mis. Cave BG yang baru terbuka setelah FG hancur)
                    local workStillDirty = false
                    for _, ry in ipairs(yBands) do
                        if ry >= 0 and ry <= ctx.maxY then
                            if (CW.Safety.isValidClearTarget(ctx, workX, ry, 1) and Core.IsInActionReach(workX, ry, "break"))
                                or (CW.Safety.isValidClearTarget(ctx, workX, ry, 2) and Core.IsInActionReach(workX, ry, "break")) then
                                workStillDirty = true
                                break
                            end
                        end
                    end
                    if not workStillDirty or okCnt == 0 then break end
                end

                -- 3) Advance safely: jika sudah di ujung world (workX == xTo), LANGSUNG selesai & turn tanpa stuck ke dinding!
                if workX == xTo then
                    tx = workX + dir
                else
                    local hopped = false
                    if not CW.MoveController.isStandable(workX, standY) then
                        local landX = nil
                        for lookGap = 1, 3 do
                            local gx = workX + lookGap * dir
                            if (dir > 0 and gx <= xTo) or (dir < 0 and gx >= xTo) then
                                if CW.MoveController.isStandable(gx, standY) then landX = gx; break end
                            end
                        end
                        if landX then
                            CW.MoveController.jumpGapToX(ctx, landX, standY, aliveFn)
                            -- Sapu ulang kolom yang baru saja dilompati (workX .. landX - dir) dari posisi landX agar tidak ada pola bolong!
                            local gapBatch = {}
                            local gCol = workX
                            while gCol ~= landX do
                                for _, ry in ipairs(yBands) do
                                    if ry >= 0 and ry <= ctx.maxY then
                                        for layer = 1, 2 do
                                            if CW.Safety.isValidClearTarget(ctx, gCol, ry, layer) and Core.IsInActionReach(gCol, ry, "break") then
                                                gapBatch[#gapBatch + 1] = { x = gCol, y = ry, layer = layer }
                                            end
                                        end
                                    end
                                end
                                gCol = gCol + dir
                            end
                            if #gapBatch > 0 then
                                CW.BreakExecutor.breakBatch(ctx, gapBatch, 0.194, aliveFn)
                            end
                            tx = landX
                            hopped = true
                        end
                    end
                    if not hopped then
                        CW.MoveController.walkFloorX(ctx, workX + 0.5, standY, 1.0, aliveFn)
                        tx = workX + dir
                    end
                end
            end
        end

        Core.ClearManualInput()
        return true
    end

    -- Phase 1A: Top-Down Hill Cleaning (preserves supporting tiles until above targets finish)
    function Planner.runPhase1AHills(ctx, curFloor, goLeftFirst, opts, aliveFn)
        if curFloor < 5 then return end
        CW.Logger.setPhase(ctx, CW.ENUMS.PHASE.PHASE_1A_HILL)
        CW.Logger.log(ctx, "PHASE", "Top-Down Hill Cleaning started (y=0.." .. tostring(curFloor - 4) .. ")")

        local revRow = not goLeftFirst
        for y = 0, math.min(ctx.maxY, curFloor - 4) do
            if not aliveFn() or shouldAbortForAutoLevelOrSeems(ctx, opts) then break end
            if (ctx.rowRemaining[y] or 0) > 0 then
                local xs = revRow and (ctx.w - 1) or 0
                local xe = revRow and 0 or (ctx.w - 1)
                local st = revRow and -1 or 1
                for x = xs, xe, st do
                    if not aliveFn() or shouldAbortForAutoLevelOrSeems(ctx, opts) then break end
                    if (ctx.colRowDirty[y * ctx.w + x] or 0) > 0 then
                        -- Hazard check below target before approaching
                        if y + 1 <= ctx.maxY and CW.Safety.isHazardAt(x, y + 1) then
                            CW.BreakExecutor.clearHazardSafely(ctx, x, y + 1, aliveFn)
                        end
                        if CW.MoveController.moveIntoBreakReach(ctx, x, y, aliveFn) then
                            CW.BreakExecutor.breakBatch(ctx, {
                                { x = x, y = y, layer = 1 },
                                { x = x, y = y, layer = 2 },
                            }, 0.194, aliveFn)
                        else
                            CW.SkipManager.mark(ctx, x, y, 1, CW.ENUMS.SKIP_REASON.UNREACHABLE)
                            CW.SkipManager.mark(ctx, x, y, 2, CW.ENUMS.SKIP_REASON.UNREACHABLE)
                        end
                    end
                end
            end
            revRow = not revRow
        end
    end

    -- Phase 1B: Nearest-Side Surface Horizontal Sweep
    function Planner.runPhase1BSurface(ctx, opts, aliveFn)
        CW.Logger.setPhase(ctx, CW.ENUMS.PHASE.PHASE_1B_SURFACE)
        local p = Core.ReadPos()
        local sFloor = CW.Util.clamp(math.floor(p.y + 0.5), 2, ctx.maxY + 1)
        local sBands = { sFloor - 3, sFloor - 2, sFloor - 1 }
        if not CW.WorldScanner.bandHasWork(ctx, sBands) then return sFloor end

        CW.Logger.log(ctx, "PHASE", "Surface Sweep started at floor Y=" .. tostring(sFloor))
        local goL = (p.tx <= math.floor(ctx.w / 2))
        local nearEdge = goL and 0 or (ctx.w - 1)
        local farEdge = goL and (ctx.w - 1) or 0

        Planner.sweepHorizontalBand(ctx, sFloor, p.tx, nearEdge, sBands, opts, aliveFn)
        if aliveFn() and CW.WorldScanner.bandHasWork(ctx, sBands) then
            Planner.sweepHorizontalBand(ctx, sFloor, nearEdge, farEdge, sBands, opts, aliveFn)
        end
        CW.Logger.log(ctx, "PHASE", "Surface Sweep completed")
        return sFloor
    end

    -- Phase 2: Underground Two-Row Bulldozer with Intelligent Band Selection (skips clean bands!)
    function Planner.runPhase2Underground(ctx, startFloor, opts, aliveFn)
        CW.Logger.setPhase(ctx, CW.ENUMS.PHASE.PHASE_2_UNDERGROUND)
        CW.Logger.log(ctx, "PHASE", "Underground Two-Row Sweep started")

        local bandFloors = {}
        local sy = math.min(ctx.maxY + 1, startFloor + 2)
        while sy < ctx.maxY + 1 do
            bandFloors[#bandFloors + 1] = sy
            sy = sy + 2
        end
        bandFloors[#bandFloors + 1] = ctx.maxY + 1

        for _, standY in ipairs(bandFloors) do
            if not aliveFn() or shouldAbortForAutoLevelOrSeems(ctx, opts) then break end
            local yBands = (standY == ctx.maxY + 1)
                and { standY - 3, standY - 2, standY - 1 }
                or { standY - 2, standY - 1 }

            -- Skip bands that already have zero remaining work!
            if CW.WorldScanner.bandHasWork(ctx, yBands) then
                local pNow = Core.ReadPos()
                local atLeft = (pNow.tx <= math.floor(ctx.w / 2))
                local edgeC = atLeft and 0 or (ctx.w - 1)
                local innerC = atLeft and 1 or (ctx.w - 2)
                local curF = math.floor(pNow.y + 0.5)

                if math.abs(pNow.tx - edgeC) > 3 then
                    CW.MoveController.walkFloorX(ctx, edgeC + 0.5, curF, math.max(1.5, math.abs(edgeC - pNow.tx) * 0.25 + 1.4), aliveFn)
                end

                pNow = Core.ReadPos()
                curF = math.floor(pNow.y + 0.5)
                if curF < standY then
                    setCwStatus(string.format("[%s] Turun aman ke band Y=%d...", ctx.worldName, standY - 1))
                    local okDesc = CW.MoveController.descendEdgeToFloor(ctx, edgeC, innerC, curF, standY, aliveFn)
                    if not okDesc and aliveFn() then
                        -- Try opposite side edge as fallback before pathfinding
                        local altEdge = atLeft and (ctx.w - 1) or 0
                        local altInner = atLeft and (ctx.w - 2) or 1
                        CW.MoveController.walkFloorX(ctx, altInner + 0.5, curF, 4.0, aliveFn)
                        if not CW.MoveController.descendEdgeToFloor(ctx, altEdge, altInner, curF, standY, aliveFn) then
                            CW.MoveController.moveIntoBreakReach(ctx, edgeC, standY - 1, aliveFn)
                        end
                    end
                end

                local pBand = Core.ReadPos()
                local startLeft = (pBand.tx <= math.floor(ctx.w / 2))
                local xS = startLeft and 0 or (ctx.w - 1)
                local xE = startLeft and (ctx.w - 1) or 0
                Planner.sweepHorizontalBand(ctx, standY, xS, xE, yBands, opts, aliveFn)
            end
        end
    end

    -- Phase 3: Isolated Leftover Sweep + Recheck Previously Unreachable Targets + Final Reconciliation
    function Planner.runPhase3Leftovers(ctx, opts, aliveFn)
        CW.Logger.setPhase(ctx, CW.ENUMS.PHASE.PHASE_3_LEFTOVER)
        CW.Logger.log(ctx, "PHASE", "Leftover Sweep started")

        -- Reopen TEMPORARY_BLOCKED / UNREACHABLE targets whose access opened during Phase 1-2
        local reopened = CW.SkipManager.recheckRecoverable(ctx)
        if reopened > 0 then
            CW.Logger.log(ctx, "PLAN", string.format("Rechecking %d previously unreachable targets", reopened))
        end

        local rem = CW.WorldScanner.reconcile(ctx)
        if rem <= 0 then return 0 end

        local leftovers = {}
        for y = 0, ctx.maxY do
            if (ctx.rowRemaining[y] or 0) > 0 then
                local xs = (y % 2 == 0) and 0 or (ctx.w - 1)
                local xe = (y % 2 == 0) and (ctx.w - 1) or 0
                local st = (y % 2 == 0) and 1 or -1
                for x = xs, xe, st do
                    if (ctx.colRowDirty[y * ctx.w + x] or 0) > 0 then
                        leftovers[#leftovers + 1] = { x = x, y = y }
                    end
                end
            end
        end

        for idxL, lt in ipairs(leftovers) do
            if not aliveFn() or shouldAbortForAutoLevelOrSeems(ctx, opts) then break end
            setCwStatus(string.format("[%s] Sapu Sisa %d/%d @(%d,%d) (%d%%)",
                ctx.worldName, idxL, #leftovers, lt.x, lt.y, ClearWorld.State.progress))
            if lt.y + 1 <= ctx.maxY and CW.Safety.isHazardAt(lt.x, lt.y + 1) then
                CW.BreakExecutor.clearHazardSafely(ctx, lt.x, lt.y + 1, aliveFn)
            end
            if CW.MoveController.moveIntoBreakReach(ctx, lt.x, lt.y, aliveFn) then
                CW.BreakExecutor.breakBatch(ctx, {
                    { x = lt.x, y = lt.y, layer = 1 },
                    { x = lt.x, y = lt.y, layer = 2 },
                }, 0.194, aliveFn)
            else
                -- Do NOT mark as COMPLETED; mark explicitly as UNREACHABLE so progress stays honest!
                CW.WorldScanner.markTargetResult(ctx, lt.x, lt.y, 1, CW.ENUMS.TARGET_STATUS.SKIPPED, CW.ENUMS.SKIP_REASON.UNREACHABLE)
                CW.WorldScanner.markTargetResult(ctx, lt.x, lt.y, 2, CW.ENUMS.TARGET_STATUS.SKIPPED, CW.ENUMS.SKIP_REASON.UNREACHABLE)
            end
        end

        CW.Logger.setPhase(ctx, CW.ENUMS.PHASE.RECONCILING)
        local finalRem = CW.WorldScanner.reconcile(ctx)
        CW.Logger.log(ctx, "VERIFY", string.format("Final reconciliation: remaining=%d completed=%d/%d blocked=%d skipped=%d failed=%d",
            finalRem, ctx.progress.completedCount, ctx.progress.initialTargets,
            ctx.progress.blockedCount, ctx.progress.skippedCount, ctx.progress.failedCount))
        return finalRem
    end

    function Planner.runWorld(ctx, opts, aliveFn)
        CW.Logger.setPhase(ctx, CW.ENUMS.PHASE.SCANNING)
        if not CW.WorldScanner.scanFull(ctx) then
            return "SCAN_FAILED"
        end

        if ctx.safety.confidence == CW.ENUMS.BEDROCK_CONFIDENCE.LOW then
            CW.Logger.log(ctx, "SAFETY", string.format("Inconsistent Bedrock detection -> limiting safeMaxY=%d", ctx.maxY))
        end

        if ctx.progress.initialTargets == 0 then
            if opts.fromAutoLevel then
                CW.Util.wait(0.70)
                CW.WorldScanner.scanFull(ctx)
            end
            if ctx.progress.initialTargets == 0 then
                return "EMPTY_OR_LOCKED"
            end
        end

        local p0 = Core.ReadPos()
        local curFloor = CW.Util.clamp(math.floor(p0.y + 0.5), 2, ctx.maxY + 1)
        local goLeftFirst = (p0.tx <= math.floor(ctx.w / 2))

        -- Phase 1A -> Phase 1B -> Phase 2 -> Phase 3
        Planner.runPhase1AHills(ctx, curFloor, goLeftFirst, opts, aliveFn)
        if not aliveFn() then return "STOPPED" end

        local surfFloor = Planner.runPhase1BSurface(ctx, opts, aliveFn)
        if not aliveFn() then return "STOPPED" end

        Planner.runPhase2Underground(ctx, surfFloor, opts, aliveFn)
        if not aliveFn() then return "STOPPED" end

        local rem = Planner.runPhase3Leftovers(ctx, opts, aliveFn)
        if not aliveFn() then return "STOPPED" end

        CW.Logger.setPhase(ctx, CW.ENUMS.PHASE.COMPLETE)
        return (rem <= 0) and "WORLD_COMPLETE" or "WORLD_COMPLETE_WITH_UNREACHABLE"
    end
end

-- Module 8: Verified Multi-World Queue & Session Recovery Helper
do
    local WorldQueue = {}
    CW.WorldQueue = WorldQueue

    local MAX_WARP_RETRIES = 3

    function WorldQueue.saveRotSession(targetWorld, worlds, halfWorld, noCollect)
        local env = CW.Util.getEnvTable()
        local ed = env.__SYT_ENV_DATA or {}
        env.__SYT_ENV_DATA = ed
        ed.rotSession = {
            mode = "ClearWorld",
            targetWorld = targetWorld,
            worlds = ClearWorld._syncEnvQueue(worlds),
            halfWorld = halfWorld == true,
            noCollect = noCollect == true,
            active = true,
            updatedAt = CW.Util.now(),
        }
    end

    function WorldQueue.clearRotSession()
        local env = CW.Util.getEnvTable()
        local ed = env.__SYT_ENV_DATA
        if type(ed) == "table" and ed.rotSession and ed.rotSession.mode == "ClearWorld" then
            ed.rotSession = nil
        end
    end

    -- Verified world warp: confirms actual world name, dimensions, and tile hydration
    function WorldQueue.enterAndVerify(targetWorld, aliveFn)
        local targetClean = CW.Util.cleanWorld(targetWorld)
        if targetClean == "" then return false, "EMPTY_WORLD" end

        for attempt = 1, MAX_WARP_RETRIES do
            if not aliveFn() then return false, "CANCELLED" end
            ClearWorld.State.switchingWorld = true
            setCwStatus(string.format("Masuk world %s (%d/%d)...", targetClean, attempt, MAX_WARP_RETRIES))
            local okWarp = Packets.EnterWorldDoor(targetClean, aliveFn)
            ClearWorld.State.switchingWorld = false
            if not aliveFn() then return false, "CANCELLED" end

            if okWarp then
                local hydrated = CW.WorldScanner.waitForWorldHydration(targetClean, aliveFn, 7.5)
                local curW = (H and H.gt) and CW.Util.cleanWorld(H.gt.name) or ""
                if hydrated and curW == targetClean then
                    return true, "VERIFIED"
                end
            end
            CW.Util.wait(1.4)
        end
        return false, "WARP_FAILED"
    end
end

-- Preserved Shared Helper (routed through centralized Safety & BreakExecutor)
local function clearSingleTileWithLavaCheck(tx, ty, layers, hitGap, showHand, noCollect, aliveFn)
    local gt = H and H.gt
    if not gt or tx < 0 or tx >= gt.w or ty < 0 or ty >= gt.h then return false end
    local tmpCtx = ClearWorld._activeCtx or {
        w = gt.w,
        h = gt.h,
        maxY = gt.h - 1,
        noCollect = (noCollect == true) or (ClearWorld.State.noCollect == true),
        safety = CW.Safety.detectBedrockBoundary(gt.w, gt.h),
        skip = CW.SkipManager.create(),
        reservedTargets = {},
        targets = {},
        rowRemaining = {},
        colRowDirty = {},
        progress = { initialTargets = 0, completedCount = 0, remainingCount = 0, blockedCount = 0, skippedCount = 0, failedCount = 0, breaksSinceReconcile = 0 },
    }
    if ty + 1 <= tmpCtx.maxY and CW.Safety.isHazardAt(tx, ty + 1) then
        CW.BreakExecutor.clearHazardSafely(tmpCtx, tx, ty + 1, aliveFn or function() return true end)
    end
    if CW.MoveController.moveIntoBreakReach(tmpCtx, tx, ty, aliveFn or function() return true end) then
        local batch = {}
        for _, lyr in ipairs(layers or { 1, 2 }) do
            batch[#batch + 1] = { x = tx, y = ty, layer = lyr }
        end
        CW.BreakExecutor.breakBatch(tmpCtx, batch, hitGap or 0.194, aliveFn or function() return true end)
    end
    return true
end

-- Public Dashboard & Lifecycle API (100% compatible with SYT.lua & AutoLevel)
function ClearWorld.GetDashboard()
    if ClearWorld._activeCtx then CW.Logger.syncDashboard(ClearWorld._activeCtx) end
    return ClearWorld.State.dashboard
end

function ClearWorld.GetLogs(limit)
    local logs = (ClearWorld._activeCtx and ClearWorld._activeCtx.logs) or ClearWorld.State.dashboard.logs or {}
    if not limit or limit >= #logs then return logs end
    local out = {}
    for i = math.max(1, #logs - limit + 1), #logs do
        out[#out + 1] = logs[i]
    end
    return out
end

function ClearWorld.Stop(keepSaved)
    if Core and Core.ClearManualInput then Core.ClearManualInput() end
    if H then H.dfSpeedForceUntil = 0 end
    ClearWorld.State.running = false
    ClearWorld.State.switchingWorld = false
    ClearWorld.State.sessionToken = (ClearWorld.State.sessionToken or 0) + 1
    if ClearWorld._activeCtx then
        ClearWorld._activeCtx.reservedTargets = {}
        ClearWorld._activeCtx = nil
    end
    if ClearWorld.State.thread then
        if task and task.cancel then pcall(task.cancel, ClearWorld.State.thread) end
        ClearWorld.State.thread = nil
    end
    if not keepSaved then
        CW.WorldQueue.clearRotSession()
        if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("CwRunToggle", false) end
    end
    setCwStatus("Stopped")
    return false
end

function ClearWorld.Start(opts)
    opts = opts or {}
    if not opts.fromAutoLevel and type(guardExclusiveStart) == "function" and not guardExclusiveStart("ClearWorld") then
        if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("CwRunToggle", false) end
        return false
    end
    if Core and Core.EnsureInit then Core.EnsureInit() end
    if Core and Core.EnsureManualInputHook then Core.EnsureManualInputHook() end
    if Core and Core.SyncOneHitHook then Core.SyncOneHitHook() end
    if SystemModule and SystemModule.State then SystemModule.State.frozenByJoin = false end

    local S = ClearWorld.State
    if S.running then return true end
    if opts.halfWorld ~= nil then S.halfWorldMode = (opts.halfWorld == true) end
    if opts.noCollect ~= nil then S.noCollect = (opts.noCollect == true) end
    S._worldLockedOrEmpty = false
    S.running = true
    S.progress = 0
    S.sessionToken = (S.sessionToken or 0) + 1
    local tok = S.sessionToken
    local function alive() return S.running and S.sessionToken == tok end

    if not opts.fromAutoLevel and UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("CwRunToggle", true) end
    if UIHooks and UIHooks.updateButtons then UIHooks.updateButtons() end

    S.thread = task.spawn(function()
        local cwErr = nil
        local okCwRun, resCwErr = xpcall(function()
            while alive() do
                local gt = H and H.gt
                if not gt or (gt.name or "") == "" then
                    setCwStatus("Menunggu masuk world...")
                    CW.Util.wait(0.4)
                else
                    local curW = CW.Util.cleanWorld(gt.name)
                    local readyCw = true

                    -- Multi-world queue validation & verified switching (preserved & hardened)
                    if not opts.fromAutoLevel and #S.worldList > 0 then
                        local inQ = false
                        for _, w in ipairs(S.worldList) do
                            if w == curW then inQ = true; break end
                        end
                        if not inQ then
                            local firstW = S.worldList[1]
                            if firstW and firstW ~= "" and firstW ~= curW then
                                readyCw = false
                                CW.WorldQueue.saveRotSession(firstW, S.worldList, S.halfWorldMode, S.noCollect)
                                local okWarp = CW.WorldQueue.enterAndVerify(firstW, alive)
                                if not alive() then break end
                                if not okWarp then
                                    setCwStatus("Gagal masuk " .. firstW .. " (antrean dipertahankan)")
                                    CW.Util.wait(1.6)
                                end
                            end
                        else
                            CW.WorldQueue.saveRotSession(curW, S.worldList, S.halfWorldMode, S.noCollect)
                        end
                    elseif not opts.fromAutoLevel then
                        CW.WorldQueue.saveRotSession(curW, {}, S.halfWorldMode, S.noCollect)
                    end

                    if readyCw and alive() then
                        -- Ensure tiles are hydrated before scanning (fixes false-empty bug for BOTH normal & AutoLevel!)
                        CW.WorldScanner.waitForWorldHydration(curW, alive, 7.5)
                        if not alive() then break end

                        local ctx = {
                            worldName = curW,
                            w = (H.gt and H.gt.w) or 100,
                            h = (H.gt and H.gt.h) or 60,
                            maxY = 0,
                            halfWorldMode = S.halfWorldMode,
                            noCollect = S.noCollect,
                            skip = CW.SkipManager.create(),
                            reservedTargets = {},
                            lastCollectAt = 0,
                        }
                        CW.Logger.init(ctx)
                        CW.MoveController.init(ctx)
                        ClearWorld._activeCtx = ctx
                        CW.Logger.log(ctx, "WORLD", "Entered " .. curW)

                        local outcome = CW.Planner.runWorld(ctx, opts, alive)
                        if not alive() then break end

                        if outcome == "EMPTY_OR_LOCKED" then
                            if opts.fromAutoLevel then
                                S.progress = 0
                                S._worldLockedOrEmpty = true
                                setCwStatus("World terkunci / kosong -> skip")
                                S.running = false
                                break
                            end
                            S.progress = 100
                        end

                        if outcome == "EMPTY_OR_LOCKED" or outcome == "WORLD_COMPLETE" or outcome == "WORLD_COMPLETE_WITH_UNREACHABLE" then
                            local nextW = nil
                            if not opts.fromAutoLevel and #S.worldList > 0 then
                                for i = #S.worldList, 1, -1 do
                                    if S.worldList[i] == curW then table.remove(S.worldList, i) end
                                end
                                ClearWorld._syncEnvQueue(S.worldList)
                                if UIHooks and UIHooks.refreshCwList then UIHooks.refreshCwList() end
                                nextW = S.worldList[1]
                            end
                            if nextW and nextW ~= curW then
                                CW.WorldQueue.saveRotSession(nextW, S.worldList, S.halfWorldMode, S.noCollect)
                                CW.WorldQueue.enterAndVerify(nextW, alive)
                            else
                                if not opts.fromAutoLevel then CW.WorldQueue.clearRotSession() end
                                local msgDone = (outcome == "WORLD_COMPLETE_WITH_UNREACHABLE")
                                    and string.format("Clear World selesai (%d%%, sisa tidak terjangkau): %s", S.progress, curW)
                                    or ("Clear World Selesai: " .. curW)
                                setCwStatus(msgDone)
                                if not opts.fromAutoLevel and emitNotify then
                                    emitNotify("Clear World", msgDone)
                                end
                                S.running = false
                                break
                            end
                        end
                    end
                end
                CW.Util.wait(0.05)
            end
        end, function(err)
            cwErr = tostring(err or "unknown error")
            return debug.traceback(cwErr, 2)
        end)

        if not okCwRun and cwErr then
            local rawErr = tostring(cwErr):match("([^\r\n]+)") or "Runtime error"
            setCwStatus("Err: " .. rawErr:sub(1, 56))
            if warn then warn("[SYT ClearWorld Error]: " .. tostring(resCwErr)) end
        end

        if Core and Core.ClearManualInput then Core.ClearManualInput() end
        if H then H.dfSpeedForceUntil = 0 end
        ClearWorld.State.switchingWorld = false
        if ClearWorld._activeCtx then
            ClearWorld._activeCtx.reservedTargets = {}
            ClearWorld._activeCtx = nil
        end
        if ClearWorld.State.sessionToken == tok then
            ClearWorld.State.running = false
            ClearWorld.State.thread = nil
            if not opts.fromAutoLevel and UIHooks and UIHooks.syncRunToggle then
                UIHooks.syncRunToggle("CwRunToggle", false)
            end
            if UIHooks and UIHooks.updateButtons then UIHooks.updateButtons() end
        end
    end)

    return true
end

function ClearWorld.Toggle()
    if ClearWorld.State.running then return ClearWorld.Stop() end
    return ClearWorld.Start()
end
end

-- MoveBlock: Smart Cross-World & Same-World Block/Seed Mover + Anti-Take Drop Tile + Zero-Lag Batching
MoveBlock = {
    State = {
        takePos = nil, dropPos = nil,
        takeWorld = "", dropWorld = "",
        itemMode = "Auto (Block + Seed)", customItemId = 0,
        antiTakeDropTile = true, lockAntiTake = false,
        moveSpeed = 7.3, dropDelay = 0.15,
        switchingWorld = false,
        running = false, sessionToken = 0, thread = nil,
        status = "Idle", itemId = nil, progress = 0, movedCount = 0,
        antiTakeGraceUntil = 0, _lastDropSpots = {},
    }
}
SYT_Logic.MoveBlock = MoveBlock

function MoveBlock._setStatus(msg)
    MoveBlock.State.status = msg
    if UI then pcall(UI.SetValue, UI, "MoveBlockStatus", msg) end
end

function MoveBlock._getDropWorldClean()
    local S = MoveBlock.State
    local wRaw = (S.dropWorld ~= "" and S.dropWorld) or (S.dropPos and S.dropPos.world) or ""
    return sanitizeWorldSpec(wRaw, false)
end

function MoveBlock._getTakeWorldSpec()
    local S = MoveBlock.State
    local raw = tostring(S.takeWorld or "")
    local up = string.upper((raw:gsub("^%s*(.-)%s*$", "%1")))
    local wRaw = (up == "" or up == "CURRENT" or up == "HERE") and ((S.takePos and S.takePos.world ~= "" and S.takePos.world) or (H.gt and H.gt.name) or "") or raw
    return sanitizeWorldSpec(wRaw, true)
end

function MoveBlock._getDropWorldSpec()
    local S = MoveBlock.State
    local raw = tostring(S.dropWorld or "")
    local up = string.upper((raw:gsub("^%s*(.-)%s*$", "%1")))
    local wRaw = (up == "" or up == "CURRENT" or up == "HERE") and ((S.dropPos and S.dropPos.world ~= "" and S.dropPos.world) or "") or raw
    if wRaw == "" then wRaw = MoveBlock._getTakeWorldSpec() end
    return sanitizeWorldSpec(wRaw, true)
end

function MoveBlock.IsProtectedDrop(d)
    local S = MoveBlock.State
    if not S.antiTakeDropTile or type(d) ~= "table" or d.id == 112 then return false end
    if not (S.running or S.lockAntiTake or os.clock() < (S.antiTakeGraceUntil or 0)) then
        return false
    end
    local dp = S.dropPos
    if not dp then return false end
    local dropW = MoveBlock._getDropWorldClean()
    local curW = H.gt and cleanWorldName(H.gt.name) or ""
    if dropW ~= "" and curW ~= "" and curW ~= dropW then
        return false
    end
    local dx, dy = tonumber(d.x), tonumber(d.y)
    if not dx or not dy then return false end
    if math.abs(dx - (dp.x + 0.5)) <= 0.95 and math.abs(dy - (dp.y + 0.5)) <= 0.95 then
        return true
    end
    local spots = S._lastDropSpots
    if type(spots) == "table" then
        for i = 1, #spots do
            local sp = spots[i]
            if sp and (sp.world == "" or sp.world == curW)
                and math.abs(dx - sp.x) <= 0.75 and math.abs(dy - sp.y) <= 0.75 then
                return true
            end
        end
    end
    return false
end

function MoveBlock.IsProtectedDropUid(uid)
    if not uid or not MoveBlock.State.antiTakeDropTile then return false end
    local gt = H.gt
    if not gt or type(gt.dropList) ~= "function" then return false end
    local ok, drops = pcall(gt.dropList)
    if ok and type(drops) == "table" then
        for i = 1, #drops do
            local d = drops[i]
            if type(d) == "table" and d.uid == uid then
                return MoveBlock.IsProtectedDrop(d)
            end
        end
    end
    return false
end

Core.IsMoveBlockProtectedDrop = MoveBlock.IsProtectedDrop
Core.IsMoveBlockProtectedUid = MoveBlock.IsProtectedDropUid

function MoveBlock._ensureHooks()
    Core.EnsureInit()
    Core.EnsureTakeDropHook()
    if type(Core.EnsureOutboundFirewall) == "function" then Core.EnsureOutboundFirewall() end
end

function MoveBlock.SetTake()
    MoveBlock._ensureHooks()
    local pos = Core.ReadPos()
    local curW = H.gt and cleanWorldName(H.gt.name) or ""
    MoveBlock.State.takePos = { x = pos.tx, y = pos.ty, world = curW }
    if curW ~= "" then MoveBlock.State.takeWorld = curW end
    local disp = (curW ~= "") and string.format("(%d, %d) @ %s", pos.sx, pos.sy, curW) or string.format("(%d, %d)", pos.sx, pos.sy)
    MoveBlock._setStatus("Take=" .. disp)
    if UI then
        pcall(UI.SetValue, UI, "MoveTakeDisplay", disp)
        if curW ~= "" then pcall(UI.SetValue, UI, "MoveTakeWorldInput", curW) end
    end
    if SYT_Logic.SaveAllSettings then pcall(SYT_Logic.SaveAllSettings, false) end
end

function MoveBlock.SetDrop()
    MoveBlock._ensureHooks()
    local pos = Core.ReadPos()
    local curW = H.gt and cleanWorldName(H.gt.name) or ""
    MoveBlock.State.dropPos = { x = pos.tx, y = pos.ty, world = curW }
    MoveBlock.State._lastDropSpots = {}
    if curW ~= "" then MoveBlock.State.dropWorld = curW end
    local disp = (curW ~= "") and string.format("(%d, %d) @ %s", pos.sx, pos.sy, curW) or string.format("(%d, %d)", pos.sx, pos.sy)
    MoveBlock._setStatus("Drop=" .. disp)
    if UI then
        pcall(UI.SetValue, UI, "MoveDropDisplay", disp)
        if curW ~= "" then pcall(UI.SetValue, UI, "MoveDropWorldInput", curW) end
    end
    if SYT_Logic.SaveAllSettings then pcall(SYT_Logic.SaveAllSettings, false) end
end

function MoveBlock.Stop(keepSession)
    local wasRun = MoveBlock.State.running
    MoveBlock.State.running = false
    MoveBlock.State.switchingWorld = false
    MoveBlock.State.sessionToken += 1
    if wasRun and MoveBlock.State.antiTakeDropTile then
        MoveBlock.State.antiTakeGraceUntil = os.clock() + 3.0
    end
    if not keepSession then
        local ed = getEnv().__SYT_ENV_DATA
        if type(ed) == "table" and ed.rotSession and ed.rotSession.mode == "MoveBlock" then
            ed.rotSession = nil
        end
    end
    if MoveBlock.State.thread then
        pcall(task.cancel, MoveBlock.State.thread)
        MoveBlock.State.thread = nil
    end
    MoveBlock._setStatus("Stopped")
    if UIHooks.syncRunToggle then UIHooks.syncRunToggle("MoveRunToggle", false) end
    if UIHooks.updateButtons then UIHooks.updateButtons() end
end

function MoveBlock.Start()
    if MoveBlock.State.running then return true end
    if not guardExclusiveStart("MoveBlock") then
        if UIHooks.syncRunToggle then UIHooks.syncRunToggle("MoveRunToggle", false) end
        return false
    end
    if not MoveBlock.State.takePos or not MoveBlock.State.dropPos then
        emitNotify("Move Block", "Set Take dan Drop position dulu!")
        if UIHooks.syncRunToggle then UIHooks.syncRunToggle("MoveRunToggle", false) end
        return false
    end
    MoveBlock._ensureHooks()
    local S = MoveBlock.State
    S.running = true
    S.itemId = nil
    S.movedCount = 0
    S.switchingWorld = false
    S.sessionToken += 1
    local tok = S.sessionToken
    local function alive() return S.running and S.sessionToken == tok end
    if UIHooks.syncRunToggle then UIHooks.syncRunToggle("MoveRunToggle", true) end
    if UIHooks.updateButtons then UIHooks.updateButtons() end

    S.thread = task.spawn(function()
        local collectedIds = {}
        local badUids = {}

        local function isEligibleId(itemId)
            local id = tonumber(itemId)
            if not id or id <= 0 or id == 18 or id == 32 or id == 112 then return false end
            local mode = tostring(S.itemMode or "Auto (Block + Seed)")
            if mode == "Custom Item ID" then
                local cid = toInt(S.customItemId, 0) or 0
                return cid > 0 and id == cid
            elseif mode == "All Items (Non-Gem)" then
                return true
            end
            local info = Core.GetItemInfo(id)
            local isSeed = (info and (info.seed ~= nil or info.kind == "seed")) == true
            if mode == "Seeds Only" then
                return isSeed
            elseif mode == "Blocks Only" then
                return not isSeed and not (info and (info.kind == "tool" or info.kind == "consumable"))
            end
            -- Auto (Block + Seed): dukung semua block, background, platform, dan seed
            return not (info and info.kind == "tool")
        end

        local function syncRotSession(targetW)
            local ed = getEnv().__SYT_ENV_DATA or {}
            getEnv().__SYT_ENV_DATA = ed
            ed.rotSession = {
                mode = "MoveBlock",
                targetWorld = targetW,
                takePos = { x = S.takePos.x, y = S.takePos.y, world = S.takePos.world },
                dropPos = { x = S.dropPos.x, y = S.dropPos.y, world = S.dropPos.world },
                takeWorld = S.takeWorld,
                dropWorld = S.dropWorld,
                active = true,
                updatedAt = os.clock(),
            }
        end

        local function mbEnsureWorld(targetSpec)
            local wName, doorId = sanitizeWorldSpec(targetSpec, true)
            if wName == "" then return true end
            local curW = H.gt and cleanWorldName(H.gt.name) or ""
            if curW == wName and H.gt and (H.gt.w or 0) > 0 and type(H.gt.fg) == "table" then
                H.gt.stuckAt = nil
                return true
            end
            syncRotSession(targetSpec)
            S.switchingWorld = true
            H.intentionalSwitchUntil = os.clock() + 18.0
            MoveBlock._setStatus("Warp -> " .. tostring(targetSpec))
            local okWarp, rsn = Packets.EnterWorldDoor(targetSpec, alive)
            S.switchingWorld = false
            H.intentionalSwitchUntil = os.clock() + 3.0
            if not alive() or not okWarp then
                return false, rsn
            end
            Core.EnsureTakeDropHook()
            local dlDrop = os.clock() + 0.45
            while alive() and os.clock() < dlDrop do
                local okD, dList = pcall(H.gt.dropList)
                if okD and type(dList) == "table" and #dList > 0 then break end
                task.wait(0.06)
            end
            return true
        end

        local function mbWalkSmart(gx, gy, isDropStand)
            local cur = Core.ReadPos()
            local gt = H.gt
            local W, Hgt = (gt and gt.w) or 100, (gt and gt.h) or 60
            local cands = {}
            if isDropStand then
                for _, ox in ipairs({ -1, 1 }) do
                    local ax = gx + ox
                    if ax >= 0 and ax < W and not Core.IsSolid(ax, gy) then
                        cands[#cands + 1] = { x = ax, y = gy, side = (ox < 0) and "right" or "left" }
                    end
                end
            end
            if not Core.IsSolid(gx, gy) then
                cands[#cands + 1] = { x = gx, y = gy, side = nil }
            end
            if not isDropStand or #cands == 0 then
                for _, sc in ipairs(Packets.FindStandCandidates(gx, gy, 1)) do
                    cands[#cands + 1] = { x = sc.x, y = sc.y, side = nil }
                end
            end
            local walkSpd = clamp(tonumber(S.moveSpeed) or 7.3, 6.0, 11.5)
            for idx, c in ipairs(cands) do
                if not alive() then return false end
                cur = Core.ReadPos()
                if cur.tx == c.x and cur.ty == c.y then
                    return true, c
                end
                local okW, msgW = Packets.WalkPathTo(c.x, c.y, walkSpd, alive, { noSnap = true })
                if okW then return true, c end
                if not alive() then return false end
                H.stopMoveUntil = 0
                H.lastBlockedMoveToAt = 0
                if H.gt then H.gt.stuckAt = nil end
                task.wait(0.10)
                local okS = Packets.WalkTeleport({ tx = c.x, ty = c.y, mode = "step", stepSize = 2, stepDelay = 0.055, shouldContinueFn = alive })
                if okS then return true, c end
                if idx == 1 then task.wait(0.05) end
            end
            cur = Core.ReadPos()
            if math.abs(cur.tx - gx) <= 1 and math.abs(cur.ty - gy) <= 1 then
                return true, { x = cur.tx, y = cur.ty, side = nil }
            end
            return false, nil
        end

        local function scanTakeDrops(tp, dp, sameW)
            local list, roomAvailable = {}, false
            local gt = H.gt
            if not gt or type(gt.dropList) ~= "function" then return list, false end
            local okD, drops = pcall(gt.dropList)
            if not okD or type(drops) ~= "table" then return list, false end
            local now = os.clock()
            for i = 1, #drops do
                local d = drops[i]
                if type(d) == "table" and d.uid and d.x and d.y and (d.n or 0) > 0 then
                    if not (badUids[d.uid] and now < badUids[d.uid]) and isEligibleId(d.id) then
                        local onDropTile = sameW and (math.abs(d.x - (dp.x + 0.5)) <= 0.75 and math.abs(d.y - (dp.y + 0.5)) <= 0.75)
                        local distT = math.max(math.abs(d.x - (tp.x + 0.5)), math.abs(d.y - (tp.y + 0.5)))
                        if not onDropTile and distT <= 1.65 then
                            list[#list + 1] = { drop = d, dist = distT }
                            if Core.GetItemRoom(d.id) > 0 then
                                roomAvailable = true
                            end
                        end
                    end
                end
            end
            table.sort(list, function(a, b) return a.dist < b.dist end)
            return list, roomAvailable
        end

        local function getCarryingList(takeDropsList)
            local wantSet = {}
            for id, on in pairs(collectedIds) do
                if on then wantSet[id] = true end
            end
            if tostring(S.itemMode) == "Custom Item ID" and (toInt(S.customItemId, 0) or 0) > 0 then
                wantSet[toInt(S.customItemId, 0)] = true
            elseif type(takeDropsList) == "table" then
                for _, item in ipairs(takeDropsList) do
                    if item.drop and isEligibleId(item.drop.id) then
                        wantSet[item.drop.id] = true
                    end
                end
            end
            local out = {}
            for id, _ in pairs(wantSet) do
                local c = Core.CountItem(id)
                if c > 0 then out[#out + 1] = { id = id, n = c } end
            end
            table.sort(out, function(a, b) return a.id < b.id end)
            return out
        end

        while alive() do
            Core.EnsureInit()
            local tp = S.takePos
            local dp = S.dropPos
            if not tp or not dp then break end
            local takeSpec = MoveBlock._getTakeWorldSpec()
            local dropSpec = MoveBlock._getDropWorldSpec()
            local sameW = (sanitizeWorldSpec(takeSpec, true) == sanitizeWorldSpec(dropSpec, true))

            -- Phase 1: Cek apakah di Take World / butuh ambil drop lagi
            local carryingNow = getCarryingList(nil)
            local okTakeW = true
            local curSpec = H.gt and cleanWorldName(H.gt.name) or ""
            if #carryingNow > 0 and curSpec == cleanWorldName(dropSpec) and curSpec ~= cleanWorldName(takeSpec) then
                -- Sudah berada di Drop World sambil membawa barang -> langsung drop dulu
                okTakeW = false
            else
                local okW, rsnW = mbEnsureWorld(takeSpec)
                if not alive() then break end
                if not okW then
                    MoveBlock._setStatus("Gagal masuk Take: " .. tostring(rsnW or "timeout"))
                    task.wait(1.0)
                    okTakeW = false
                end
            end

            if okTakeW and alive() then
                local dropsHere, canFit = scanTakeDrops(tp, dp, sameW)
                carryingNow = getCarryingList(dropsHere)

                if #dropsHere == 0 and #carryingNow == 0 then
                    mbWalkSmart(tp.x, tp.y, false)
                    if not alive() then break end
                    pcall(Core.ClearStuckDropVisuals)
                    MoveBlock._setStatus(string.format("Menunggu drop di (%d,%d) | Moved:%d", tp.x + 1, tp.y + 1, S.movedCount))
                    local wDl = os.clock() + 0.25
                    while os.clock() < wDl and alive() do task.wait(0.05) end
                elseif canFit and #dropsHere > 0 then
                    local okAtTake = mbWalkSmart(tp.x, tp.y, false)
                    if not alive() then break end
                    if not okAtTake then
                        MoveBlock._setStatus(string.format("Terhalang ke Take (%d,%d)", tp.x + 1, tp.y + 1))
                        task.wait(0.35)
                    else
                        local failStreak = 0
                        while alive() do
                            local dNow, fitNow = scanTakeDrops(tp, dp, sameW)
                            if #dNow == 0 or not fitNow then break end
                            local beforeSnap = {}
                            for _, sl in ipairs(Core.GetBackpackSlots(true)) do
                                beforeSnap[sl.id] = (beforeSnap[sl.id] or 0) + (sl.n or 0)
                            end
                            local firstDrop = dNow[1].drop
                            local cp = Core.ReadPos()
                            if math.max(math.abs(firstDrop.x - cp.x), math.abs(firstDrop.y - (cp.y - 0.5))) > 2.2 then
                                Packets.WalkPathTo(math.floor(firstDrop.x), math.floor(firstDrop.y), clamp(tonumber(S.moveSpeed) or 7.3, 6.0, 11.5), alive, { noSnap = true })
                            end
                            MoveBlock._setStatus(string.format("Ambil %s x%d...", Core.GetItemName(firstDrop.id), firstDrop.n or 1))
                            local colRes = Packets.Collect({
                                radius = 2.6,
                                filterFn = function(d)
                                    if not isEligibleId(d.id) then return false end
                                    if sameW and math.abs(d.x - (dp.x + 0.5)) <= 0.75 and math.abs(d.y - (dp.y + 0.5)) <= 0.75 then
                                        return false
                                    end
                                    return math.max(math.abs(d.x - (tp.x + 0.5)), math.abs(d.y - (tp.y + 0.5))) <= 1.85
                                end,
                                stepMoveIfFar = false,
                                preferWalk = true,
                                collectDelay = 0,
                                shouldContinue = alive,
                            })
                            task.wait(0.03)
                            local gainedAny = false
                            for _, sl in ipairs(Core.GetBackpackSlots(true)) do
                                if isEligibleId(sl.id) and (sl.n or 0) > (beforeSnap[sl.id] or 0) then
                                    collectedIds[sl.id] = true
                                    S.itemId = sl.id
                                    gainedAny = true
                                end
                            end
                            if (colRes and (colRes.itemsTaken or 0) > 0) or gainedAny then
                                failStreak = 0
                            else
                                failStreak += 1
                                if failStreak >= 2 then
                                    badUids[firstDrop.uid] = os.clock() + 4.0
                                    pcall(Core.ClearStuckDropVisuals)
                                    break
                                end
                                task.wait(0.05)
                            end
                        end
                    end
                    carryingNow = getCarryingList(dropsHere)
                end
            end

            -- Phase 2: Antar semua block / seed yg sudah terkumpul ke Drop World / Drop Tile
            if alive() and #carryingNow > 0 then
                local okW, rsnW = mbEnsureWorld(dropSpec)
                if not alive() then break end
                if not okW then
                    MoveBlock._setStatus("Gagal masuk Drop: " .. tostring(rsnW or "timeout"))
                    task.wait(1.0)
                else
                    local okAtDrop, standChoice = mbWalkSmart(dp.x, dp.y, true)
                    if not alive() then break end
                    if not okAtDrop then
                        MoveBlock._setStatus(string.format("Terhalang ke Drop (%d,%d)", dp.x + 1, dp.y + 1))
                        task.wait(0.35)
                    else
                        local dropCurW = H.gt and cleanWorldName(H.gt.name) or ""
                        local prefSide = standChoice and standChoice.side or nil
                        for _, stack in ipairs(carryingNow) do
                            if not alive() then break end
                            local rem = Core.CountItem(stack.id)
                            while rem > 0 and alive() do
                                local qty = math.min(200, rem)
                                MoveBlock._setStatus(string.format("Drop %s x%d -> (%d,%d)", Core.GetItemName(stack.id), qty, dp.x + 1, dp.y + 1))
                                S._lastDropSpots[#S._lastDropSpots + 1] = { world = dropCurW, x = dp.x + 0.5, y = dp.y + 0.5 }
                                if #S._lastDropSpots > 12 then table.remove(S._lastDropSpots, 1) end
                                local okD = Packets.Drop(stack.id, qty, {
                                    preferSide = prefSide,
                                    exactX = dp.x + 0.5,
                                    exactY = dp.y + 0.5,
                                    shouldContinue = alive,
                                })
                                if okD then
                                    S.movedCount += qty
                                    S.antiTakeGraceUntil = os.clock() + 3.0
                                end
                                rem = Core.CountItem(stack.id)
                                if not okD then break end
                            end
                        end
                        MoveBlock._setStatus(string.format("Done Drop -> Total:%d", S.movedCount))
                        local dly = clamp(tonumber(S.dropDelay) or 0.15, 0.04, 3.0)
                        local endWait = os.clock() + dly
                        while os.clock() < endWait and alive() do task.wait(0.04) end
                    end
                end
            else
                local idleWait = os.clock() + 0.15
                while os.clock() < idleWait and alive() do task.wait(0.05) end
            end
        end

        S.switchingWorld = false
        if S.sessionToken == tok then
            S.running = false
            S.thread = nil
            local ed = getEnv().__SYT_ENV_DATA
            if type(ed) == "table" and ed.rotSession and ed.rotSession.mode == "MoveBlock" then
                ed.rotSession = nil
            end
            if UIHooks.syncRunToggle then UIHooks.syncRunToggle("MoveRunToggle", false) end
            if UIHooks.updateButtons then UIHooks.updateButtons() end
        end
    end)
    return true
end

function MoveBlock.Toggle()
    if MoveBlock.State.running then return MoveBlock.Stop() end
    return MoveBlock.Start()
end

-- System & Security + Auto Leveling (Target L10 via Half-World ClearWorld & 7-8 Random Letter Worlds)
SystemModule = {
    State = {
        enabled = true,      -- ON / OFF security (Default ON + FREEZE)
        mode = "FREEZE",     -- "FREEZE" | "LEAVE"
        discordLog = false,  -- Sync join log to DiscordHook
        frozenByJoin = false,
        joinLogs = {},       -- Scrollable join entries
        knownPlayers = {},
        safeCount = 0,
    }
}
SYT_Logic.System = SystemModule

function SystemModule._pushJoinLog(name, isStaff, actionTag)
    local stamp = os.date("%H:%M:%S")
    local roleTag = isStaff and "[MOD]" or "[PLAYER]"
    local line = string.format("[%s] %s %s -> %s", stamp, roleTag, tostring(name or "-"), tostring(actionTag or "JOIN"))
    table.insert(SystemModule.State.joinLogs, 1, { text = line, isStaff = isStaff == true, name = tostring(name or "-") })
    while #SystemModule.State.joinLogs > 80 do
        table.remove(SystemModule.State.joinLogs)
    end
    if SystemModule.State.discordLog and DiscordHook and DiscordHook.State.url ~= "" then
        task.spawn(function() pcall(DiscordHook.Send, line) end)
    end
    if UIHooks.refreshSysLog then pcall(UIHooks.refreshSysLog) end
end

function SystemModule.CheckWorldEntrants(preloadedPlrs)
    if not H.gt or (H.gt.name or "") == "" then return end
    local plrs = type(preloadedPlrs) == "table" and preloadedPlrs or Core.GetInWorldPlayers(false)
    local curWorld = cleanWorldName(H.gt.name)
    local currentSet = {}
    SystemModule.State._seedUntil = SystemModule.State._seedUntil or {}
    if not SystemModule.State._seedUntil[curWorld] then
        SystemModule.State._seedUntil[curWorld] = os.clock() + 4.0
    end
    local seedPass = os.clock() < SystemModule.State._seedUntil[curWorld]
    for _, p in ipairs(plrs) do
        local k = curWorld .. ":" .. tostring(p.userId)
        currentSet[k] = true
        if not SystemModule.State.knownPlayers[k] then
            SystemModule.State.knownPlayers[k] = true
            local actionDesc = seedPass and "ALREADY HERE" or (SystemModule.State.enabled and SystemModule.State.mode or "LOG ONLY")
            SystemModule._pushJoinLog(p.gameName, p.isStaff, actionDesc)
            if p.isStaff then
                emitNotify("MOD JOINED!", p.gameName .. " bergabung ke world!")
            end
            if H._pendingAutoLvlBoot == nil then
                local bootAutoLvl = safeReadStorage("syt_autolvl.dat")
                H._pendingAutoLvlBoot = (type(bootAutoLvl) == "string" and string.sub(bootAutoLvl, 1, 3) == "ON|")
            end
            local edSys = getEnv().__SYT_ENV_DATA
            local autoLvlGuard = (AutoLeveling and AutoLeveling.State and AutoLeveling.State.running)
                or (type(edSys) == "table" and type(edSys.rotSession) == "table" and edSys.rotSession.active == true and edSys.rotSession.mode == "AutoLeveling")
                or (H._pendingAutoLvlBoot == true)
            if SystemModule.State.enabled and not autoLvlGuard and not seedPass then
                SystemModule.State.safeCount = (SystemModule.State.safeCount or 0) + 1
                if SystemModule.State.mode == "LEAVE" then
                    stopAllAutomationImpl("SYSTEM LEAVE: " .. p.gameName)
                    if H.Net and type(H.Net.call) == "function" then
                        pcall(H.Net.call, "LeaveWorld")
                    elseif H.gt and type(H.gt.enter) == "function" then
                        pcall(H.gt.enter, "EXIT")
                    end
                else
                    SystemModule.State.frozenByJoin = true
                    stopAllAutomationImpl("SYSTEM FREEZE: " .. p.gameName)
                    Core.ClearManualInput()
                end
            end
        end
    end
    for k in pairs(SystemModule.State.knownPlayers) do
        if k:sub(1, #curWorld + 1) == (curWorld .. ":") and not currentSet[k] then
            SystemModule.State.knownPlayers[k] = nil
        end
    end
end

function SystemModule._random78World()
    local len = math.random(7, 8)
    local chars = {}
    for i = 1, len do
        chars[i] = string.char(math.random(65, 90))
    end
    return table.concat(chars)
end

AutoLeveling = {
    State = {
        running = false, sessionToken = 0, thread = nil, status = "Idle",
        targetLevel = 10, switchingWorld = false,
        targetWorld = "", completedWorlds = {}
    }
}
SYT_Logic.AutoLeveling = AutoLeveling

function AutoLeveling._setStatus(msg)
    AutoLeveling.State.status = tostring(msg or "")
    if UI then pcall(UI.SetValue, UI, "AutoLvlStatus", AutoLeveling.State.status) end
end

function AutoLeveling.GetLevel()
    if LP then
        local vs = Visual and Visual.State
        if vs and (tonumber(vs.spoofLevel) or 0) > 0 then
            if type(vs.origPlayerLevel) == "number" then return vs.origPlayerLevel end
            if type(vs.origLevel) == "number" then return vs.origLevel end
        else
            local lvAttr = LP:GetAttribute("PlayerLevel") or LP:GetAttribute("Level") or LP:GetAttribute("playerLevel") or LP:GetAttribute("level")
            if type(lvAttr) == "number" then return lvAttr end
        end
    end
    if H.gt and type(rawget(H.gt, "level")) == "number" then return rawget(H.gt, "level") end
    if H.stateObj and type(H.stateObj.state) == "function" then
        local okS, st = pcall(H.stateObj.state)
        if okS and type(st) == "table" then
            local slv = tonumber(st.level or st.playerLevel or st.lvl)
            if slv and slv >= 1 then return math.floor(slv) end
        end
    end
    local now = os.clock()
    if H._cachedCharLevel and (now - (H._cachedCharLevelAt or 0)) < 1.5 then
        return H._cachedCharLevel
    end
    local foundLv = 0
    if LP then
        pcall(function()
            local pg = LP:FindFirstChildOfClass("PlayerGui")
            local gg = pg and pg:FindFirstChild("GameGui")
            if gg then
                for _, obj in ipairs(gg:GetDescendants()) do
                    if obj:IsA("TextLabel") and obj.Visible then
                        local t = tostring(obj.Text or "")
                        local nStr = t:match("[Ll][Vv]%.?%s*(%d+)") or t:match("[Ll]evel%s*:?%s*(%d+)")
                        if nStr then
                            local n = tonumber(nStr)
                            if n and n >= 1 and n <= 999 then
                                foundLv = n
                                break
                            end
                        end
                    end
                end
            end
        end)
    end
    if foundLv > 0 then
        H._cachedCharLevel = foundLv
        H._cachedCharLevelAt = now
        return foundLv
    end
    return H._cachedCharLevel or 0
end

function AutoLeveling.RefreshLevelUi()
    local lv = AutoLeveling.GetLevel()
    local tgt = AutoLeveling.State.targetLevel or 10
    local curW = cleanWorldName(H.gt and H.gt.name or "")
    if UI then
        pcall(UI.SetValue, UI, "AutoLvlCurDisplay", string.format("Lv %d / Target Lv %d", lv, tgt))
        pcall(UI.SetValue, UI, "AutoLvlWorldDisplay", string.format("%s (%d%%)", curW ~= "" and curW or (AutoLeveling.State.targetWorld or "-"), tonumber(ClearWorld and ClearWorld.State and ClearWorld.State.progress) or 0))
    end
    return lv
end

function AutoLeveling.Stop(keepSaved)
    AutoLeveling.State.running = false
    AutoLeveling.State.switchingWorld = false
    AutoLeveling.State.sessionToken += 1
    Core.ClearManualInput()
    H.dfSpeedForceUntil = 0
    if AutoLeveling.State.thread then
        pcall(task.cancel, AutoLeveling.State.thread)
        AutoLeveling.State.thread = nil
    end
    if not keepSaved then
        H._pendingAutoLvlBoot = false
        AutoLeveling.State.targetWorld = ""
        safeWriteStorage("syt_autolvl.dat", "")
        local ed = getEnv().__SYT_ENV_DATA
        if type(ed) == "table" and ed.rotSession and ed.rotSession.mode == "AutoLeveling" then
            ed.rotSession = nil
        end
    end
    if ClearWorld and ClearWorld.State and ClearWorld.State.running then
        ClearWorld.Stop(true)
    end
    AutoLeveling._setStatus("Stopped")
    if not keepSaved and UIHooks.syncRunToggle then
        UIHooks.syncRunToggle("SysAutoLevelToggle", false)
    end
    if UIHooks.updateButtons then UIHooks.updateButtons() end
    return false
end

function AutoLeveling.Start()
    if AutoLeveling.State.running then return true end
    if not guardExclusiveStart("AutoLeveling") then
        if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SysAutoLevelToggle", false) end
        return false
    end
    Core.EnsureInit()
    Core.EnsureManualInputHook()
    Core.SyncOneHitHook()
    if SystemModule and SystemModule.State then
        SystemModule.State.frozenByJoin = false
    end
    local S = AutoLeveling.State
    S.running = true
    S.switchingWorld = false
    S.sessionToken += 1
    H._pendingAutoLvlBoot = false
    local tok = S.sessionToken
    local function alive() return S.running and S.sessionToken == tok end
    if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SysAutoLevelToggle", true) end

    -- Pastikan global auto-rerun siap sebelum teleport saat AutoLevel
    if type(Core.RegisterGlobalAutoRerun) == "function" then
        pcall(Core.RegisterGlobalAutoRerun)
    end

    local initWorld = cleanWorldName(H.gt and H.gt.name or "")
    S.targetWorld = initWorld ~= "" and initWorld or (S.targetWorld or "")
    safeWriteStorage("syt_autolvl.dat", "ON|" .. tostring(S.targetWorld or ""))
    do
        local ed = getEnv().__SYT_ENV_DATA or {}
        getEnv().__SYT_ENV_DATA = ed
        ed.rotSession = {
            mode = "AutoLeveling",
            targetWorld = S.targetWorld,
            completedWorlds = S.completedWorlds,
            active = true,
            updatedAt = os.clock(),
        }
    end
    if UIHooks.updateButtons then UIHooks.updateButtons() end

    S.thread = task.spawn(function()
        local alErr = nil
        local okAlRun, resAlErr = xpcall(function()
            local zeroProgRetries = {}
            local function pickUnusedRandomWorld(avoidW)
                for _ = 1, 12 do
                    local cand = SystemModule._random78World()
                    if cand ~= avoidW and not S.completedWorlds[cand] then
                        return cand
                    end
                end
                return SystemModule._random78World()
            end
            local function waitWorldLoaded(prevW, maxWaitSec)
                local dl = os.clock() + (maxWaitSec or 6.5)
                while alive() and os.clock() < dl do
                    Core.EnsureInit()
                    local g = H.gt
                    local nW = cleanWorldName(g and g.name or "")
                    if nW ~= "" and (prevW == "" or nW ~= prevW) and type(g and g.fg) == "table" and (g.w or 0) > 0 then
                        local fgCnt = 0
                        for yy = 0, (g.h or 60) - 1, 2 do
                            local row = g.fg[yy]
                            if type(row) == "table" then
                                for xx = 0, (g.w or 100) - 1, 4 do
                                    if (row[xx] or 0) ~= 0 then fgCnt += 1 end
                                end
                            end
                            if fgCnt >= 12 then break end
                        end
                        if fgCnt >= 12 then return true, nW end
                    end
                    task.wait(0.20)
                end
                return false, cleanWorldName(H.gt and H.gt.name or "")
            end
            local function warpToRandomWorld(curW, prefixLabel)
                local sinceWarp = os.clock() - (H._lastAutoLvlWarpAt or 0)
                if sinceWarp < 4.0 then
                    local gapDl = os.clock() + (4.0 - sinceWarp)
                    while alive() and os.clock() < gapDl do task.wait(0.15) end
                    if not alive() then return false end
                end
                local rw = pickUnusedRandomWorld(curW)
                S.targetWorld = rw
                safeWriteStorage("syt_autolvl.dat", "ON|" .. rw)
                local ed = getEnv().__SYT_ENV_DATA or {}
                getEnv().__SYT_ENV_DATA = ed
                ed.rotSession = { mode = "AutoLeveling", targetWorld = rw, completedWorlds = S.completedWorlds, active = true, updatedAt = os.clock() }
                S.switchingWorld = true
                H.intentionalSwitchUntil = os.clock() + 20.0
                H._lastAutoLvlWarpAt = os.clock()
                AutoLeveling._setStatus(string.format("Lv%d/%d | %s -> %s", AutoLeveling.GetLevel(), S.targetLevel, prefixLabel or "Warp", rw))
                local okRw = Packets.EnterWorldDoor(rw, alive)
                if okRw then
                    waitWorldLoaded(curW, 6.5)
                    if alive() then task.wait(0.45) end
                elseif alive() then
                    task.wait(1.6)
                end
                S.switchingWorld = false
                H.intentionalSwitchUntil = os.clock() + 5.0
                return okRw
            end

            while alive() do
                Core.EnsureInit()
                local lv = AutoLeveling.RefreshLevelUi()
                if lv >= S.targetLevel then
                    AutoLeveling._setStatus(string.format("Target Lv%d Tercapai!", lv))
                    safeWriteStorage("syt_autolvl.dat", "")
                    local ed = getEnv().__SYT_ENV_DATA
                    if type(ed) == "table" and ed.rotSession and ed.rotSession.mode == "AutoLeveling" then ed.rotSession = nil end
                    if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SysAutoLevelToggle", false) end
                    emitNotify("Auto Leveling", S.status)
                    break
                end

                local curW = cleanWorldName(H.gt and H.gt.name or "")
                local readyDl = os.clock() + 6.5
                while alive() and os.clock() < readyDl do
                    Core.EnsureInit()
                    curW = cleanWorldName(H.gt and H.gt.name or "")
                    if H.gt and curW ~= "" and curW ~= "START" and curW ~= "EXIT" and type(H.gt.fg) == "table" and (H.gt.w or 0) > 0 then
                        local fgReady = 0
                        for yy = 0, (H.gt.h or 60) - 1, 2 do
                            local r = H.gt.fg[yy]
                            if type(r) == "table" then
                                for xx = 0, (H.gt.w or 100) - 1, 4 do
                                    if (r[xx] or 0) ~= 0 then fgReady += 1 end
                                end
                            end
                            if fgReady >= 12 then break end
                        end
                        if fgReady >= 12 then break end
                    end
                    task.wait(0.20)
                end
                if not alive() then break end

                local isHubWorld = (curW == "" or curW == "START" or curW == "EXIT")
                local others = Core.GetInWorldPlayers(false)
                if isHubWorld or #others > 0 or S.completedWorlds[curW] then
                    warpToRandomWorld(curW, "Warp")
                else
                    S.targetWorld = curW
                    safeWriteStorage("syt_autolvl.dat", "ON|" .. curW)
                    local ed = getEnv().__SYT_ENV_DATA or {}
                    getEnv().__SYT_ENV_DATA = ed
                    ed.rotSession = { mode = "AutoLeveling", targetWorld = curW, completedWorlds = S.completedWorlds, active = true, updatedAt = os.clock() }
                    AutoLeveling._setStatus(string.format("Lv%d/%d | Half Clear %s", lv, S.targetLevel, curW))
                    if ClearWorld and ClearWorld.State and ClearWorld.State.running then
                        ClearWorld.Stop(true)
                    end
                    local okCw = ClearWorld.Start({ fromAutoLevel = true, halfWorld = true, noCollect = true })
                    local peakProg = 0
                    while okCw and ClearWorld.State.running and alive() do
                        peakProg = math.max(peakProg, tonumber(ClearWorld.State.progress) or 0)
                        AutoLeveling.RefreshLevelUi()
                        if AutoLeveling.GetLevel() >= S.targetLevel then
                            ClearWorld.Stop(true)
                            break
                        end
                        if #Core.GetInWorldPlayers(false) > 0 then
                            S.completedWorlds[curW] = true
                            ClearWorld.Stop(true)
                            break
                        end
                        AutoLeveling._setStatus(string.format("Lv%d/%d | %s (%d%%)", AutoLeveling.GetLevel(), S.targetLevel, cleanWorldName(H.gt and H.gt.name or curW), ClearWorld.State.progress or 0))
                        task.wait(0.4)
                    end
                    peakProg = math.max(peakProg, tonumber(ClearWorld.State.progress) or 0)
                    local worldLocked = ClearWorld and ClearWorld.State and ClearWorld.State._worldLockedOrEmpty == true
                    if alive() and AutoLeveling.GetLevel() < S.targetLevel then
                        if not okCw or peakProg >= 45 or worldLocked or #Core.GetInWorldPlayers(false) > 0 then
                            S.completedWorlds[curW] = true
                            warpToRandomWorld(curW, "Next Random")
                        else
                            zeroProgRetries[curW] = (zeroProgRetries[curW] or 0) + 1
                            if zeroProgRetries[curW] >= 2 then
                                S.completedWorlds[curW] = true
                                warpToRandomWorld(curW, "Next Random")
                            else
                                task.wait(0.6)
                            end
                        end
                    end
                end
                task.wait(0.25)
            end
        end, function(err)
            alErr = tostring(err or "unknown error")
            return debug.traceback(alErr, 2)
        end)
        if not okAlRun and alErr then
            local rawErr = tostring(alErr):match("([^\r\n]+)") or "Runtime error"
            local lineTail = rawErr:match(":(%d+:%s*.+)$")
            local cleanErr = lineTail and ("L" .. lineTail) or rawErr:gsub('^.-%[string%s+["\'][^"\']*["\']%]:', 'L')
            local shortErr = cleanErr:sub(1, 52)
            AutoLeveling._setStatus("Err: " .. shortErr)
            warn("[SYT AutoLeveling Error]: " .. tostring(resAlErr))
        end
        Core.ClearManualInput()
        if S.sessionToken == tok then
            S.running = false
            S.switchingWorld = false
            if ClearWorld and ClearWorld.State and ClearWorld.State.running then
                ClearWorld.Stop(true)
            end
            S.thread = nil
            if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SysAutoLevelToggle", false) end
            if UIHooks.updateButtons then UIHooks.updateButtons() end
        end
    end)
    return true
end

function AutoLeveling.Toggle()
    if AutoLeveling.State.running then return AutoLeveling.Stop() end
    return AutoLeveling.Start()
end

-- Override Misc Engine Features to match exact README.MD specifications:
-- 1. Ghost/NoClip (pure visual movement only - no server move - returns to start position on OFF)
function Misc.SetNoClip(enabled)
    Core.EnsureInit()
    Core.EnsureMoveHook()
    pcall(RunService.UnbindFromRenderStep, RunService, "SYT_NoClipStep")
    if H.noClipConn then
        pcall(function() H.noClipConn:Disconnect() end)
        H.noClipConn = nil
    end

    local gt = H.gt
    if not gt then
        Misc.State.noClip = false
        return false
    end

    local on = enabled == true
    if on then
        if Misc.State.fly then
            Misc.SetFly(false)
        end
        local pos = Core.ReadPos()
        local anchor = { x = pos.x, y = pos.y, tx = pos.tx, ty = pos.ty, sx = pos.sx, sy = pos.sy }
        Misc.State.noClipAnchor = anchor
        Misc.State.noClip = true
        -- Kunci posisi server pada posisi awal sebelum NoClip & aktifkan visual ghost
        Core.SetLocalCoords(anchor.x, anchor.y, 0, 0)
        gt.ghost = true
        gt.stuckAt = nil
        gt.portalGo = nil
        if type(SYT_Logic.InstallNetGuard) == "function" then pcall(SYT_Logic.InstallNetGuard) end
        if UI then
            pcall(UI.SetValue, UI, "MiscNoClipStatus", string.format("VISUAL ON | Anchor (%d,%d)", anchor.sx, anchor.sy))
        end

        local visX, visY = anchor.x, anchor.y
        local lastHudAt = 0
        local touchBtns = { left = {}, right = {}, up = {}, down = {} }
        local function scanTouchBtns()
            touchBtns = { left = {}, right = {}, up = {}, down = {} }
            pcall(function()
                local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
                local gg = pg and pg:FindFirstChild("GameGui")
                if gg then
                    for _, d in ipairs(gg:GetDescendants()) do
                        if d:IsA("GuiButton") and d.Visible then
                            local nm = string.lower(d.Name)
                            if string.find(nm, "left", 1, true) then table.insert(touchBtns.left, d)
                            elseif string.find(nm, "right", 1, true) then table.insert(touchBtns.right, d)
                            elseif string.find(nm, "jump", 1, true) or string.find(nm, "up", 1, true) then table.insert(touchBtns.up, d)
                            elseif string.find(nm, "down", 1, true) or string.find(nm, "crouch", 1, true) then table.insert(touchBtns.down, d) end
                        end
                    end
                end
            end)
        end
        local function anyTouchDown(list)
            for _, b in ipairs(list) do
                if b.Parent and b.Visible and b.GuiState == Enum.GuiState.Press then return true end
            end
            return false
        end
        scanTouchBtns()

        local alive = true
        RunService:BindToRenderStep("SYT_NoClipStep", Enum.RenderPriority.Last.Value + 18, function(dt)
            if not alive or getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN or not Misc.State.noClip or H.gt ~= gt then
                alive = false
                pcall(RunService.UnbindFromRenderStep, RunService, "SYT_NoClipStep")
                return
            end
            gt.ghost = true
            gt.stuckAt = nil
            gt.portalGo = nil

            local frameDt = clamp(tonumber(dt) or 0.016, 0.004, 0.06)
            local speed = 13.5
            local mvX, mvY = 0, 0
            if not UserInputService:GetFocusedTextBox() then
                if UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.Left) or anyTouchDown(touchBtns.left) then mvX -= 1 end
                if UserInputService:IsKeyDown(Enum.KeyCode.D) or UserInputService:IsKeyDown(Enum.KeyCode.Right) or anyTouchDown(touchBtns.right) then mvX += 1 end
                if UserInputService:IsKeyDown(Enum.KeyCode.W) or UserInputService:IsKeyDown(Enum.KeyCode.Up) or UserInputService:IsKeyDown(Enum.KeyCode.Space) or anyTouchDown(touchBtns.up) then mvY -= 1 end
                if UserInputService:IsKeyDown(Enum.KeyCode.S) or UserInputService:IsKeyDown(Enum.KeyCode.Down) or UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or anyTouchDown(touchBtns.down) then mvY += 1 end
            end

            if mvX ~= 0 or mvY ~= 0 then
                local mag = math.sqrt(mvX * mvX + mvY * mvY)
                if mag > 0 then mvX, mvY = mvX / mag, mvY / mag end
                visX = clamp(visX + mvX * speed * frameDt, 0.5, math.max(1, (gt.w or 100) - 0.5))
                visY = clamp(visY + mvY * speed * frameDt, 0.25, math.max(1, (gt.h or 60) - 0.5))
            end

            Core.SetLocalCoords(visX, visY, 0, 0)
            local now = os.clock()
            if UI and (now - lastHudAt) >= 0.30 then
                lastHudAt = now
                pcall(UI.SetValue, UI, "MiscNoClipStatus", string.format("VISUAL (%d,%d) | Anchor (%d,%d)", math.floor(visX) + 1, math.floor(visY) + 1, anchor.sx, anchor.sy))
            end
        end)
        H.noClipConn = {
            Disconnect = function()
                alive = false
                pcall(RunService.UnbindFromRenderStep, RunService, "SYT_NoClipStep")
            end
        }
        getEnv().__SYT_NOCLIP_CONN = H.noClipConn
    else
        local anchor = Misc.State.noClipAnchor
        Misc.State.noClip = false
        Misc.State.noClipAnchor = nil
        gt.ghost = (Misc.State.fly == true)
        gt.stuckAt = nil
        gt.portalGo = nil
        if anchor then
            local function restoreAnchor()
                if H.gt == gt and not Misc.State.noClip then
                    gt.stuckAt = nil
                    gt.portalGo = nil
                    Core.SetLocalCoords(anchor.x, anchor.y, 0, 0)
                end
            end
            restoreAnchor()
            Packets.SendRawMove(anchor.x, anchor.y, 0, 0, 2, { forceBypass = true })
            task.defer(restoreAnchor)
            task.delay(0.05, restoreAnchor)
            if UI then
                pcall(UI.SetValue, UI, "MiscNoClipStatus", string.format("OFF | Returned (%d,%d)", anchor.sx, anchor.sy))
            end
        elseif UI then
            pcall(UI.SetValue, UI, "MiscNoClipStatus", "Idle")
        end
    end
    return Misc.State.noClip
end

-- 2. Bounded Fly (max +5 up, max +-4 left/right from start, visual barrier indicators, fall on OFF)
do
local flyBarriers = {}
local function clearFlyBarriers()
    for _, b in ipairs(flyBarriers) do pcall(function() b:Destroy() end) end
    table.clear(flyBarriers)
end

local function showFlyBarrierFeedback(reasonTxt)
    local now = os.clock()
    if (H._lastFlyWallAt or 0) + 0.6 < now then
        H._lastFlyWallAt = now
        pcall(emitNotify, "Fly", reasonTxt)
    end
end

function Misc.SetFly(enabled)
    Core.EnsureInit()
    Core.EnsureMoveHook()
    unbindFlyRenderStep()
    clearFlyBarriers()
    if H.flyConn then H.flyConn:Disconnect(); H.flyConn = nil end
    Misc.State.fly = enabled == true
    local gt = H.gt
    if not gt then return false end

    if not Misc.State.fly then
        gt.ghost = (Misc.State.noClip == true)
        -- Jatuh dari posisi saat ini dan geser keluar jika overlap solid agar anti-stuck tidak respawn ke spawn
        if not snapOutOfSolidAtCurrentPos(gt) then
            local p = Core.ReadPos()
            Core.SetLocalCoords(p.x, p.y, 0, 0.2)
            Packets.SendRawMove(p.x, p.y, 0, 0, 0)
        end
        return false
    end

    pcall(Core.InstallAntiBackGuard)
    if type(SYT_Logic.InstallNetGuard) == "function" then pcall(SYT_Logic.InstallNetGuard) end
    local p0 = Core.ReadPos()
    local visX, visY = p0.x, p0.y
    local syncX, syncY = p0.x, p0.y
    local minX = math.max(0.5, p0.x - 4.0)
    local maxX = math.min(math.max(1, (gt.w or 100) - 0.5), p0.x + 4.0)
    local minY = math.max(0.35, p0.y - 5.0)
    local maxY = math.min(math.max(1, (gt.h or 60) - 0.5), p0.y + 0.5)
    local lastSyncAt, facing = os.clock(), 1

    -- Buat penanda batas visual blok pada HUD (atas -5, kiri -4, kanan +4)
    ensureExecCap()
    local parentHud = nil
    for _, cand in ipairs({ getSafeHui(), CoreGui, LP and LP:FindFirstChildOfClass("PlayerGui") }) do
        if cand and canReadInst(cand) then parentHud = cand; break end
    end
    if parentHud then
        local bgui = Instance.new("ScreenGui")
        bgui.Name = "SYT_FlyBarrierHud"
        bgui.IgnoreGuiInset = true
        bgui.ResetOnSpawn = false
        local okP = pcall(function() bgui.Parent = parentHud end)
        if okP and canAccessInst(bgui) then
            flyBarriers[#flyBarriers + 1] = bgui
            local pill = Instance.new("TextLabel", bgui)
            pill.Size = UDim2.fromOffset(196, 22)
            pill.AnchorPoint = Vector2.new(0.5, 0)
            pill.Position = UDim2.new(0.5, 0, 0, 38)
            pill.BackgroundColor3 = Color3.fromRGB(14, 19, 28)
            pill.BackgroundTransparency = 0.14
            pill.BorderSizePixel = 0
            pill.Active = false
            pill.Font = Enum.Font.GothamBold
            pill.TextSize = 10
            pill.TextColor3 = Color3.fromRGB(226, 232, 240)
            pill.Text = "FLY • X: -4..+4 | UP: +5"
            Instance.new("UICorner", pill).CornerRadius = UDim.new(0, 4)
            local stP = Instance.new("UIStroke", pill)
            stP.Color = Color3.fromRGB(56, 189, 248)
            stP.Thickness = 1
            stP.Transparency = 0.35
            flyBarriers[#flyBarriers + 1] = pill
        else
            pcall(function() bgui:Destroy() end)
        end
    end

    gt.ghost = true
    gt.stuckAt = nil
    H.lastSentMove = { x = syncX, y = syncY, vx = 0, vy = 0, flags = 3, t = lastSyncAt }
    Packets.SendRawMove(syncX, syncY, 0, 0, 3)

    local alive = true
    RunService:BindToRenderStep("SYT_FlyStep", Enum.RenderPriority.Last.Value + 20, function(dt)
        if not alive or getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN or not Misc.State.fly or H.gt ~= gt then
            alive = false
            unbindFlyRenderStep()
            clearFlyBarriers()
            return
        end
        gt.ghost = true
        gt.stuckAt = nil
        local frameDt = clamp(tonumber(dt) or 0.016, 0.004, 0.06)
        local speed = 10.5
        local mvX, mvY = 0, 0
        if not UserInputService:GetFocusedTextBox() then
            if UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.Left) then mvX -= 1 end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) or UserInputService:IsKeyDown(Enum.KeyCode.Right) then mvX += 1 end
            if UserInputService:IsKeyDown(Enum.KeyCode.W) or UserInputService:IsKeyDown(Enum.KeyCode.Up) or UserInputService:IsKeyDown(Enum.KeyCode.Space) then mvY -= 1 end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) or UserInputService:IsKeyDown(Enum.KeyCode.Down) then mvY += 1 end
        end
        if mvX == 0 and mvY == 0 and not H.autoMove then
            local raw = Core.ReadPos()
            local engDx, engDy = raw.x - visX, raw.y - visY
            local engDist = math.abs(engDx) + math.abs(engDy)
            if engDist > 0.002 and engDist <= 1.25 then
                mvX, mvY = engDx, engDy
            end
        end
        if mvX ~= 0 then facing = (mvX > 0) and 1 or -1 end
        local mag = math.sqrt(mvX * mvX + mvY * mvY)
        if mag > 0 then mvX, mvY = mvX / mag, mvY / mag end

        local nextX = visX + mvX * speed * frameDt
        local nextY = visY + mvY * speed * frameDt
        if nextX < minX then nextX = minX; showFlyBarrierFeedback("[BARRIER] Batas Kiri (-4)") end
        if nextX > maxX then nextX = maxX; showFlyBarrierFeedback("[BARRIER] Batas Kanan (+4)") end
        if nextY < minY then nextY = minY; showFlyBarrierFeedback("[BARRIER] Batas Atas (+5)") end
        if nextY > maxY then nextY = maxY end
        visX, visY = nextX, nextY
        Core.SetLocalCoords(visX, visY, 0, 0)

        local now = os.clock()
        local elapsed = now - lastSyncAt
        if elapsed >= 0.068 then
            local stepDx = clamp(visX - syncX, -1.0, 1.0)
            local stepDy = clamp(visY - syncY, -1.1, 1.1)
            syncX, syncY = syncX + stepDx, syncY + stepDy
            Packets.SendRawMove(syncX, syncY, 0, 0, (facing > 0 and 1 or 0) + 2)
            lastSyncAt = now
        end
    end)
    H.flyConn = { Disconnect = function() alive = false; unbindFlyRenderStep(); clearFlyBarriers() end }
    return true
end

-- 3. Zoom 2.5x Out (anti-overshoot render boundary + cached zoom hooks)
Misc.State.zoom25x = false
local ZoomCache = { gt = nil, scale = nil, viewport = nil, slots = nil, slotsAt = 0, lastVw = 0, lastVh = 0, lastSafe = nil, lastCheckAt = 0 }

local function unbindModZoomStep()
    pcall(RunService.UnbindFromRenderStep, RunService, "SYT_ModZoomStep")
end

local function readViewportDims(viewport)
    local vw, vh = 1280, 720
    if viewport and canAccessInst(viewport) then
        local ax, ay = viewport.AbsoluteSize.X, viewport.AbsoluteSize.Y
        if ax > 32 and ay > 32 then return ax, ay end
    end
    local cam = workspace.CurrentCamera
    if cam and cam.ViewportSize.X > 32 and cam.ViewportSize.Y > 32 then
        vw, vh = cam.ViewportSize.X, cam.ViewportSize.Y
    end
    return vw, vh
end

local function resolveZoomParts(gt)
    if gt and ZoomCache.gt == gt and canAccessInst(ZoomCache.scale) then
        local vw, vh = readViewportDims(ZoomCache.viewport)
        return ZoomCache.scale, ZoomCache.viewport, vw, vh
    end
    local worldScale = nil
    if H.renderFn then
        for idx = 1, 160 do
            local val = uv(H.renderFn, idx)
            if val == nil and idx > 110 then break end
            if typeof(val) == "Instance" and val:IsA("UIScale") then
                worldScale = val
                break
            end
        end
    end
    if not worldScale and LP then
        local pg = LP:FindFirstChildOfClass("PlayerGui")
        local gg = pg and pg:FindFirstChild("GameGui")
        if gg then
            for _, d in ipairs(gg:GetDescendants()) do
                if d:IsA("UIScale") and d.Parent and d.Parent.Name == "Camera" then
                    worldScale = d
                    break
                end
            end
        end
    end
    local viewport = (worldScale and worldScale.Parent and worldScale.Parent.Parent and worldScale.Parent.Parent:IsA("GuiObject")) and worldScale.Parent.Parent or nil
    ZoomCache.gt = gt
    ZoomCache.scale = worldScale
    ZoomCache.viewport = viewport
    ZoomCache.slots = nil
    local vw, vh = readViewportDims(viewport)
    return worldScale, viewport, vw, vh
end

local function computeSafeModZoomMin(gt, baseMin)
    local _, vp, vw, vh = resolveZoomParts(gt)
    local w = (gt and tonumber(rawget(gt, "w")) and gt.w > 1) and gt.w or 100
    local h = (gt and tonumber(rawget(gt, "h")) and gt.h > 1) and gt.h or 60
    -- Jaga agar layar saat zoom out tidak melebihi batas render world (w x h)
    local minPx = math.max(1, math.ceil(math.max(vw / math.max(1, w - 1), vh / math.max(1, h - 1))))
    local worldFitMin = minPx / 64
    local raw25x = baseMin / 2.5
    return clamp(math.max(raw25x, worldFitMin), 0.24, baseMin), vw, vh, vp
end

local function rebuildWorldTilePool(gt, viewport)
    if type(getconnections) ~= "function" or not gt or not viewport then return end
    local okC, conns = pcall(getconnections, viewport:GetPropertyChangedSignal("AbsoluteSize"))
    if okC and type(conns) == "table" then
        for _, c in ipairs(conns) do
            local fn = type(c) == "table" and (c.Function or c["function"]) or nil
            if type(fn) == "function" then
                local hasGt = false
                for idx = 1, 32 do
                    if uv(fn, idx) == gt then hasGt = true; break end
                end
                if hasGt then pcall(fn) end
            end
        end
    end
end

local function clampZoomInputUpvalues(gt, minAllowed, maxAllowed, forceRescan)
    if type(getconnections) ~= "function" or not gt then return end
    local minZ = clamp(tonumber(minAllowed) or 0.24, 0.24, 1.6)
    local maxZ = clamp(tonumber(maxAllowed) or 1.6, minZ, 2.0)
    local now = os.clock()
    if forceRescan or not ZoomCache.slots or ZoomCache.gt ~= gt or (now - (ZoomCache.slotsAt or 0)) >= 3.0 then
        local cached = {}
        for _, sig in ipairs({ UserInputService.InputChanged, UserInputService.TouchPinch }) do
            local okC, conns = pcall(getconnections, sig)
            if okC and type(conns) == "table" then
                for _, c in ipairs(conns) do
                    local fn = type(c) == "table" and (c.Function or c["function"]) or nil
                    if type(fn) == "function" then
                        local hasGt, numIndices = false, {}
                        for idx = 1, 8 do
                            local val = uv(fn, idx)
                            if val == gt then
                                hasGt = true
                            elseif type(val) == "number" and val >= 0.05 and val <= 2.5 then
                                numIndices[#numIndices + 1] = idx
                            end
                        end
                        if hasGt and #numIndices > 0 then
                            cached[#cached + 1] = { fn = fn, indices = numIndices }
                        end
                    end
                end
            end
        end
        ZoomCache.gt = gt
        ZoomCache.slots = cached
        ZoomCache.slotsAt = now
    end
    for _, entry in ipairs(ZoomCache.slots or {}) do
        for _, idx in ipairs(entry.indices) do
            local val = uv(entry.fn, idx)
            if type(val) == "number" then
                if val < minZ then
                    suv(entry.fn, idx, minZ)
                elseif val > maxZ then
                    suv(entry.fn, idx, maxZ)
                end
            end
        end
    end
end

function Misc.SetZoom25x(enabled)
    Core.EnsureInit()
    local on = enabled == true
    Misc.State.zoom25x = on
    local gt = H.gt
    if on then
        if Misc.State._origCamMaxZoom == nil and LP then
            pcall(function() Misc.State._origCamMaxZoom = LP.CameraMaxZoomDistance end)
        end
        if gt and Misc.State._hadOrigGtZoomMin == nil then
            local rawMin = rawget(gt, "zoomMin")
            Misc.State._hadOrigGtZoomMin = (type(rawMin) == "number")
            Misc.State._origGtZoomMin = (type(rawMin) == "number") and rawMin or 0.6
        end
        local baseMin = clamp(tonumber(Misc.State._origGtZoomMin) or 0.6, 0.35, 1.0)
        local safeMin, vw, vh, viewport = computeSafeModZoomMin(gt, baseMin)
        Misc.State._lastSafeZoomMin = safeMin
        ZoomCache.lastSafe, ZoomCache.lastVw, ZoomCache.lastVh, ZoomCache.lastCheckAt = safeMin, vw, vh, os.clock()

        if gt then
            gt.zoomMin = safeMin
        end
        if LP then
            pcall(function() LP:SetAttribute("ModZoom", true) end)
            pcall(function()
                if Misc.State._origCamMaxZoom then
                    LP.CameraMaxZoomDistance = math.min(400, Misc.State._origCamMaxZoom * 2.5)
                end
            end)
        end
        if gt then
            gt.zoomMin = safeMin
            rebuildWorldTilePool(gt, viewport)
            clampZoomInputUpvalues(gt, safeMin, 1.6, true)
        end

        unbindModZoomStep()
        local lastPoolZoomMin = safeMin
        pcall(RunService.BindToRenderStep, RunService, "SYT_ModZoomStep", Enum.RenderPriority.First.Value + 5, function()
            if not Misc.State.zoom25x or getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then
                unbindModZoomStep()
                return
            end
            local g = H.gt
            if not g then return end
            local now = os.clock()
            local cachedMin = ZoomCache.lastSafe or safeMin
            if rawget(g, "zoomMin") ~= cachedMin then
                g.zoomMin = cachedMin
            end
            if type(rawget(g, "zoom")) == "number" and g.zoom < cachedMin then
                g.zoom = cachedMin
            end
            local _, vp, curVw, curVh = resolveZoomParts(g)
            local sizeChanged = (curVw ~= ZoomCache.lastVw or curVh ~= ZoomCache.lastVh)
            if sizeChanged or ZoomCache.gt ~= g or (now - (ZoomCache.lastCheckAt or 0)) >= 0.25 then
                ZoomCache.lastCheckAt = now
                ZoomCache.lastVw, ZoomCache.lastVh = curVw, curVh
                local bMin = clamp(tonumber(Misc.State._origGtZoomMin) or 0.6, 0.35, 1.0)
                local curSafe = computeSafeModZoomMin(g, bMin)
                ZoomCache.lastSafe = curSafe
                Misc.State._lastSafeZoomMin = curSafe
                if rawget(g, "zoomMin") ~= curSafe then
                    g.zoomMin = curSafe
                end
                if math.abs(curSafe - lastPoolZoomMin) > 0.008 or sizeChanged then
                    lastPoolZoomMin = curSafe
                    rebuildWorldTilePool(g, vp)
                end
                clampZoomInputUpvalues(g, curSafe, 1.6, sizeChanged)
            end
        end)

        task.defer(function()
            if not Misc.State.zoom25x or getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then return end
            local g = H.gt
            if not g then return end
            local bMin = clamp(tonumber(Misc.State._origGtZoomMin) or 0.6, 0.35, 1.0)
            local sMin, _, _, vp = computeSafeModZoomMin(g, bMin)
            ZoomCache.lastSafe = sMin
            g.zoomMin = sMin
            rebuildWorldTilePool(g, vp)
            clampZoomInputUpvalues(g, sMin, 1.6, true)
        end)
    else
        unbindModZoomStep()
        ZoomCache.lastSafe = nil
        local baseMin = clamp(tonumber(Misc.State._origGtZoomMin) or 0.6, 0.35, 1.0)
        if LP then
            pcall(function() LP:SetAttribute("ModZoom", nil) end)
            pcall(function()
                if Misc.State._origCamMaxZoom then
                    LP.CameraMaxZoomDistance = Misc.State._origCamMaxZoom
                end
            end)
        end
        if gt then
            gt.zoomMin = Misc.State._hadOrigGtZoomMin and Misc.State._origGtZoomMin or nil
            if type(rawget(gt, "zoom")) == "number" and gt.zoom < baseMin then
                gt.zoom = baseMin
            end
            local _, viewport = resolveZoomParts(gt)
            rebuildWorldTilePool(gt, viewport)
            clampZoomInputUpvalues(gt, baseMin, 1.6, true)
        end
    end
    return on
end

-- 4. Skip Update Item
Misc.State.skipUpdateItem = false
function Misc.SetSkipUpdateItem(enabled)
    local on = enabled == true
    Misc.State.skipUpdateItem = on
    GetcSkipper.SetSkipUpdateItems(on)
    if H._skipUpdConn then H._skipUpdConn:Disconnect(); H._skipUpdConn = nil end
    if on then
        local function hideLoadingBanners()
            local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
            if not pg then return end
            for _, obj in ipairs(pg:GetDescendants()) do
                if obj:IsA("TextLabel") and obj.Visible then
                    local txt = string.lower(obj.Text or "")
                    if string.find(txt, "updating", 1, true) or string.find(txt, "entering", 1, true) then
                        local f = obj:FindFirstAncestorOfClass("Frame")
                        if f and f.Name ~= "Console" then f.Visible = false end
                    end
                end
            end
        end
        hideLoadingBanners()
        local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
        if pg then
            H._skipUpdConn = pg.DescendantAdded:Connect(function(obj)
                if Misc.State.skipUpdateItem and obj:IsA("TextLabel") and not H._skipUpdScanQueued then
                    H._skipUpdScanQueued = true
                    task.delay(0.6, function()
                        H._skipUpdScanQueued = false
                        if Misc.State.skipUpdateItem then hideLoadingBanners() end
                    end)
                end
            end)
        end
    end
    return on
end

-- 5. Slow Fall (2x lebih lambat dari jatuh normal)
Misc.State.slowFall = false
function Misc.SetSlowFall(enabled)
    local on = enabled == true
    Misc.State.slowFall = on
    pcall(RunService.UnbindFromRenderStep, RunService, "SYT_SlowFallStep")
    if on then
        local lastY, lastVelSet = nil, 0
        RunService:BindToRenderStep("SYT_SlowFallStep", Enum.RenderPriority.Last.Value + 10, function(dt)
            if not Misc.State.slowFall or getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then
                pcall(RunService.UnbindFromRenderStep, RunService, "SYT_SlowFallStep")
                return
            end
            local gt = H.gt
            if not gt or (gt.name or "") == "" or Misc.State.fly or Misc.State.noClip then
                lastY = nil
                return
            end
            local p = Core.ReadPos()
            if not p.grounded and p.vy > 0.45 then
                -- Kurangi kenaikan jatuh sebesar 50% (2x lebih lambat)
                if lastY and p.y > lastY then
                    local dy = p.y - lastY
                    local slowY = lastY + dy * 0.5
                    Core.SetLocalCoords(p.x, slowY, p.vx, p.vy * 0.5)
                    p.y = slowY
                end
                if os.clock() - lastVelSet > 0.08 then
                    lastVelSet = os.clock()
                    Core.SetLocalCoords(p.x, p.y, p.vx, math.min(p.vy, 6.5))
                end
            end
            lastY = p.y
        end)
    end
    return on
end
end

-- Enhance Spam per README.MD: Random `0..`9 per-word rainbow OR single prefix, REQUIRED empty check, send first then delay
do
Spam.State.maxLength = 85
Spam.State.rainbowOn = false
Spam.State.prefixOn = false
Spam.State.delay = 5.0

local function randColorCode()
    return "`" .. tostring(math.random(0, 9))
end

function Spam.FormatNextMessage()
    local S = Spam.State
    local raw = tostring(S.text or ""):sub(1, 85)
    if S.rainbowOn then
        local out = ""
        for w in raw:gmatch("%S+") do
            local colSeg = randColorCode() .. " " .. w
            local cand = (out == "") and colSeg or (out .. " " .. colSeg)
            if #cand <= 85 then
                out = cand
            else
                local plainCand = (out == "") and w or (out .. " " .. w)
                if #plainCand <= 85 then
                    out = plainCand
                else
                    break
                end
            end
        end
        return (out ~= "") and out or raw
    elseif S.prefixOn then
        local pfx = randColorCode() .. " "
        return pfx .. raw:sub(1, math.max(0, 85 - #pfx))
    end
    return raw
end

H._origSpamStop = Spam.Stop
function Spam.Stop()
    Spam.State.running = false
    Spam.State.sessionToken += 1
    if Spam.State.thread then
        pcall(task.cancel, Spam.State.thread)
        Spam.State.thread = nil
    end
    if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SpamRunToggle", false) end
    setSpamStatus("Stopped")
    return false
end

function Spam.Start()
    Core.EnsureInit()
    local S = Spam.State
    if S.running then return true end
    local curInput = UI and UI:GetValue("SpamTextInput")
    if type(curInput) == "string" and curInput ~= "REQUIRED" then
        S.text = curInput:sub(1, 85)
    end
    if not S.text or S.text == "" or S.text == "REQUIRED" then
        S.text = ""
        if UI then UI:SetValue("SpamTextInput", "REQUIRED") end
        setSpamStatus("REQUIRED: Isi pesan spam dulu!")
        emitNotify("Spam", "Text wajib diisi (REQUIRED)")
        if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SpamRunToggle", false) end
        return false
    end
    S.running = true
    S.sessionToken += 1
    local token = S.sessionToken
    local function alive() return S.running and S.sessionToken == token end
    setSpamStatus("Spamming...")
    if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SpamRunToggle", true) end

    S.thread = task.spawn(function()
        Core.EnsureOutboundFirewall()
        while alive() do
            if evaluateSeems() then break end
            if not H.gt or H.gt.name == "" then break end
            local msg = Spam.FormatNextMessage()
            Packets.SendChat({ message = msg, maxLength = 85, shouldContinue = alive })
            local d = clamp(tonumber(S.delay) or 5.0, 3.0, 7.0)
            local dl = os.clock() + d
            while os.clock() < dl and alive() do task.wait(0.05) end
        end
        if S.sessionToken == token then
            S.running = false
            S.thread = nil
            setSpamStatus("Stopped")
            if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SpamRunToggle", false) end
        end
    end)
    return true
end
end

-- Enhance PNB with README.MD Storage Block, Safe, Auto Buy (5x gems, 2s delay)
PNB.State.storageBlock = ""
PNB.State.storageSafe = ""
PNB.State.autoBuyKey = "OFF"
PNB.State.speedPct = 60
PNB.State.switchingWorld = false
PNB.State.progress = 0

function UIHooks.syncPnbToggle(val)
    if UIHooks.syncRunToggle then
        UIHooks.syncRunToggle("PnbRunToggle", val)
    end
end

H._origPnbStop = PNB.Stop
function PNB.Stop()
    PNB.State.running = false
    PNB.State.switchingWorld = false
    PNB.State.sessionToken += 1
    if PNB.State.thread then
        pcall(task.cancel, PNB.State.thread)
        PNB.State.thread = nil
    end
    Core.ClearManualInput()
    setPNBStatus("Stopped", "Idle", "Cycle: " .. tostring(PNB.State.cycles or 0))
    UIHooks.syncPnbToggle(false)
    if UIHooks.updateButtons then
        pcall(UIHooks.updateButtons)
        task.delay(0.62, function() if UIHooks.updateButtons then pcall(UIHooks.updateButtons) end end)
    end
    return false
end

H._origPnbStart = PNB.Start
function PNB.Start()
    if PNB.State.running then return true end
    if not guardExclusiveStart("PNB") then
        UIHooks.syncPnbToggle(false)
        return false
    end
    Core.EnsureInit()
    local S = PNB.State
    if not S.selectedBlockId then
        setPNBStatus("Pilih block di Block Selector!", "Waiting Block", "-")
        emitNotify("PNB", "Pilih block dulu di Block Selector!")
        UIHooks.syncPnbToggle(false)
        if UIHooks.updateButtons then pcall(UIHooks.updateButtons) end
        return false
    end
    if #PNB.GetActiveOffsets() == 0 then
        setPNBStatus("Pilih minimal 1 tile pada Pad 5x5", "Waiting Pad", "-")
        emitNotify("PNB", "Pilih minimal 1 tile di Pad 5x5!")
        UIHooks.syncPnbToggle(false)
        if UIHooks.updateButtons then pcall(UIHooks.updateButtons) end
        return false
    end
    if Core.CountItem(S.selectedBlockId) <= 0 and S.storageBlock == "" then
        setPNBStatus("Block habis & World Storage Block kosong", "No Block", "-")
        emitNotify("PNB", "Block habis di Backpack & Storage kosong!")
        UIHooks.syncPnbToggle(false)
        if UIHooks.updateButtons then pcall(UIHooks.updateButtons) end
        return false
    end

    if SystemModule and SystemModule.State then
        SystemModule.State.frozenByJoin = false
    end

    -- Speed 0-100% -> PNB.State.speed (1..10)
    local pct = clamp(tonumber(S.speedPct) or 60, 0, 100)
    S.speed = clamp(math.floor(1 + (pct / 100) * 9 + 0.5), 1, 10)
    S.oneHit = false

    S.running = true
    S.cycles = 0
    S.progress = 0
    S.sessionToken += 1
    local token = S.sessionToken
    local pos0 = Core.ReadPos()
    S.centerPos = { tx = pos0.tx, ty = pos0.ty }
    local pnbWorld = cleanWorldName(H.gt and H.gt.name or "")
    local function alive() return S.running and S.sessionToken == token end
    setPNBStatus("Running...", "Inspecting", "-")
    UIHooks.syncPnbToggle(true)
    if UIHooks.updateButtons then
        pcall(UIHooks.updateButtons)
        task.delay(0.62, function() if UIHooks.updateButtons then pcall(UIHooks.updateButtons) end end)
    end

    local function warpToStorageAndBack(spec, taskKind, extraPayload)
        if not spec or spec == "" then return false end
        local originPos = S.centerPos
        S.switchingWorld = true
        setPNBStatus("Storage: Masuk " .. spec, "Storage", taskKind)
        local okW = Packets.EnterWorldDoor(spec, alive)
        if okW and alive() then
            if taskKind == "fetch" then
                local gt = H.gt
                if gt and type(gt.dropList) == "function" then
                    local okD, drops = pcall(gt.dropList)
                    if okD and type(drops) == "table" then
                        for _, d in ipairs(drops) do
                            if not alive() or Core.GetItemRoom(S.selectedBlockId) <= 0 then break end
                            if type(d) == "table" and d.id == S.selectedBlockId and (d.n or 0) > 0 then
                                Packets.WalkTeleport({ tx = math.floor(d.x), ty = math.floor(d.y), mode = "walk" })
                                Packets.Collect({ radius = 3, filterId = S.selectedBlockId, stepMoveIfFar = true, preferWalk = true, collectDelay = 0.05, shouldContinue = alive })
                            end
                        end
                    end
                end
            elseif taskKind == "safe" and type(extraPayload) == "table" then
                for _, item in ipairs(extraPayload) do
                    if not alive() then break end
                    if Core.CountItem(item.id) >= item.amount then
                        Packets.Drop(item.id, item.amount)
                        SystemModule.State.safeCount = (SystemModule.State.safeCount or 0) + item.amount
                    end
                end
            end
        end
        if alive() and pnbWorld ~= "" then
            Packets.EnterWorldDoor(pnbWorld, alive)
            if alive() and originPos then
                Packets.WalkTeleport({ tx = originPos.tx, ty = originPos.ty, mode = "step", stepSize = 3 })
            end
        end
        S.switchingWorld = false
        return true
    end

    local function runAutoBuyCheck()
        local offer = findStoreOfferByDisplay(S.autoBuyKey)
        if not offer then return end
        local gems = Core.ReadGems()
        -- Minimal kelipatan 5 dari harga item sebelum memicu Auto Buy
        if gems < (offer.price * 5) then return end
        setPNBStatus(string.format("AutoBuy %s (Gems: %d >= 5x %d)", offer.name, gems, offer.price), "AutoBuy", offer.key)
        local beforeBp = {}
        for _, sl in ipairs(Core.GetBackpackSlots(true)) do
            if sl.id ~= 18 and sl.id ~= 32 and sl.id ~= 112 and sl.id ~= S.selectedBlockId then
                beforeBp[sl.id] = (beforeBp[sl.id] or 0) + (sl.n or 0)
            end
        end
        local boughtItems = {}
        while alive() do
            local curGems = Core.ReadGems()
            if curGems < offer.price then break end
            task.wait(0.45)
            if not alive() then break end
            local okB, resB = Packets.BuyStoreOffer(offer.key)
            task.wait(0.45)
            if not okB then break end
            if type(resB) == "table" and type(resB.items) == "table" then
                for _, pair in ipairs(resB.items) do
                    if type(pair) == "table" and pair[1] then
                        boughtItems[pair[1]] = true
                    end
                end
            end
        end
        for _, sl in ipairs(Core.GetBackpackSlots(true)) do
            if sl.id ~= 18 and sl.id ~= 32 and sl.id ~= 112 and sl.id ~= S.selectedBlockId then
                if (sl.n or 0) > (beforeBp[sl.id] or 0) then
                    boughtItems[sl.id] = true
                end
            end
        end
        if alive() and S.storageSafe ~= "" then
            local payload = {}
            for id in pairs(boughtItems) do
                local c = Core.CountItem(id)
                if c > 0 then payload[#payload + 1] = { id = id, amount = c } end
            end
            if #payload > 0 then warpToStorageAndBack(S.storageSafe, "safe", payload) end
        end
    end

    local function checkSafeMultiples()
        if S.storageSafe == "" then return end
        local payload = {}
        -- Kelipatan 10 untuk Locks (WL=242, Small=202, Big=204, Huge=206) dan 200 untuk seed/SSP box
        for _, lockId in ipairs({ 242, 202, 204, 206, 4994 }) do
            local cnt = Core.CountItem(lockId)
            if cnt >= 10 then
                payload[#payload + 1] = { id = lockId, amount = math.floor(cnt / 10) * 10 }
            end
        end
        for _, sl in ipairs(Core.GetBackpackSlots()) do
            if sl.id ~= S.selectedBlockId and sl.id ~= 18 and sl.id ~= 32 and sl.id ~= 112 and (sl.n or 0) >= 200 then
                local info = Core.GetItemInfo(sl.id)
                if info and (info.kind == "seed" or string.find(string.lower(info.name or ""), "pack", 1, true)) then
                    payload[#payload + 1] = { id = sl.id, amount = 200 }
                end
            end
        end
        if #payload > 0 then
            warpToStorageAndBack(S.storageSafe, "safe", payload)
        end
    end

    S.thread = task.spawn(function()
        local function coolIfFwBlocked()
            if H.fwLastBlockAt and (os.clock() - H.fwLastBlockAt) < 0.45 then
                task.wait(0.35)
            end
        end

        local function returnToPnbCenter()
            local cp = S.centerPos
            if not cp then return true end
            local nowP = Core.ReadPos()
            if math.abs(nowP.tx - cp.tx) > 0 or math.abs(nowP.ty - cp.ty) > 0 then
                Packets.WalkPathTo(cp.tx, cp.ty, 7.1, alive, { fastWalk = false, noSnap = true })
                nowP = Core.ReadPos()
            end
            local cxWant = cp.tx + 0.5
            local nudgeStart = os.clock()
            while alive() and math.abs((nowP.x or cxWant) - cxWant) > 0.14 and (os.clock() - nudgeStart) < 0.35 do
                Core.SetManualInput(((nowP.x or cxWant) < cxWant) and 1 or -1, false)
                task.wait(0.025)
                nowP = Core.ReadPos()
            end
            Core.ClearManualInput()
            local gWait = os.clock()
            while alive() and not nowP.grounded and (os.clock() - gWait) < 0.22 do
                task.wait(0.02)
                nowP = Core.ReadPos()
            end
            return true
        end

        while alive() do
            if not H.gt or H.gt.name == "" then setPNBStatus("Keluar world", "Idle", "-"); break end
            if SystemModule.State.enabled and SystemModule.State.frozenByJoin then
                setPNBStatus("Pause: Player/Mod Join", "Frozen", "-")
                break
            end
            runAutoBuyCheck()
            checkSafeMultiples()

            local bid = S.selectedBlockId
            local startCnt = Core.CountItem(bid)
            if startCnt <= 0 then
                if S.storageBlock ~= "" then
                    warpToStorageAndBack(S.storageBlock, "fetch")
                    if Core.CountItem(bid) <= 0 then
                        setPNBStatus("Block habis di BP & Storage", "Selesai", "-")
                        break
                    end
                else
                    setPNBStatus("Block habis di Backpack", "Selesai", "-")
                    break
                end
            end

            returnToPnbCenter()
            if not alive() then break end

            local info = Core.GetItemInfo(bid)
            local layer = (info and info.background) and 2 or 1
            local cp = S.centerPos or Core.ReadPos()
            local centerStand = { x = cp.tx + 0.5, y = cp.ty + 1 }
            local targets = {}
            for _, off in ipairs(PNB.GetActiveOffsets()) do
                local tx, ty = cp.tx + off.dx, cp.ty + off.dy
                if tx >= 0 and tx < H.gt.w and ty >= 0 and ty < H.gt.h and Core.CanEditTile(tx, ty) then
                    if not (info and info.solid and layer == 1 and tx == cp.tx and ty == cp.ty) then
                        if Core.IsInActionReach(tx, ty, "build", centerStand) and Core.IsInActionReach(tx, ty, "break", centerStand) then
                            targets[#targets + 1] = { tx = tx, ty = ty, layer = layer }
                        end
                    end
                end
            end
            if #targets == 0 then setPNBStatus("Pilih tile dalam jangkauan", "Idle", "-"); break end

            local placeGap = math.max(H.adaptivePlaceGap or 0.174, clamp(0.34 - (pct / 100) * 0.165, 0.174, 0.34))
            local hitDelay = math.max(0.192, clamp(0.28 - (pct / 100) * 0.088, 0.192, 0.28))
            local nThreads = (pct >= 70 and #targets >= 2) and 2 or 1
            local cycleWait = clamp(0.08 - (pct / 100) * 0.05, 0.025, 0.08)

            local breakOpts = {
                layer = layer, threads = nThreads,
                oneHit = (S.oneHit == true), customHits = nil,
                hitDelay = hitDelay, verifyTimeout = 0.26,
                stable = 0.04, noLocalMirror = false,
                autoRange = true, preferWalk = true, walkSpeed = 7.1,
                showHand = S.showHand, showVisual = true, shouldContinue = alive,
            }

            local snap = inspectPnbTargets(targets, bid, layer)
            if #snap.foreign > 0 then
                setPNBStatus(string.format("Pre-Clean %d tile asing...", #snap.foreign), "Clean", "-")
                for _ = 1, 3 do
                    if not alive() then break end
                    coolIfFwBlocked()
                    local _, failedF = Packets.BreakVerified(snap.foreign, {
                        layer = layer, threads = 1, oneHit = false, customHits = nil,
                        hitDelay = hitDelay, verifyTimeout = 0.26, noLocalMirror = false,
                        autoRange = true, preferWalk = true, walkSpeed = 7.1,
                        showHand = S.showHand, showVisual = true, shouldContinue = alive,
                    })
                    if failedF == 0 then break end
                end
                snap = inspectPnbTargets(targets, bid, layer)
            end

            if #snap.empty > 0 and Core.CountItem(bid) > 0 then
                setPNBStatus(string.format("Fase 1: Place (%d%%)", pct), "Place", "-")
                returnToPnbCenter()
                local placedThisRound, lastErrPl = 0, nil
                for round = 1, 2 do
                    if not alive() then break end
                    local curSnap = inspectPnbTargets(targets, bid, layer)
                    if #curSnap.empty == 0 or Core.CountItem(bid) <= 0 then break end
                    for _, t in ipairs(curSnap.empty) do
                        if not alive() or Core.CountItem(bid) <= 0 then break end
                        coolIfFwBlocked()
                        local okPl, errPl = Packets.PlaceVerified(t.tx, t.ty, bid, layer, {
                            showHand = S.showHand, delay = 0, noLocalMirror = false, optimisticFast = true,
                            autoRange = true, preferWalk = true, walkSpeed = 7.1,
                            placeGap = placeGap, verifyTimeout = 0.08, shouldContinue = alive,
                        })
                        if okPl or Core.GetLayerTile(t.tx, t.ty, layer) == bid then
                            placedThisRound += 1
                        else
                            lastErrPl = errPl
                        end
                    end
                end
                snap = inspectPnbTargets(targets, bid, layer)
                if placedThisRound == 0 and #snap.placed == 0 and lastErrPl then
                    setPNBStatus(string.format("Place tunggu (%s)...", tostring(lastErrPl)), "Wait", "-")
                end
            end

            if #snap.placed > 0 then
                setPNBStatus(string.format("Fase 2: Break (%d%%)", pct), "Break", "-")
                returnToPnbCenter()
                for _ = 1, 5 do
                    if not alive() then break end
                    local curS = inspectPnbTargets(targets, bid, layer)
                    if #curS.placed == 0 then break end
                    coolIfFwBlocked()
                    Packets.BreakVerified(curS.placed, breakOpts)
                end
                if S.autoCollect ~= false then
                    setPNBStatus(string.format("Fase 3: Collect (%d%%)", pct), "Collect", "-")
                    Packets.CollectVerified(targets, {
                        expectDrops = true, waitDrop = 0.14,
                        preferWalk = true, collectDelay = 0.02, shouldContinue = alive,
                    })
                    returnToPnbCenter()
                end
                S.cycles += 1
                S.progress = clamp(100 - math.floor((Core.CountItem(bid) / math.max(1, startCnt)) * 100), 1, 100)
                setPNBStatus(string.format("Cycle #%d | Sisa BP: %d", S.cycles, Core.CountItem(bid)), "OK", "Done")
            elseif snap.totalDrops > 0 and S.autoCollect ~= false then
                Packets.CollectVerified(targets, {
                    expectDrops = false, waitDrop = 0.10,
                    preferWalk = true, collectDelay = 0.02, shouldContinue = alive,
                })
                returnToPnbCenter()
            end
            task.wait(cycleWait)
        end
        if S.sessionToken == token then
            S.running = false
            S.thread = nil
            Core.ClearManualInput()
            UIHooks.syncPnbToggle(false)
            if UIHooks.refreshBP then UIHooks.refreshBP() end
            if UIHooks.updateButtons then UIHooks.updateButtons() end
        end
    end)
    return true
end

function PNB.Toggle()
    if PNB.State.running then
        return PNB.Stop()
    end
    return PNB.Start()
end


-- [2] INTELLIGENT PABRIK & PRODUCTION SCHEDULER (Refactored V3)
do
Pabrik = {
    State = {
        running = false,
        sessionToken = 0,
        thread = nil,
        status = "Idle",
        selectedTiles = {},
        selectedLines = {},
        blockId = nil,
        seedId = nil,
        itemName = "",
        breakPos = nil,
        breakTileCount = 3,
        breakEnabled = true,
        oneHit = false,
        showHand = true,
        placeDelay = 0.16,
        breakDelay = 0.192,
        collectDelay = 0.04,
        speedPct = 60,
        progress = 0,
        selectMode = "DERET",
        mapZoom = 1.0,
        maxBlockCapacity = 200,
        maxSeedCapacity = 200,
        nearCapacityMargin = 4,
        saveConfig = {
            enabled = false,
            world = "",
            pos = nil,
            blockId = nil,
            seedId = nil,
            maxBlock = 200,
            maxSeed = 200,
            saveBlockAmount = nil,
            saveSeedAmount = nil,
            mode = "BOTH",
            manualSaveRequested = false,
        },
        dashboard = {
            inventory = {},
            production = {},
            activity = {},
            logs = {},
        },
    },
    _sys = {},
    _activeCtx = nil,
}
SYT_Logic.Pabrik = Pabrik

local PF = Pabrik._sys

local function setPabrikStatus(msg)
    Pabrik.State.status = msg
    local tileCnt = 0
    for _ in pairs(Pabrik.State.selectedTiles) do tileCnt = tileCnt + 1 end
    local lineCnt = (type(Pabrik.GetConnectedLines) == "function") and #Pabrik.GetConnectedLines() or 0
    if UI then
        pcall(UI.SetValue, UI, "PabrikStatusDisplay", string.format("%s | Tiles: %d | Lines: %d", msg, tileCnt, lineCnt))
    end
    if UIHooks and UIHooks.updateButtons then UIHooks.updateButtons() end
end

-- Module 0: Shared Enums & Low-Level Utilities
do
    PF.ENUMS = {
        TILE_STATE = {
            EMPTY = "EMPTY",
            PLANT_PENDING = "PLANT_PENDING",
            PLANTING = "PLANTING",
            GROWING = "GROWING",
            READY = "READY",
            HARVEST_PENDING = "HARVEST_PENDING",
            HARVESTING = "HARVESTING",
            COLLECT_PENDING = "COLLECT_PENDING",
            BREAK_PENDING = "BREAK_PENDING",
            BREAKING = "BREAKING",
            VERIFYING = "VERIFYING",
            COMPLETED = "COMPLETED",
            BLOCKED = "BLOCKED",
            FAILED = "FAILED",
        },
        TASK_LIFECYCLE = {
            DISCOVERED = "DISCOVERED",
            RESERVED = "RESERVED",
            EXECUTING = "EXECUTING",
            VERIFYING = "VERIFYING",
            RETRY_PENDING = "RETRY_PENDING",
            COMPLETED = "COMPLETED",
            BLOCKED = "BLOCKED",
            FAILED = "FAILED",
        },
        DECISION = {
            SAFETY_ABORT = "SAFETY_ABORT",
            SAVE_INVENTORY = "SAVE_INVENTORY",
            COLLECT_PENDING = "COLLECT_PENDING",
            HARVEST_READY = "HARVEST_READY",
            PLANT_EMPTY = "PLANT_EMPTY",
            BREAK_REQUIRED = "BREAK_REQUIRED",
            RECOVERY = "RECOVERY",
            IDLE_RESCAN = "IDLE_RESCAN",
        },
        SAVE_MODE = {
            BOTH = "BOTH",
            BLOCK_ONLY = "BLOCK_ONLY",
            SEED_ONLY = "SEED_ONLY",
            SEPARATE = "SEPARATE",
        },
    }

    PF.Util = {}

    function PF.Util.now()
        return os.clock()
    end

    function PF.Util.wait(sec)
        if task and type(task.wait) == "function" then
            return task.wait(sec)
        end
        return sec
    end

    function PF.Util.clamp(v, lo, hi)
        if v < lo then return lo end
        if v > hi then return hi end
        return v
    end

    function PF.Util.toInt(v, def)
        if type(toInt) == "function" then return toInt(v, def) end
        local n = tonumber(v)
        if not n then return def end
        return math.floor(n)
    end

    function PF.Util.tileKey(x, y)
        if type(tileKey) == "function" then return tileKey(x, y) end
        return tostring(x) .. "," .. tostring(y)
    end

    function PF.Util.cleanWorld(name)
        if type(cleanWorldName) == "function" then return cleanWorldName(name) end
        return string.upper((tostring(name or ""):gsub("^%s*(.-)%s*$", "%1")))
    end

    function PF.Util.coolAntiKick()
        if H and H.fwLastBlockAt and (PF.Util.now() - H.fwLastBlockAt) < 0.45 then
            PF.Util.wait(0.28)
            return true
        end
        return false
    end

    function PF.Util.isProtectedOrImmutable(tx, ty, layer)
        local gt = H and H.gt
        if not gt or tx < 0 or tx >= gt.w or ty < 0 or ty >= gt.h then return true end
        if DirtFarm and DirtFarm._impl and type(DirtFarm._impl.isImmutableTile) == "function" then
            if DirtFarm._impl.isImmutableTile(tx, ty, nil, layer == 2) then
                return true
            end
        end
        if Core and Core.CanEditTile and not Core.CanEditTile(tx, ty) then return true end
        local cid = Core.GetLayerTile(tx, ty, layer or 1)
        if cid ~= 0 then
            if cid == 8 or cid == 6 then return true end
            if Core.IsProtectedTile and Core.IsProtectedTile(cid) then return true end
            local info = Core.GetItemInfo(cid)
            if not info or info.unbreakable == true or (type(info.hits) == "number" and info.hits <= 0) then
                return true
            end
        end
        return false
    end

    function PF.Util.getEnvTable()
        if type(getEnv) == "function" then
            local ok, e = pcall(getEnv)
            if ok and type(e) == "table" then return e end
        end
        return _G
    end
end

-- Module 1: Logger & Dashboard Manager
do
    local Logger = {}
    PF.Logger = Logger

    local MAX_LOGS = 120

    function Logger.init(ctx)
        ctx.logs = ctx.logs or {}
        ctx.stats = ctx.stats or {
            harvestedCount = 0,
            plantedCount = 0,
            brokenCount = 0,
            collectedBlocks = 0,
            collectedSeeds = 0,
            savedRuns = 0,
            failedTasks = 0,
        }
        ctx.activity = {
            world = ctx.productionWorld or "",
            posX = 0,
            posY = 0,
            action = "INIT",
            target = "-",
            taskStatus = "IDLE",
        }
    end

    function Logger.log(ctx, tag, msg)
        local line = string.format("[%s] %s", tostring(tag or "INFO"), tostring(msg or ""))
        if ctx and ctx.logs then
            ctx.logs[#ctx.logs + 1] = line
            if #ctx.logs > MAX_LOGS then
                table.remove(ctx.logs, 1)
            end
            Pabrik.State.dashboard.logs = ctx.logs
        end
        return line
    end

    function Logger.setActivity(ctx, action, targetCoord, taskStatus)
        if not ctx then return end
        local p = (Core and Core.ReadPos) and Core.ReadPos() or { tx = 0, ty = 0 }
        local gt = H and H.gt
        ctx.activity = {
            world = gt and PF.Util.cleanWorld(gt.name) or (ctx.productionWorld or ""),
            posX = p.tx or 0,
            posY = p.ty or 0,
            action = action or "IDLE",
            target = targetCoord or "-",
            taskStatus = taskStatus or "IDLE",
        }
        Logger.syncDashboard(ctx)
    end

    function Logger.syncDashboard(ctx)
        if not ctx then return end
        local TS = PF.ENUMS.TILE_STATE
        local total, emptyCnt, growingCnt, readyCnt, pendingCnt, failedCnt = 0, 0, 0, 0, 0, 0
        if ctx.placeTiles then
            for _, rec in pairs(ctx.placeTiles) do
                total = total + 1
                if rec.state == TS.EMPTY then emptyCnt = emptyCnt + 1
                elseif rec.state == TS.GROWING then growingCnt = growingCnt + 1
                elseif rec.state == TS.READY then readyCnt = readyCnt + 1
                elseif rec.state == TS.FAILED then failedCnt = failedCnt + 1
                elseif rec.state == TS.PLANT_PENDING or rec.state == TS.PLANTING
                    or rec.state == TS.HARVEST_PENDING or rec.state == TS.HARVESTING
                    or rec.state == TS.COLLECT_PENDING or rec.state == TS.VERIFYING then
                    pendingCnt = pendingCnt + 1
                end
            end
        end
        local inv = ctx.inv or {}
        Pabrik.State.dashboard = {
            inventory = {
                blockCount = inv.blockCount or 0,
                maxBlock = inv.maxBlock or Pabrik.State.maxBlockCapacity or 200,
                seedCount = inv.seedCount or 0,
                maxSeed = inv.maxSeed or Pabrik.State.maxSeedCapacity or 200,
                pendingBlockDrop = inv.pendingBlockDrop or 0,
                pendingSeedDrop = inv.pendingSeedDrop or 0,
                storageStatus = ctx.storageStatus or "IDLE",
            },
            production = {
                totalTile = total,
                emptyTile = emptyCnt,
                growingTile = growingCnt,
                readyTile = readyCnt,
                harvestedTile = ctx.stats and ctx.stats.harvestedCount or 0,
                plantedTile = ctx.stats and ctx.stats.plantedCount or 0,
                pendingTask = pendingCnt,
                failedTask = failedCnt + (ctx.stats and ctx.stats.failedTasks or 0),
            },
            activity = ctx.activity or {},
            logs = ctx.logs or {},
        }
    end
end

-- Module 2: Configuration Manager (Public Config & Selection APIs Preserved)
do
    local Config = {}
    PF.Config = Config

    function Config.computeBreakOffsets(count)
        local c = PF.Util.clamp(PF.Util.toInt(count, 3) or 3, 1, 3)
        if c == 1 then
            return { { dx = 0, dy = -1 } }
        elseif c == 2 then
            return { { dx = 0, dy = -1 }, { dx = 1, dy = -1 } }
        end
        -- Strictly 3 tiles directly above Break Position
        return { { dx = -1, dy = -1 }, { dx = 0, dy = -1 }, { dx = 1, dy = -1 } }
    end

    function Config.getSnapshot()
        local S = Pabrik.State
        local sc = S.saveConfig or {}
        local maxBlk = PF.Util.clamp(PF.Util.toInt(S.maxBlockCapacity, 200) or 200, 1, 200)
        local maxSd = PF.Util.clamp(PF.Util.toInt(S.maxSeedCapacity, 200) or 200, 1, 200)
        local saveMaxBlk = PF.Util.clamp(PF.Util.toInt(sc.maxBlock, maxBlk) or maxBlk, 1, maxBlk)
        local saveMaxSd = PF.Util.clamp(PF.Util.toInt(sc.maxSeed, maxSd) or maxSd, 1, maxSd)
        local pct = PF.Util.clamp(tonumber(S.speedPct) or 60, 0, 100)
        local factor = 0.35 + (pct / 100) * 1.15

        return {
            blockId = S.blockId,
            seedId = S.seedId,
            itemName = S.itemName or "",
            maxBlock = maxBlk,
            maxSeed = maxSd,
            nearMargin = PF.Util.clamp(PF.Util.toInt(S.nearCapacityMargin, 4) or 4, 1, 20),
            breakPos = S.breakPos and { x = math.floor(S.breakPos.x), y = math.floor(S.breakPos.y) } or nil,
            breakTileCount = PF.Util.clamp(PF.Util.toInt(S.breakTileCount, 3) or 3, 1, 3),
            breakEnabled = (S.breakEnabled ~= false),
            oneHit = (S.oneHit == true),
            showHand = (S.showHand ~= false),
            placeDelay = PF.Util.clamp(0.165 / factor, 0.145, 0.26),
            breakDelay = PF.Util.clamp(0.192 / factor, 0.192, 0.28),
            collectDelay = PF.Util.clamp(0.05 / factor, 0.015, 0.10),
            save = {
                enabled = (sc.enabled == true) and (tostring(sc.world or "") ~= ""),
                world = PF.Util.cleanWorld(sc.world or ""),
                pos = (type(sc.pos) == "table" and sc.pos.x and sc.pos.y)
                    and { x = math.floor(sc.pos.x), y = math.floor(sc.pos.y) } or nil,
                blockId = PF.Util.toInt(sc.blockId, S.blockId) or S.blockId,
                seedId = PF.Util.toInt(sc.seedId, S.seedId) or S.seedId,
                maxBlock = saveMaxBlk,
                maxSeed = saveMaxSd,
                saveBlockAmount = sc.saveBlockAmount and PF.Util.toInt(sc.saveBlockAmount, nil) or nil,
                saveSeedAmount = sc.saveSeedAmount and PF.Util.toInt(sc.saveSeedAmount, nil) or nil,
                mode = sc.mode or PF.ENUMS.SAVE_MODE.BOTH,
                manualSaveRequested = (sc.manualSaveRequested == true),
            },
        }
    end
end

-- Public Configuration & Tile Selection Functions (100% compatible with SYT.lua UI)
function Pabrik.GetConnectedLines()
    local rows = {}
    for _, pt in pairs(Pabrik.State.selectedTiles) do
        local y = pt.y
        rows[y] = rows[y] or {}
        rows[y][#rows[y] + 1] = pt.x
    end
    local lines = {}
    local ys = {}
    for y in pairs(rows) do ys[#ys + 1] = y end
    table.sort(ys)
    for _, y in ipairs(ys) do
        local xs = rows[y]
        table.sort(xs)
        local xStart, xPrev = xs[1], xs[1]
        for i = 2, #xs do
            if xs[i] <= xPrev + 1 then
                xPrev = xs[i]
            else
                lines[#lines + 1] = { y = y, x1 = xStart, x2 = xPrev, len = (xPrev - xStart + 1) }
                xStart, xPrev = xs[i], xs[i]
            end
        end
        lines[#lines + 1] = { y = y, x1 = xStart, x2 = xPrev, len = (xPrev - xStart + 1) }
    end
    return lines
end

function Pabrik.IsTilePlantable(tx, ty)
    local gt = H and H.gt
    tx, ty = PF.Util.toInt(tx), PF.Util.toInt(ty)
    if not gt or not tx or not ty or tx < 0 or tx >= gt.w or ty < 0 or ty >= gt.h - 1 then return false end
    if Core and Core.CanEditTile and not Core.CanEditTile(tx, ty) then return false end
    local curId = Core.GetFG(tx, ty)
    if curId ~= 0 then
        local cInfo = Core.GetItemInfo(curId)
        if not ((cInfo and cInfo.kind == "seed") or (Pabrik.State.blockId and curId == Pabrik.State.blockId)) then
            return false
        end
    end
    local belowId = Core.GetFG(tx, ty + 1)
    if belowId == 0 then return false end
    local bInfo = Core.GetItemInfo(belowId)
    if not bInfo or not (bInfo.solid == true or bInfo.platform == true) then return false end
    if bInfo.lock or bInfo.door or bInfo.deadly or bInfo.hurts or bInfo.kind == "seed" or bInfo.kind == "door" or bInfo.kind == "lock" then
        return false
    end
    return true
end

function Pabrik.ResolvePlantableTap(tx, ty)
    local gt = H and H.gt
    tx, ty = PF.Util.toInt(tx), PF.Util.toInt(ty)
    if not gt or not tx or not ty then return nil, nil end
    tx = PF.Util.clamp(tx, 0, gt.w - 1)
    ty = PF.Util.clamp(ty, 0, gt.h - 1)
    local k = PF.Util.tileKey(tx, ty)
    if Pabrik.IsTilePlantable(tx, ty) or Pabrik.State.selectedTiles[k] then
        return tx, ty
    end
    if ty > 0 and Core.GetFG(tx, ty) ~= 0 then
        local upK = PF.Util.tileKey(tx, ty - 1)
        if Pabrik.IsTilePlantable(tx, ty - 1) or Pabrik.State.selectedTiles[upK] then
            return tx, ty - 1
        end
    end
    return nil, nil
end

function Pabrik.PruneInvalidTiles()
    local S = Pabrik.State
    local removed = 0
    for k, t in pairs(S.selectedTiles) do
        if type(t) ~= "table" or not Pabrik.IsTilePlantable(t.x, t.y) then
            S.selectedTiles[k] = nil
            removed = removed + 1
        end
    end
    for y in pairs(S.selectedLines) do
        local anyY = false
        for _, t in pairs(S.selectedTiles) do
            if t.y == y then anyY = true; break end
        end
        if not anyY then S.selectedLines[y] = nil end
    end
    return removed
end

function Pabrik.ToggleTile(tx, ty)
    if Core and Core.EnsureInit then Core.EnsureInit() end
    local gt = H and H.gt
    tx, ty = PF.Util.toInt(tx), PF.Util.toInt(ty)
    if not tx or not ty or (gt and (tx < 0 or tx >= gt.w or ty < 0 or ty >= gt.h)) then return false end
    local k = PF.Util.tileKey(tx, ty)
    if Pabrik.State.selectedTiles[k] then
        Pabrik.State.selectedTiles[k] = nil
        setPabrikStatus(Pabrik.State.running and Pabrik.State.status or string.format("Hapus (%d, %d)", tx, ty))
        if UIHooks and UIHooks.refreshMap then UIHooks.refreshMap(true) end
        return false
    end
    if not Pabrik.IsTilePlantable(tx, ty) then
        setPabrikStatus("Bukan slot tanam (bawah harus block/platform!)")
        return false
    end
    Pabrik.State.selectedTiles[k] = { x = tx, y = ty }
    setPabrikStatus(Pabrik.State.running and Pabrik.State.status or string.format("Pilih (%d, %d)", tx, ty))
    if UIHooks and UIHooks.refreshMap then UIHooks.refreshMap(true) end
    return true
end

function Pabrik.ToggleLine(ty, refTx)
    if Core and Core.EnsureInit then Core.EnsureInit() end
    local gt = H and H.gt
    ty = PF.Util.toInt(ty)
    refTx = PF.Util.toInt(refTx)
    if not gt or not ty or ty < 0 or ty >= gt.h - 1 then return false end

    if refTx and Pabrik.State.selectedTiles[PF.Util.tileKey(refTx, ty)] then
        local lx, rx = refTx, refTx
        while lx > 0 and Pabrik.State.selectedTiles[PF.Util.tileKey(lx - 1, ty)] do lx = lx - 1 end
        while rx < gt.w - 1 and Pabrik.State.selectedTiles[PF.Util.tileKey(rx + 1, ty)] do rx = rx + 1 end
        for x = lx, rx do Pabrik.State.selectedTiles[PF.Util.tileKey(x, ty)] = nil end
        local anyLeft = false
        for x = 0, gt.w - 1 do
            if Pabrik.State.selectedTiles[PF.Util.tileKey(x, ty)] then anyLeft = true; break end
        end
        if not anyLeft then Pabrik.State.selectedLines[ty] = nil end
        setPabrikStatus(string.format("Hapus Deret Y=%d (%d..%d)", ty, lx, rx))
        if UIHooks and UIHooks.refreshMap then UIHooks.refreshMap(true) end
        return false
    end

    local runs, curRun = {}, nil
    for x = 0, gt.w - 1 do
        if Pabrik.IsTilePlantable(x, ty) then
            if not curRun then
                curRun = { x1 = x, x2 = x }
                runs[#runs + 1] = curRun
            else
                curRun.x2 = x
            end
        else
            curRun = nil
        end
    end
    if #runs == 0 then
        setPabrikStatus("Tidak ada deret tanam valid di Y=" .. tostring(ty))
        return false
    end

    local targetRun = nil
    if refTx then
        for _, r in ipairs(runs) do
            if refTx >= r.x1 and refTx <= r.x2 then targetRun = r; break end
        end
        if not targetRun then
            setPabrikStatus("Bawah tile ini tidak bisa ditanami seed")
            return false
        end
    end

    if targetRun then
        local alreadySelected = true
        for x = targetRun.x1, targetRun.x2 do
            if not Pabrik.State.selectedTiles[PF.Util.tileKey(x, ty)] then alreadySelected = false; break end
        end
        for x = targetRun.x1, targetRun.x2 do
            Pabrik.State.selectedTiles[PF.Util.tileKey(x, ty)] = (not alreadySelected) and { x = x, y = ty } or nil
        end
        Pabrik.State.selectedLines[ty] = (not alreadySelected) or nil
        setPabrikStatus(string.format("%s Deret Y=%d (%d..%d)", alreadySelected and "Hapus" or "Pilih", ty, targetRun.x1, targetRun.x2))
        if UIHooks and UIHooks.refreshMap then UIHooks.refreshMap(true) end
        return not alreadySelected
    end

    local added = 0
    for _, r in ipairs(runs) do
        for x = r.x1, r.x2 do
            Pabrik.State.selectedTiles[PF.Util.tileKey(x, ty)] = { x = x, y = ty }
            added = added + 1
        end
    end
    if added > 0 then Pabrik.State.selectedLines[ty] = true end
    setPabrikStatus(string.format("Pilih %d tile Y=%d", added, ty))
    if UIHooks and UIHooks.refreshMap then UIHooks.refreshMap(true) end
    return added > 0
end

function Pabrik.SelectAllPlantable()
    if Core and Core.EnsureInit then Core.EnsureInit() end
    local gt = H and H.gt
    if not gt then return 0 end
    Pabrik.State.selectedTiles = {}
    Pabrik.State.selectedLines = {}
    local cnt = 0
    for y = 0, gt.h - 2 do
        local rowHit = false
        for x = 0, gt.w - 1 do
            if Pabrik.IsTilePlantable(x, y) then
                Pabrik.State.selectedTiles[PF.Util.tileKey(x, y)] = { x = x, y = y }
                cnt = cnt + 1
                rowHit = true
            end
        end
        if rowHit then Pabrik.State.selectedLines[y] = true end
    end
    setPabrikStatus(string.format("Auto All Valid: %d tile tanam", cnt))
    if UIHooks and UIHooks.refreshMap then UIHooks.refreshMap(true) end
    return cnt
end

function Pabrik.ClearSelection()
    Pabrik.State.selectedTiles = {}
    Pabrik.State.selectedLines = {}
    setPabrikStatus("Pilihan dibersihkan")
    if UIHooks and UIHooks.refreshMap then UIHooks.refreshMap(true) end
end

function Pabrik.SetItem(idOrName)
    local pair = Core.ResolveBlockAndSeedPair(idOrName)
    if not pair then return nil end
    Pabrik.State.blockId = pair.blockId
    Pabrik.State.seedId = pair.seedId
    Pabrik.State.itemName = (pair.blockName and pair.blockName ~= "") and pair.blockName or pair.seedName
    if UI then
        pcall(UI.SetValue, UI, "PabrikPairDisplay", string.format("%s | Block:%s Seed:%s", Pabrik.State.itemName, tostring(pair.blockId), tostring(pair.seedId)))
    end
    if UIHooks and UIHooks.refreshPadPab then UIHooks.refreshPadPab() end
    return pair
end

function Pabrik.SetCapacities(maxBlock, maxSeed, nearMargin)
    if maxBlock then Pabrik.State.maxBlockCapacity = PF.Util.clamp(PF.Util.toInt(maxBlock, 200), 1, 200) end
    if maxSeed then Pabrik.State.maxSeedCapacity = PF.Util.clamp(PF.Util.toInt(maxSeed, 200), 1, 200) end
    if nearMargin then Pabrik.State.nearCapacityMargin = PF.Util.clamp(PF.Util.toInt(nearMargin, 4), 1, 20) end
    return Pabrik.State.maxBlockCapacity, Pabrik.State.maxSeedCapacity
end

function Pabrik.SetSaveConfig(cfg)
    if type(cfg) ~= "table" then return Pabrik.State.saveConfig end
    local sc = Pabrik.State.saveConfig
    if cfg.enabled ~= nil then sc.enabled = (cfg.enabled == true) end
    if cfg.world ~= nil then sc.world = PF.Util.cleanWorld(cfg.world) end
    if type(cfg.pos) == "table" and cfg.pos.x and cfg.pos.y then
        sc.pos = { x = math.floor(cfg.pos.x), y = math.floor(cfg.pos.y) }
    end
    if cfg.blockId ~= nil then sc.blockId = PF.Util.toInt(cfg.blockId, nil) end
    if cfg.seedId ~= nil then sc.seedId = PF.Util.toInt(cfg.seedId, nil) end
    if cfg.maxBlock ~= nil then sc.maxBlock = PF.Util.clamp(PF.Util.toInt(cfg.maxBlock, 200), 1, 200) end
    if cfg.maxSeed ~= nil then sc.maxSeed = PF.Util.clamp(PF.Util.toInt(cfg.maxSeed, 200), 1, 200) end
    if cfg.saveBlockAmount ~= nil then sc.saveBlockAmount = PF.Util.toInt(cfg.saveBlockAmount, nil) end
    if cfg.saveSeedAmount ~= nil then sc.saveSeedAmount = PF.Util.toInt(cfg.saveSeedAmount, nil) end
    if cfg.mode ~= nil then sc.mode = tostring(cfg.mode) end
    return sc
end

function Pabrik.RequestManualSave(flag)
    Pabrik.State.saveConfig.manualSaveRequested = (flag ~= false)
    return Pabrik.State.saveConfig.manualSaveRequested
end

function Pabrik.SetBreakPos(tx, ty)
    if tx == nil or ty == nil then
        local p = Core.ReadPos()
        tx, ty = p.tx, p.ty
    end
    Pabrik.State.breakPos = { x = math.floor(tx), y = math.floor(ty) }
    if UI then
        pcall(UI.SetValue, UI, "PabrikBreakPosDisplay", string.format("BreakPos (%d, %d) [%d tile]", Pabrik.State.breakPos.x, Pabrik.State.breakPos.y, Pabrik.State.breakTileCount))
    end
    if UIHooks and UIHooks.refreshPadPab then UIHooks.refreshPadPab() end
    if UIHooks and UIHooks.refreshMap then UIHooks.refreshMap(true) end
    return Pabrik.State.breakPos
end

function Pabrik.SetBreakCount(c)
    Pabrik.State.breakTileCount = PF.Util.clamp(PF.Util.toInt(c, 3) or 3, 1, 3)
    if Pabrik.State.breakPos and UI then
        pcall(UI.SetValue, UI, "PabrikBreakPosDisplay", string.format("BreakPos (%d, %d) [%d tile]", Pabrik.State.breakPos.x, Pabrik.State.breakPos.y, Pabrik.State.breakTileCount))
    end
    if UIHooks and UIHooks.refreshPadPab then UIHooks.refreshPadPab() end
    return Pabrik.State.breakTileCount
end

function Pabrik.GetSortedTiles()
    local list = {}
    for _, t in pairs(Pabrik.State.selectedTiles) do
        list[#list + 1] = { x = t.x, y = t.y }
    end
    table.sort(list, function(a, b)
        if a.y ~= b.y then return a.y < b.y end
        return (a.y % 2 == 0) and (a.x < b.x) or (a.x > b.x)
    end)
    return list
end

function Pabrik.GetDashboard()
    if Pabrik._activeCtx then PF.Logger.syncDashboard(Pabrik._activeCtx) end
    return Pabrik.State.dashboard
end

function Pabrik.GetLogs(limit)
    local logs = (Pabrik._activeCtx and Pabrik._activeCtx.logs) or Pabrik.State.dashboard.logs or {}
    if not limit or limit >= #logs then return logs end
    local out = {}
    for i = math.max(1, #logs - limit + 1), #logs do
        out[#out + 1] = logs[i]
    end
    return out
end

-- Module 3: Tile State Manager (Independent Per-Tile States + World Reconciliation)
do
    local TileState = {}
    PF.TileState = TileState

    function TileState.createRecord(x, y, zone)
        return {
            x = x,
            y = y,
            key = PF.Util.tileKey(x, y),
            zone = zone, -- "PLACE" or "BREAK"
            state = PF.ENUMS.TILE_STATE.EMPTY,
            fgId = 0,
            bgId = 0,
            ripe = false,
            remSec = nil,
            currentTaskId = nil,
            lastAction = nil,
            retryCount = 0,
            lastVerifiedFg = nil,
            lastVerifiedBg = nil,
            lastVerifiedAt = 0,
            reservedByTaskId = nil,
            failReason = nil,
        }
    end

    function TileState.reconcilePlaceTile(ctx, rec)
        local TS = PF.ENUMS.TILE_STATE
        local fg = Core.GetFG(rec.x, rec.y)
        local bg = Core.GetBG(rec.x, rec.y)
        local ripe = false
        local remSec = nil
        local seedId = ctx.cfg.seedId

        rec.fgId = fg
        rec.bgId = bg
        rec.lastVerifiedFg = fg
        rec.lastVerifiedBg = bg
        rec.lastVerifiedAt = PF.Util.now()

        -- Do not overwrite active in-flight reservation states unless world clearly contradicted
        if rec.reservedByTaskId ~= nil and (rec.state == TS.PLANTING or rec.state == TS.HARVESTING or rec.state == TS.VERIFYING) then
            return rec.state
        end

        -- Strict check: Place Position cannot conflict with Break targets or protected tiles
        if ctx.breakTargetSet[rec.key] then
            rec.state = TS.BLOCKED
            rec.failReason = "BREAK_ZONE_CONFLICT"
            return rec.state
        end
        if PF.Util.isProtectedOrImmutable(rec.x, rec.y, 1) then
            rec.state = TS.BLOCKED
            rec.failReason = "IMMUTABLE_OR_PROTECTED"
            return rec.state
        end

        if fg == seedId then
            ripe = (Core.IsTreeRipe and Core.IsTreeRipe(rec.x, rec.y) == true) or false
            if not ripe and Core.GetTreeRemainingSec then
                remSec = Core.GetTreeRemainingSec(rec.x, rec.y)
            end
            rec.ripe = ripe
            rec.remSec = remSec
            if rec.state ~= TS.FAILED then
                rec.state = ripe and TS.READY or TS.GROWING
                rec.failReason = nil
            end
        elseif fg == 0 then
            rec.ripe = false
            rec.remSec = nil
            if rec.state == TS.COLLECT_PENDING then
                -- Keep COLLECT_PENDING until CollectManager verifies drops collected
                return rec.state
            end
            if Pabrik.IsTilePlantable(rec.x, rec.y) then
                if rec.state ~= TS.FAILED then
                    rec.state = TS.EMPTY
                    rec.failReason = nil
                end
            else
                rec.state = TS.BLOCKED
                rec.failReason = "NOT_PLANTABLE"
            end
        else
            -- Foreign block occupying Place tile
            rec.ripe = false
            rec.remSec = nil
            rec.state = TS.BLOCKED
            rec.failReason = "FOREIGN_BLOCK_" .. tostring(fg)
        end

        return rec.state
    end

    function TileState.reconcileBreakTile(ctx, rec)
        local TS = PF.ENUMS.TILE_STATE
        local layer = ctx.blockLayer
        local fg = Core.GetFG(rec.x, rec.y)
        local bg = Core.GetBG(rec.x, rec.y)
        local cur = (layer == 2) and bg or fg

        rec.fgId = fg
        rec.bgId = bg
        rec.lastVerifiedFg = fg
        rec.lastVerifiedBg = bg
        rec.lastVerifiedAt = PF.Util.now()

        if rec.reservedByTaskId ~= nil and (rec.state == TS.BREAKING or rec.state == TS.VERIFYING) then
            return rec.state
        end

        if PF.Util.isProtectedOrImmutable(rec.x, rec.y, layer) or ctx.placeTileSet[rec.key] then
            rec.state = TS.BLOCKED
            rec.failReason = ctx.placeTileSet[rec.key] and "PLACE_ZONE_CONFLICT" or "PROTECTED_BREAK_TILE"
            return rec.state
        end

        if cur == 0 then
            rec.state = TS.EMPTY
            rec.failReason = nil
        elseif cur == ctx.cfg.blockId then
            rec.state = TS.BREAK_PENDING
            rec.failReason = nil
        else
            -- Foreign non-target block on break slot: NEVER blindly destroy foreign/supporting solid blocks
            rec.state = TS.BLOCKED
            rec.failReason = "NON_TARGET_BLOCK_" .. tostring(cur)
        end
        return rec.state
    end
end

-- Module 4: World Scanner (Incremental + Cached Scanning & Strict Break/Place Separation)
do
    local WorldScanner = {}
    PF.WorldScanner = WorldScanner

    function WorldScanner.validateBreakTargets(ctx)
        local gt = H and H.gt
        local bp = ctx.cfg.breakPos
        local targets = {}
        local targetSet = {}
        ctx.breakTiles = {}
        ctx.breakTargetList = targets
        ctx.breakTargetSet = targetSet

        if not gt or not bp then return targets end
        local bpPos = { x = bp.x + 0.5, y = bp.y + 1 }
        local bInfo = Core.GetItemInfo(ctx.cfg.blockId)
        local layer = ctx.blockLayer

        -- Strictly evaluate ONLY the configured 1..3 tiles directly ABOVE Break Position
        for _, off in ipairs(PF.Config.computeBreakOffsets(ctx.cfg.breakTileCount)) do
            local tx = bp.x + off.dx
            local ty = bp.y + off.dy
            local key = PF.Util.tileKey(tx, ty)
            local valid = true

            if tx < 0 or tx >= gt.w or ty < 0 or ty >= gt.h then valid = false end
            if valid and (tx == bp.x and ty == bp.y) then valid = false end
            -- Never overlap Place/Harvest Position
            if valid and ctx.placeTileSet[key] then valid = false end
            -- Never touch protected/immutable/bedrock tiles
            if valid and PF.Util.isProtectedOrImmutable(tx, ty, layer) then valid = false end
            -- Never destroy a ceiling tile that directly supports a selected Place tile or growing tree above it
            if valid and layer == 1 and ty > 0 then
                if ctx.placeTileSet[PF.Util.tileKey(tx, ty - 1)] then
                    valid = false
                else
                    local aboveId = Core.GetFG(tx, ty - 1)
                    if aboveId > 0 then
                        local aInf = Core.GetItemInfo(aboveId)
                        if aInf and aInf.kind == "seed" then valid = false end
                    end
                end
            end
            -- Never destroy foreign solid blocks already sitting there (only empty or target blockId)
            if valid then
                local cid = Core.GetLayerTile(tx, ty, layer)
                if cid ~= 0 and cid ~= ctx.cfg.blockId then
                    valid = false
                end
            end
            if valid and Core.CanPlaceBodyOk and not Core.CanPlaceBodyOk(tx, ty, bInfo, bpPos) then
                valid = false
            end
            if valid and Core.IsInActionReach then
                if not Core.IsInActionReach(tx, ty, "place", bpPos) or not Core.IsInActionReach(tx, ty, "break", bpPos) then
                    valid = false
                end
            end

            if valid then
                local rec = PF.TileState.createRecord(tx, ty, "BREAK")
                PF.TileState.reconcileBreakTile(ctx, rec)
                ctx.breakTiles[key] = rec
                targetSet[key] = true
                targets[#targets + 1] = rec
            end
        end
        return targets
    end

    function WorldScanner.scanAll(ctx)
        local gt = H and H.gt
        if not gt then return false end
        ctx.placeTiles = ctx.placeTiles or {}
        ctx.placeTileSet = {}
        local sorted = Pabrik.GetSortedTiles()

        -- Build placeTileSet first so validateBreakTargets enforces strict separation
        for _, t in ipairs(sorted) do
            ctx.placeTileSet[PF.Util.tileKey(t.x, t.y)] = true
        end

        WorldScanner.validateBreakTargets(ctx)

        -- Preserve existing tile records (retry counts, reservations) while reconciling with live world
        local activeKeys = {}
        for _, t in ipairs(sorted) do
            local k = PF.Util.tileKey(t.x, t.y)
            activeKeys[k] = true
            local rec = ctx.placeTiles[k]
            if not rec then
                rec = PF.TileState.createRecord(t.x, t.y, "PLACE")
                ctx.placeTiles[k] = rec
            end
            PF.TileState.reconcilePlaceTile(ctx, rec)
        end
        -- Prune deselected tiles
        for k in pairs(ctx.placeTiles) do
            if not activeKeys[k] then ctx.placeTiles[k] = nil end
        end

        ctx.lastFullScanAt = PF.Util.now()
        PF.Logger.log(ctx, "SCAN", string.format("World %s scanned | Place:%d Break:%d", PF.Util.cleanWorld(gt.name), #sorted, #ctx.breakTargetList))
        return true
    end

    -- Incremental rescan of specific coordinates + growing trees near readiness
    function WorldScanner.scanIncremental(ctx, specificCoords)
        if specificCoords then
            for _, c in ipairs(specificCoords) do
                local k = PF.Util.tileKey(c.x, c.y)
                if ctx.placeTiles[k] then
                    PF.TileState.reconcilePlaceTile(ctx, ctx.placeTiles[k])
                end
                if ctx.breakTiles[k] then
                    PF.TileState.reconcileBreakTile(ctx, ctx.breakTiles[k])
                end
            end
        end
        -- Check GROWING tiles only when their remaining time may have reached 0 (avoids redundant full scans)
        local now = PF.Util.now()
        local TS = PF.ENUMS.TILE_STATE
        for _, rec in pairs(ctx.placeTiles) do
            if rec.state == TS.GROWING then
                local elapsed = now - (rec.lastVerifiedAt or 0)
                if not rec.remSec or rec.remSec <= elapsed + 0.5 or elapsed >= 2.0 then
                    PF.TileState.reconcilePlaceTile(ctx, rec)
                end
            elseif rec.state == TS.READY or rec.state == TS.EMPTY then
                if (now - (rec.lastVerifiedAt or 0)) >= 1.5 then
                    PF.TileState.reconcilePlaceTile(ctx, rec)
                end
            end
        end
    end

    function WorldScanner.scanPendingDrops(ctx)
        local gt = H and H.gt
        local blkDrops, seedDrops = {}, {}
        local blkQty, seedQty = 0, 0
        if not gt or type(gt.dropList) ~= "function" then
            return { blockDrops = blkDrops, seedDrops = seedDrops, blockQty = 0, seedQty = 0 }
        end
        local ok, drops = pcall(gt.dropList)
        if not ok or type(drops) ~= "table" then
            return { blockDrops = blkDrops, seedDrops = seedDrops, blockQty = 0, seedQty = 0 }
        end
        local blkId = ctx.cfg.blockId
        local sdId = ctx.cfg.seedId
        for _, d in ipairs(drops) do
            if type(d) == "table" and (d.n or 0) > 0 and d.x and d.y then
                local tx = PF.Util.clamp(math.floor(d.x), 0, gt.w - 1)
                local ty = PF.Util.clamp(math.floor(d.y), 0, gt.h - 1)
                if d.id == blkId then
                    blkQty = blkQty + (d.n or 0)
                    blkDrops[#blkDrops + 1] = { id = d.id, n = d.n, x = tx, y = ty, rawX = d.x, rawY = d.y, uid = d.uid }
                elseif d.id == sdId then
                    seedQty = seedQty + (d.n or 0)
                    seedDrops[#seedDrops + 1] = { id = d.id, n = d.n, x = tx, y = ty, rawX = d.x, rawY = d.y, uid = d.uid }
                end
            end
        end
        return {
            blockDrops = blkDrops,
            seedDrops = seedDrops,
            blockQty = blkQty,
            seedQty = seedQty,
        }
    end
end

-- Module 5: Independent Inventory & Resource Reservation Manager
do
    local Inventory = {}
    PF.Inventory = Inventory

    function Inventory.create(ctx)
        ctx.inv = {
            blockCount = 0,
            seedCount = 0,
            maxBlock = ctx.cfg.maxBlock,
            maxSeed = ctx.cfg.maxSeed,
            nearMargin = ctx.cfg.nearMargin,
            pendingBlockDrop = 0,
            pendingSeedDrop = 0,
            seedReservations = {},
            reservedSeedsTotal = 0,
            saveBlockRequired = false,
            saveSeedRequired = false,
            saveRequired = false,
            nearBlockLimit = false,
            nearSeedLimit = false,
            lastUpdatedAt = 0,
        }
        return Inventory.refresh(ctx, true)
    end

    function Inventory.refresh(ctx, scanDrops)
        local inv = ctx.inv
        local cfg = ctx.cfg
        inv.maxBlock = cfg.maxBlock
        inv.maxSeed = cfg.maxSeed
        inv.blockCount = Core.CountItem(cfg.blockId)
        inv.seedCount = Core.CountItem(cfg.seedId)
        inv.lastUpdatedAt = PF.Util.now()

        if scanDrops then
            local dInfo = PF.WorldScanner.scanPendingDrops(ctx)
            inv.pendingBlockDrop = dInfo.blockQty
            inv.pendingSeedDrop = dInfo.seedQty
            ctx.latestDrops = dInfo
        end

        -- Threshold logic strictly uses >= (never ==)
        local saveBlkLimit = cfg.save.enabled and cfg.save.maxBlock or inv.maxBlock
        local saveSdLimit = cfg.save.enabled and cfg.save.maxSeed or inv.maxSeed
        inv.saveBlockRequired = (inv.blockCount >= saveBlkLimit)
        inv.saveSeedRequired = (inv.seedCount >= saveSdLimit)
        inv.nearBlockLimit = (inv.blockCount >= math.max(1, saveBlkLimit - inv.nearMargin))
        inv.nearSeedLimit = (inv.seedCount >= math.max(1, saveSdLimit - inv.nearMargin))

        local mode = cfg.save.mode or PF.ENUMS.SAVE_MODE.BOTH
        local manual = (Pabrik.State.saveConfig and Pabrik.State.saveConfig.manualSaveRequested == true)
        if manual then
            inv.saveRequired = true
        elseif mode == PF.ENUMS.SAVE_MODE.BLOCK_ONLY then
            inv.saveRequired = inv.saveBlockRequired
        elseif mode == PF.ENUMS.SAVE_MODE.SEED_ONLY then
            inv.saveRequired = inv.saveSeedRequired
        else
            inv.saveRequired = inv.saveBlockRequired or inv.saveSeedRequired
        end

        PF.Logger.syncDashboard(ctx)
        return inv
    end

    function Inventory.getAvailableSeeds(ctx)
        local inv = ctx.inv
        return math.max(0, (inv.seedCount or 0) - (inv.reservedSeedsTotal or 0))
    end

    function Inventory.reserveSeeds(ctx, taskId, amount)
        amount = math.max(1, math.floor(amount or 1))
        if Inventory.getAvailableSeeds(ctx) < amount then
            return false
        end
        ctx.inv.seedReservations[taskId] = amount
        ctx.inv.reservedSeedsTotal = (ctx.inv.reservedSeedsTotal or 0) + amount
        return true
    end

    function Inventory.releaseSeeds(ctx, taskId)
        local amt = ctx.inv and ctx.inv.seedReservations[taskId]
        if amt then
            ctx.inv.seedReservations[taskId] = nil
            ctx.inv.reservedSeedsTotal = math.max(0, (ctx.inv.reservedSeedsTotal or 0) - amt)
        end
    end

    function Inventory.getBlockRoom(ctx)
        local inv = ctx.inv
        local roomByCap = math.max(0, inv.maxBlock - inv.blockCount)
        if Core.GetItemRoom then
            return math.min(roomByCap, Core.GetItemRoom(ctx.cfg.blockId))
        end
        return roomByCap
    end

    function Inventory.getSeedRoom(ctx)
        local inv = ctx.inv
        local roomByCap = math.max(0, inv.maxSeed - inv.seedCount)
        if Core.GetItemRoom then
            return math.min(roomByCap, Core.GetItemRoom(ctx.cfg.seedId))
        end
        return roomByCap
    end

    -- Prevents harvesting when e.g. 199/200 would overflow block capacity
    function Inventory.canSafelyHarvest(ctx)
        local room = Inventory.getBlockRoom(ctx)
        if room <= 0 then return false end
        if ctx.inv.blockCount >= ctx.inv.maxBlock then return false end
        -- If only 1..2 slots remain and Save World is enabled, trigger Save before risking drop overflow
        if room <= 1 and ctx.cfg.save.enabled then
            return false
        end
        return true
    end

    function Inventory.canSafelyBreak(ctx)
        if ctx.inv.blockCount <= 0 then return false end
        if ctx.inv.seedCount >= ctx.inv.maxSeed then return false end
        if Inventory.getSeedRoom(ctx) <= 0 then return false end
        return true
    end
end

-- Module 6: Task Lifecycle & Duplicate Prevention Manager
do
    local TaskManager = {}
    PF.TaskManager = TaskManager

    local MAX_RETRIES = 3
    local RETRY_COOLDOWNS = { 0.35, 0.75, 1.35 }

    function TaskManager.create(ctx)
        ctx.tasks = {
            nextId = 1,
            byId = {},
            reservedByCoord = {},
            coordRetryState = {},
        }
    end

    function TaskManager.isCoordReserved(ctx, key)
        return ctx.tasks.reservedByCoord[key] ~= nil
    end

    function TaskManager.isCoordInBackoff(ctx, key)
        local rs = ctx.tasks.coordRetryState[key]
        if not rs then return false end
        if rs.failed then return true end
        return PF.Util.now() < (rs.nextRetryAt or 0)
    end

    function TaskManager.createAndReserve(ctx, kind, tileRec, opts)
        opts = opts or {}
        local LC = PF.ENUMS.TASK_LIFECYCLE
        local key = tileRec.key
        if TaskManager.isCoordReserved(ctx, key) then
            return nil, "ALREADY_RESERVED"
        end
        if TaskManager.isCoordInBackoff(ctx, key) then
            return nil, "RETRY_BACKOFF_OR_FAILED"
        end

        local id = ctx.tasks.nextId
        ctx.tasks.nextId = id + 1

        -- Reserve Seeds upfront for PLANT tasks so two tasks never consume the same seed
        if kind == "PLANT" then
            if not PF.Inventory.reserveSeeds(ctx, id, 1) then
                return nil, "NO_AVAILABLE_SEED"
            end
        end

        local taskObj = {
            id = id,
            kind = kind,
            key = key,
            x = tileRec.x,
            y = tileRec.y,
            tile = tileRec,
            state = LC.RESERVED,
            createdAt = PF.Util.now(),
            failReason = nil,
            opts = opts,
        }
        ctx.tasks.byId[id] = taskObj
        ctx.tasks.reservedByCoord[key] = id
        tileRec.reservedByTaskId = id
        tileRec.currentTaskId = id
        return taskObj, "OK"
    end

    function TaskManager.markExecuting(ctx, taskObj)
        taskObj.state = PF.ENUMS.TASK_LIFECYCLE.EXECUTING
        taskObj.tile.lastAction = taskObj.kind
    end

    function TaskManager.markVerifying(ctx, taskObj)
        taskObj.state = PF.ENUMS.TASK_LIFECYCLE.VERIFYING
        taskObj.tile.state = PF.ENUMS.TILE_STATE.VERIFYING
    end

    function TaskManager.complete(ctx, taskObj, newTileState)
        local LC = PF.ENUMS.TASK_LIFECYCLE
        taskObj.state = LC.COMPLETED
        PF.Inventory.releaseSeeds(ctx, taskObj.id)
        ctx.tasks.reservedByCoord[taskObj.key] = nil
        ctx.tasks.coordRetryState[taskObj.key] = nil
        taskObj.tile.reservedByTaskId = nil
        taskObj.tile.currentTaskId = nil
        taskObj.tile.retryCount = 0
        taskObj.tile.failReason = nil
        if newTileState then
            taskObj.tile.state = newTileState
        end
    end

    function TaskManager.fail(ctx, taskObj, reason, hardBlock)
        local LC = PF.ENUMS.TASK_LIFECYCLE
        local TS = PF.ENUMS.TILE_STATE
        PF.Inventory.releaseSeeds(ctx, taskObj.id)
        ctx.tasks.reservedByCoord[taskObj.key] = nil
        taskObj.tile.reservedByTaskId = nil
        taskObj.tile.currentTaskId = nil
        taskObj.failReason = reason or "UNKNOWN_ERROR"
        taskObj.tile.failReason = taskObj.failReason

        if hardBlock then
            taskObj.state = LC.BLOCKED
            taskObj.tile.state = TS.BLOCKED
            ctx.tasks.coordRetryState[taskObj.key] = { retries = MAX_RETRIES, failed = true, reason = taskObj.failReason }
            return LC.BLOCKED
        end

        local rs = ctx.tasks.coordRetryState[taskObj.key] or { retries = 0, failed = false }
        rs.retries = rs.retries + 1
        taskObj.tile.retryCount = rs.retries
        if rs.retries >= MAX_RETRIES then
            rs.failed = true
            taskObj.state = LC.FAILED
            taskObj.tile.state = TS.FAILED
            ctx.stats.failedTasks = (ctx.stats.failedTasks or 0) + 1
        else
            taskObj.state = LC.RETRY_PENDING
            rs.nextRetryAt = PF.Util.now() + (RETRY_COOLDOWNS[rs.retries] or 1.35)
        end
        ctx.tasks.coordRetryState[taskObj.key] = rs
        return taskObj.state
    end

    function TaskManager.resetFailedTile(ctx, key)
        if ctx and ctx.tasks then
            ctx.tasks.coordRetryState[key] = nil
        end
    end

    function TaskManager.clearAll(ctx)
        if not ctx or not ctx.tasks then return end
        for id in pairs(ctx.tasks.byId) do
            PF.Inventory.releaseSeeds(ctx, id)
        end
        ctx.tasks.byId = {}
        ctx.tasks.reservedByCoord = {}
        if ctx.placeTiles then
            for _, rec in pairs(ctx.placeTiles) do
                rec.reservedByTaskId = nil
                rec.currentTaskId = nil
            end
        end
        if ctx.breakTiles then
            for _, rec in pairs(ctx.breakTiles) do
                rec.reservedByTaskId = nil
                rec.currentTaskId = nil
            end
        end
    end
end

-- Module 7: Dedicated Verification Manager (Never Blindly Trusts Command Send)
do
    local Verifier = {}
    PF.Verifier = Verifier

    local function rttTimeout()
        if H and H.serverTileEchoSeen then
            return PF.Util.clamp((H.serverEchoRtt or 0.22) + 0.18, 0.24, 0.65)
        end
        return 0.28
    end

    local function getTileAck(w, x, y, layer)
        if not (H and H.serverTileEchoSeen and type(H.tileAck) == "table") then return nil end
        local key = ((layer == 2) and "bg" or "fg") .. ":" .. (y * w + x)
        return H.tileAck[key]
    end

    function Verifier.waitTileValue(ctx, tx, ty, layer, expectedId, sentAt, aliveFn)
        local gt = H and H.gt
        local w = gt and gt.w or 100
        local deadline = PF.Util.now() + rttTimeout()
        while PF.Util.now() <= deadline do
            if aliveFn and not aliveFn() then return false, "CANCELLED" end
            if Core.ReconcileTile then Core.ReconcileTile(tx, ty, layer) end
            local live = Core.GetLayerTile(tx, ty, layer)
            local ack = getTileAck(w, tx, ty, layer)
            if H and H.serverTileEchoSeen then
                if ack and ack.t >= (sentAt - 0.02) then
                    if ack.id == expectedId then
                        return true, "SERVER_ACK_CONFIRMED"
                    else
                        return false, "SERVER_MISMATCH"
                    end
                end
            else
                if live == expectedId then
                    return true, "WORLD_STATE_CONFIRMED"
                end
            end
            PF.Util.wait(0.025)
        end
        if Core.ReconcileTile then Core.ReconcileTile(tx, ty, layer) end
        if Core.GetLayerTile(tx, ty, layer) == expectedId then
            return true, "POST_WINDOW_MATCHED"
        end
        return false, "VERIFY_TIMEOUT"
    end

    function Verifier.verifyPlant(ctx, tileRec, seedBefore, sentAt, aliveFn)
        local okTile, rsn = Verifier.waitTileValue(ctx, tileRec.x, tileRec.y, 1, ctx.cfg.seedId, sentAt, aliveFn)
        if not okTile then
            return false, rsn
        end
        local seedAfter = Core.CountItem(ctx.cfg.seedId)
        -- Confirm seed actually decremented or tile genuinely holds seedId on server
        if seedAfter < seedBefore or rsn == "SERVER_ACK_CONFIRMED" then
            return true, "PLANT_VERIFIED"
        end
        -- Small grace window for inventory sync packet
        PF.Util.wait(0.08)
        if Core.CountItem(ctx.cfg.seedId) < seedBefore or Core.GetFG(tileRec.x, tileRec.y) == ctx.cfg.seedId then
            return true, "PLANT_VERIFIED_SYNC"
        end
        return false, "SEED_NOT_CONSUMED"
    end

    function Verifier.verifyHarvest(ctx, tileRec, sentAt, aliveFn)
        local okTile, rsn = Verifier.waitTileValue(ctx, tileRec.x, tileRec.y, 1, 0, sentAt, aliveFn)
        if okTile then
            return true, "HARVEST_VERIFIED"
        end
        if Core.GetFG(tileRec.x, tileRec.y) ~= ctx.cfg.seedId then
            return true, "TREE_REMOVED"
        end
        return false, rsn
    end

    function Verifier.verifyCollect(ctx, beforeBlk, beforeSeed, beforeDropTotal)
        local inv = PF.Inventory.refresh(ctx, true)
        local gainedBlk = math.max(0, inv.blockCount - beforeBlk)
        local gainedSeed = math.max(0, inv.seedCount - beforeSeed)
        local afterDropTotal = (inv.pendingBlockDrop or 0) + (inv.pendingSeedDrop or 0)
        if gainedBlk > 0 or gainedSeed > 0 or afterDropTotal < beforeDropTotal then
            return true, gainedBlk, gainedSeed
        end
        return false, 0, 0
    end

    function Verifier.verifyDropSave(ctx, itemId, beforeCount, expectedDrop, aliveFn)
        local targetMax = math.max(0, beforeCount - expectedDrop)
        local dl = PF.Util.now() + 0.90
        while PF.Util.now() <= dl do
            if aliveFn and not aliveFn() then return false, "CANCELLED" end
            local nowCnt = Core.CountItem(itemId)
            if nowCnt <= targetMax then
                return true, "DROP_VERIFIED"
            end
            PF.Util.wait(0.05)
        end
        local finalCnt = Core.CountItem(itemId)
        if finalCnt < beforeCount then
            return true, "PARTIAL_DROP_VERIFIED"
        end
        return false, "DROP_NOT_VERIFIED"
    end
end

-- Module 8: Unified Movement Controller (Single Owner of Movement & Path Caching)
do
    local MoveController = {}
    PF.MoveController = MoveController

    function MoveController.init(ctx)
        ctx.moveCache = {
            lastTargetKey = nil,
            lastFromX = nil,
            lastFromY = nil,
            lastCands = nil,
            cachedAt = 0,
        }
    end

    local function dfImpl()
        return DirtFarm and DirtFarm._impl or nil
    end

    function MoveController.isHazardTile(tx, ty)
        local fid = Core.GetFG(tx, ty)
        local impl = dfImpl()
        return fid > 0 and impl and impl.dfIsHazard and impl.dfIsHazard(Core.GetItemInfo(fid)) == true
    end

    function MoveController.isStandable(tx, ty)
        local impl = dfImpl()
        if impl and impl.dfIsStandable then
            return impl.dfIsStandable(tx, ty)
        end
        return Core.IsSolid(tx, ty)
    end

    function MoveController.hasClearFlatWalk(fromTx, toTx, standTy)
        local step = (toTx >= fromTx) and 1 or -1
        for cx = fromTx, toTx, step do
            if Core.IsSolid(cx, standTy) or MoveController.isHazardTile(cx, standTy) or MoveController.isHazardTile(cx, standTy + 1) then
                return false
            end
            if not MoveController.isStandable(cx, standTy + 1) then
                return false
            end
        end
        return true
    end

    function MoveController.isSameRowReach(tx, ty, actionKind, posOverride)
        local p = posOverride or Core.ReadPos()
        if p.grounded == false or p.ty ~= ty then return false end
        if math.abs((tx + 0.5) - (p.x or 0)) > 2.05 then return false end
        return Core.IsInActionReach(tx, ty, actionKind, p)
    end

    function MoveController.sortNearestSnake(tiles, startTx)
        if #tiles <= 1 then return tiles end
        local byY, ys = {}, {}
        for _, t in ipairs(tiles) do
            if not byY[t.y] then
                byY[t.y] = {}
                ys[#ys + 1] = t.y
            end
            byY[t.y][#byY[t.y] + 1] = t
        end
        table.sort(ys)
        local curP = Core.ReadPos()
        local curY = curP.ty or ys[1]
        local orderedYs = {}
        if #ys == 1 then
            orderedYs[1] = ys[1]
        elseif math.abs(ys[#ys] - curY) < math.abs(curY - ys[1]) then
            for i = 1, #ys do if ys[i] >= curY then orderedYs[#orderedYs + 1] = ys[i] end end
            for i = #ys, 1, -1 do if ys[i] < curY then orderedYs[#orderedYs + 1] = ys[i] end end
        else
            for i = #ys, 1, -1 do if ys[i] <= curY then orderedYs[#orderedYs + 1] = ys[i] end end
            for i = 1, #ys do if ys[i] > curY then orderedYs[#orderedYs + 1] = ys[i] end end
        end
        local out = {}
        local curX = tonumber(startTx) or (curP.tx or 0)
        for _, y in ipairs(orderedYs) do
            local row = byY[y]
            table.sort(row, function(a, b) return a.x < b.x end)
            if math.abs(curX - row[1].x) <= math.abs(curX - row[#row].x) then
                for i = 1, #row do out[#out + 1] = row[i] end
                curX = row[#row].x
            else
                for i = #row, 1, -1 do out[#out + 1] = row[i] end
                curX = row[1].x
            end
        end
        return out
    end

    function MoveController.settleAtTile(tx, ty, aliveFn)
        local p = Core.ReadPos()
        local cxWant = tx + 0.5
        if p.ty == ty and math.abs((p.x or cxWant) - cxWant) > 0.16 then
            local dl = PF.Util.now() + 0.35
            while aliveFn() and math.abs((p.x or cxWant) - cxWant) > 0.16 and PF.Util.now() < dl do
                Core.SetManualInput(((p.x or cxWant) < cxWant) and 1 or -1, false)
                PF.Util.wait(0.025)
                p = Core.ReadPos()
            end
        end
        Core.ClearManualInput()
        local impl = dfImpl()
        if impl and impl.dfSettleGrounded then
            impl.dfSettleGrounded(aliveFn, 0.22)
        end
    end

    function MoveController.moveToAction(ctx, tx, ty, actionKind, aliveFn, opts)
        opts = opts or {}
        if not aliveFn() then return false end
        local cur = Core.ReadPos()
        local impl = dfImpl()

        -- Fast path: already in reach & verified position
        if actionKind then
            if MoveController.isSameRowReach(tx, ty, actionKind, cur) then
                return true
            end
            local goalX = opts.standGoalX or tx
            if cur.grounded and cur.ty == ty and impl and impl.dfStepWalkToX and MoveController.hasClearFlatWalk(cur.tx, goalX, ty) then
                local span = math.max(1.4, math.abs(goalX - cur.tx) * 0.25 + 1.0)
                impl.dfStepWalkToX(goalX + 0.5, ty + 1, span, aliveFn, nil)
                if MoveController.isSameRowReach(tx, ty, actionKind) then
                    if impl.dfSettleGrounded then impl.dfSettleGrounded(aliveFn, 0.14) end
                    return true
                end
            end
        else
            -- Exact stand tile (e.g., BreakPos or SavePos)
            if cur.grounded and cur.tx == tx and cur.ty == ty then
                MoveController.settleAtTile(tx, ty, aliveFn)
                return true
            end
            if cur.grounded and cur.ty == ty and impl and impl.dfStepWalkToX and MoveController.hasClearFlatWalk(cur.tx, tx, ty) then
                local span = math.max(1.4, math.abs(tx - cur.tx) * 0.25 + 1.0)
                impl.dfStepWalkToX(tx + 0.5, ty + 1, span, aliveFn, nil)
                local p2 = Core.ReadPos()
                if math.abs(p2.tx - tx) <= 1 and p2.ty == ty then
                    MoveController.settleAtTile(tx, ty, aliveFn)
                    return true
                end
            end
        end

        -- Avoid redundant FindStandCandidates if same target & same origin within 1.5s
        local cache = ctx.moveCache
        local targetKey = tostring(tx) .. "," .. tostring(ty) .. ":" .. tostring(actionKind or "exact")
        local cands
        if cache and cache.lastTargetKey == targetKey
            and cache.lastFromX == cur.tx and cache.lastFromY == cur.ty
            and (PF.Util.now() - cache.cachedAt) < 1.5 and cache.lastCands then
            cands = cache.lastCands
        else
            local searchR = actionKind and math.max(1, math.floor((Core.GetActionRange(actionKind) or 2.3) - 0.35)) or 0
            cands = Packets.FindStandCandidates(tx, ty, searchR) or {}
            if cache then
                cache.lastTargetKey = targetKey
                cache.lastFromX = cur.tx
                cache.lastFromY = cur.ty
                cache.lastCands = cands
                cache.cachedAt = PF.Util.now()
            end
        end

        if actionKind then
            local sameRow, other = {}, {}
            for _, c in ipairs(cands) do
                if c.y == ty and Core.IsInActionReach(tx, ty, actionKind, { x = c.x + 0.5, y = c.y + 1 }) then
                    sameRow[#sameRow + 1] = c
                elseif math.abs(c.y - ty) <= 1 and Core.IsInActionReach(tx, ty, actionKind, { x = c.x + 0.5, y = c.y + 1 }) then
                    other[#other + 1] = c
                end
            end
            local ordered = (#sameRow > 0) and sameRow or other
            for i = 1, math.min(#ordered, 3) do
                if not aliveFn() then return false end
                local c = ordered[i]
                Packets.WalkPathTo(c.x, c.y, 6.9, aliveFn, { fastWalk = false, noSnap = true, customPath = c.path })
                local chk = Core.ReadPos()
                if MoveController.isSameRowReach(tx, ty, actionKind, chk) or (#sameRow == 0 and Core.IsInActionReach(tx, ty, actionKind, chk)) then
                    if impl and impl.dfSettleGrounded then impl.dfSettleGrounded(aliveFn, 0.14) end
                    return true
                end
            end
            return false
        else
            if not Core.IsSolid(tx, ty) then
                Packets.WalkPathTo(tx, ty, 6.9, aliveFn, { fastWalk = false, noSnap = true })
                local chk = Core.ReadPos()
                if math.abs(chk.tx - tx) <= 1 and math.abs(chk.ty - ty) <= 1 then
                    MoveController.settleAtTile(tx, ty, aliveFn)
                    return true
                end
            end
            for i = 1, math.min(#cands, 3) do
                if not aliveFn() then return false end
                local c = cands[i]
                Packets.WalkPathTo(c.x, c.y, 6.9, aliveFn, { fastWalk = false, noSnap = true, customPath = c.path })
                local chk = Core.ReadPos()
                if math.abs(chk.tx - tx) <= 1 and math.abs(chk.ty - ty) <= 1 then
                    MoveController.settleAtTile(tx, ty, aliveFn)
                    return true
                end
            end
            return false
        end
    end
end

-- Module 9: Dedicated Drop Collection Manager (Separate from Production)
do
    local CollectManager = {}
    PF.CollectManager = CollectManager

    local MAX_COLLECT_FAILS = 3

    function CollectManager.hasCollectableDrops(ctx)
        local d = ctx.latestDrops or PF.WorldScanner.scanPendingDrops(ctx)
        ctx.latestDrops = d
        local wantBlk = (d.blockQty > 0) and (PF.Inventory.getBlockRoom(ctx) > 0)
        local wantSd = (d.seedQty > 0) and (PF.Inventory.getSeedRoom(ctx) > 0)
        return wantBlk or wantSd, d
    end

    function CollectManager.collectPending(ctx, aliveFn, nearCoords)
        local hasDrops, d = CollectManager.hasCollectableDrops(ctx)
        if not hasDrops then
            -- Clear COLLECT_PENDING tiles cleanly if no relevant drops remain
            for _, rec in pairs(ctx.placeTiles) do
                if rec.state == PF.ENUMS.TILE_STATE.COLLECT_PENDING then
                    PF.TileState.reconcilePlaceTile(ctx, rec)
                end
            end
            return true, 0, 0
        end

        PF.Logger.setActivity(ctx, "COLLECT", "Drops", "EXECUTING")
        local beforeBlk = Core.CountItem(ctx.cfg.blockId)
        local beforeSeed = Core.CountItem(ctx.cfg.seedId)
        local beforeDropTotal = (d.blockQty or 0) + (d.seedQty or 0)

        -- Build prioritized drop target list (configured blockId & seedId ONLY)
        local targets = {}
        if PF.Inventory.getSeedRoom(ctx) > 0 then
            for _, sd in ipairs(d.seedDrops) do targets[#targets + 1] = sd end
        end
        if PF.Inventory.getBlockRoom(ctx) > 0 then
            for _, bd in ipairs(d.blockDrops) do targets[#targets + 1] = bd end
        end

        targets = PF.MoveController.sortNearestSnake(targets, Core.ReadPos().tx)
        local visited = 0
        for _, drop in ipairs(targets) do
            if not aliveFn() then break end
            local wantThis = (drop.id == ctx.cfg.blockId and PF.Inventory.getBlockRoom(ctx) > 0)
                or (drop.id == ctx.cfg.seedId and PF.Inventory.getSeedRoom(ctx) > 0)
            if wantThis then
                local pos = Core.ReadPos()
                local dx = drop.rawX - pos.x
                local dy = drop.rawY - pos.y
                local dist = math.sqrt(dx * dx + dy * dy)
                if dist > 4.2 then
                    PF.MoveController.moveToAction(ctx, drop.x, drop.y, "break", aliveFn)
                end
                Packets.Collect({
                    radius = 4.6,
                    filterId = drop.id,
                    stepMoveIfFar = false,
                    collectDelay = math.min(0.025, ctx.cfg.collectDelay or 0.025),
                    shouldContinue = aliveFn,
                })
                visited = visited + 1
                if visited >= 8 then break end
            end
        end

        local okVerify, gainedBlk, gainedSeed = PF.Verifier.verifyCollect(ctx, beforeBlk, beforeSeed, beforeDropTotal)
        if okVerify then
            ctx.collectFailStreak = 0
            ctx.stats.collectedBlocks = (ctx.stats.collectedBlocks or 0) + gainedBlk
            ctx.stats.collectedSeeds = (ctx.stats.collectedSeeds or 0) + gainedSeed
            PF.Logger.log(ctx, "COLLECT", string.format("Collected +Block:%d +Seed:%d | Inv B:%d S:%d",
                gainedBlk, gainedSeed, ctx.inv.blockCount, ctx.inv.seedCount))
            if nearCoords then
                for _, c in ipairs(nearCoords) do
                    local rec = ctx.placeTiles[PF.Util.tileKey(c.x, c.y)]
                    if rec and rec.state == PF.ENUMS.TILE_STATE.COLLECT_PENDING then
                        rec.state = PF.ENUMS.TILE_STATE.EMPTY
                        PF.TileState.reconcilePlaceTile(ctx, rec)
                    end
                end
            end
            return true, gainedBlk, gainedSeed
        else
            ctx.collectFailStreak = (ctx.collectFailStreak or 0) + 1
            PF.Logger.log(ctx, "COLLECT", string.format("Collect verify no-change (%d/%d)", ctx.collectFailStreak, MAX_COLLECT_FAILS))
            if ctx.collectFailStreak >= MAX_COLLECT_FAILS then
                -- Prevent infinite collect loop on unreachable drop
                ctx.collectCooldownUntil = PF.Util.now() + 4.0
                ctx.collectFailStreak = 0
                if nearCoords then
                    for _, c in ipairs(nearCoords) do
                        local rec = ctx.placeTiles[PF.Util.tileKey(c.x, c.y)]
                        if rec and rec.state == PF.ENUMS.TILE_STATE.COLLECT_PENDING then
                            PF.TileState.reconcilePlaceTile(ctx, rec)
                        end
                    end
                end
            end
            return false, 0, 0
        end
    end
end

-- Module 10: Plant, Harvest, and Break Production Managers
do
    local PlantManager = {}
    local HarvestManager = {}
    local BreakManager = {}
    PF.PlantManager = PlantManager
    PF.HarvestManager = HarvestManager
    PF.BreakManager = BreakManager

    function PlantManager.execute(ctx, emptyTiles, aliveFn)
        if #emptyTiles == 0 or PF.Inventory.getAvailableSeeds(ctx) <= 0 then return false end
        local ordered = PF.MoveController.sortNearestSnake(emptyTiles, Core.ReadPos().tx)
        local seedId = ctx.cfg.seedId
        local placeGap = math.max(0.155, ctx.cfg.placeDelay or 0.16)
        local anyDone = false

        for idx, rec in ipairs(ordered) do
            if not aliveFn() or evaluateSeems() then break end
            if PF.Inventory.getAvailableSeeds(ctx) <= 0 then break end
            -- Reconcile live before reserving (handles external world change before task executes!)
            PF.TileState.reconcilePlaceTile(ctx, rec)
            if rec.state == PF.ENUMS.TILE_STATE.EMPTY and not ctx.breakTargetSet[rec.key] then
                -- Check if a tree became READY mid-plant -> yield back to scheduler immediately!
                for _, pRec in pairs(ctx.placeTiles) do
                    if pRec.state == PF.ENUMS.TILE_STATE.GROWING and Core.IsTreeRipe and Core.IsTreeRipe(pRec.x, pRec.y) then
                        PF.TileState.reconcilePlaceTile(ctx, pRec)
                        return anyDone
                    end
                end

                local taskObj, rsn = PF.TaskManager.createAndReserve(ctx, "PLANT", rec)
                if taskObj then
                    rec.state = PF.ENUMS.TILE_STATE.PLANT_PENDING
                    PF.Logger.setActivity(ctx, "PLANT", string.format("(%d,%d)", rec.x, rec.y), "RESERVED")
                    local nextT = ordered[idx + 1]
                    local goalX = rec.x
                    if nextT and nextT.y == rec.y and math.abs(nextT.x - rec.x) == 1 then
                        goalX = nextT.x
                    end
                    local okMove = PF.MoveController.moveToAction(ctx, rec.x, rec.y, "place", aliveFn, { standGoalX = goalX })
                    if okMove and aliveFn() then
                        -- Final live check before packet send (never plant on growing/occupied tile)
                        if Core.GetFG(rec.x, rec.y) == 0 and Pabrik.IsTilePlantable(rec.x, rec.y) and not PF.Util.isProtectedOrImmutable(rec.x, rec.y, 1) then
                            PF.TaskManager.markExecuting(ctx, taskObj)
                            rec.state = PF.ENUMS.TILE_STATE.PLANTING
                            PF.Logger.log(ctx, "PLANT", string.format("Target X:%d Y:%d", rec.x, rec.y))
                            PF.Util.coolAntiKick()
                            local seedBefore = Core.CountItem(seedId)
                            local sentAt = PF.Util.now()
                            Packets.PlaceVerified(rec.x, rec.y, seedId, 1, {
                                showHand = ctx.cfg.showHand,
                                delay = 0,
                                noLocalMirror = false,
                                optimisticFast = false,
                                autoRange = false,
                                retries = 1,
                                placeGap = placeGap,
                                verifyTimeout = 0.30,
                                shouldContinue = aliveFn,
                            })
                            PF.TaskManager.markVerifying(ctx, taskObj)
                            local okV, vRsn = PF.Verifier.verifyPlant(ctx, rec, seedBefore, sentAt, aliveFn)
                            if okV then
                                PF.TaskManager.complete(ctx, taskObj, PF.ENUMS.TILE_STATE.GROWING)
                                ctx.stats.plantedCount = (ctx.stats.plantedCount or 0) + 1
                                anyDone = true
                                PF.Logger.log(ctx, "VERIFY", string.format("Plant X:%d Y:%d -> GROWING", rec.x, rec.y))
                            else
                                PF.TaskManager.fail(ctx, taskObj, vRsn, false)
                                PF.Logger.log(ctx, "VERIFY", string.format("Plant failed X:%d Y:%d (%s)", rec.x, rec.y, tostring(vRsn)))
                            end
                            PF.Inventory.refresh(ctx, false)
                        else
                            PF.TaskManager.fail(ctx, taskObj, "TILE_CHANGED_BEFORE_PLANT", false)
                            PF.TileState.reconcilePlaceTile(ctx, rec)
                        end
                    else
                        PF.TaskManager.fail(ctx, taskObj, "MOVE_UNREACHABLE", false)
                    end
                elseif rsn == "NO_AVAILABLE_SEED" then
                    break
                end
            end
        end
        return anyDone
    end

    -- Harvests each READY tile independently without waiting for GROWING tiles
    function HarvestManager.execute(ctx, readyTiles, aliveFn)
        if #readyTiles == 0 or not PF.Inventory.canSafelyHarvest(ctx) then return false end
        local ordered = PF.MoveController.sortNearestSnake(readyTiles, Core.ReadPos().tx)
        local anyDone = false
        local harvestedCoords = {}

        for idx, rec in ipairs(ordered) do
            if not aliveFn() or evaluateSeems() then break end
            if not PF.Inventory.canSafelyHarvest(ctx) then
                PF.Logger.log(ctx, "INVENTORY", "Stopping harvest batch: approaching Block capacity limit")
                break
            end

            -- Reconcile live before harvesting (never harvest GROWING or already-gone tile)
            PF.TileState.reconcilePlaceTile(ctx, rec)
            if rec.state == PF.ENUMS.TILE_STATE.READY then
                local taskObj = PF.TaskManager.createAndReserve(ctx, "HARVEST", rec)
                if taskObj then
                    rec.state = PF.ENUMS.TILE_STATE.HARVEST_PENDING
                    PF.Logger.setActivity(ctx, "HARVEST", string.format("(%d,%d)", rec.x, rec.y), "RESERVED")
                    local nextT = ordered[idx + 1]
                    local goalX = rec.x
                    if nextT and nextT.y == rec.y and math.abs(nextT.x - rec.x) == 1 then
                        goalX = nextT.x
                    end
                    local okMove = PF.MoveController.moveToAction(ctx, rec.x, rec.y, "break", aliveFn, { standGoalX = goalX })
                    if okMove and aliveFn() then
                        if Core.GetFG(rec.x, rec.y) == ctx.cfg.seedId and Core.IsTreeRipe(rec.x, rec.y) and not PF.Util.isProtectedOrImmutable(rec.x, rec.y, 1) then
                            PF.TaskManager.markExecuting(ctx, taskObj)
                            rec.state = PF.ENUMS.TILE_STATE.HARVESTING
                            PF.Logger.log(ctx, "HARVEST", string.format("Target X:%d Y:%d", rec.x, rec.y))
                            PF.Util.coolAntiKick()
                            local sentAt = PF.Util.now()
                            Packets.BreakVerified({ { tx = rec.x, ty = rec.y, layer = 1 } }, {
                                threads = 1,
                                layer = 1,
                                oneHit = true,
                                customHits = 1,
                                hitDelay = 0.165,
                                verifyTimeout = 0.28,
                                showHand = ctx.cfg.showHand,
                                showVisual = true,
                                noLocalMirror = false,
                                autoRange = false,
                                skipPlaceCooldown = true,
                                shouldContinue = aliveFn,
                            })
                            PF.TaskManager.markVerifying(ctx, taskObj)
                            local okV, vRsn = PF.Verifier.verifyHarvest(ctx, rec, sentAt, aliveFn)
                            if okV then
                                PF.TaskManager.complete(ctx, taskObj, PF.ENUMS.TILE_STATE.COLLECT_PENDING)
                                ctx.stats.harvestedCount = (ctx.stats.harvestedCount or 0) + 1
                                harvestedCoords[#harvestedCoords + 1] = { x = rec.x, y = rec.y }
                                anyDone = true
                                PF.Logger.log(ctx, "VERIFY", string.format("Harvest X:%d Y:%d verified -> COLLECT_PENDING", rec.x, rec.y))
                                -- Collect & verify drops independently after harvest
                                PF.CollectManager.collectPending(ctx, aliveFn, { { x = rec.x, y = rec.y } })
                                PF.TileState.reconcilePlaceTile(ctx, rec)
                            else
                                PF.TaskManager.fail(ctx, taskObj, vRsn, false)
                                PF.Logger.log(ctx, "VERIFY", string.format("Harvest failed X:%d Y:%d (%s)", rec.x, rec.y, tostring(vRsn)))
                            end
                        else
                            PF.TaskManager.fail(ctx, taskObj, "NOT_READY_OR_CHANGED", false)
                            PF.TileState.reconcilePlaceTile(ctx, rec)
                        end
                    else
                        PF.TaskManager.fail(ctx, taskObj, "MOVE_UNREACHABLE", false)
                    end
                end
            end
        end

        if #harvestedCoords > 0 and aliveFn() then
            PF.CollectManager.collectPending(ctx, aliveFn, harvestedCoords)
            PF.WorldScanner.scanIncremental(ctx, harvestedCoords)
        end
        return anyDone
    end

    -- Executes 1 clean, verified Break cycle on validated Break Position targets (never traps scheduler in an infinite loop)
    function BreakManager.executeCycle(ctx, aliveFn)
        if not ctx.cfg.breakEnabled or not ctx.cfg.breakPos then return false end
        if not PF.Inventory.canSafelyBreak(ctx) then return false end

        local targets = PF.WorldScanner.validateBreakTargets(ctx)
        if #targets == 0 then
            PF.Logger.log(ctx, "BREAK", "No valid Break targets above BreakPos")
            return false
        end

        local bp = ctx.cfg.breakPos
        PF.Logger.setActivity(ctx, "BREAK", string.format("(%d,%d)", bp.x, bp.y), "MOVING")
        local okMove = PF.MoveController.moveToAction(ctx, bp.x, bp.y, nil, aliveFn)
        if not okMove or not aliveFn() then
            PF.Logger.log(ctx, "BREAK", "Cannot reach BreakPos")
            return false
        end

        local layer = ctx.blockLayer
        local blockId = ctx.cfg.blockId
        local reservedTasks = {}
        local placeList = {}

        for _, rec in ipairs(targets) do
            PF.TileState.reconcileBreakTile(ctx, rec)
            if rec.state == PF.ENUMS.TILE_STATE.EMPTY or rec.state == PF.ENUMS.TILE_STATE.BREAK_PENDING then
                local tObj = PF.TaskManager.createAndReserve(ctx, "BREAK", rec)
                if tObj then
                    reservedTasks[#reservedTasks + 1] = tObj
                    placeList[#placeList + 1] = tObj
                end
            end
        end
        if #reservedTasks == 0 then return false end

        -- Step 1: Place target block on empty validated Break slots (strictly verified, no optimisticFast)
        local placeGap = math.max(0.155, ctx.cfg.placeDelay or 0.165)
        for _, tObj in ipairs(placeList) do
            if not aliveFn() or Core.CountItem(blockId) <= 0 then break end
            local r = tObj.tile
            if Core.GetLayerTile(r.x, r.y, layer) == 0 and not PF.Util.isProtectedOrImmutable(r.x, r.y, layer) then
                PF.TaskManager.markExecuting(ctx, tObj)
                PF.Util.coolAntiKick()
                local sentAt = PF.Util.now()
                Packets.PlaceVerified(r.x, r.y, blockId, layer, {
                    showHand = ctx.cfg.showHand,
                    delay = 0,
                    noLocalMirror = false,
                    optimisticFast = false,
                    autoRange = false,
                    retries = 1,
                    placeGap = placeGap,
                    verifyTimeout = 0.30,
                    shouldContinue = aliveFn,
                })
                PF.Verifier.waitTileValue(ctx, r.x, r.y, layer, blockId, sentAt, aliveFn)
            end
        end

        -- Step 2: Break ONLY tiles currently holding our target blockId (never foreign/protected tiles!)
        local breakTargets = {}
        local breakTasks = {}
        for _, tObj in ipairs(reservedTasks) do
            local r = tObj.tile
            if Core.GetLayerTile(r.x, r.y, layer) == blockId and not PF.Util.isProtectedOrImmutable(r.x, r.y, layer) then
                PF.TaskManager.markExecuting(ctx, tObj)
                r.state = PF.ENUMS.TILE_STATE.BREAKING
                breakTargets[#breakTargets + 1] = { tx = r.x, ty = r.y, layer = layer }
                breakTasks[#breakTasks + 1] = tObj
            end
        end

        local anyBroke = false
        if #breakTargets > 0 and aliveFn() then
            PF.Util.coolAntiKick()
            local sentAt = PF.Util.now()
            Packets.BreakVerified(breakTargets, {
                threads = math.min(2, #breakTargets),
                layer = layer,
                oneHit = ctx.cfg.oneHit,
                hitDelay = math.max(0.192, ctx.cfg.breakDelay or 0.192),
                verifyTimeout = 0.30,
                showHand = ctx.cfg.showHand,
                showVisual = true,
                noLocalMirror = false,
                autoRange = false,
                shouldContinue = aliveFn,
            })

            for _, tObj in ipairs(breakTasks) do
                PF.TaskManager.markVerifying(ctx, tObj)
                local okV, vRsn = PF.Verifier.waitTileValue(ctx, tObj.x, tObj.y, layer, 0, sentAt, aliveFn)
                if okV then
                    PF.TaskManager.complete(ctx, tObj, PF.ENUMS.TILE_STATE.COMPLETED)
                    ctx.stats.brokenCount = (ctx.stats.brokenCount or 0) + 1
                    anyBroke = true
                else
                    PF.TaskManager.fail(ctx, tObj, vRsn, false)
                    PF.Logger.log(ctx, "VERIFY", string.format("Break failed X:%d Y:%d (%s)", tObj.x, tObj.y, tostring(vRsn)))
                end
            end
        end

        -- Release any un-broken reserved tasks cleanly
        for _, tObj in ipairs(reservedTasks) do
            if tObj.state == PF.ENUMS.TASK_LIFECYCLE.RESERVED or tObj.state == PF.ENUMS.TASK_LIFECYCLE.EXECUTING then
                PF.TaskManager.complete(ctx, tObj, PF.ENUMS.TILE_STATE.EMPTY)
            end
        end

        -- Step 3: Collect & verify drops from Break
        if aliveFn() then
            PF.CollectManager.collectPending(ctx, aliveFn, nil)
            PF.Inventory.refresh(ctx, true)
        end
        return anyBroke
    end
end

-- Module 11: Storage / Save World Manager & Persistent Checkpoints
do
    local StorageManager = {}
    PF.StorageManager = StorageManager

    local MAX_SAVE_RETRIES = 3

    function StorageManager.saveCheckpoint(ctx, stage, plan)
        local env = PF.Util.getEnvTable()
        local ed = env.__SYT_ENV_DATA or {}
        env.__SYT_ENV_DATA = ed

        local tileSnap = {}
        for k, rec in pairs(ctx.placeTiles or {}) do
            tileSnap[k] = { x = rec.x, y = rec.y, state = rec.state, fgId = rec.fgId, ripe = rec.ripe }
        end
        local pos = Core.ReadPos()
        ed.pabrikCheckpoint = {
            stage = stage,
            productionWorld = ctx.productionWorld,
            pos = { x = pos.tx or 0, y = pos.ty or 0 },
            tileStates = tileSnap,
            inventory = {
                blockCount = ctx.inv and ctx.inv.blockCount or 0,
                seedCount = ctx.inv and ctx.inv.seedCount or 0,
            },
            savePlan = plan,
            savedAt = PF.Util.now(),
        }
        return ed.pabrikCheckpoint
    end

    function StorageManager.loadCheckpoint()
        local env = PF.Util.getEnvTable()
        local ed = env.__SYT_ENV_DATA
        return (type(ed) == "table") and ed.pabrikCheckpoint or nil
    end

    function StorageManager.clearCheckpoint()
        local env = PF.Util.getEnvTable()
        local ed = env.__SYT_ENV_DATA
        if type(ed) == "table" then
            ed.pabrikCheckpoint = nil
        end
    end

    -- Computes exact partial/full storage plan (e.g., Block=200 & Seed=80 -> saves ONLY Block unless configured otherwise)
    function StorageManager.computeSavePlan(ctx)
        local sc = ctx.cfg.save
        local inv = ctx.inv
        local mode = sc.mode or PF.ENUMS.SAVE_MODE.BOTH
        local manual = (Pabrik.State.saveConfig and Pabrik.State.saveConfig.manualSaveRequested == true)
        local items = {}

        local wantBlk = (mode ~= PF.ENUMS.SAVE_MODE.SEED_ONLY) and (inv.saveBlockRequired or manual)
        local wantSd = (mode ~= PF.ENUMS.SAVE_MODE.BLOCK_ONLY) and (inv.saveSeedRequired or manual)

        if wantBlk and inv.blockCount > 0 then
            local amt = sc.saveBlockAmount and math.min(sc.saveBlockAmount, inv.blockCount) or inv.blockCount
            if amt > 0 then
                items[#items + 1] = { id = sc.blockId or ctx.cfg.blockId, amount = amt, kind = "BLOCK" }
            end
        end
        if wantSd and inv.seedCount > 0 then
            local amt = sc.saveSeedAmount and math.min(sc.saveSeedAmount, inv.seedCount) or inv.seedCount
            if amt > 0 then
                items[#items + 1] = { id = sc.seedId or ctx.cfg.seedId, amount = amt, kind = "SEED" }
            end
        end
        return items
    end

    function StorageManager.executeSave(ctx, aliveFn)
        local sc = ctx.cfg.save
        if not sc.enabled or sc.world == "" then
            ctx.storageStatus = "NOT_CONFIGURED"
            PF.Logger.log(ctx, "SAVE", "Inventory limit reached but Save World not configured")
            return false, "SAVE_NOT_CONFIGURED"
        end

        -- Drain pending drops before leaving production world
        PF.CollectManager.collectPending(ctx, aliveFn, nil)
        PF.Inventory.refresh(ctx, true)

        local plan = StorageManager.computeSavePlan(ctx)
        if #plan == 0 then
            Pabrik.State.saveConfig.manualSaveRequested = false
            ctx.storageStatus = "IDLE"
            return true, "NOTHING_TO_SAVE"
        end

        ctx.storageStatus = "SAVING"
        PF.Logger.setActivity(ctx, "SAVE", sc.world, "CHECKPOINT")
        StorageManager.saveCheckpoint(ctx, "PRE_WARP_TO_SAVE", plan)
        PF.Logger.log(ctx, "SAVE", string.format("Checkpoint saved -> Warping to %s (%d item group)", sc.world, #plan))

        -- Warp to Save World with bounded retries
        local enteredSave = false
        for attempt = 1, MAX_SAVE_RETRIES do
            if not aliveFn() then return false, "CANCELLED" end
            local okWarp = Packets.EnterWorldDoor(sc.world, aliveFn)
            local curW = (H and H.gt) and PF.Util.cleanWorld(H.gt.name) or ""
            if okWarp and curW == sc.world then
                enteredSave = true
                break
            end
            PF.Logger.log(ctx, "SAVE", string.format("Failed entering %s (%d/%d)", sc.world, attempt, MAX_SAVE_RETRIES))
            PF.Util.wait(1.2)
        end

        if not enteredSave then
            ctx.storageStatus = "FAILED_ENTER_SAVE_WORLD"
            PF.Logger.log(ctx, "ERROR", "Cannot enter Save World " .. sc.world .. " (checkpoint preserved)")
            return false, "SAVE_WORLD_UNREACHABLE"
        end

        StorageManager.saveCheckpoint(ctx, "IN_SAVE_WORLD", plan)

        -- Move to configured Save Position
        if sc.pos then
            local okPos = PF.MoveController.moveToAction(ctx, sc.pos.x, sc.pos.y, nil, aliveFn)
            if not okPos then
                ctx.storageStatus = "FAILED_SAVE_POS"
                PF.Logger.log(ctx, "ERROR", string.format("Save position (%d,%d) unreachable", sc.pos.x, sc.pos.y))
                return false, "SAVE_POS_INVALID"
            end
        end

        -- Drop each item group & verify actual inventory decreased
        local allDropped = true
        for _, item in ipairs(plan) do
            if not aliveFn() then return false, "CANCELLED" end
            local beforeCnt = Core.CountItem(item.id)
            local dropAmt = math.min(item.amount, beforeCnt)
            if dropAmt > 0 then
                local droppedOk = false
                for attempt = 1, MAX_SAVE_RETRIES do
                    if not aliveFn() then return false, "CANCELLED" end
                    local okD = Packets.Drop(item.id, dropAmt, { shouldContinue = aliveFn })
                    if okD then
                        local okV = PF.Verifier.verifyDropSave(ctx, item.id, beforeCnt, dropAmt, aliveFn)
                        if okV then
                            droppedOk = true
                            PF.Logger.log(ctx, "SAVE", string.format("Verified drop %s x%d (ID:%d)", item.kind, dropAmt, item.id))
                            break
                        end
                    end
                    PF.Util.wait(0.6)
                end
                if not droppedOk then
                    allDropped = false
                    ctx.storageStatus = "FAILED_DROP_" .. item.kind
                    PF.Logger.log(ctx, "ERROR", string.format("Drop verification failed for %s (ID:%d)", item.kind, item.id))
                end
            end
        end

        if not allDropped then
            return false, "DROP_VERIFICATION_FAILED"
        end

        StorageManager.saveCheckpoint(ctx, "RETURNING_TO_PROD", plan)

        -- Return to Production World with bounded retries
        local returned = false
        for attempt = 1, MAX_SAVE_RETRIES do
            if not aliveFn() then return false, "CANCELLED" end
            local okRet = Packets.EnterWorldDoor(ctx.productionWorld, aliveFn)
            local curW = (H and H.gt) and PF.Util.cleanWorld(H.gt.name) or ""
            if okRet and curW == ctx.productionWorld then
                returned = true
                break
            end
            PF.Logger.log(ctx, "SAVE", string.format("Failed returning to %s (%d/%d)", ctx.productionWorld, attempt, MAX_SAVE_RETRIES))
            PF.Util.wait(1.2)
        end

        if not returned then
            ctx.storageStatus = "FAILED_RETURN_PROD"
            PF.Logger.log(ctx, "ERROR", "Dropped items safely, but failed returning to " .. ctx.productionWorld .. " (checkpoint kept)")
            return false, "RETURN_WORLD_FAILED"
        end

        -- Rescan production area & reconcile with checkpoint
        Pabrik.State.saveConfig.manualSaveRequested = false
        StorageManager.clearCheckpoint()
        ctx.stats.savedRuns = (ctx.stats.savedRuns or 0) + 1
        ctx.storageStatus = "IDLE"
        PF.WorldScanner.scanAll(ctx)
        PF.Inventory.refresh(ctx, true)
        PF.Logger.log(ctx, "SAVE", "Returned to " .. ctx.productionWorld .. " and reconciled production state")
        return true, "SAVE_COMPLETE"
    end
end

-- Module 12: Recovery Manager (Restart, World Drift, & Zero-Stock Recovery)
do
    local RecoveryManager = {}
    PF.RecoveryManager = RecoveryManager

    function RecoveryManager.recoverOnStart(ctx, aliveFn)
        local cp = PF.StorageManager.loadCheckpoint()
        if not cp then return true end
        PF.Logger.log(ctx, "RECOVERY", "Found checkpoint from stage: " .. tostring(cp.stage))

        local curW = (H and H.gt) and PF.Util.cleanWorld(H.gt.name) or ""
        if cp.productionWorld and cp.productionWorld ~= "" then
            ctx.productionWorld = cp.productionWorld
            if curW ~= cp.productionWorld then
                PF.Logger.log(ctx, "RECOVERY", "Returning from " .. curW .. " to production world " .. cp.productionWorld)
                local okRet = Packets.EnterWorldDoor(cp.productionWorld, aliveFn)
                if not okRet then
                    return false, "RECOVERY_RETURN_FAILED"
                end
            end
        end

        -- Scan live world & live inventory and reconcile with checkpoint without repeating completed work
        PF.WorldScanner.scanAll(ctx)
        PF.Inventory.refresh(ctx, true)
        if cp.stage == "RETURNING_TO_PROD" or cp.stage == "PRE_WARP_TO_SAVE" or cp.stage == "IN_SAVE_WORLD" then
            PF.StorageManager.clearCheckpoint()
        end
        PF.Logger.log(ctx, "RECOVERY", "State reconciled after restart")
        return true, "RECOVERED"
    end

    function RecoveryManager.handleZeroStock(ctx, aliveFn)
        PF.Logger.setActivity(ctx, "RECOVERY", "Stock=0", "SCANNING_DROPS")
        PF.Logger.log(ctx, "RECOVERY", "Block=0 & Seed=0 -> Entering stock recovery mode")
        local okCol, gBlk, gSeed = PF.CollectManager.collectPending(ctx, aliveFn, nil)
        PF.Inventory.refresh(ctx, true)
        if okCol and (gBlk > 0 or gSeed > 0) then
            return true
        end
        -- Rescan tiles in case trees became READY or external seeds appeared
        PF.WorldScanner.scanAll(ctx)
        return (ctx.inv.blockCount > 0 or ctx.inv.seedCount > 0)
    end
end

-- Module 13: Intelligent Dynamic Production Scheduler
do
    local Scheduler = {}
    PF.Scheduler = Scheduler

    function Scheduler.collectTileBuckets(ctx)
        local TS = PF.ENUMS.TILE_STATE
        local empty, growing, ready, collectPending = {}, {}, {}, {}
        local minRem = nil
        for _, rec in pairs(ctx.placeTiles or {}) do
            if rec.state == TS.READY then
                ready[#ready + 1] = rec
            elseif rec.state == TS.EMPTY then
                empty[#empty + 1] = rec
            elseif rec.state == TS.GROWING then
                growing[#growing + 1] = rec
                if rec.remSec and (not minRem or rec.remSec < minRem) then
                    minRem = rec.remSec
                end
            elseif rec.state == TS.COLLECT_PENDING then
                collectPending[#collectPending + 1] = rec
            end
        end
        return {
            empty = empty,
            growing = growing,
            ready = ready,
            collectPending = collectPending,
            minRem = minRem,
        }
    end

    -- Pure decision function (also directly testable by unit/simulation suites!)
    function Scheduler.decide(ctx, buckets)
        local DEC = PF.ENUMS.DECISION
        local inv = ctx.inv
        local cfg = ctx.cfg

        -- 1. SAFETY CHECK
        local gt = H and H.gt
        if not gt or PF.Util.cleanWorld(gt.name) ~= ctx.productionWorld then
            return DEC.SAFETY_ABORT, "WORLD_MISMATCH"
        end

        -- 2. INVENTORY SAVE (strictly >= threshold, OR near limit blocking READY harvest)
        if inv.saveRequired then
            if cfg.save.enabled then
                return DEC.SAVE_INVENTORY, "THRESHOLD_REACHED"
            elseif inv.blockCount >= inv.maxBlock and inv.seedCount >= inv.maxSeed then
                return DEC.SAFETY_ABORT, "INVENTORY_FULL_NO_SAVE"
            end
        end
        if #buckets.ready > 0 and not PF.Inventory.canSafelyHarvest(ctx) and cfg.save.enabled then
            return DEC.SAVE_INVENTORY, "MAKE_ROOM_FOR_HARVEST"
        end

        -- 3. COLLECT PENDING DROPS (only if not in unreachable-drop cooldown & room exists)
        local inCollectCooldown = ctx.collectCooldownUntil and (PF.Util.now() < ctx.collectCooldownUntil)
        if not inCollectCooldown then
            local hasDrops = PF.CollectManager.hasCollectableDrops(ctx)
            if hasDrops or #buckets.collectPending > 0 then
                return DEC.COLLECT_PENDING, "UNCOLLECTED_DROPS"
            end
        end

        -- 4. HARVEST READY TREES IMMEDIATELY (never wait for GROWING tiles!)
        if #buckets.ready > 0 and PF.Inventory.canSafelyHarvest(ctx) then
            return DEC.HARVEST_READY, string.format("%d_READY_TREES", #buckets.ready)
        end

        -- 5. PLANT EMPTY TILES WHEN SEEDS AVAILABLE
        if #buckets.empty > 0 and PF.Inventory.getAvailableSeeds(ctx) > 0 then
            return DEC.PLANT_EMPTY, string.format("%d_EMPTY_TILES", #buckets.empty)
        end

        -- 6. BREAK REQUIRED (dynamic need-based evaluation, NOT blind unconditional breaking!)
        local needSeedsForPlant = (#buckets.empty > 0 and inv.seedCount < #buckets.empty)
        local needRoomForHarvest = (#buckets.ready > 0 and PF.Inventory.getBlockRoom(ctx) <= 0 and not cfg.save.enabled)
        local excessBlockIdle = (inv.blockCount > 0 and inv.seedCount < inv.maxSeed and #buckets.ready == 0 and #buckets.empty == 0)
        if cfg.breakEnabled and cfg.breakPos and PF.Inventory.canSafelyBreak(ctx)
            and (needSeedsForPlant or needRoomForHarvest or excessBlockIdle) then
            return DEC.BREAK_REQUIRED, needRoomForHarvest and "FREE_BLOCK_ROOM" or (needSeedsForPlant and "NEED_SEEDS" or "CONVERT_EXCESS_BLOCK")
        end

        -- 7. RECOVERY MODE (Block == 0 and Seed == 0)
        if inv.blockCount <= 0 and inv.seedCount <= 0 and #buckets.growing == 0 and #buckets.ready == 0 then
            return DEC.RECOVERY, "ZERO_STOCK"
        end

        -- 8. IDLE & PERIODIC RESCAN (e.g. all tiles GROWING, or waiting for stock)
        return DEC.IDLE_RESCAN, (#buckets.growing > 0) and "WAITING_GROWTH" or "NO_ACTIONABLE_TASK"
    end

    function Scheduler.runLoop(ctx, aliveFn)
        local DEC = PF.ENUMS.DECISION
        local okRec, recRsn = PF.RecoveryManager.recoverOnStart(ctx, aliveFn)
        if not okRec then
            return "Recovery gagal: " .. tostring(recRsn)
        end

        PF.WorldScanner.scanAll(ctx)
        PF.Inventory.create(ctx)
        PF.Logger.log(ctx, "INVENTORY", string.format("Block: %d/%d | Seed: %d/%d",
            ctx.inv.blockCount, ctx.inv.maxBlock, ctx.inv.seedCount, ctx.inv.maxSeed))

        local recoveryIdleStreak = 0
        while aliveFn() do
            PF.Util.wait(0.02)
            if evaluateSeems and evaluateSeems() then
                return "SEEMS: " .. tostring(Misc and Misc.State and Misc.State.seemsReason or "Paused")
            end
            if SystemModule and SystemModule.State and SystemModule.State.enabled and SystemModule.State.frozenByJoin then
                return "Pause: Player/Mod Join"
            end

            -- Refresh live config snapshot, incremental tile scan, and actual inventory
            ctx.cfg = PF.Config.getSnapshot()
            PF.WorldScanner.scanIncremental(ctx, nil)
            PF.Inventory.refresh(ctx, true)
            local buckets = Scheduler.collectTileBuckets(ctx)

            local decision, reason = Scheduler.decide(ctx, buckets)
            PF.Logger.log(ctx, "DECISION", string.format("%s (%s) | B:%d S:%d E:%d G:%d R:%d",
                decision, tostring(reason), ctx.inv.blockCount, ctx.inv.seedCount,
                #buckets.empty, #buckets.growing, #buckets.ready))

            if decision == DEC.SAFETY_ABORT then
                if reason == "INVENTORY_FULL_NO_SAVE" then
                    if emitNotify then emitNotify("Pabrik", "Inventory penuh (Block & Seed batas maks) & Save World belum aktif!") end
                    return "Inventory penuh (Save World nonaktif)"
                end
                return "Safety stop: " .. tostring(reason)

            elseif decision == DEC.SAVE_INVENTORY then
                recoveryIdleStreak = 0
                setPabrikStatus("Menyimpan ke Save World: " .. ctx.cfg.save.world)
                local okSave, saveErr = PF.StorageManager.executeSave(ctx, aliveFn)
                if not okSave then
                    if emitNotify then emitNotify("Pabrik Save Error", tostring(saveErr)) end
                    return "Save gagal: " .. tostring(saveErr)
                end

            elseif decision == DEC.COLLECT_PENDING then
                recoveryIdleStreak = 0
                setPabrikStatus("Collect & Verify drop...")
                PF.CollectManager.collectPending(ctx, aliveFn, buckets.collectPending)

            elseif decision == DEC.HARVEST_READY then
                recoveryIdleStreak = 0
                setPabrikStatus(string.format("Harvest %d pohon READY...", #buckets.ready))
                PF.HarvestManager.execute(ctx, buckets.ready, aliveFn)

            elseif decision == DEC.PLANT_EMPTY then
                recoveryIdleStreak = 0
                setPabrikStatus(string.format("Plant %d tile kosong (Seed:%d)...", #buckets.empty, ctx.inv.seedCount))
                PF.PlantManager.execute(ctx, buckets.empty, aliveFn)

            elseif decision == DEC.BREAK_REQUIRED then
                recoveryIdleStreak = 0
                setPabrikStatus(string.format("Break (%s) | B:%d S:%d", tostring(reason), ctx.inv.blockCount, ctx.inv.seedCount))
                local broke = PF.BreakManager.executeCycle(ctx, aliveFn)
                if not broke then
                    PF.Util.wait(0.30)
                end

            elseif decision == DEC.RECOVERY then
                recoveryIdleStreak = recoveryIdleStreak + 1
                setPabrikStatus(string.format("Recovery stok (B:0 S:0) [%d]...", recoveryIdleStreak))
                local recovered = PF.RecoveryManager.handleZeroStock(ctx, aliveFn)
                if not recovered then
                    PF.Util.wait(0.80)
                end

            else
                -- IDLE_RESCAN: responsive short sleep while monitoring growth
                PF.Logger.setActivity(ctx, "IDLE", "-", tostring(reason))
                if #buckets.growing > 0 then
                    setPabrikStatus(string.format("Grow %d/%d (~%.1fs) | B:%d S:%d",
                        #buckets.ready, #buckets.growing + #buckets.ready, buckets.minRem or 0,
                        ctx.inv.blockCount, ctx.inv.seedCount))
                else
                    setPabrikStatus(string.format("Idle (%s) | B:%d S:%d", tostring(reason), ctx.inv.blockCount, ctx.inv.seedCount))
                end
                if GetcSkipper and GetcSkipper.RandomizedWait then
                    GetcSkipper.RandomizedWait(0.30, nil, aliveFn)
                else
                    PF.Util.wait(0.30)
                end
            end
        end

        return "Stopped"
    end
end

-- Public Lifecycle API (Stop / Start / Toggle — 100% SYT compatible)
function Pabrik.Stop()
    Pabrik.State.running = false
    Pabrik.State.sessionToken = (Pabrik.State.sessionToken or 0) + 1
    if H then H.dfSpeedForceUntil = 0 end
    if Pabrik._activeCtx then
        PF.TaskManager.clearAll(Pabrik._activeCtx)
        Pabrik._activeCtx = nil
    end
    if Pabrik.State.thread then
        if task and task.cancel then pcall(task.cancel, Pabrik.State.thread) end
        Pabrik.State.thread = nil
    end
    if Core and Core.ClearManualInput then Core.ClearManualInput() end
    if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("PabRunToggle", false) end
    setPabrikStatus("Stopped")
    return false
end

function Pabrik.Start()
    if Pabrik.State.running then return true end
    if type(guardExclusiveStart) == "function" and not guardExclusiveStart("Pabrik") then
        if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("PabRunToggle", false) end
        return false
    end
    if Core and Core.EnsureInit then Core.EnsureInit() end
    if Core and Core.EnsureManualInputHook then Core.EnsureManualInputHook() end
    if Core and Core.SyncOneHitHook then Core.SyncOneHitHook() end
    pcall(function()
        local tb = UserInputService and UserInputService:GetFocusedTextBox()
        if tb then tb:ReleaseFocus() end
    end)

    local S = Pabrik.State
    S.progress = 0
    if (not S.blockId or not S.seedId) and UI and UI.GetValue then
        local okInp, rawInp = pcall(UI.GetValue, UI, "PabrikItemInput")
        if okInp and rawInp and tostring(rawInp) ~= "" then
            Pabrik.SetItem(tostring(rawInp))
        end
    end
    Pabrik.PruneInvalidTiles()
    if #Pabrik.GetSortedTiles() == 0 then
        Pabrik.SelectAllPlantable()
    end

    -- Auto-resolve item pair from planted seeds or backpack if user didn't pick yet
    if not S.blockId or not S.seedId then
        local gt0 = H and H.gt
        if gt0 and gt0.fg then
            local seedCounts = {}
            for _, t in ipairs(Pabrik.GetSortedTiles()) do
                local fid = Core.GetFG(t.x, t.y)
                if fid > 0 then
                    local inf = Core.GetItemInfo(fid)
                    if inf and inf.kind == "seed" then
                        seedCounts[fid] = (seedCounts[fid] or 0) + 1
                    end
                end
            end
            local bestSeed, bestCnt = nil, 0
            for sid, c in pairs(seedCounts) do
                if c > bestCnt then bestSeed, bestCnt = sid, c end
            end
            if bestSeed then Pabrik.SetItem(bestSeed) end
        end
        if (not S.blockId or not S.seedId) and PNB and type(PNB.GetBackpackBlocks) == "function" then
            local bpItems = PNB.GetBackpackBlocks(true, true)
            local bestId, bestScore = nil, -1
            for _, it in ipairs(bpItems or {}) do
                local pair = Core.ResolveBlockAndSeedPair(it.id)
                if pair and pair.blockId and pair.seedId then
                    local sc = (it.count or 0) + ((pair.blockId ~= 2 and pair.blockId ~= 10 and pair.blockId ~= 14) and 1000 or 0)
                    if sc > bestScore then
                        bestScore = sc
                        bestId = it.id
                    end
                end
            end
            if bestId then
                Pabrik.SetItem(bestId)
                if UI then pcall(UI.SetValue, UI, "PabrikItemInput", tostring(bestId), true) end
            end
        end
        if (not S.blockId or not S.seedId) and PNB and PNB.State and PNB.State.selectedBlockId then
            Pabrik.SetItem(PNB.State.selectedBlockId)
        end
    end

    if not S.blockId or not S.seedId then
        setPabrikStatus("Pilih Block / Seed dulu")
        if emitNotify then emitNotify("Pabrik", "Pilih Block / Seed dulu di Card!") end
        if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("PabRunToggle", false) end
        return false
    end
    if #Pabrik.GetSortedTiles() == 0 then
        setPabrikStatus("Pilih tile / deret valid di Dirt Selector")
        if emitNotify then emitNotify("Pabrik", "Pilih minimal 1 deret/tile di Dirt Selector!") end
        if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("PabRunToggle", false) end
        return false
    end
    if not S.breakPos then Pabrik.SetBreakPos() end
    if SystemModule and SystemModule.State then SystemModule.State.frozenByJoin = false end

    local gt = H and H.gt
    if not gt or (gt.name or "") == "" then
        setPabrikStatus("Belum masuk world")
        if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("PabRunToggle", false) end
        return false
    end

    S.running = true
    S.sessionToken = (S.sessionToken or 0) + 1
    local token = S.sessionToken
    local function alive() return S.running and S.sessionToken == token end
    setPabrikStatus("Initializing Intelligent Factory Scheduler...")
    if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("PabRunToggle", true) end

    S.thread = task.spawn(function()
        local cfg = PF.Config.getSnapshot()
        local bInfo = Core.GetItemInfo(cfg.blockId)
        local ctx = {
            cfg = cfg,
            productionWorld = PF.Util.cleanWorld(gt.name),
            blockLayer = (bInfo and bInfo.background) and 2 or 1,
            placeTiles = {},
            placeTileSet = {},
            breakTiles = {},
            breakTargetList = {},
            breakTargetSet = {},
            storageStatus = "IDLE",
            collectFailStreak = 0,
            collectCooldownUntil = 0,
        }
        PF.Logger.init(ctx)
        PF.TaskManager.create(ctx)
        PF.MoveController.init(ctx)
        Pabrik._activeCtx = ctx

        local finishReason = "Stopped"
        local okRun, errMsg = xpcall(function()
            finishReason = PF.Scheduler.runLoop(ctx, alive)
        end, function(err)
            return debug.traceback(tostring(err), 2)
        end)

        if not okRun then
            finishReason = "Err: " .. tostring(errMsg):match("([^\r\n]+)"):sub(1, 56)
            PF.Logger.log(ctx, "ERROR", tostring(errMsg))
            if warn then warn("[SYT Pabrik Error]: " .. tostring(errMsg)) end
        end

        if H then H.dfSpeedForceUntil = 0 end
        if Core and Core.ClearManualInput then Core.ClearManualInput() end
        PF.TaskManager.clearAll(ctx)
        if Pabrik._activeCtx == ctx then Pabrik._activeCtx = nil end
        if S.sessionToken == token then
            S.running = false
            S.thread = nil
            setPabrikStatus(finishReason)
            if UIHooks and UIHooks.syncRunToggle then UIHooks.syncRunToggle("PabRunToggle", false) end
            if UIHooks and UIHooks.refreshBP then pcall(UIHooks.refreshBP) end
            if UIHooks and UIHooks.updateButtons then UIHooks.updateButtons() end
        end
    end)

    return true
end

function Pabrik.Toggle()
    if Pabrik.State.running then
        return Pabrik.Stop()
    end
    return Pabrik.Start()
end
end

-- Discord Hook: Clean Running Status Embed + OS Storage MessageID (Only User Configured Webhook)
DiscordHook = {
    State = {
        url = "",
        delay = 120, -- 1-5 menit
        enabled = false,
        messageId = nil,
        startTime = nil,
        thread = nil,
        lastActionNote = "",
        lastUrl = nil,
        lastSentAt = 0,
        _sending = false,
        _pendingSend = false,
        _dirty = false,
        _rateLimitUntil = 0,
    }
}
SYT_Logic.DiscordHook = DiscordHook

function DiscordHook._jsonEscape(s)
    return tostring(s or ""):gsub("\\", "\\\\"):gsub('"', '\\"'):gsub("\n", "\\n"):gsub("\r", "")
end

function DiscordHook.GetSafeRequest()
    if type(syn) == "table" and type(syn.request) == "function" then return syn.request end
    if type(http) == "table" and type(http.request) == "function" then return http.request end
    if type(http_request) == "function" then return http_request end
    if type(request) == "function" then return request end
    return nil
end

function DiscordHook.NotifyStateChanged()
    if DiscordHook and DiscordHook.State then
        DiscordHook.State._dirty = true
    end
end

function DiscordHook._normalizeWebhookUrl(rawUrl)
    local s = (tostring(rawUrl or ""):sub(1, 300):match("^%s*(.-)%s*$")) or ""
    if s == "" then return "", "", "" end
    local baseUrl, queryStr = s:match("^([^?]+)(%?.*)$")
    if not baseUrl then baseUrl, queryStr = s, "" end
    baseUrl = baseUrl:gsub("/+$", "")
    return baseUrl .. queryStr, baseUrl, queryStr
end

function DiscordHook._extractMsgId(bodyStr)
    if type(bodyStr) ~= "string" or bodyStr == "" then return nil end
    local okJ, dec = pcall(function() return HttpService:JSONDecode(bodyStr) end)
    if okJ and type(dec) == "table" and dec.id ~= nil then
        local cleanId = tostring(dec.id):match("^(%d+)$")
        if cleanId then return cleanId end
    end
    return bodyStr:match('"id"%s*:%s*"(%d+)"')
end

function DiscordHook._activeFarmProgress()
    if PNB.State.running then return "PNB", tostring(PNB.State.progress or 0) .. "%" end
    if Pabrik.State.running then return "PABRIK", tostring(Pabrik.State.progress or 0) .. "%" end
    if DirtFarm.State.running then
        local secLbl = (DirtFarm.State.activeSection == "BAGAN_2") and "Bagan 2" or "Bagan 1"
        return "DIRT FARM (" .. secLbl .. ")", string.format("Tile %d%% | Work %d%% | Rem %d",
            tonumber(DirtFarm.State.tileProgressPct or DirtFarm.State.progress) or 0,
            tonumber(DirtFarm.State.estimatedWorkProgressPct or DirtFarm.State.progress) or 0,
            tonumber(DirtFarm.State.remainingTasks) or 0)
    end
    if ClearWorld.State.running then return "CLEAR WORLD", tostring(ClearWorld.State.progress or 0) .. "%" end
    if MoveBlock.State.running then return "MOVE BLOCK", tostring(MoveBlock.State.status or "Running") end
    if AutoLeveling.State.running then return "AUTO LEVELING", "Lv" .. tostring(AutoLeveling.GetLevel()) .. "/10" end
    if type(DirtFarm.State.status) == "string" and string.sub(DirtFarm.State.status, 1, 9) == "DF Error:" then
        return "ERROR (DF)", tostring(DirtFarm.State.status)
    end
    return "IDLE", "0%"
end

function DiscordHook.Send(noteLine, _retryDepth)
    local reqFn = DiscordHook.GetSafeRequest()
    local curUiUrl = UI and UI:GetValue("SysDiscordUrlInput")
    local rawSrcUrl = (type(curUiUrl) == "string" and curUiUrl:match("^%s*(.-)%s*$") ~= "") and curUiUrl or DiscordHook.State.url
    local hookUrl, baseUrl, queryStr = DiscordHook._normalizeWebhookUrl(rawSrcUrl)
    if not reqFn or hookUrl == "" then return false end
    DiscordHook.State.url = hookUrl
    if noteLine then DiscordHook.State.lastActionNote = tostring(noteLine) end

    if DiscordHook.State._sending and (_retryDepth or 0) == 0 then
        DiscordHook.State._pendingSend = true
        return false
    end
    DiscordHook.State._sending = true

    local function finishSend(resOk)
        DiscordHook.State._sending = false
        return resOk
    end

    local savedUrl = tostring(DiscordHook.State.lastUrl or safeReadStorage("syt_dhook_url.txt") or "")
    if savedUrl ~= "" and savedUrl ~= hookUrl then
        DiscordHook.State.messageId = nil
        safeWriteStorage("syt_dhook_mid.txt", "")
        if UI then pcall(UI.SetValue, UI, "DhMessageIdDisplay", "-") end
    end
    DiscordHook.State.lastUrl = hookUrl
    safeWriteStorage("syt_dhook_url.txt", hookUrl)

    local gt = H.gt
    local worldName = (gt and gt.name ~= "" and gt.name) or "-"
    local playerName = Core.GetInGameName(LP, true)
    local stName, progStr = DiscordHook._activeFarmProgress()
    local uptime = DiscordHook.State.startTime and math.floor(os.clock() - DiscordHook.State.startTime) or 0
    local uptimeStr = string.format("%02dh %02dm %02ds", math.floor(uptime / 3600), math.floor((uptime % 3600) / 60), uptime % 60)
    local safeTotal = tostring(SystemModule.State.safeCount or 0)
    if DiscordHook.State.lastActionNote ~= "" then
        safeTotal = safeTotal .. " | " .. DiscordHook.State.lastActionNote
    end

    local authorIcon = "https://media.discordapp.net/attachments/1571862046969176137/1571872000744620164/9b3d0135-5ab8-4239-8589-7ca6a12e246b.webp?ex=6afc4f60&is=6afafde0&hm=83fe3e652dfa9a704e7928a1ea692ebc432994e6259785fa8f3a8ef3d177c8b6&format=webp&width=768&height=768"
    local bannerImg = "https://media.discordapp.net/attachments/1571862046969176137/1571872352936140860/Gemini_Generated_Image_kqlim5kqlim5kqli.jpg?ex=6afc4fb4&is=6afafe34&hm=959ae0c770f6998ed2116041a9ff3af55278c2d0808a541d5276539c6bcb2cec&format=webp&width=1536&height=651"

    local bodyStr = string.format(
        '{"content":null,"embeds":[{"color":5765375,"fields":[' ..
        '{"name":"[  <a:king:1238156871282724895>  ]  -  NAME","value":"<a:angry:1515044838008160258> [ %s ]"},' ..
        '{"name":"[  <a:world:1113108638094069880>  ] -  WORLD","value":"<a:angry:1515044838008160258> [ %s ]"},' ..
        '{"name":"[  <a:damn:1462853718713045225>  ] -  STATE","value":"<a:angry:1515044838008160258> [ %s ]"},' ..
        '{"name":"[  <a:time:1345668076854841374>  ] -  UP TIME","value":"<a:angry:1515044838008160258> [ %s ]"},' ..
        '{"name":"[  <a:PROG:1430165994885746821>  ] -  PROGRESS","value":"<a:angry:1515044838008160258> [ %s ]"},' ..
        '{"name":"[  <a:SAFE:1280719300495282246>  ] -  SAFE TOTAL","value":"<a:angry:1515044838008160258> [ %s ]"}' ..
        '],"author":{"name":"%s","icon_url":"%s"},"footer":{"text":"Script created By DryCursed Community"},"image":{"url":"%s"}}],"attachments":[]}',
        DiscordHook._jsonEscape(playerName),
        DiscordHook._jsonEscape(worldName),
        DiscordHook._jsonEscape(stName),
        DiscordHook._jsonEscape(uptimeStr),
        DiscordHook._jsonEscape(progStr),
        DiscordHook._jsonEscape(safeTotal),
        DiscordHook._jsonEscape(playerName),
        authorIcon,
        bannerImg
    )

    local midRaw = DiscordHook.State.messageId or safeReadStorage("syt_dhook_mid.txt")
    local mid = type(midRaw) == "string" and midRaw:match("^%s*(%d+)%s*$") or nil
    local isPatch = (mid ~= nil)
    local method = isPatch and "PATCH" or "POST"
    local reqUrl = isPatch
        and (baseUrl .. "/messages/" .. mid .. queryStr)
        or ((queryStr ~= "") and (baseUrl .. queryStr .. "&wait=true") or (baseUrl .. "?wait=true"))

    local ok2, resp = pcall(reqFn, {
        Url = reqUrl,
        Method = method,
        Headers = { ["Content-Type"] = "application/json" },
        Body = bodyStr
    })
    if ok2 and type(resp) == "table" then
        local sc = tonumber(resp.StatusCode)
        if sc == 404 and isPatch and (_retryDepth or 0) < 1 then
            DiscordHook.State.messageId = nil
            safeWriteStorage("syt_dhook_mid.txt", "")
            if UI then pcall(UI.SetValue, UI, "DhMessageIdDisplay", "-") end
            DiscordHook.State._sending = false
            return DiscordHook.Send(noteLine, (_retryDepth or 0) + 1)
        elseif sc == 429 then
            local retryAfter = 2.5
            if type(resp.Body) == "string" then
                local ra = tonumber(resp.Body:match('"retry_after"%s*:%s*([%d%.]+)'))
                if ra then retryAfter = clamp(ra + 0.3, 1.0, 15.0) end
            end
            DiscordHook.State._rateLimitUntil = os.clock() + retryAfter
            DiscordHook.State._pendingSend = true
            return finishSend(false)
        elseif sc and sc >= 200 and sc < 300 then
            DiscordHook.State.lastSentAt = os.clock()
            if method == "POST" and type(resp.Body) == "string" then
                local newId = DiscordHook._extractMsgId(resp.Body)
                if newId then
                    DiscordHook.State.messageId = newId
                    safeWriteStorage("syt_dhook_mid.txt", newId)
                    if UI then pcall(UI.SetValue, UI, "DhMessageIdDisplay", newId) end
                end
            elseif method == "PATCH" and UI then
                pcall(UI.SetValue, UI, "DhMessageIdDisplay", mid)
            end
            return finishSend(true)
        end
    end
    return finishSend(false)
end

function DiscordHook.Stop()
    DiscordHook.State.enabled = false
    DiscordHook.State._pendingSend = false
    DiscordHook.State._dirty = false
    if DiscordHook.State.thread then
        pcall(task.cancel, DiscordHook.State.thread)
        DiscordHook.State.thread = nil
    end
end

function DiscordHook.Start()
    local curUrl = UI and UI:GetValue("SysDiscordUrlInput")
    local chosen = (type(curUrl) == "string" and curUrl ~= "") and curUrl or DiscordHook.State.url
    local normUrl = select(1, DiscordHook._normalizeWebhookUrl(chosen))
    DiscordHook.State.url = normUrl
    if DiscordHook.State.url == "" then
        DiscordHook.State.enabled = false
        if UI then pcall(UI.SetValue, UI, "DhEnabledToggle", false, true) end
        emitNotify("Discord Hook", "Masukkan link Discord Webhook terlebih dahulu!")
        return false
    end
    if DiscordHook.State.enabled and DiscordHook.State.thread then
        DiscordHook.NotifyStateChanged()
        return true
    end
    DiscordHook.State.enabled = true
    DiscordHook.State.startTime = DiscordHook.State.startTime or os.clock()
    local savedMid = tostring(DiscordHook.State.messageId or safeReadStorage("syt_dhook_mid.txt") or ""):match("^%s*(%d+)%s*$")
    DiscordHook.State.messageId = savedMid
    if UI then
        pcall(UI.SetValue, UI, "DhMessageIdDisplay", savedMid or "-")
    end

    DiscordHook.State.lastSentAt = 0
    DiscordHook.State._dirty = true
    DiscordHook.State._pendingSend = true
    DiscordHook.State.thread = task.spawn(function()
        local lastMajorSig, lastFullSig = "", ""
        while DiscordHook.State.enabled do
            if getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then
                DiscordHook.State.enabled = false
                break
            end
            local now = os.clock()
            local waitSec = clamp(tonumber(DiscordHook.State.delay) or 120, 60, 300)
            local rateUntil = tonumber(DiscordHook.State._rateLimitUntil) or 0
            local lastSentAt = tonumber(DiscordHook.State.lastSentAt) or 0
            if now >= rateUntil and not DiscordHook.State._sending then
                local gt = H.gt
                local worldName = (gt and gt.name ~= "" and gt.name) or "-"
                local stName, progStr = DiscordHook._activeFarmProgress()
                local safeTotal = tostring(SystemModule.State.safeCount or 0)
                local majorSig = stName .. "|" .. worldName .. "|" .. safeTotal
                local fullSig = majorSig .. "|" .. progStr

                local shouldSend = false
                if lastSentAt == 0 then
                    shouldSend = true
                elseif (majorSig ~= lastMajorSig or DiscordHook.State._dirty) and (now - lastSentAt) >= 1.8 then
                    shouldSend = true
                elseif DiscordHook.State._pendingSend and (now - lastSentAt) >= 1.8 then
                    shouldSend = true
                elseif fullSig ~= lastFullSig and stName ~= "IDLE" and (now - lastSentAt) >= 8.0 then
                    shouldSend = true
                elseif (now - lastSentAt) >= waitSec then
                    shouldSend = true
                end

                if shouldSend then
                    DiscordHook.State._dirty = false
                    DiscordHook.State._pendingSend = false
                    local okCall, okSend = pcall(DiscordHook.Send)
                    if okCall and okSend then
                        lastMajorSig = majorSig
                        lastFullSig = fullSig
                    else
                        DiscordHook.State.lastSentAt = os.clock()
                    end
                end
            end
            task.wait(0.45)
        end
    end)
    return true
end

function DiscordHook.Toggle()
    if DiscordHook.State.enabled then return DiscordHook.Stop() end
    return DiscordHook.Start()
end

function DiscordHook.SendRunLogOnce()
    -- [SAFE] Hidden "SYT First Run Log" removed: previously sent Username, UserId,
    -- DisplayName, World, Executor & PlaceId to the developer's hardcoded Discord webhook.
    return false
end

