    local function computePreviewLook()
        local wt = H.wornTbl or {}
        local eff = {}
        for _, sl in ipairs(Visual.Presets.wearSlots or { "back", "hand", "hat", "hair", "shirt", "pants", "feet", "face", "chest", "ances", "neck", "mask", "ring", "pet" }) do
            local fv = Visual.State.fakeWorn[sl]
            if fv ~= nil then
                if type(fv) == "number" and fv > 0 then eff[sl] = fv end
            elseif type(wt[sl]) == "number" and wt[sl] > 0 then
                eff[sl] = wt[sl]
            end
        end
        local spNm = Visual.State.skinPreset or "Real (Server Skin)"
        local skinCol = (spNm ~= "Real (Server Skin)" and spNm ~= "Ghost (See-Through)" and Visual.Presets.skins[spNm])
            or Visual.State.origSkin
            or (H.playerSpriteObj and rawget(H.playerSpriteObj, "SKIN"))
            or Color3.fromRGB(255, 214, 178)
        local isGhost = (Visual.State.ghostSkin == true or spNm == "Ghost (See-Through)")
        return eff, skinCol, isGhost
    end

    local previewAnimConn = nil
    local lastAnimTick = 0
    if sg and typeof(sg) == "Instance" then
        previewAnimConn = RunService.Heartbeat:Connect(function()
            if not sg.Parent or not staticRig then
                if previewAnimConn then previewAnimConn:Disconnect(); previewAnimConn = nil end
                return
            end
            if not UI or UI.IsMinimized or not canAccessInst(UI.MainWindow) or UI.MainWindow.Visible ~= true then
                return
            end
            local okVis, boxVis = pcall(function() return avatarBox.Visible and charStage.Visible end)
            if not okVis or not boxVis then return end
            local t = os.clock()
            if (t - lastAnimTick) >= 0.14 then
                lastAnimTick = t
                local eff, skinCol, isGhost = computePreviewLook()
                pcall(Core.ApplyLookToStaticRig, staticRig, eff, skinCol, isGhost, t)
            end
        end)
    end
    local function cleanupPortraitRig()
        if previewAnimConn then
            pcall(function() previewAnimConn:Disconnect() end)
            previewAnimConn = nil
        end
        staticRig = nil
    end
