    local function makeRounded(parent, radius, strokeColor, strokeThick, strokeTrans)
        local c = Instance.new("UICorner", parent)
        c.CornerRadius = UDim.new(0, radius or 6)
        if strokeColor then
            local st = Instance.new("UIStroke", parent)
            st.Color = strokeColor
            st.Thickness = strokeThick or 1
            st.Transparency = strokeTrans or 0
        end
    end

    local function addDetailSection(parent, order, title, bodyText, accentColor, isCode)
        local card = Instance.new("Frame", parent)
        card.LayoutOrder = order
        card.Size = UDim2.new(1, -6, 0, 0)
        card.AutomaticSize = Enum.AutomaticSize.Y
        card.BackgroundColor3 = isCode and Color3.fromRGB(8, 22, 44) or Color3.fromRGB(16, 40, 74)
        card.BorderSizePixel = 0
        makeRounded(card, 7, isCode and Color3.fromRGB(245, 158, 11) or Color3.fromRGB(46, 102, 168), 1, isCode and 0.15 or 0.35)

        local bar = Instance.new("Frame", card)
        bar.Size = UDim2.new(0, 4, 1, -10)
        bar.Position = UDim2.fromOffset(5, 5)
        bar.BackgroundColor3 = accentColor or Color3.fromRGB(56, 189, 248)
        bar.BorderSizePixel = 0
        makeRounded(bar, 2)

        local pad = Instance.new("UIPadding", card)
        pad.PaddingLeft = UDim.new(0, 15)
        pad.PaddingRight = UDim.new(0, 10)
        pad.PaddingTop = UDim.new(0, 7)
        pad.PaddingBottom = UDim.new(0, 8)

        local lay = Instance.new("UIListLayout", card)
        lay.SortOrder = Enum.SortOrder.LayoutOrder
        lay.Padding = UDim.new(0, 4)

        local tLbl = Instance.new("TextLabel", card)
        tLbl.LayoutOrder = 1
        tLbl.Size = UDim2.new(1, 0, 0, 15)
        tLbl.BackgroundTransparency = 1
        tLbl.Font = Enum.Font.GothamBold
        tLbl.TextSize = 11
        tLbl.TextXAlignment = Enum.TextXAlignment.Left
        tLbl.TextColor3 = accentColor or Color3.fromRGB(251, 191, 36)
        tLbl.Text = string.upper(tostring(title or "INFO"))

        local bLbl = Instance.new("TextLabel", card)
        bLbl.LayoutOrder = 2
        bLbl.Size = UDim2.new(1, 0, 0, 0)
        bLbl.AutomaticSize = Enum.AutomaticSize.Y
        bLbl.BackgroundTransparency = 1
        bLbl.RichText = true
        bLbl.TextWrapped = true
        bLbl.Font = isCode and Enum.Font.Code or Enum.Font.Gotham
        bLbl.TextSize = isCode and 12 or 11.5
        bLbl.TextXAlignment = Enum.TextXAlignment.Left
        bLbl.TextYAlignment = Enum.TextYAlignment.Top
        bLbl.TextColor3 = isCode and Color3.fromRGB(254, 240, 138) or Color3.fromRGB(226, 238, 252)
        bLbl.Text = bodyText
        return card
    end

    function ProxyCommands.OpenListDialog()
        local sg, inner = makeNativeGameDialog("List", "", 760, 485)
        -- Hide default plain header/close so our custom Growtopia Event Dialog Banner renders cleanly
        for _, ch in ipairs(inner:GetChildren()) do
            if ch:IsA("TextLabel") or ch:IsA("TextButton") then
                ch.Visible = false
            end
        end

        -- Layered Growtopia Blue + Gold Event Dialog Styling
        local outerBox = inner.Parent
        if outerBox and outerBox:IsA("Frame") then
            outerBox.BackgroundColor3 = Color3.fromRGB(11, 34, 68)
            local oCorner = outerBox:FindFirstChildOfClass("UICorner")
            if oCorner then oCorner.CornerRadius = UDim.new(0, 12) end
            local oStroke = outerBox:FindFirstChildOfClass("UIStroke")
            if oStroke then
                oStroke.Color = Color3.fromRGB(56, 189, 248)
                oStroke.Thickness = 2.2
                oStroke.Transparency = 0.08
            end
        end
        inner.Position = UDim2.fromOffset(4, 4)
        inner.Size = UDim2.new(1, -8, 1, -8)
        inner.BackgroundColor3 = Color3.fromRGB(10, 27, 54)
        local iCorner = inner:FindFirstChildOfClass("UICorner")
        if iCorner then iCorner.CornerRadius = UDim.new(0, 10) end
        local iStroke = inner:FindFirstChildOfClass("UIStroke")
        if iStroke then
            iStroke.Color = Color3.fromRGB(245, 158, 11)
            iStroke.Thickness = 1.4
            iStroke.Transparency = 0.25
        end

        local categories, allFeatures = ProxyCommands.BuildFeatureCatalog()
        local uiState = {
            category = "ALL",
            search = "",
            selectedId = nil,
            showOverview = true,
            tutorialExpanded = true,
            filtered = {},
        }

        -- 1. COLORFUL GROWTOPIA EVENT HEADER BANNER
        local banner = Instance.new("Frame", inner)
        banner.Size = UDim2.new(1, -12, 0, 74)
        banner.Position = UDim2.fromOffset(6, 6)
        banner.BackgroundColor3 = Color3.fromRGB(20, 86, 168)
        banner.BorderSizePixel = 0
        banner.ClipsDescendants = true
        makeRounded(banner, 9, Color3.fromRGB(251, 191, 36), 1.4, 0.12)

        local banGrad = Instance.new("UIGradient", banner)
        banGrad.Rotation = 18
        banGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(29, 118, 218)),
            ColorSequenceKeypoint.new(0.55, Color3.fromRGB(16, 66, 142)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(11, 44, 102)),
        })

        -- Bottom warm gold trim inside banner
        local goldTrim = Instance.new("Frame", banner)
        goldTrim.Size = UDim2.new(1, 0, 0, 3)
        goldTrim.Position = UDim2.new(0, 0, 1, -3)
        goldTrim.BackgroundColor3 = Color3.fromRGB(245, 158, 11)
        goldTrim.BorderSizePixel = 0

        -- Pixel-game decorative stars/blocks on banner background
        for _, dec in ipairs({
            { x = 515, y = 10, s = 8,  c = Color3.fromRGB(251, 191, 36), t = 0.25 },
            { x = 532, y = 26, s = 5,  c = Color3.fromRGB(125, 211, 252), t = 0.20 },
            { x = 560, y = 14, s = 6,  c = Color3.fromRGB(253, 224, 71), t = 0.30 },
            { x = 602, y = 44, s = 7,  c = Color3.fromRGB(56, 189, 248), t = 0.35 },
            { x = 472, y = 48, s = 5,  c = Color3.fromRGB(251, 146, 60), t = 0.30 },
        }) do
            local px = Instance.new("Frame", banner)
            px.Size = UDim2.fromOffset(dec.s, dec.s)
            px.Position = UDim2.fromOffset(dec.x, dec.y)
            px.BackgroundColor3 = dec.c
            px.BackgroundTransparency = dec.t
            px.BorderSizePixel = 0
            makeRounded(px, 2)
        end

        -- Proxy Branding Logo Shield
        local logoFrame = Instance.new("Frame", banner)
        logoFrame.Size = UDim2.fromOffset(52, 52)
        logoFrame.Position = UDim2.fromOffset(12, 10)
        logoFrame.BackgroundColor3 = Color3.fromRGB(12, 42, 92)
        logoFrame.BorderSizePixel = 0
        makeRounded(logoFrame, 9, Color3.fromRGB(251, 191, 36), 2, 0.05)

        local logoGrad = Instance.new("UIGradient", logoFrame)
        logoGrad.Rotation = 45
        logoGrad.Color = ColorSequence.new(Color3.fromRGB(37, 99, 235), Color3.fromRGB(14, 116, 144))

        local logoTop = Instance.new("TextLabel", logoFrame)
        logoTop.Size = UDim2.new(1, 0, 0, 16)
        logoTop.Position = UDim2.fromOffset(0, 5)
        logoTop.BackgroundTransparency = 1
        logoTop.Font = Enum.Font.GothamBlack
        logoTop.TextSize = 11
        logoTop.TextColor3 = Color3.fromRGB(253, 224, 71)
        logoTop.Text = "★ SYT ★"

        local logoMid = Instance.new("TextLabel", logoFrame)
        logoMid.Size = UDim2.new(1, 0, 0, 22)
        logoMid.Position = UDim2.fromOffset(0, 22)
        logoMid.BackgroundTransparency = 1
        logoMid.Font = Enum.Font.GothamBlack
        logoMid.TextSize = 14
        logoMid.TextColor3 = Color3.new(1, 1, 1)
        logoMid.Text = "PRX"

        -- Main Title + Drop Shadow + Subtitle
        local titleShadow = Instance.new("TextLabel", banner)
        titleShadow.Size = UDim2.new(0, 390, 0, 28)
        titleShadow.Position = UDim2.fromOffset(77, 13)
        titleShadow.BackgroundTransparency = 1
        titleShadow.Font = Enum.Font.GothamBlack
        titleShadow.TextSize = 21
        titleShadow.TextXAlignment = Enum.TextXAlignment.Left
        titleShadow.TextColor3 = Color3.fromRGB(6, 18, 38)
        titleShadow.TextTransparency = 0.35
        titleShadow.Text = "PROXY CONTROL CENTER"

        local titleMain = Instance.new("TextLabel", banner)
        titleMain.Size = UDim2.new(0, 390, 0, 28)
        titleMain.Position = UDim2.fromOffset(75, 11)
        titleMain.BackgroundTransparency = 1
        titleMain.Font = Enum.Font.GothamBlack
        titleMain.TextSize = 21
        titleMain.TextXAlignment = Enum.TextXAlignment.Left
        titleMain.TextColor3 = Color3.fromRGB(255, 250, 235)
        titleMain.Text = "PROXY CONTROL CENTER"

        local subtitle = Instance.new("TextLabel", banner)
        subtitle.Size = UDim2.new(0, 410, 0, 18)
        subtitle.Position = UDim2.fromOffset(76, 40)
        subtitle.BackgroundTransparency = 1
        subtitle.Font = Enum.Font.GothamMedium
        subtitle.TextSize = 12
        subtitle.TextXAlignment = Enum.TextXAlignment.Left
        subtitle.TextColor3 = Color3.fromRGB(253, 230, 138)
        subtitle.Text = "Explore Features & Learn How To Use  |  Interactive Proxy Guide"

        -- Banner Live Summary Pill
        local summaryPill = Instance.new("TextLabel", banner)
        summaryPill.Size = UDim2.fromOffset(175, 24)
        summaryPill.Position = UDim2.new(1, -252, 0, 23)
        summaryPill.BackgroundColor3 = Color3.fromRGB(9, 28, 60)
        summaryPill.BackgroundTransparency = 0.12
        summaryPill.BorderSizePixel = 0
        summaryPill.Font = Enum.Font.GothamBold
        summaryPill.TextSize = 11
        summaryPill.TextColor3 = Color3.fromRGB(125, 211, 252)
        summaryPill.Text = string.format("%d Features  •  %d Categories", #allFeatures, #categories - 1)
