        -- Render Helpers
        local function clearScrollChildren(sf)
            for _, ch in ipairs(sf:GetChildren()) do
                if not ch:IsA("UIListLayout") and not ch:IsA("UIPadding") then
                    ch:Destroy()
                end
            end
        end

        local function getFilteredFeatures()
            local q = string.lower((uiState.search or ""):match("^%s*(.-)%s*$") or "")
            local out = {}
            for _, f in ipairs(allFeatures) do
                local catOk = (uiState.category == "ALL") or (f.category == uiState.category)
                if catOk then
                    if q == "" then
                        out[#out + 1] = f
                    else
                        local hay = string.lower(table.concat({
                            f.name or "", f.syntax or "", f.shortDesc or "", f.category or "", f.whatItDoes or ""
                        }, " "))
                        if string.find(hay, q, 1, true) then
                            out[#out + 1] = f
                        end
                    end
                end
            end
            return out
        end

