            copyBtn.Text = "COPY EXAMPLE"
            makeRounded(copyBtn, 5)
            copyBtn.MouseButton1Click:Connect(function()
                copyExampleToUser(feat.example)
            end)

            if feat.quickAction and type(feat.quickAction.run) == "function" then
                local actBtn = Instance.new("TextButton", head)
                actBtn.Size = UDim2.fromOffset(112, 20)
                actBtn.Position = UDim2.fromOffset(176, 49)
                actBtn.BackgroundColor3 = Color3.fromRGB(34, 197, 94)
                actBtn.BorderSizePixel = 0
                actBtn.Font = Enum.Font.GothamBold
                actBtn.TextSize = 10
                actBtn.TextColor3 = Color3.fromRGB(10, 18, 32)
                actBtn.Text = tostring(feat.quickAction.label or "RUN")
                makeRounded(actBtn, 5)
                actBtn.MouseButton1Click:Connect(function()
                    pcall(feat.quickAction.run)
                    task.delay(0.1, function()
                        if sg and sg.Parent then
                            refreshLiveStrip()
                            renderAll()
                        end
                    end)
                end)
            end

            -- Syntax & Parameters Code Card
            local synBody = string.format(
                '<b>Syntax:</b> %s\n<b>Parameters:</b> %s\n<b>Default:</b> %s',
