            expBtn.TextSize = 11
            expBtn.TextColor3 = Color3.fromRGB(253, 224, 71)
            expBtn.Text = uiState.tutorialExpanded
                and "[-] Hide Step-by-Step Tutorial, Example & Notes"
                or  "[+] Expand Step-by-Step Tutorial, Example & Notes"
            makeRounded(expBtn, 6, Color3.fromRGB(56, 189, 248), 1, 0.35)
            expBtn.MouseButton1Click:Connect(function()
                uiState.tutorialExpanded = not uiState.tutorialExpanded
                renderFeatureDetail(feat, idxInList)
            end)

            if uiState.tutorialExpanded then
                local stepLines = {}
                for i, stp in ipairs(feat.steps or {}) do
                    stepLines[#stepLines + 1] = string.format("<b>%d.</b> %s", i, escapeRichText(clampDialogText(stp, 140)))
                end
                if #stepLines == 0 then stepLines[1] = "Undocumented" end
                addDetailSection(rightPanel, 5, "How To Activate (Tutorial)", table.concat(stepLines, "\n"), Color3.fromRGB(34, 197, 94), false)

                local exBody = string.format(
                    '<b>Example:</b> <font color="#FDE047">%s</font>\n<b>Expected Result:</b> %s',
                    escapeRichText(clampDialogText(feat.example, 110)),
                    escapeRichText(clampDialogText(feat.expectedResult, 240))
                )
                addDetailSection(rightPanel, 6, "Usage Example & Expected Result", exBody, Color3.fromRGB(74, 222, 128), false)

                addDetailSection(rightPanel, 7, "Important Notes & Limitations", escapeRichText(clampDialogText(feat.notes, 260)), Color3.fromRGB(251, 146, 60), false)
            end
        end

        renderAll = function()
            refreshLiveStrip()
            uiState.filtered = getFilteredFeatures()

            -- Update category tab highlight
            for cid, btn in pairs(catButtons) do
                local active = (cid == uiState.category)
                btn.BackgroundColor3 = active and Color3.fromRGB(245, 158, 11) or Color3.fromRGB(20, 54, 102)
                btn.TextColor3 = active and Color3.fromRGB(15, 23, 42) or Color3.fromRGB(224, 242, 254)
            end

            -- Rebuild left feature cards
            clearScrollChildren(leftList)
            local selectedFeat, selectedIdx = nil, 0
            if #uiState.filtered == 0 then
                local emptyLbl = Instance.new("TextLabel", leftList)
                emptyLbl.Size = UDim2.new(1, 0, 0, 50)
                emptyLbl.BackgroundTransparency = 1
                emptyLbl.TextWrapped = true
                emptyLbl.Font = Enum.Font.GothamMedium
                emptyLbl.TextSize = 12
                emptyLbl.TextColor3 = Color3.fromRGB(148, 163, 184)
                emptyLbl.Text = "No matching features found.\nTry clearing your search."
            else
                for idx, feat in ipairs(uiState.filtered) do
                    if not uiState.showOverview and (uiState.selectedId == feat.id or (uiState.selectedId == nil and idx == 1)) then
                        selectedFeat = feat
                        selectedIdx = idx
                        uiState.selectedId = feat.id
                    end
                    local isSel = (not uiState.showOverview and selectedFeat == feat)
                    local stText, stCol = "READY", Color3.fromRGB(56, 189, 248)
                    if type(feat.statusFn) == "function" then stText, stCol = feat.statusFn() end

                    local btn = Instance.new("TextButton", leftList)
                    btn.LayoutOrder = idx
                    btn.Size = UDim2.new(1, 0, 0, 52)
                    btn.BackgroundColor3 = isSel and Color3.fromRGB(26, 78, 146) or Color3.fromRGB(16, 40, 74)
                    btn.BorderSizePixel = 0
                    btn.Text = ""
                    btn.AutoButtonColor = false
                    makeRounded(btn, 7, isSel and Color3.fromRGB(251, 191, 36) or Color3.fromRGB(37, 84, 140), isSel and 1.6 or 1, isSel and 0.05 or 0.35)

                    local badge = Instance.new("TextLabel", btn)
                    badge.Size = UDim2.fromOffset(32, 32)
                    badge.Position = UDim2.fromOffset(7, 10)
                    badge.BackgroundColor3 = feat.iconColor or Color3.fromRGB(56, 189, 248)
                    badge.BorderSizePixel = 0
                    badge.Font = Enum.Font.GothamBlack
                    badge.TextSize = 10
                    badge.TextColor3 = Color3.fromRGB(10, 18, 32)
                    badge.Text = feat.icon or "PRX"
                    makeRounded(badge, 6)

                    local nm = Instance.new("TextLabel", btn)
                    nm.Size = UDim2.new(1, -104, 0, 16)
                    nm.Position = UDim2.fromOffset(45, 6)
                    nm.BackgroundTransparency = 1
                    nm.Font = Enum.Font.GothamBold
                    nm.TextSize = 11.5
                    nm.TextXAlignment = Enum.TextXAlignment.Left
                    nm.TextTruncate = Enum.TextTruncate.AtEnd
                    nm.TextColor3 = isSel and Color3.fromRGB(253, 224, 71) or Color3.new(1, 1, 1)
                    nm.Text = feat.name

                    local syn = Instance.new("TextLabel", btn)
                    syn.Size = UDim2.new(1, -52, 0, 14)
                    syn.Position = UDim2.fromOffset(45, 22)
                    syn.BackgroundTransparency = 1
                    syn.Font = Enum.Font.Code
                    syn.TextSize = 10
                    syn.TextXAlignment = Enum.TextXAlignment.Left
                    syn.TextTruncate = Enum.TextTruncate.AtEnd
                    syn.TextColor3 = Color3.fromRGB(125, 211, 252)
                    syn.Text = feat.syntax

                    local sd = Instance.new("TextLabel", btn)
                    sd.Size = UDim2.new(1, -52, 0, 13)
                    sd.Position = UDim2.fromOffset(45, 36)
                    sd.BackgroundTransparency = 1
                    sd.Font = Enum.Font.Gotham
                    sd.TextSize = 9.5
                    sd.TextXAlignment = Enum.TextXAlignment.Left
                    sd.TextTruncate = Enum.TextTruncate.AtEnd
                    sd.TextColor3 = Color3.fromRGB(186, 210, 236)
                    sd.Text = feat.shortDesc

                    local stBadge = Instance.new("TextLabel", btn)
                    stBadge.Size = UDim2.fromOffset(52, 14)
                    stBadge.Position = UDim2.new(1, -57, 0, 6)
                    stBadge.BackgroundColor3 = stCol
                    stBadge.BorderSizePixel = 0
                    stBadge.Font = Enum.Font.GothamBold
                    stBadge.TextSize = 8.5
                    stBadge.TextColor3 = Color3.fromRGB(10, 18, 32)
                    stBadge.Text = tostring(stText)
                    makeRounded(stBadge, 4)

                    btn.MouseButton1Click:Connect(function()
                        uiState.showOverview = false
                        uiState.selectedId = feat.id
                        renderAll()
                    end)
                end
            end

            if uiState.showOverview or not selectedFeat then
                renderOverview()
            else
                renderFeatureDetail(selectedFeat, selectedIdx)
            end
        end

        -- Build Category Tabs
        for i, cat in ipairs(categories) do
            local cnt = 0
            for _, f in ipairs(allFeatures) do
                if cat.id == "ALL" or f.category == cat.id then cnt = cnt + 1 end
            end
            local cBtn = Instance.new("TextButton", catBar)
            cBtn.LayoutOrder = i
            cBtn.Size = UDim2.new(0, (cat.id == "ALL") and 78 or 116, 1, 0)
            cBtn.BackgroundColor3 = Color3.fromRGB(20, 54, 102)
            cBtn.BorderSizePixel = 0
            cBtn.Font = Enum.Font.GothamBold
            cBtn.TextSize = 11
            cBtn.TextColor3 = Color3.fromRGB(224, 242, 254)
            cBtn.Text = string.format("%s (%d)", cat.label, cnt)
            makeRounded(cBtn, 6, Color3.fromRGB(56, 189, 248), 1, 0.4)
            cBtn.MouseButton1Click:Connect(function()
                uiState.category = cat.id
                if cat.id == "ALL" then
                    uiState.showOverview = true
                    uiState.selectedId = nil
                else
                    uiState.showOverview = false
                    uiState.selectedId = nil
                end
                renderAll()
            end)
            catButtons[cat.id] = cBtn
        end

        -- Interactive Wiring (Search, Clear, Prev/Next, Back to Overview)
        searchBox:GetPropertyChangedSignal("Text"):Connect(function()
            uiState.search = searchBox.Text or ""
            if uiState.search ~= "" then
                uiState.showOverview = false
                uiState.selectedId = nil
            end
            renderAll()
        end)

        clearSearchBtn.MouseButton1Click:Connect(function()
            searchBox.Text = ""
            uiState.search = ""
            uiState.showOverview = true
            uiState.selectedId = nil
            renderAll()
        end)

        prevBtn.MouseButton1Click:Connect(function()
            if #uiState.filtered == 0 then return end
            if uiState.showOverview then
                uiState.showOverview = false
                uiState.selectedId = uiState.filtered[#uiState.filtered].id
            else
                local curIdx = 1
                for i, f in ipairs(uiState.filtered) do
                    if f.id == uiState.selectedId then curIdx = i; break end
                end
                local nextIdx = (curIdx <= 1) and #uiState.filtered or (curIdx - 1)
                uiState.selectedId = uiState.filtered[nextIdx].id
            end
            renderAll()
        end)

        nextBtn.MouseButton1Click:Connect(function()
            if #uiState.filtered == 0 then return end
            if uiState.showOverview then
                uiState.showOverview = false
                uiState.selectedId = uiState.filtered[1].id
            else
                local curIdx = 1
                for i, f in ipairs(uiState.filtered) do
                    if f.id == uiState.selectedId then curIdx = i; break end
                end
                local nextIdx = (curIdx >= #uiState.filtered) and 1 or (curIdx + 1)
                uiState.selectedId = uiState.filtered[nextIdx].id
            end
            renderAll()
        end)

        backOverviewBtn.MouseButton1Click:Connect(function()
            uiState.showOverview = true
            uiState.selectedId = nil
            renderAll()
        end)

        renderAll()
    end
end

-- Host BJ /cal Execution
function ProxyCommands.RunHostBjCalculate()
    local bj = ProxyCommands.State.bj
    if bj.running then proxyConsole("`4[BJ] Kalkulasi sedang berjalan!``"); return end
    if not bj.b1 or not bj.b2 or not bj.t1 or not bj.t2 then
        proxyConsole("`4[BJ] Set semua posisi dulu (/set b 1, /set b 2, /lock t 1, /lock t 2)!``")
        return
    end
    bj.running = true
    task.spawn(function()
        local function alive() return bj.running end
        local function countGemsAroundB(pos)
            Packets.WalkTeleport({ tx = pos.x, ty = pos.y, mode = "walk" })
            task.wait(0.25)
            local before = Core.ReadGems()
            -- Radius kecil (1.15) agar akurat dan tidak terambil ke kotak lawan
            Packets.Collect({ radius = 1.15, filterId = 112, stepMoveIfFar = false, preferWalk = true, collectDelay = 0.05, shouldContinue = alive })
            task.wait(0.30)
            return math.max(0, Core.ReadGems() - before)
        end

        local g1 = countGemsAroundB(bj.b1)
        Packets.SendChat({ message = string.format("[ + %d ]", g1), maxLength = 85 })
        task.wait(2.0)

        local g2 = countGemsAroundB(bj.b2)
        Packets.SendChat({ message = string.format("[ + %d ]", g2), maxLength = 85 })
        task.wait(0.8)

        -- Cek gems paling besar, lalu kumpulkan Lock dari T1 dan T2
        local winPos = (g1 >= g2) and bj.t1 or bj.t2
        local winnerLabel = (g1 >= g2) and "P1" or "P2"
        local beforeWL = Core.CountItem(242)
        local beforeDL = Core.CountItem(1796)
        Packets.WalkTeleport({ tx = bj.t1.x, ty = bj.t1.y, mode = "walk" })
        Packets.Collect({ radius = 1.4, stepMoveIfFar = false, preferWalk = true, collectDelay = 0.05, shouldContinue = alive })
        task.wait(0.3)
        Packets.WalkTeleport({ tx = bj.t2.x, ty = bj.t2.y, mode = "walk" })
        Packets.Collect({ radius = 1.4, stepMoveIfFar = false, preferWalk = true, collectDelay = 0.05, shouldContinue = alive })
        task.wait(0.3)

        local totalWL = math.max(0, (Core.CountItem(242) - beforeWL)) + math.max(0, (Core.CountItem(1796) - beforeDL)) * 100
        local payoutWL = math.floor(totalWL * (100 - clamp(bj.tax or 0, 0, 100)) / 100)
        Packets.WalkTeleport({ tx = winPos.x, ty = winPos.y, mode = "walk" })
        task.wait(0.25)
        if payoutWL >= 100 and Core.CountItem(1796) > 0 then
            local dls = math.min(Core.CountItem(1796), math.floor(payoutWL / 100))
            if dls > 0 then Packets.Drop(1796, dls); payoutWL = payoutWL - dls * 100 end
        end
        if payoutWL > 0 and Core.CountItem(242) > 0 then
            Packets.Drop(242, math.min(Core.CountItem(242), payoutWL))
        end
        proxyConsole(string.format("`2[BJ] %s WIN (%d vs %d) | Total:%d WL | Tax:%d%% | Drop:%d WL``", winnerLabel, g1, g2, totalWL, bj.tax or 0, math.floor(totalWL * (100 - (bj.tax or 0)) / 100)))
        bj.running = false
    end)
end

do
local function forceExpireWheelCooldown(px, py)
    local gt = H.gt
    if not gt or not gt.w or px == nil or py == nil then return end
    local tx, ty = toInt(px, 0), toInt(py, 0)
    local idx = ty * gt.w + tx
    local function expireOnce()
        local spins = H.wheelSpins or Core.DiscoverWheelSpins(false)
        if type(spins) == "table" and type(spins[idx]) == "table" then
            local e = spins[idx]
            if (e.ends or 0) > os.clock() - 0.05 then
                e.ends = os.clock() - 0.1
            end
        end
    end
    expireOnce()
    task.defer(expireOnce)
    for _, dly in ipairs({ 0.02, 0.06, 0.14, 0.24 }) do
        task.delay(dly, expireOnce)
    end
end

local function resolveWorldPlayerUid(uidHint, nameHint)
    local numUid = tonumber(uidHint)
    if numUid and numUid ~= 0 then
        local nm = stripColorTags(tostring(nameHint or ""))
        if nm == "" then
            local plr = Players:GetPlayerByUserId(numUid)
            if plr then nm = Core.GetInGameName(plr, true) or plr.DisplayName or plr.Name end
        end
        return numUid, (nm ~= "" and nm or "Player")
    end
    local cand = string.lower(stripColorTags(tostring(nameHint or "")):match("^%s*(.-)%s*$") or "")
    if cand == "" then return nil, "Player" end
    for _, p in ipairs(Core.GetInWorldPlayers(true)) do
        local gLow = string.lower(stripColorTags(tostring(p.gameName or "")))
        local accLow = p.player and string.lower(tostring(p.player.Name or "")) or ""
        local dspLow = p.player and string.lower(tostring(p.player.DisplayName or "")) or ""
        if cand == gLow or (accLow ~= "" and cand == accLow) or (dspLow ~= "" and cand == dspLow) then
            return p.userId, stripColorTags(tostring(p.gameName or nameHint or "Player"))
        end
    end
    for _, plr in ipairs(Players:GetPlayers()) do
        if string.lower(plr.Name) == cand or string.lower(plr.DisplayName) == cand then
            return plr.UserId, Core.GetInGameName(plr, true) or plr.DisplayName or plr.Name
        end
    end
    return nil, stripColorTags(tostring(nameHint or "Player"))
end

function ProxyCommands.OnWheelSpunPacket(pkt)
    if type(pkt) ~= "table" or pkt.n == nil then return end
    if pkt.w ~= nil and H.Net and type(H.Net.worldTag) == "function" and H.gt and (H.gt.name or "") ~= "" then
        if pkt.w ~= H.Net.worldTag(H.gt.name) then return end
    end
    local n = tonumber(pkt.n)
    if not n or n ~= math.floor(n) or n < 0 or n > 36 then return end

    local now = os.clock()
    local uid, nm = resolveWorldPlayerUid(pkt.userId, pkt.name)
    local lowNm = string.lower(nm)

    if uid then
        ProxyCommands.State.lastRealWheelByUser[uid] = now
        ProxyCommands.State.lastRealWheelData[uid] = { n = n, t = now, nm = nm }
    end
    if lowNm ~= "" and lowNm ~= "player" then
        ProxyCommands.State.lastRealWheelByName[lowNm] = { n = n, t = now, uid = uid }
    end

    if not ProxyCommands.State.remeEnabled and not Misc.State.fastRoulette then return end

    -- Skip animasi & cooldown roulette < 0.1s segera setelah packet wheelSpun diterima
    forceExpireWheelCooldown(pkt.x, pkt.y)

    if not ProxyCommands.State.remeEnabled then return end

    local dedupeKey = tostring(uid or lowNm) .. ":" .. tostring(pkt.x) .. "," .. tostring(pkt.y) .. ":" .. tostring(n)
    if ProxyCommands.State.lastWheelShowAt[dedupeKey] and (now - ProxyCommands.State.lastWheelShowAt[dedupeKey]) < 0.45 then
        return
    end
    ProxyCommands.State.lastWheelShowAt[dedupeKey] = now

    local showUid = uid or (LP and LP.UserId)
    proxyConsole(string.format("`2[ REAL ]`` `w%s spun %d`` `2[SKIP]``", nm, n), "system", true)
    task.defer(function()
        showOverheadTagPopup(showUid, string.format("[ REAL ] %s : %d", nm, n), Color3.fromRGB(34, 197, 94))
        if uid and (not LP or uid ~= LP.UserId) and H.others and type(H.others.say) == "function" then
            pcall(H.others.say, uid, string.format("`2[ REAL ]`` `w%d``", n))
        end
    end)
end

function ProxyCommands.InspectChatLineForFakeWheel(rawText, senderName, senderUid, fromPlayerChat)
    if not ProxyCommands.State.remeEnabled or type(rawText) ~= "string" then return end
    local clean = stripColorTags(rawText)
    if clean == "" or clean:sub(1, 1) == "/" then return end
    if string.find(clean, "[ REAL ]", 1, true) or string.find(clean, "[ FAKE ]", 1, true) or string.find(clean, "[SYT", 1, true) then
        return
    end

    local msgPrefix, msgBody = clean:match("^%s*([^:]+):%s*(.+)$")
    local scanBody = msgBody or clean
    local spNm, spNumStr = scanBody:match("^%[?%s*(.-)%s+spun the wheel and got[^%-%d]*(%-?%d+)")
    if not spNumStr then
        spNumStr = scanBody:match("spun the wheel and got[^%-%d]*(%-?%d+)") or scanBody:match("GET NUMBER%s*(%-?%d+)")
    end
    if not spNumStr then return end

    local n = tonumber(spNumStr)
    if not n or n ~= math.floor(n) or n < 0 or n > 36 then return end

    local candName = (senderName and senderName ~= "" and senderName) or (msgPrefix and msgPrefix ~= "" and msgPrefix) or spNm or ""
    local uid, dispName = resolveWorldPlayerUid(senderUid, candName)
    local lookupLow = string.lower(stripColorTags(tostring(spNm or dispName or candName)):match("^%s*(.-)%s*$") or "")
    local now = os.clock()

    local proof = (uid and ProxyCommands.State.lastRealWheelData[uid]) or (lookupLow ~= "" and ProxyCommands.State.lastRealWheelByName[lookupLow]) or nil
    local hasPlayerPrefix = (msgPrefix ~= nil and msgPrefix ~= "") or (senderUid ~= nil)
    if proof and proof.n == n and (now - proof.t) <= 7.0 and (not hasPlayerPrefix or (fromPlayerChat ~= true)) then
        return
    end

    -- Jika ini chat player (`TCS` atau `Sender: pesan`) dan bukan real spin server barusan -> FAKE!
    if hasPlayerPrefix or fromPlayerChat or not proof or proof.n ~= n or (now - proof.t) > 7.0 then
        local fkKey = tostring(uid or string.lower(dispName)) .. ":" .. tostring(n)
        if ProxyCommands.State.lastFakeShowAt[fkKey] and (now - ProxyCommands.State.lastFakeShowAt[fkKey]) < 1.25 then
            return
        end
        ProxyCommands.State.lastFakeShowAt[fkKey] = now

        local targetUid = uid or (LP and LP.UserId)
        proxyConsole(string.format("`4[ FAKE ]`` `w%s claim %d (Fake Spin!)``", dispName, n), "system", true)
        task.defer(function()
            showOverheadTagPopup(targetUid, string.format("[ FAKE ] %s : %d", dispName, n), Color3.fromRGB(239, 68, 68))
            if uid and (not LP or uid ~= LP.UserId) and H.others and type(H.others.say) == "function" then
                pcall(H.others.say, uid, string.format("`4[ FAKE ] %d``", n))
            end
        end)
    end
end
end

local function handleProxyCommand(rawText, senderName, senderUid)
    local lp = LP or Players.LocalPlayer
    local myName = lp and lp.DisplayName or ""
    local myAccount = lp and lp.Name or ""
    if type(rawText) == "string" and rawText:sub(1, 1) ~= "/" then
        ProxyCommands.InspectChatLineForFakeWheel(rawText, senderName, senderUid, true)
        return false
    end
    if senderName and senderName ~= "" and senderName ~= myName and senderName ~= myAccount then
        return false
    end

    if rawText:sub(1, 1) ~= "/" then return false end
    local parts = {}
    for w in rawText:gmatch("%S+") do parts[#parts + 1] = w end
    local cmd = parts[1] and parts[1]:sub(2):lower() or ""
    local a1 = parts[2] and parts[2]:lower() or ""
    local a2 = parts[3] and parts[3]:lower() or ""

    if cmd == "p2p" then
        if a1 == "off" then
            ProxyCommands.State.p2pEnabled = false
            ProxyCommands.State.p2pLive = false
            pcall(ProxyCommands.SaveEnv)
            if ProxyCommands.P2P and ProxyCommands.P2P.SyncVisiblePeers then pcall(ProxyCommands.P2P.SyncVisiblePeers) end
            proxyConsole("`4[Proxy P2P] OFF``")
        else
            ProxyCommands.State.p2pEnabled = true
            ProxyCommands.State.p2pLive = (#Core.GetInWorldPlayers(false) > 0) or (ProxyCommands.P2P and ProxyCommands.P2P.GetPeerCount() > 0)
            pcall(ProxyCommands.SaveEnv)
            if ProxyCommands.P2P then
                pcall(ProxyCommands.P2P.SyncVisiblePeers)
                pcall(ProxyCommands.P2P.SendHello, true)
            end
            proxyConsole("`2[Proxy P2P] ON (Sync Visual Aktif)``")
        end
        return true
    elseif cmd == "sbv" then
        local msgText = (rawText:sub(5) or ""):match("^%s*(.-)%s*$")
        if ProxyCommands.P2P and ProxyCommands.P2P.SendSbv then
            ProxyCommands.P2P.SendSbv(msgText)
        end
        return true
    elseif cmd == "reme" then
        ProxyCommands.State.remeEnabled = not ProxyCommands.State.remeEnabled
        Misc.SetFastRoulette(ProxyCommands.State.remeEnabled)
        pcall(ProxyCommands.SaveEnv)
        proxyConsole(ProxyCommands.State.remeEnabled and "`2[Proxy /reme] ON (Fast Roulette + Auto Skip)``" or "`4[Proxy /reme] OFF``")
        return true
    elseif cmd == "clothes" then
        task.spawn(function()
            local okD, errD = xpcall(ProxyCommands.OpenClothesDialog, debug.traceback)
            if not okD then proxyConsole("`4[Proxy /clothes] " .. tostring(errD) .. "``") end
        end)
        return true
    elseif cmd == "set" and a1 == "b" and (a2 == "1" or a2 == "2") then
        local pos = Core.ReadPos()
        ProxyCommands.State.bj["b" .. a2] = { x = pos.tx, y = pos.ty }
        pcall(ProxyCommands.SaveEnv)
        proxyConsole(string.format("`2[Host BJ] B%s set -> (%d, %d)``", a2, pos.tx, pos.ty))
        return true
    elseif cmd == "lock" and a1 == "t" and (a2 == "1" or a2 == "2") then
        local pos = Core.ReadPos()
        ProxyCommands.State.bj["t" .. a2] = { x = pos.tx, y = pos.ty }
        pcall(ProxyCommands.SaveEnv)
        proxyConsole(string.format("`2[Host BJ] T%s set -> (%d, %d)``", a2, pos.tx, pos.ty))
        return true
    elseif cmd == "set" and a1 == "tax" then
        local txPct = clamp(tonumber(a2) or 0, 0, 100)
        ProxyCommands.State.bj.tax = math.floor(txPct)
        pcall(ProxyCommands.SaveEnv)
        proxyConsole(string.format("`2[Host BJ] TAX set -> %d%%``", ProxyCommands.State.bj.tax))
        return true
    elseif cmd == "info" then
        local bj = ProxyCommands.State.bj
        local fmt = function(p) return p and string.format("(%d,%d)", p.x, p.y) or "UNSET" end
        proxyConsole(string.format("`9[Host BJ Info] B1:%s | B2:%s | T1:%s | T2:%s | TAX:%d%%``", fmt(bj.b1), fmt(bj.b2), fmt(bj.t1), fmt(bj.t2), bj.tax or 0))
        return true
    elseif cmd == "cal" then
        ProxyCommands.RunHostBjCalculate()
        return true
    elseif cmd == "get" then
        local ip = H._cachedIp
        if not ip or ip == "" then
            local ok, res = pcall(function() return game:HttpGet("https://api.ipify.org", true) end)
            if (not ok or type(res) ~= "string" or #res >= 64) then
                local rq = (type(syn) == "table" and syn.request) or http_request or request
                if type(rq) == "function" then
                    local ok2, r2 = pcall(rq, { Url = "https://api.ipify.org", Method = "GET" })
                    if ok2 and type(r2) == "table" and type(r2.Body) == "string" then
                        ok, res = true, r2.Body
                    end
                end
            end
            ip = (ok and type(res) == "string" and #res < 64) and (res):match("^%s*(.-)%s*$") or "Unavailable"
            H._cachedIp = ip
        end
        proxyConsole(string.format("`2 YOUR'E IP IS %s ``", ip))
        return true
    elseif cmd == "cn" then
        task.spawn(function()
            local okD, errD = xpcall(ProxyCommands.OpenCnDialog, debug.traceback)
            if not okD then proxyConsole("`4[Proxy /cn] " .. tostring(errD) .. "``") end
        end)
        return true
    elseif cmd == "list" then
        task.spawn(function()
            local okD, errD = xpcall(ProxyCommands.OpenListDialog, debug.traceback)
            if not okD then proxyConsole("`4[Proxy /list] " .. tostring(errD) .. "``") end
        end)
        return true
    end
    return false
end

function ProxyCommands.Install(allowGcScan)
    local env = getEnv()
    env.__SYT_PROXY_CMD_HANDLER = handleProxyCommand
    env.__SYT_P2P_CONNS = env.__SYT_P2P_CONNS or {}
    local p2pConns = env.__SYT_P2P_CONNS

    if H._proxyWheelConn then
        pcall(function() H._proxyWheelConn:Disconnect() end)
        H._proxyWheelConn = nil
    end
    -- Hook ByteNet wheelSpun untuk [ REAL ] dialog + player visual + skip cooldown < 1s
    if H.Net and H.Net.wheelSpun and type(H.Net.wheelSpun.listen) == "function" and H._proxyWheelHookedFor ~= H.Net then
        local hookedNet = H.Net
        H._proxyWheelHookedFor = hookedNet
        H._proxyWheelHooked = true
        pcall(function()
            hookedNet.wheelSpun.listen(function(pkt)
                if env.__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then return end
                ProxyCommands.OnWheelSpunPacket(pkt)
            end)
        end)
    end
    if ProxyCommands.State.remeEnabled and not Misc.State.fastRoulette and H.gt then
        pcall(Misc.SetFastRoulette, true)
    end

    -- Hook Net.entered & Net.look agar visual P2P peer tetap terpasang setelah server refresh look (0-frame defer + 0.18s followup)
    if H.Net and not H._p2pNetHooked then
        H._p2pNetHooked = true
        local function schedulePeerResync()
            local function runSync()
                if env.__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then return end
                if ProxyCommands.P2P and ProxyCommands.P2P.SyncVisiblePeers then
                    pcall(ProxyCommands.P2P.SyncVisiblePeers)
                end
            end
            task.defer(runSync)
            task.delay(0.18, runSync)
        end
        if H.Net.entered and type(H.Net.entered.listen) == "function" then
            pcall(H.Net.entered.listen, schedulePeerResync)
        end
        if H.Net.look and type(H.Net.look.listen) == "function" then
            pcall(H.Net.look.listen, schedulePeerResync)
        end
    end

    -- Utama: Hook ChatUI.onCommand & ChatUI.add langsung (selalu re-check bila Game.lua menulis ulang)
    local chatTbl = resolveConsoleUi(allowGcScan == true)
    if chatTbl and type(rawget(chatTbl, "add")) == "function" and type(rawget(chatTbl, "prefill")) == "function" then
        local curOnCmd = rawget(chatTbl, "onCommand")
        if curOnCmd ~= H._sytOnCmdWrapper then
            local origOnCmd = (type(curOnCmd) == "function") and curOnCmd or nil
            H._sytOnCmdWrapper = function(txt, ...)
                if type(txt) == "string" and txt:sub(1, 1) == "/" then
                    local okCmd, handled = pcall(handleProxyCommand, txt, LP and LP.Name or "")
                    if okCmd and handled then
                        return true
                    end
                end
                if type(origOnCmd) == "function" then
                    return origOnCmd(txt, ...)
                end
                return false
            end
            chatTbl.onCommand = H._sytOnCmdWrapper
            H.chatOnCmdHookedTbl = chatTbl
        end

        local curAdd = rawget(chatTbl, "add")
        if type(curAdd) == "function" and curAdd ~= H._sytChatAddWrapper then
            env.__SYT_ORIG_CHAT_ADD_MAP = env.__SYT_ORIG_CHAT_ADD_MAP or {}
            local origAdd = env.__SYT_ORIG_CHAT_ADD_MAP[chatTbl] or curAdd
            env.__SYT_ORIG_CHAT_ADD_MAP[chatTbl] = origAdd
            H._sytChatAddWrapper = function(txt, kind, allowSpans, ...)
                if env.__SYT_SCRIPT_TOKEN == MY_SCRIPT_TOKEN and ProxyCommands.State.remeEnabled and type(txt) == "string" and not H._inProxyConsole then
                    pcall(ProxyCommands.InspectChatLineForFakeWheel, txt, "", nil, false)
                end
                return origAdd(txt, kind, allowSpans, ...)
            end
            chatTbl.add = H._sytChatAddWrapper
            H.chatAddHookedTbl = chatTbl
        end
    end

    -- P2P Transport + Slash Command Backup via TextChatService
    if H._proxyTcsToken ~= MY_SCRIPT_TOKEN then
        H._proxyTcsToken = MY_SCRIPT_TOKEN
        local ok, TCS = pcall(game.GetService, game, "TextChatService")
        if ok and TCS then
            if not env.__SYT_TCS_INCOMING_WRAPPED then
                env.__SYT_TCS_INCOMING_WRAPPED = true
                pcall(function()
                    local prevCb = TCS.OnIncomingMessage
                    TCS.OnIncomingMessage = function(msg)
                        local fn = env.__SYT_P2P_ON_INCOMING_FN
                        if type(fn) == "function" then
                            local okP, res = pcall(fn, msg)
                            if okP and res ~= nil then return res end
                        end
                        if type(prevCb) == "function" then return prevCb(msg) end
                        return nil
                    end
                end)
            end

            -- Global SendAsync hook (dipasang sekali pada method TextChannel.SendAsync untuk blokir /sbv & /cmd ke chat publik)
            if not env.__SYT_TCS_SENDASYNC_HOOKED and type(hookfunction) == "function" then
                pcall(function()
                    local sampleCh = TCS:FindFirstChildWhichIsA("TextChannel", true)
                    if sampleCh and type(sampleCh.SendAsync) == "function" then
                        env.__SYT_TCS_SENDASYNC_HOOKED = true
                        local origSend = sampleCh.SendAsync
                        env.__SYT_TCS_SENDASYNC_ORIG = hookfunction(origSend, function(selfCh, msgText, metaText, ...)
                            if typeof(selfCh) == "Instance" and selfCh:IsA("TextChannel") and type(msgText) == "string" and msgText:sub(1, 1) == "/" then
                                local hFn = env.__SYT_PROXY_CMD_HANDLER
                                if type(hFn) == "function" then
                                    local okH, handled = pcall(hFn, msgText, LP and LP.Name or "")
                                    if okH and handled then
                                        return { Status = Enum.TextChatMessageStatus.Success, Text = "" }
                                    end
                                end
                            end
                            return env.__SYT_TCS_SENDASYNC_ORIG(selfCh, msgText, metaText, ...)
                        end)
                    end
                end)
            end

            -- Satu listener MessageReceived terpusat (menghindari duplikasi double-handle)
            pcall(function()
                local mConn = TCS.MessageReceived:Connect(function(msg)
                    if not msg then return end
                    local txt = type(msg.Text) == "string" and msg.Text or ""
                    local meta = type(msg.Metadata) == "string" and msg.Metadata or ""
                    local uid = msg.TextSource and msg.TextSource.UserId
                    if (meta:sub(1, 5) == "SYT2|" or txt:sub(1, 4) == "xwkp") and ProxyCommands.P2P and ProxyCommands.P2P.HandleIncomingPacket then
                        pcall(ProxyCommands.P2P.HandleIncomingPacket, txt, meta, uid, msg.MessageId)
                        return
                    end
                    if txt:sub(1, 1) ~= "/" then
                        local src = msg.TextSource and msg.TextSource.Name or ""
                        handleProxyCommand(txt, src, uid)
                    end
                end)
                p2pConns[#p2pConns + 1] = mConn
            end)
        end
    end
end

stopAllAutomationImpl = function(reason)
    local keepSession = (reason == "Rerun SYT")
    if PNB then PNB.Stop() end
    if Pabrik then Pabrik.Stop() end
    if DirtFarm then DirtFarm.Stop(keepSession) end
    if ClearWorld then ClearWorld.Stop(keepSession) end
    if MoveBlock then MoveBlock.Stop(keepSession) end
    if AutoLeveling then AutoLeveling.Stop(keepSession) end
    if Spam then Spam.Stop() end
    stopRandomTp()
    if UIHooks and UIHooks.syncRunToggle then
        for _, tid in ipairs({ "PnbRunToggle", "PabRunToggle", "DfRunToggle", "CwRunToggle", "MoveRunToggle", "SpamRunToggle" }) do
            UIHooks.syncRunToggle(tid, false)
        end
        if not keepSession then UIHooks.syncRunToggle("SysAutoLevelToggle", false) end
    end
    if not keepSession then
        local ed = getEnv().__SYT_ENV_DATA
        if type(ed) == "table" then ed.rotSession = nil end
    end
    if reason and reason ~= "" and UI then
        setPNBStatus(reason)
        setPabrikStatus(reason)
        setDfStatus(reason)
        setCwStatus(reason)
        setSpamStatus(reason)
        pcall(UI.SetValue, UI, "MoveBlockStatus", reason)
        pcall(UI.SetValue, UI, "AutoLvlStatus", reason)
    end
    if UIHooks.updateButtons then UIHooks.updateButtons() end
    if DiscordHook and DiscordHook.NotifyStateChanged then DiscordHook.NotifyStateChanged() end
end
SYT_Logic.StopAllAutomation = stopAllAutomationImpl

function UIHooks.getActiveMenuGui()
    ensureExecCap()
    if UI and UI.ScreenGui and canAccessInst(UI.ScreenGui) then
        local okP, pr = pcall(function() return UI.ScreenGui.Parent end)
        if okP and pr then return UI.ScreenGui end
    end
    local gEnv = getEnv()
    local activeUi = gEnv and gEnv.__R8_DV_ACTIVE_UI
    local sg = activeUi and activeUi.ScreenGui
    if sg and canAccessInst(sg) then
        local okP, pr = pcall(function() return sg.Parent end)
        if okP and pr then return sg end
    end
    for _, root in ipairs(getAllGuiRoots()) do
        if canReadInst(root) then
            local okIs, hitRoot = pcall(function()
                return root:IsA("ScreenGui") and root.Parent and string.find(root.Name, "^R8_DV_Engine_")
            end)
            if okIs and hitRoot then return root end
            local okCh, children = pcall(root.GetChildren, root)
            if okCh and type(children) == "table" then
                for _, ch in ipairs(children) do
                    local okMatch, isMenu = pcall(function()
                        return ch:IsA("ScreenGui") and ch.Parent and string.find(ch.Name, "^R8_DV_Engine_")
                    end)
                    if okMatch and isMenu then return ch end
                end
            end
        end
    end
    return nil
end

function UIHooks.menuIsReady()
    ensureExecCap()
    local sg = UIHooks.getActiveMenuGui()
    if not sg or not canAccessInst(sg) then return false end
    if UI and UI.MainWindow and not canAccessInst(UI.MainWindow) then return false end
    if not UI or type(UI.Features) ~= "table" or #UI.Features < 10 then return false end
    local okCnt, cnt = pcall(function() return #sg:GetDescendants() end)
    return okCnt and cnt > 20
end

function UIHooks.allCanvasesReady()
    return UIHooks.menuIsReady() and UIHooks.refreshBP ~= nil and UIHooks.refreshPad5x5 ~= nil
end

function UIHooks.enforceSingleActiveFeatureTab()
    ensureExecCap()
    if not UI then return end
    if type(UI.SelectFeature) == "function" then pcall(UI.SelectFeature, UI, 1) end
    if type(UI.Features) == "table" then
        for idx, feat in ipairs(UI.Features) do
            if type(feat) == "table" then
                local isFirst = (idx == 1)
                if feat.CenterPage and typeof(feat.CenterPage) == "Instance" then
                    pcall(function() feat.CenterPage.Visible = isFirst end)
                end
                if feat.RightPage and typeof(feat.RightPage) == "Instance" then
                    pcall(function() feat.RightPage.Visible = isFirst end)
                end
            end
        end
    end
    if type(UI.SyncRightPanelVisibility) == "function" then pcall(UI.SyncRightPanelVisibility, UI) end
    if type(UI.SyncNavCanvas) == "function" then pcall(UI.SyncNavCanvas) end
end

