buildSYTMenuFn = function()
    UIHooks.refreshBP      = nil
    UIHooks.refreshPabBP   = nil
    UIHooks.refreshPad5x5  = nil
    UIHooks.refreshMap     = nil
    UIHooks.refreshDfList  = nil
    UIHooks.refreshCwList  = nil
    UIHooks.refreshSysLog  = nil
    UIHooks.sidebarNameLbl = nil
    UIHooks.sidebarSubLbl  = nil

    local autoBuyOptions = { "OFF" }
    for _, o in ipairs(STORE_OFFERS) do
        autoBuyOptions[#autoBuyOptions + 1] = string.format("%s | %s (%d)", o.key, o.name, o.price)
    end

    local function bindRunToggle(card, label, toggleId, modTbl)
        return card:Toggle(label, toggleId, (modTbl and modTbl.State and modTbl.State.running) == true, function(v)
            if UIHooks._syncingToggles and UIHooks._syncingToggles[toggleId] then return end
            if v == true then
                if not (modTbl and modTbl.State and modTbl.State.running) then
                    local ok = modTbl.Start()
                    if not ok and UIHooks.syncRunToggle then
                        UIHooks.syncRunToggle(toggleId, false)
                    end
                    if DiscordHook and DiscordHook.NotifyStateChanged then DiscordHook.NotifyStateChanged() end
                end
            else
                if modTbl and modTbl.State and modTbl.State.running then
                    modTbl.Stop()
                end
                if DiscordHook and DiscordHook.NotifyStateChanged then DiscordHook.NotifyStateChanged() end
            end
        end)
    end

    if UI.Category then UI:Category("Core") end

    -- 1. + SYSTEM
    feature("System", "System")({
        center = center(function(c)
            c:Header("System Security", "Anti-Ban/Kick & World Entrant Protection", "SYS")
