UIHooks.buttonMap = {}

function UIHooks.scanResponsiveButtons()
    ensureExecCap()
    local buttonMap = UIHooks.buttonMap
    local specs = {}
    local scanRoots = {}
    local ownSg = UIHooks.getActiveMenuGui()
    if ownSg then scanRoots[1] = ownSg else scanRoots = getAllGuiRoots() end
    for _, root in ipairs(scanRoots) do
        if canReadInst(root) then
            local okD, desc = pcall(root.GetDescendants, root)
            if okD and type(desc) == "table" then
                for _, d in ipairs(desc) do
                    local okL, dTxt = pcall(function()
                        return d:IsA("TextLabel") and d.Text or nil
                    end)
                    if okL and type(dTxt) == "string" then
                        for _, sp in ipairs(specs) do
                            if not buttonMap[sp.prefix] and string.sub(dTxt, 1, #sp.prefix) == sp.prefix then
                                local okBtn, btn = pcall(d.FindFirstAncestorOfClass, d, "TextButton")
                                if okBtn and btn and canAccessInst(btn) then
                                    local badgeTxt, badgePill = nil, nil
                                    local okCh, chList = pcall(btn.GetDescendants, btn)
                                    if okCh and type(chList) == "table" then
                                        for _, ch in ipairs(chList) do
                                            local okB, isB = pcall(function()
                                                return ch:IsA("TextLabel") and ch ~= d and (ch.Text == "TOGGLE" or ch.Text == "START" or ch.Text == "STOP" or ch.Text == "CLICKED")
                                            end)
                                            if okB and isB then
                                                badgeTxt = ch
                                                pcall(function() badgePill = ch.Parent end)
                                                break
                                            end
                                        end
                                    end
                                    buttonMap[sp.prefix] = { lbl = d, badgeTxt = badgeTxt, badgePill = badgePill, getState = sp.getState }
                                    pcall(function()
                                        btn.MouseButton1Click:Connect(function()
                                            task.delay(0.05, function() if UIHooks.updateButtons then UIHooks.updateButtons() end end)
                                            task.delay(0.20, function() if UIHooks.updateButtons then UIHooks.updateButtons() end end)
                                            task.delay(0.62, function() if UIHooks.updateButtons then UIHooks.updateButtons() end end)
                                        end)
                                    end)
                                end
                            end
                        end
                        if not UIHooks.sidebarSubLbl and dTxt == "Active Session" then
                            UIHooks.sidebarSubLbl = d
                            local okCP, cardParent = pcall(function() return d.Parent end)
                            if okCP and canReadInst(cardParent) then
                                local okS, sibs = pcall(cardParent.GetDescendants, cardParent)
                                if okS and type(sibs) == "table" then
                                    for _, sib in ipairs(sibs) do
                                        local okN, isN = pcall(function()
                                            return sib:IsA("TextLabel") and sib ~= d and (sib.Text == (LP and LP.DisplayName) or sib.Text == (LP and LP.Name) or sib.Text == "Operator")
                                        end)
                                        if okN and isN then
                                            UIHooks.sidebarNameLbl = sib; break
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
end

UIHooks.updateButtons = function()
    ensureExecCap()
    for _, item in pairs(UIHooks.buttonMap) do
        if canAccessInst(item.lbl) then
            pcall(function()
                local active, onBadge, offBadge, onLbl, offLbl = item.getState()
                item.lbl.Text = active and onLbl or offLbl
                if canAccessInst(item.badgeTxt) then item.badgeTxt.Text = active and onBadge or offBadge end
                if canAccessInst(item.badgePill) and item.badgePill:IsA("Frame") then
                    item.badgePill.BackgroundColor3 = active and Color3.fromRGB(220, 38, 38) or Color3.fromRGB(16, 185, 129)
                    item.badgePill.BackgroundTransparency = 0
                end
            end)
        end
    end
end

UIHooks.buildMountedCanvasesFn = function()
    ensureExecCap()
    table.clear(UIHooks.buttonMap)

    local function findAllTextBoxesWithKey(key)
        ensureExecCap()
        local found = {}
        local function scanRoot(root)
            if not canReadInst(root) then return end
            local okD, desc = pcall(root.GetDescendants, root)
            if not okD or type(desc) ~= "table" then return end
            for _, d in ipairs(desc) do
                local okMatch, hit = pcall(function()
                    return d:IsA("TextBox") and d.Text == key
                end)
                if okMatch and hit then found[#found + 1] = d end
            end
        end
        local ownSg = UIHooks.getActiveMenuGui()
        if ownSg then scanRoot(ownSg); if #found > 0 then return found end end
        for _, root in ipairs(getAllGuiRoots()) do
            if root ~= ownSg then scanRoot(root); if #found > 0 then return found end end
        end
        return found
    end

    local function mountEmbeddedCanvas(anchorKey, heightPx, buildFn)
        local function tryMountNow()
            ensureExecCap()
            local hits = findAllTextBoxesWithKey(anchorKey)
            if #hits == 0 then return false end
            local anchorBox = hits[1]
            if not canAccessInst(anchorBox) then return false end
            local okP, rowContainer = pcall(function() return anchorBox.Parent end)
            if not okP or not canAccessInst(rowContainer) then return false end
            pcall(function()
                for _, ch in ipairs(rowContainer:GetChildren()) do
                    if not ch:IsA("UICorner") and not ch:IsA("UIStroke") then ch:Destroy() end
                end
                rowContainer.Size = UDim2.new(1, 0, 0, heightPx)
                rowContainer.BackgroundColor3 = Color3.fromRGB(11, 14, 20)
                rowContainer.ClipsDescendants = true
            end)
            local okB, bErr = xpcall(buildFn, debug.traceback, rowContainer)
            if not okB then warn("[SYT Canvas Error " .. tostring(anchorKey) .. "]: " .. tostring(bErr)) end
            return true
        end
        if tryMountNow() then return end
        task.spawn(function()
            for _ = 1, 80 do
                if getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then return end
                if tryMountNow() then return end
                task.wait(0.05)
            end
        end)
    end

    -- 1. PNB 5x5 TILE SELECTOR PAD (__PAD_5X5_ANCHOR_KEY__)
    mountEmbeddedCanvas("__PAD_5X5_ANCHOR_KEY__", 210, function(rowContainer)
        local padFrame = Instance.new("Frame", rowContainer)
        padFrame.Size = UDim2.new(1, -12, 1, -12)
        padFrame.Position = UDim2.fromOffset(6, 6)
        padFrame.BackgroundTransparency = 1
        local cellMap = {}
        local function refresh5x5()
            ensureExecCap()
            if not canAccessInst(padFrame) then return end
            pcall(function()
                local pos = Core.ReadPos()
                local myGameName = Core.GetInGameName(LP, true)
                for dy = -2, 2 do
                    for dx = -2, 2 do
                        local cell = cellMap[tileKey(dx, dy)]
                        if cell then
                            if dx == 0 and dy == 0 then
                                cell.BackgroundColor3 = Color3.fromRGB(161, 98, 7)
                                cell.TextColor3 = Color3.fromRGB(254, 240, 138)
                                cell.Text = string.format("%s\n(%d,%d)", string.sub(myGameName, 1, 6), pos.tx, pos.ty)
                            else
                                local on = PNB.State.grid5x5[tileKey(dx, dy)] == true
                                cell.BackgroundColor3 = on and Color3.fromRGB(14, 116, 144) or Color3.fromRGB(23, 29, 41)
                                cell.TextColor3 = on and Color3.new(1, 1, 1) or Color3.fromRGB(148, 163, 184)
                                cell.Text = string.format("%+d,%+d", dx, dy)
                            end
                        end
                    end
                end
            end)
        end
        for r = 0, 4 do
            local dy = r - 2
            for c = 0, 4 do
                local dx = c - 2
                local btn = Instance.new("TextButton", padFrame)
                btn.Size = UDim2.new(0.2, -4, 0.2, -4)
                btn.Position = UDim2.new(c * 0.2, 2, r * 0.2, 2)
                btn.BorderSizePixel = 0
                btn.Font = Enum.Font.Code
                btn.TextSize = 10
                btn.TextWrapped = true
                Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 5)
                if dx ~= 0 or dy ~= 0 then
                    btn.MouseButton1Click:Connect(function() PNB.ToggleTile5x5(dx, dy) end)
                end
                cellMap[tileKey(dx, dy)] = btn
            end
        end
        UIHooks.refreshPad5x5 = refresh5x5
        refresh5x5()
    end)

    -- 2. BACKPACK CARD GRID (3-column Flex Grid: __BP_ITEM_ANCHOR_KEY__)
    mountEmbeddedCanvas("__BP_ITEM_ANCHOR_KEY__", 220, function(rowContainer)
        local scroller = rowContainer:FindFirstAncestorOfClass("ScrollingFrame")
        local topBar = Instance.new("Frame", rowContainer)
        topBar.Size = UDim2.new(1, -12, 0, 22)
        topBar.Position = UDim2.fromOffset(6, 4)
        topBar.BackgroundTransparency = 1
        topBar.ZIndex = 6
        local infoLbl = Instance.new("TextLabel", topBar)
        infoLbl.Size = UDim2.new(1, -68, 1, 0)
        infoLbl.BackgroundTransparency = 1
        infoLbl.Font = Enum.Font.Code
        infoLbl.TextSize = 10
        infoLbl.TextXAlignment = Enum.TextXAlignment.Left
        infoLbl.TextColor3 = Color3.fromRGB(148, 163, 184)
        infoLbl.ZIndex = 7
        infoLbl.Text = "Block Selector (Scanning...)"

        local scanBtn = Instance.new("TextButton", topBar)
        scanBtn.Size = UDim2.fromOffset(62, 18)
        scanBtn.Position = UDim2.new(1, -62, 0, 2)
        scanBtn.BackgroundColor3 = Color3.fromRGB(22, 78, 99)
        scanBtn.BorderSizePixel = 0
        scanBtn.Font = Enum.Font.GothamBold
        scanBtn.TextSize = 9
        scanBtn.TextColor3 = Color3.fromRGB(224, 242, 254)
        scanBtn.ZIndex = 8
        scanBtn.Text = "SCAN BP"
        Instance.new("UICorner", scanBtn).CornerRadius = UDim.new(0, 4)

        local scroll = Instance.new("ScrollingFrame", rowContainer)
        scroll.Size = UDim2.new(1, -12, 1, -32)
        scroll.Position = UDim2.fromOffset(6, 28)
        scroll.BackgroundColor3 = Color3.fromRGB(8, 10, 15)
        scroll.BorderSizePixel = 0
        scroll.ScrollBarThickness = 4
        scroll.ClipsDescendants = true
        scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
        scroll.ZIndex = 5
        local grid = Instance.new("UIGridLayout", scroll)
        grid.CellSize = UDim2.new(0.32, 0, 0, 74)
        grid.CellPadding = UDim2.fromOffset(4, 5)
        grid.SortOrder = Enum.SortOrder.LayoutOrder
        grid:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            local cs = grid.AbsoluteContentSize
            scroll.CanvasSize = UDim2.fromOffset(0, cs.Y + 10)
        end)

        local function rebuildBP(forceScan)
            ensureExecCap()
            if not canAccessInst(scroll) then return end
            local okR, errR = xpcall(function()
                for _, ch in ipairs(scroll:GetChildren()) do
                    if ch:IsA("TextButton") or ch:IsA("TextLabel") then ch:Destroy() end
                end
                -- Hanya block (seed tidak masuk per README PNB spec)
                local items = PNB.GetBackpackBlocks(false, forceScan == true)
                ensureExecCap()
                if not canAccessInst(scroll) then return end
                if #items == 0 then
                    local emptyLbl = Instance.new("TextLabel", scroll)
                    emptyLbl.Size = UDim2.new(1, -8, 0, 56)
                    emptyLbl.BackgroundTransparency = 1
                    emptyLbl.Font = Enum.Font.GothamBold
                    emptyLbl.TextSize = 11
                    emptyLbl.TextWrapped = true
                    emptyLbl.TextColor3 = Color3.fromRGB(148, 163, 184)
                    emptyLbl.ZIndex = 7
                    emptyLbl.Text = "Belum ada Block di Backpack atau modul sedang scan. Tekan [SCAN BP]!"
                end
                for idx, it in ipairs(items) do
                    local isSel = (PNB.State.selectedBlockId == it.id)
                    local cell = Instance.new("TextButton", scroll)
                    cell.LayoutOrder = idx
                    cell.Text = ""
                    cell.AutoButtonColor = false
                    cell.BackgroundColor3 = isSel and Color3.fromRGB(22, 48, 68) or Color3.fromRGB(19, 24, 34)
                    cell.BorderSizePixel = 0
                    cell.ZIndex = 6
                    Instance.new("UICorner", cell).CornerRadius = UDim.new(0, 6)
                    local st = Instance.new("UIStroke", cell)
                    st.Color = isSel and Color3.fromRGB(56, 189, 248) or Color3.fromRGB(48, 58, 76)
                    st.Thickness = isSel and 1.8 or 1

                    local iconHolder = Instance.new("Frame", cell)
                    iconHolder.Size = UDim2.fromOffset(32, 32)
                    iconHolder.AnchorPoint = Vector2.new(0.5, 0)
                    iconHolder.Position = UDim2.new(0.5, 0, 0, 5)
                    iconHolder.BackgroundTransparency = 1
                    iconHolder.ZIndex = 7
                    pcall(Core.AttachItemSprite, iconHolder, it.id, 30)

                    local cntLbl = Instance.new("TextLabel", cell)
                    cntLbl.Size = UDim2.fromOffset(34, 14)
                    cntLbl.Position = UDim2.new(1, -36, 0, 2)
                    cntLbl.BackgroundTransparency = 1
                    cntLbl.Font = Enum.Font.Code
                    cntLbl.TextSize = 9
                    cntLbl.TextXAlignment = Enum.TextXAlignment.Right
                    cntLbl.TextColor3 = Color3.fromRGB(250, 204, 21)
                    cntLbl.ZIndex = 9
                    cntLbl.Text = "x" .. tostring(it.count)

                    local nameLbl = Instance.new("TextLabel", cell)
                    nameLbl.Size = UDim2.new(1, -6, 0, 24)
                    nameLbl.Position = UDim2.new(0, 3, 1, -26)
                    nameLbl.BackgroundTransparency = 1
                    nameLbl.Font = Enum.Font.Gotham
                    nameLbl.TextSize = 9
                    nameLbl.TextWrapped = true
                    nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
                    nameLbl.TextColor3 = Color3.fromRGB(226, 232, 240)
                    nameLbl.ZIndex = 9
                    nameLbl.Text = string.format("%s [%d]", tostring(it.name), tonumber(it.id) or 0)

                    cell.MouseButton1Click:Connect(function()
                        if PNB.State.selectedBlockId == it.id then
                            PNB.State.selectedBlockId = nil
                            UI:SetValue("PnbSelectedDisplay", "None")
                        else
                            PNB.State.selectedBlockId = it.id
                            UI:SetValue("PnbSelectedDisplay", string.format("%s (ID:%d | x%d)", it.name, it.id, it.count))
                            Pabrik.SetItem(it.id)
                            UI:SetValue("PabrikItemInput", tostring(it.id))
                            if UIHooks.refreshPabBP then pcall(UIHooks.refreshPabBP) end
                        end
                        rebuildBP(false)
                    end)
                end
                scroll.CanvasSize = UDim2.fromOffset(0, grid.AbsoluteContentSize.Y + 10)
                infoLbl.Text = string.format("Blocks di Backpack: %d (Tap pilih / batal)", #items)
            end, debug.traceback)
            if not okR then
                ensureExecCap()
                pcall(function() infoLbl.Text = "Scan BP retry: " .. string.sub(tostring(errR), 1, 36) end)
            end
        end
        scanBtn.MouseButton1Click:Connect(function()
            pcall(SYT_Logic.Init, true)
            rebuildBP(true)
            if UIHooks.refreshPabBP then pcall(UIHooks.refreshPabBP, true) end
        end)
        UIHooks.refreshBP = rebuildBP
        if scroller then
            scroller:GetPropertyChangedSignal("Visible"):Connect(function() if scroller.Visible then rebuildBP(false) end end)
        end
        rebuildBP(false)
        task.delay(0.35, function() rebuildBP(false) end)
        task.delay(1.25, function() rebuildBP(true) end)
    end)

    -- 2B. PABRIK BLOCK / SEED CARD GRID (__PAB_BP_ANCHOR_KEY__)
    mountEmbeddedCanvas("__PAB_BP_ANCHOR_KEY__", 185, function(rowContainer)
        local scroller = rowContainer:FindFirstAncestorOfClass("ScrollingFrame")
        local scroll = Instance.new("ScrollingFrame", rowContainer)
        scroll.Size = UDim2.new(1, -12, 1, -12)
        scroll.Position = UDim2.fromOffset(6, 6)
        scroll.BackgroundColor3 = Color3.fromRGB(8, 10, 15)
        scroll.BorderSizePixel = 0
        scroll.ScrollBarThickness = 4
        scroll.ClipsDescendants = true
        scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
        scroll.ZIndex = 5
        local grid = Instance.new("UIGridLayout", scroll)
        grid.CellSize = UDim2.new(0.32, 0, 0, 72)
        grid.CellPadding = UDim2.fromOffset(4, 5)
        grid.SortOrder = Enum.SortOrder.LayoutOrder
        grid:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            local cs = grid.AbsoluteContentSize
            scroll.CanvasSize = UDim2.fromOffset(0, cs.Y + 10)
        end)

        local function rebuildPabBP(forceScan)
            ensureExecCap()
            if not canAccessInst(scroll) then return end
            pcall(function()
                for _, ch in ipairs(scroll:GetChildren()) do
                    if ch:IsA("TextButton") or ch:IsA("TextLabel") then ch:Destroy() end
                end
                local items = PNB.GetBackpackBlocks(true, forceScan == true)
                ensureExecCap()
                if not canAccessInst(scroll) then return end
                for idx, it in ipairs(items) do
                    local isSel = (Pabrik.State.blockId == it.id) or (Pabrik.State.seedId == it.id)
                    local cell = Instance.new("TextButton", scroll)
                    cell.LayoutOrder = idx
                    cell.Text = ""
                    cell.AutoButtonColor = false
                    cell.BackgroundColor3 = isSel and Color3.fromRGB(46, 28, 72) or Color3.fromRGB(19, 24, 34)
                    cell.BorderSizePixel = 0
                    cell.ZIndex = 6
                    Instance.new("UICorner", cell).CornerRadius = UDim.new(0, 6)
                    local st = Instance.new("UIStroke", cell)
                    st.Color = isSel and Color3.fromRGB(168, 85, 247) or Color3.fromRGB(48, 58, 76)
                    st.Thickness = isSel and 1.8 or 1

                    local iconHolder = Instance.new("Frame", cell)
                    iconHolder.Size = UDim2.fromOffset(30, 30)
                    iconHolder.AnchorPoint = Vector2.new(0.5, 0)
                    iconHolder.Position = UDim2.new(0.5, 0, 0, 4)
                    iconHolder.BackgroundTransparency = 1
                    iconHolder.ZIndex = 7
                    pcall(Core.AttachItemSprite, iconHolder, it.id, 28)

                    local cntLbl = Instance.new("TextLabel", cell)
                    cntLbl.Size = UDim2.fromOffset(34, 14)
                    cntLbl.Position = UDim2.new(1, -36, 0, 2)
                    cntLbl.BackgroundTransparency = 1
                    cntLbl.Font = Enum.Font.Code
                    cntLbl.TextSize = 9
                    cntLbl.TextXAlignment = Enum.TextXAlignment.Right
                    cntLbl.TextColor3 = Color3.fromRGB(250, 204, 21)
                    cntLbl.ZIndex = 9
                    cntLbl.Text = "x" .. tostring(it.count)

                    local nameLbl = Instance.new("TextLabel", cell)
                    nameLbl.Size = UDim2.new(1, -6, 0, 24)
                    nameLbl.Position = UDim2.new(0, 3, 1, -26)
                    nameLbl.BackgroundTransparency = 1
                    nameLbl.Font = Enum.Font.Gotham
                    nameLbl.TextSize = 9
                    nameLbl.TextWrapped = true
                    nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
                    nameLbl.TextColor3 = Color3.fromRGB(226, 232, 240)
                    nameLbl.ZIndex = 9
                    nameLbl.Text = string.format("%s [%d]", tostring(it.name), tonumber(it.id) or 0)

                    cell.MouseButton1Click:Connect(function()
                        if isSel then
                            Pabrik.State.blockId, Pabrik.State.seedId, Pabrik.State.itemName = nil, nil, ""
                            UI:SetValue("PabrikPairDisplay", "Unset")
                        else
                            Pabrik.SetItem(it.id)
                            UI:SetValue("PabrikItemInput", tostring(it.id))
                        end
                        rebuildPabBP(false)
                    end)
                end
                scroll.CanvasSize = UDim2.fromOffset(0, grid.AbsoluteContentSize.Y + 10)
            end)
        end
        UIHooks.refreshPabBP = rebuildPabBP
        if scroller then
            scroller:GetPropertyChangedSignal("Visible"):Connect(function() if scroller.Visible then rebuildPabBP(false) end end)
        end
        rebuildPabBP(false)
        task.delay(0.4, function() rebuildPabBP(false) end)
        task.delay(1.3, function() rebuildPabBP(true) end)
    end)

    -- 3. PABRIK RENDERED ZOOMABLE PLANTABLE DIRT SELECTOR (__WORLD_MAP_ANCHOR_KEY__)
    mountEmbeddedCanvas("__WORLD_MAP_ANCHOR_KEY__", 248, function(rowContainer)
        local hudLbl = Instance.new("TextLabel", rowContainer)
        hudLbl.Size = UDim2.new(1, -12, 0, 18)
        hudLbl.Position = UDim2.fromOffset(6, 3)
        hudLbl.BackgroundTransparency = 1
        hudLbl.Font = Enum.Font.Code
        hudLbl.TextSize = 10
        hudLbl.TextXAlignment = Enum.TextXAlignment.Left
        hudLbl.TextTruncate = Enum.TextTruncate.AtEnd
        hudLbl.TextColor3 = Color3.fromRGB(167, 243, 208)
        hudLbl.Text = "DERET | Tap block/slot tanam -> otomatis 1 deret"

        local mapView = Instance.new("Frame", rowContainer)
        mapView.Size = UDim2.new(1, -12, 1, -55)
        mapView.Position = UDim2.fromOffset(6, 23)
        mapView.BackgroundColor3 = Color3.fromRGB(14, 24, 42)
        mapView.BorderSizePixel = 0
        mapView.ClipsDescendants = true
        Instance.new("UICorner", mapView).CornerRadius = UDim.new(0, 6)

        local mapScroll = Instance.new("ScrollingFrame", mapView)
        mapScroll.Size = UDim2.fromScale(1, 1)
        mapScroll.BackgroundTransparency = 1
        mapScroll.BorderSizePixel = 0
        mapScroll.ScrollBarThickness = 5
        mapScroll.ScrollingDirection = Enum.ScrollingDirection.XY
        mapScroll.ElasticBehavior = Enum.ElasticBehavior.Never
        mapScroll.CanvasSize = UDim2.fromScale(1, 1)

        local mapCanvas = Instance.new("Frame", mapScroll)
        mapCanvas.Size = UDim2.fromScale(1, 1)
        mapCanvas.BackgroundColor3 = Color3.fromRGB(18, 34, 58)
        mapCanvas.BorderSizePixel = 0

        local bpMarker = Instance.new("Frame", mapCanvas)
        bpMarker.BackgroundColor3 = Color3.fromRGB(245, 158, 11)
        bpMarker.BackgroundTransparency = 0.25
        bpMarker.BorderSizePixel = 0
        bpMarker.ZIndex = 12
        bpMarker.Visible = false
        local bpStroke = Instance.new("UIStroke", bpMarker)
        bpStroke.Color = Color3.fromRGB(253, 224, 71)
        bpStroke.Thickness = 1

        local playerMarker = Instance.new("Frame", mapCanvas)
        playerMarker.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        playerMarker.BorderSizePixel = 0
        playerMarker.ZIndex = 14
        playerMarker.Visible = false
        local pStroke = Instance.new("UIStroke", playerMarker)
        pStroke.Color = Color3.fromRGB(14, 165, 233)
        pStroke.Thickness = 1.4

        local hitBtn = Instance.new("TextButton", mapCanvas)
        hitBtn.Size = UDim2.fromScale(1, 1)
        hitBtn.BackgroundTransparency = 1
        hitBtn.AutoButtonColor = false
        hitBtn.Text = ""
        hitBtn.ZIndex = 20

        local bar = Instance.new("Frame", rowContainer)
        bar.Size = UDim2.new(1, -12, 0, 24)
        bar.Position = UDim2.new(0, 6, 1, -28)
        bar.BackgroundTransparency = 1
        local barLay = Instance.new("UIListLayout", bar)
        barLay.FillDirection = Enum.FillDirection.Horizontal
        barLay.VerticalAlignment = Enum.VerticalAlignment.Center
        barLay.Padding = UDim.new(0, 4)

        local function makeMapBtn(txt, wPx, bgCol, txtCol)
            local b = Instance.new("TextButton", bar)
            b.Size = UDim2.fromOffset(wPx, 22)
            b.BackgroundColor3 = bgCol or Color3.fromRGB(30, 41, 59)
            b.BorderSizePixel = 0
            b.Font = Enum.Font.GothamBold
            b.TextSize = 10
            b.TextColor3 = txtCol or Color3.fromRGB(241, 245, 249)
            b.Text = txt
            Instance.new("UICorner", b).CornerRadius = UDim.new(0, 5)
            return b
        end

        local modeBtn = makeMapBtn("MODE: DERET", 86, Color3.fromRGB(16, 185, 129), Color3.fromRGB(8, 20, 18))
        local allBtn = makeMapBtn("ALL", 36, Color3.fromRGB(59, 130, 246), Color3.new(1, 1, 1))
        local clrBtn = makeMapBtn("CLR", 36, Color3.fromRGB(220, 38, 38), Color3.new(1, 1, 1))
        local fitBtn = makeMapBtn("FIT", 32, Color3.fromRGB(51, 65, 85), Color3.new(1, 1, 1))
        local zoomOutBtn = makeMapBtn("-", 26, Color3.fromRGB(31, 41, 55), Color3.new(1, 1, 1))
        local zoomLbl = Instance.new("TextLabel", bar)
        zoomLbl.Size = UDim2.fromOffset(36, 22)
        zoomLbl.BackgroundColor3 = Color3.fromRGB(15, 23, 42)
        zoomLbl.BorderSizePixel = 0
        zoomLbl.Font = Enum.Font.Code
        zoomLbl.TextSize = 10
        zoomLbl.TextColor3 = Color3.fromRGB(148, 163, 184)
        zoomLbl.Text = "1.0x"
        Instance.new("UICorner", zoomLbl).CornerRadius = UDim.new(0, 5)
        local zoomInBtn = makeMapBtn("+", 26, Color3.fromRGB(31, 41, 55), Color3.new(1, 1, 1))

        local pool = {}
        local lastDraw, lastMapSig, wasMapVisible = 0, "", false
        local mapViewMinY, mapViewMaxY = 0, 59
        local calib = { Mouse = {}, Touch = {} }

        local function learnCalibFromBtn(btn, inp)
            if not inp or not btn then return end
            local okIn, tl = pcall(function() return GuiService:GetGuiInset() end)
            if not okIn or not tl then return end
            local key = (inp.UserInputType == Enum.UserInputType.Touch) and "Touch" or "Mouse"
            local bp, bs = btn.AbsolutePosition, btn.AbsoluteSize
            local py, px = inp.Position.Y, inp.Position.X
            if tl.Y > bs.Y + 4 then
                local rawIn = (py >= bp.Y - 3 and py <= bp.Y + bs.Y + 3)
                local insIn = (py + tl.Y >= bp.Y - 3 and py + tl.Y <= bp.Y + bs.Y + 3)
                if rawIn and not insIn then calib[key].dy = 0
                elseif insIn and not rawIn then calib[key].dy = tl.Y end
            end
            if tl.X > bs.X + 4 then
                local rawIn = (px >= bp.X - 3 and px <= bp.X + bs.X + 3)
                local insIn = (px + tl.X >= bp.X - 3 and px + tl.X <= bp.X + bs.X + 3)
                if rawIn and not insIn then calib[key].dx = 0
                elseif insIn and not rawIn then calib[key].dx = tl.X end
            end
        end
        for _, cb in ipairs({ modeBtn, allBtn, clrBtn, fitBtn, zoomOutBtn, zoomInBtn }) do
            cb.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                    learnCalibFromBtn(cb, inp)
                end
            end)
        end

        local function resolvePointerPos(inp)
            local key = (inp.UserInputType == Enum.UserInputType.Touch) and "Touch" or "Mouse"
            local cx, cy = inp.Position.X, inp.Position.Y
            local dx = (calib[key] and calib[key].dx) or 0
            local dy = (calib[key] and calib[key].dy) or 0
            return cx + dx, cy + dy
        end

        local function isGuiChainVisible(obj)
            local cur, depth = obj, 0
            while cur and depth < 7 do
                if not canAccessInst(cur) then return false end
                local okG, isGui = pcall(function() return cur:IsA("GuiObject") end)
                if okG and isGui then
                    local okV, vis = pcall(function() return cur.Visible == true end)
                    if not (okV and vis) then return false end
                end
                local okSg, isSg = pcall(function() return cur:IsA("ScreenGui") end)
                if okSg and isSg then
                    local okE, en = pcall(function() return cur.Enabled == true end)
                    return okE and en == true
                end
                cur = cur.Parent
                depth += 1
            end
            return true
        end

        local function getBox(i, col)
            local f = pool[i]
            if not f then
                f = Instance.new("Frame", mapCanvas)
                f.BorderSizePixel = 0
                pool[i] = f
            end
            f.Visible = true
            f.BackgroundColor3 = col
            return f
        end

        local function applyMapZoom(newZ, keepCenter)
            local oldZ = clamp(tonumber(Pabrik.State.mapZoom) or 1.0, 1.0, 5.0)
            local targetZ = clamp(math.floor((tonumber(newZ) or 1.0) * 10 + 0.5) / 10, 1.0, 5.0)
            Pabrik.State.mapZoom = targetZ
            zoomLbl.Text = string.format("%.1fx", targetZ)
            mapScroll.ScrollingEnabled = false
            local vs = mapScroll.AbsoluteSize
            local vw, vh = math.max(100, vs.X), math.max(80, vs.Y)
            local oldAbs = mapCanvas.AbsoluteSize
            local oldW = (oldAbs.X > 10) and oldAbs.X or math.max(vw, math.floor(vw * oldZ + 0.5))
            local oldH = (oldAbs.Y > 10) and oldAbs.Y or math.max(vh, math.floor(vh * oldZ + 0.5))
            local cxFrac = clamp((mapScroll.CanvasPosition.X + vw * 0.5) / oldW, 0, 1)
            local cyFrac = clamp((mapScroll.CanvasPosition.Y + vh * 0.5) / oldH, 0, 1)
            local newW = math.max(vw, math.floor(vw * targetZ + 0.5))
            local newH = math.max(vh, math.floor(vh * targetZ + 0.5))
            if targetZ <= 1.01 then
                mapCanvas.Size = UDim2.fromScale(1, 1)
                mapScroll.CanvasSize = UDim2.fromScale(1, 1)
                mapScroll.CanvasPosition = Vector2.zero
            else
                mapCanvas.Size = UDim2.fromOffset(newW, newH)
                mapScroll.CanvasSize = UDim2.fromOffset(newW, newH)
                if keepCenter then
                    mapScroll.CanvasPosition = Vector2.new(
                        clamp(cxFrac * newW - vw * 0.5, 0, math.max(0, newW - vw)),
                        clamp(cyFrac * newH - vh * 0.5, 0, math.max(0, newH - vh))
                    )
                end
            end
        end

        local function syncModeBtnUi()
            local isDeret = (Pabrik.State.selectMode or "DERET") == "DERET"
            modeBtn.Text = isDeret and "MODE: DERET" or "MODE: 1 TILE"
            modeBtn.BackgroundColor3 = isDeret and Color3.fromRGB(16, 185, 129) or Color3.fromRGB(56, 189, 248)
        end

        local COL_SEL = Color3.fromRGB(168, 85, 247)
        local COL_SEED = Color3.fromRGB(34, 197, 94)
        local COL_PLT = Color3.fromRGB(52, 211, 153)
        local COL_BED = Color3.fromRGB(48, 54, 66)
        local COL_LOCK = Color3.fromRGB(250, 204, 21)
        local COL_BLK = Color3.fromRGB(115, 82, 52)
        local COL_OTH = Color3.fromRGB(71, 85, 105)

        local function renderDirtSelector(force)
            if not force and (not isGuiChainVisible(mapView) or mapView.AbsoluteSize.X <= 4) then
                wasMapVisible = false
                return
            end
            if not force and not wasMapVisible then force = true end
            wasMapVisible = true
            ensureExecCap()
            if not canAccessInst(rowContainer) then return end
            pcall(function()
                local now = os.clock()
                if not force and (now - lastDraw) < 0.75 then return end
                lastDraw = now
                Core.EnsureInit()
                local gt = H.gt
                if not gt or not gt.fg then return end
                local w, h = gt.w or 100, gt.h or 60
                local fgSum, selCnt, selHash = 0, 0, 0
                local minY, maxY, hasCrop = h - 1, 0, false
                for y = 0, h - 1 do
                    local row = gt.fg[y]
                    local rowInteresting = false
                    for x = 0, w - 1 do
                        local id = row and (row[x] or 0) or 0
                        if id ~= 0 then
                            fgSum += id * ((x % 17) + (y % 11) + 1)
                            local info = Core.GetItemInfo(id)
                            if info and info.kind == "seed" then rowInteresting = true end
                        elseif Pabrik.IsTilePlantable(x, y) then
                            rowInteresting = true
                        end
                        if not rowInteresting and Pabrik.State.selectedTiles[tileKey(x, y)] ~= nil then
                            rowInteresting = true
                        end
                    end
                    if rowInteresting then
                        hasCrop = true
                        if y < minY then minY = y end
                        if y > maxY then maxY = y end
                    end
                end
                if not hasCrop then
                    for y = 0, h - 1 do
                        local row = gt.fg[y]
                        if row then
                            for x = 0, w - 1 do
                                local id = row[x] or 0
                                if id ~= 0 and id ~= 8 then
                                    hasCrop = true
                                    if y < minY then minY = y end
                                    if y > maxY then maxY = y end
                                end
                            end
                        end
                    end
                end
                local bp = Pabrik.State.breakPos
                if not hasCrop then
                    minY, maxY = 0, h - 1
                else
                    if bp and bp.y then
                        local by = clamp(math.floor(tonumber(bp.y) or 0), 0, h - 1)
                        if by < minY then minY = by end
                        if by > maxY then maxY = by end
                    end
                    maxY = clamp(maxY + 1, 0, h - 1)
                end
                mapViewMinY, mapViewMaxY = minY, maxY
                local viewH = math.max(1, maxY - minY + 1)

                for _, pt in pairs(Pabrik.State.selectedTiles) do
                    selCnt += 1
                    selHash += ((pt.x or 0) * 13 + (pt.y or 0) * 31 + 7) % 997
                end
                local bpSig = bp and (tostring(bp.x) .. "," .. tostring(bp.y)) or "-"
                local sPos = Core.ReadPos()
                local mapSig = string.format("%s:%dx%d:%d-%d:%d:%d:%d:%s:%d,%d:%.1f", tostring(gt.name or ""), w, h, minY, maxY, fgSum, selCnt, selHash, bpSig, sPos.tx, sPos.ty, tonumber(Pabrik.State.mapZoom) or 1)

                syncModeBtnUi()
                local lineCnt = 0
                if type(Pabrik.GetConnectedLines) == "function" then lineCnt = #Pabrik.GetConnectedLines() end
                hudLbl.Text = string.format("%s | %d tile (%d baris) | %.1fx",
                    (Pabrik.State.selectMode or "DERET") == "DERET" and "DERET" or "1-TILE",
                    selCnt, lineCnt, tonumber(Pabrik.State.mapZoom) or 1.0)

                if not force and mapSig == lastMapSig then return end
                lastMapSig = mapSig

                local used = 0
                for y = minY, maxY do
                    local runKey, runCol, runZ, runStart = nil, nil, 2, 0
                    local function flushRun(xEnd)
                        if runKey and runCol and xEnd >= runStart then
                            used += 1
                            local f = getBox(used, runCol)
                            f.Position = UDim2.fromScale(runStart / w, (y - minY) / viewH)
                            f.Size = UDim2.fromScale((xEnd - runStart + 1) / w, 1 / viewH)
                            f.ZIndex = runZ
                        end
                    end
                    for x = 0, w - 1 do
                        local k = tileKey(x, y)
                        local isSelected = Pabrik.State.selectedTiles[k] ~= nil
                        local id = Core.GetFG(x, y)
                        local cKey, cCol, cZ = nil, nil, 2
                        if isSelected then
                            cKey, cCol, cZ = "SEL", COL_SEL, 6
                        elseif id ~= 0 then
                            local info = Core.GetItemInfo(id)
                            if info and info.kind == "seed" then
                                cKey, cCol, cZ = "SEED", COL_SEED, 5
                            elseif id == 8 then
                                cKey, cCol, cZ = "BED", COL_BED, 2
                            elseif info and info.lock then
                                cKey, cCol, cZ = "LOCK", COL_LOCK, 4
                            elseif info and (info.solid == true or info.platform == true) and not info.door and not info.deadly and not info.hurts then
                                cKey, cCol, cZ = "BLK", COL_BLK, 2
                            else
                                cKey, cCol, cZ = "OTH", COL_OTH, 2
                            end
                        elseif Pabrik.IsTilePlantable(x, y) then
                            cKey, cCol, cZ = "PLT", COL_PLT, 4
                        end
                        if cKey ~= runKey then
                            flushRun(x - 1)
                            runKey, runCol, runZ, runStart = cKey, cCol, cZ, x
                        end
                    end
                    flushRun(w - 1)
                end
                for i = used + 1, #pool do pool[i].Visible = false end

                if bp and bp.x and bp.y and bp.y >= minY and bp.y <= maxY then
                    bpMarker.Visible = true
                    bpMarker.Position = UDim2.fromScale(clamp(bp.x, 0, w - 1) / w, (bp.y - minY) / viewH)
                    bpMarker.Size = UDim2.fromScale(math.max(1 / w, 0.015), math.max(1 / viewH, 0.024))
                else
                    bpMarker.Visible = false
                end
                if sPos.ty >= minY and sPos.ty <= maxY then
                    playerMarker.Visible = true
                    playerMarker.AnchorPoint = Vector2.new(0.5, 0.5)
                    playerMarker.Position = UDim2.fromScale((clamp(sPos.tx, 0, w - 1) + 0.5) / w, (sPos.ty - minY + 0.5) / viewH)
                    playerMarker.Size = UDim2.fromOffset(6, 6)
                else
                    playerMarker.Visible = false
                end
            end)
        end
        UIHooks.refreshMap = renderDirtSelector

        mapView:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
            if mapView.AbsoluteSize.X > 4 and isGuiChainVisible(mapView) then
                applyMapZoom(Pabrik.State.mapZoom or 1.0, false)
                task.defer(renderDirtSelector, true)
            end
        end)

        modeBtn.MouseButton1Click:Connect(function()
            Pabrik.State.selectMode = ((Pabrik.State.selectMode or "DERET") == "DERET") and "TILE" or "DERET"
            renderDirtSelector(true)
        end)
        allBtn.MouseButton1Click:Connect(function()
            Pabrik.SelectAllPlantable()
            renderDirtSelector(true)
        end)
        clrBtn.MouseButton1Click:Connect(function()
            Pabrik.ClearSelection()
            renderDirtSelector(true)
        end)
        fitBtn.MouseButton1Click:Connect(function()
            applyMapZoom(1.0, false)
            renderDirtSelector(true)
        end)
        zoomOutBtn.MouseButton1Click:Connect(function()
            applyMapZoom((Pabrik.State.mapZoom or 1.0) - 0.5, true)
            renderDirtSelector(true)
        end)
        zoomInBtn.MouseButton1Click:Connect(function()
            applyMapZoom((Pabrik.State.mapZoom or 1.0) + 0.5, true)
            renderDirtSelector(true)
        end)

        mapScroll.InputChanged:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseWheel and inp.Position then
                local delta = (inp.Position.Z > 0) and 0.5 or -0.5
                applyMapZoom((Pabrik.State.mapZoom or 1.0) + delta, true)
                renderDirtSelector(true)
            end
        end)

        local dragActive, dragBeganAt, dragStartPos, scrollStartPos, didPan = false, 0, nil, nil, false
        hitBtn.InputBegan:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                dragActive = true
                didPan = false
                dragBeganAt = os.clock()
                dragStartPos = Vector2.new(inp.Position.X, inp.Position.Y)
                scrollStartPos = mapScroll.CanvasPosition
            end
        end)
        hitBtn.InputChanged:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseWheel and inp.Position then
                local delta = (inp.Position.Z > 0) and 0.5 or -0.5
                applyMapZoom((Pabrik.State.mapZoom or 1.0) + delta, true)
                renderDirtSelector(true)
                return
            end
            if dragActive and (inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch) and dragStartPos and scrollStartPos then
                local maxX = math.max(0, mapCanvas.AbsoluteSize.X - mapScroll.AbsoluteSize.X)
                local maxY = math.max(0, mapCanvas.AbsoluteSize.Y - mapScroll.AbsoluteSize.Y)
                if maxX <= 1 and maxY <= 1 then return end
                local curPos = Vector2.new(inp.Position.X, inp.Position.Y)
                local d = curPos - dragStartPos
                if d.Magnitude > 6 then
                    didPan = true
                    mapScroll.CanvasPosition = Vector2.new(
                        clamp(scrollStartPos.X - d.X, 0, maxX),
                        clamp(scrollStartPos.Y - d.Y, 0, maxY)
                    )
                end
            end
        end)
        hitBtn.InputEnded:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                local wasTap = dragActive and not didPan and dragStartPos and (Vector2.new(inp.Position.X, inp.Position.Y) - dragStartPos).Magnitude <= 10 and (os.clock() - dragBeganAt) <= 0.65
                dragActive = false
                if not wasTap then return end
                local gt = H.gt
                if not gt then return end
                local cx, cy = resolvePointerPos(inp)
                local vp, vs = mapView.AbsolutePosition, mapView.AbsoluteSize
                if cx < vp.X or cy < vp.Y or cx > vp.X + vs.X or cy > vp.Y + vs.Y then return end
                local ap, as = mapCanvas.AbsolutePosition, mapCanvas.AbsoluteSize
                if as.X <= 1 or as.Y <= 1 then return end
                local rx = clamp((cx - ap.X) / as.X, 0, 0.9999)
                local ry = clamp((cy - ap.Y) / as.Y, 0, 0.9999)
                local viewH = math.max(1, mapViewMaxY - mapViewMinY + 1)
                local rawTx = clamp(math.floor(rx * gt.w), 0, gt.w - 1)
                local rawTy = clamp(mapViewMinY + math.floor(ry * viewH), mapViewMinY, mapViewMaxY)
                local tx, ty = Pabrik.ResolvePlantableTap(rawTx, rawTy)
                if not tx or not ty then
                    tx, ty = Pabrik.ResolvePlantableTap(rawTx, clamp(rawTy - 1, 0, gt.h - 1))
                end
                if not tx or not ty then
                    tx, ty = Pabrik.ResolvePlantableTap(rawTx, clamp(rawTy + 1, 0, gt.h - 1))
                end
                if not tx or not ty then
                    hudLbl.Text = string.format("(%d,%d) bukan tempat tanam! Pilih baris di atas block", rawTx, rawTy)
                    return
                end
                if (Pabrik.State.selectMode or "DERET") == "DERET" then
                    Pabrik.ToggleLine(ty, tx)
                else
                    Pabrik.ToggleTile(tx, ty)
                end
                renderDirtSelector(true)
            end
        end)

        syncModeBtnUi()
        applyMapZoom(Pabrik.State.mapZoom or 1.0, false)
        task.delay(0.4, function() renderDirtSelector(true) end)
    end)

    -- 4 & 5. FIFO WORLD QUEUE LISTS (DF: __DF_LIST_ANCHOR_KEY__ | CW: __CW_LIST_ANCHOR_KEY__)
    local function mountWorldQueueList(anchorKey, getListFn, removeFn, hookName)
        mountEmbeddedCanvas(anchorKey, 96, function(rowContainer)
            local scroll = Instance.new("ScrollingFrame", rowContainer)
            scroll.Size = UDim2.new(1, -8, 1, -8)
            scroll.Position = UDim2.fromOffset(4, 4)
            scroll.BackgroundColor3 = Color3.fromRGB(15, 20, 30)
            scroll.BorderSizePixel = 0
            scroll.ScrollBarThickness = 4
            scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
            scroll.CanvasSize = UDim2.new()
            Instance.new("UIListLayout", scroll).Padding = UDim.new(0, 3)

            local function refresh()
                ensureExecCap()
                if not canAccessInst(scroll) then return end
                pcall(function()
                    for _, ch in ipairs(scroll:GetChildren()) do
                        if ch:IsA("Frame") then ch:Destroy() end
                    end
                    local list = getListFn() or {}
                    for i, wName in ipairs(list) do
                        local row = Instance.new("Frame", scroll)
                        row.Size = UDim2.new(1, -6, 0, 22)
                        row.BackgroundColor3 = Color3.fromRGB(26, 34, 48)
                        Instance.new("UICorner", row).CornerRadius = UDim.new(0, 4)
                        local lbl = Instance.new("TextLabel", row)
                        lbl.Size = UDim2.new(1, -30, 1, 0)
                        lbl.Position = UDim2.fromOffset(6, 0)
                        lbl.BackgroundTransparency = 1
                        lbl.Font = Enum.Font.Code
                        lbl.TextSize = 11
                        lbl.TextXAlignment = Enum.TextXAlignment.Left
                        lbl.TextColor3 = Color3.new(1, 1, 1)
                        lbl.Text = string.format("%d. %s", i, tostring(wName))
                        local del = Instance.new("TextButton", row)
                        del.Size = UDim2.fromOffset(22, 18)
                        del.Position = UDim2.new(1, -24, 0, 2)
                        del.BackgroundColor3 = Color3.fromRGB(185, 28, 28)
                        del.Font = Enum.Font.GothamBold
                        del.TextSize = 10
                        del.TextColor3 = Color3.new(1, 1, 1)
                        del.Text = "X"
                        Instance.new("UICorner", del).CornerRadius = UDim.new(0, 3)
                        del.MouseButton1Click:Connect(function() removeFn(i) end)
                    end
                end)
            end
            UIHooks[hookName] = refresh
            refresh()
        end)
    end

    mountWorldQueueList("__DF_LIST_ANCHOR_KEY__",
        function() return DirtFarm.State.rotationWorlds end,
        function(i)
            table.remove(DirtFarm.State.rotationWorlds, i)
            DirtFarm.State.rotationText = table.concat(DirtFarm.State.rotationWorlds, ", ")
            if DirtFarm._syncEnvQueue then DirtFarm._syncEnvQueue(DirtFarm.State.rotationWorlds) end
            if UIHooks.refreshDfList then UIHooks.refreshDfList() end
        end,
        "refreshDfList"
    )
    mountWorldQueueList("__CW_LIST_ANCHOR_KEY__",
        function() return ClearWorld.State.worldList end,
        function(i) ClearWorld.RemoveWorldAt(i) end,
        "refreshCwList"
    )

    -- 6. SCROLLABLE SYSTEM JOIN & MOD LOG (__SYS_LOG_ANCHOR_KEY__)
    mountEmbeddedCanvas("__SYS_LOG_ANCHOR_KEY__", 120, function(rowContainer)
        local scroll = Instance.new("ScrollingFrame", rowContainer)
        scroll.Size = UDim2.new(1, -8, 1, -8)
        scroll.Position = UDim2.fromOffset(4, 4)
        scroll.BackgroundColor3 = Color3.fromRGB(12, 16, 24)
        scroll.BorderSizePixel = 0
        scroll.ScrollBarThickness = 4
        scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
        scroll.CanvasSize = UDim2.new()
        Instance.new("UIListLayout", scroll).Padding = UDim.new(0, 3)

        local function refreshSysLog()
            ensureExecCap()
            if not canAccessInst(scroll) then return end
            pcall(function()
                for _, ch in ipairs(scroll:GetChildren()) do
                    if ch:IsA("TextLabel") then ch:Destroy() end
                end
                for _, item in ipairs(SystemModule.State.joinLogs) do
                    local lbl = Instance.new("TextLabel", scroll)
                    lbl.Size = UDim2.new(1, -6, 0, 18)
                    lbl.BackgroundTransparency = 1
                    lbl.Font = Enum.Font.Code
                    lbl.TextSize = 10
                    lbl.TextXAlignment = Enum.TextXAlignment.Left
                    lbl.TextColor3 = item.isStaff and Color3.fromRGB(248, 113, 113) or Color3.fromRGB(148, 163, 184)
                    lbl.Text = item.text
                end
            end)
        end
        UIHooks.refreshSysLog = refreshSysLog
        refreshSysLog()
    end)

    -- 7 & 8. RADIO GROUPS (SPAM 3-7s | DISCORD HOOK 1-5m)
    local function mountRadioGroup(anchorKey, values, labels, getCurrent, onPick)
        mountEmbeddedCanvas(anchorKey, 34, function(rowContainer)
            local btns = {}
            local function syncVis()
                local cur = getCurrent()
                for val, b in pairs(btns) do
                    local on = (val == cur)
                    b.BackgroundColor3 = on and Color3.fromRGB(56, 189, 248) or Color3.fromRGB(31, 35, 44)
                    b.TextColor3 = on and Color3.new(0, 0, 0) or Color3.new(1, 1, 1)
                end
            end
            local n = #values
            for i, val in ipairs(values) do
                local b = Instance.new("TextButton", rowContainer)
                b.Size = UDim2.new(1 / n, -4, 1, -6)
                b.Position = UDim2.new((i - 1) / n, 2, 0, 3)
                b.BorderSizePixel = 0
                b.Font = Enum.Font.GothamBold
                b.TextSize = 10
                b.Text = labels[i]
                Instance.new("UICorner", b).CornerRadius = UDim.new(0, 4)
                btns[val] = b
                b.MouseButton1Click:Connect(function()
                    onPick(val)
                    syncVis()
                end)
            end
            syncVis()
        end)
    end

    mountRadioGroup("__SPAM_RADIO_ANCHOR_KEY__", { 3, 4, 5, 6, 7 }, { "3s", "4s", "5s", "6s", "7s" },
        function() return math.floor(Spam.State.delay or 5) end,
        function(v) Spam.State.delay = v end
    )
    mountRadioGroup("__DH_RADIO_ANCHOR_KEY__", { 60, 120, 180, 240, 300 }, { "1m", "2m", "3m", "4m", "5m" },
        function() return math.floor(DiscordHook.State.delay or 120) end,
        function(v) DiscordHook.State.delay = v end
    )

    task.defer(function()
        if getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then return end
        pcall(SYT_Logic.Init, false)
        pcall(UIHooks.scanResponsiveButtons)
        pcall(UIHooks.updateButtons)
        if UIHooks.refreshBP then pcall(UIHooks.refreshBP) end
        if UIHooks.refreshPabBP then pcall(UIHooks.refreshPabBP) end
        if UIHooks.refreshMap then pcall(UIHooks.refreshMap, true) end
    end)
end

do
    local function escVal(s)
        return tostring(s or ""):gsub("%%", "%%25"):gsub("\r", "%%0D"):gsub("\n", "%%0A"):gsub("=", "%%3D")
    end
    local function unescVal(s)
        return tostring(s or ""):gsub("%%3D", "="):gsub("%%0A", "\n"):gsub("%%0D", "\r"):gsub("%%25", "%%")
    end

    function SYT_Logic.SaveAllSettings(forceWrite)
        local env = getEnv()
        local ed = env and env.__SYT_ENV_DATA or {}
        if env then env.__SYT_ENV_DATA = ed end

        local gridKeys = {}
        for k, v in pairs((PNB and PNB.State and PNB.State.grid5x5) or {}) do
            if v == true then gridKeys[#gridKeys + 1] = tostring(k) end
        end
        table.sort(gridKeys)

        local dfList = {}
        for _, w in ipairs((DirtFarm and DirtFarm.State and DirtFarm.State.rotationWorlds) or {}) do
            dfList[#dfList + 1] = tostring(w)
        end
        local cwList = {}
        for _, w in ipairs((ClearWorld and ClearWorld.State and ClearWorld.State.worldList) or {}) do
            cwList[#cwList + 1] = tostring(w)
        end

        local kv = {
            uiMinimized = (ed.uiMinimized == false) and "0" or "1",
            sysEnabled = (SystemModule and SystemModule.State.enabled ~= false) and "1" or "0",
            sysMode = tostring((SystemModule and SystemModule.State.mode) or "FREEZE"),
            sysDiscordLog = (SystemModule and SystemModule.State.discordLog == true) and "1" or "0",
            autoLvlTarget = tostring(math.clamp(math.floor(tonumber(AutoLeveling and AutoLeveling.State.targetLevel) or 100), 2, 100)),
            miscZoom = (Misc and Misc.State.zoom25x == true) and "1" or "0",
            miscSkipUpd = (Misc and Misc.State.skipUpdateItem == true) and "1" or "0",
            miscSlowFall = (Misc and Misc.State.slowFall == true) and "1" or "0",
            miscFly = (Misc and Misc.State.fly == true) and "1" or "0",
            spamText = tostring((Spam and Spam.State.text) or ""),
            spamRainbow = (Spam and Spam.State.rainbowOn == true) and "1" or "0",
            spamPrefix = (Spam and Spam.State.prefixOn == true) and "1" or "0",
            spamDelay = tostring(tonumber(Spam and Spam.State.delay) or 5),
            pnbBlockId = tostring((PNB and PNB.State.selectedBlockId) or ""),
            pnbStorageBlock = tostring((PNB and PNB.State.storageBlock) or ""),
            pnbStorageSafe = tostring((PNB and PNB.State.storageSafe) or ""),
            pnbSpeedPct = tostring(tonumber(PNB and PNB.State.speedPct) or 60),
            pnbAutoBuyKey = tostring((PNB and PNB.State.autoBuyKey) or "OFF"),
            pnbGrid5x5 = table.concat(gridKeys, ";"),
            pabItemName = tostring((Pabrik and Pabrik.State.itemName) or ""),
            pabBlockId = tostring((Pabrik and Pabrik.State.blockId) or ""),
            pabSeedId = tostring((Pabrik and Pabrik.State.seedId) or ""),
            pabSpeedPct = tostring(tonumber(Pabrik and Pabrik.State.speedPct) or 60),
            pabBreakCnt = tostring(tonumber(Pabrik and Pabrik.State.breakTileCount) or 1),
            pabSelectMode = tostring((Pabrik and Pabrik.State.selectMode) or "DERET"),
            pabMapZoom = tostring(tonumber(Pabrik and Pabrik.State.mapZoom) or 1.0),
            dfQueue = table.concat(dfList, ","),
            cwQueue = table.concat(cwList, ","),
            dhUrl = tostring((DiscordHook and DiscordHook.State.url) or ""),
            dhDelay = tostring(tonumber(DiscordHook and DiscordHook.State.delay) or 120),
            dhEnabled = ((DiscordHook and (DiscordHook.State.enabled == true or DiscordHook.State._wantResume == true)) and "1" or "0"),
            prxP2p = (ProxyCommands and ProxyCommands.State.p2pEnabled ~= false) and "1" or "0",
            prxReme = (ProxyCommands and ProxyCommands.State.remeEnabled == true) and "1" or "0",
            prxTax = tostring(tonumber(ProxyCommands and ProxyCommands.State.bj and ProxyCommands.State.bj.tax) or 0),
            mbTakeWorld = tostring((MoveBlock and MoveBlock.State.takeWorld) or ""),
            mbDropWorld = tostring((MoveBlock and MoveBlock.State.dropWorld) or ""),
            mbMode = tostring((MoveBlock and MoveBlock.State.itemMode) or "Auto (Block + Seed)"),
            mbCustomId = tostring((MoveBlock and MoveBlock.State.customItemId) or 0),
            mbAntiTake = (MoveBlock and MoveBlock.State.antiTakeDropTile ~= false) and "1" or "0",
            mbLockAnti = (MoveBlock and MoveBlock.State.lockAntiTake == true) and "1" or "0",
            mbSpeed = tostring(tonumber(MoveBlock and MoveBlock.State.moveSpeed) or 7.3),
            mbDelay = tostring(tonumber(MoveBlock and MoveBlock.State.dropDelay) or 0.15),
            mbTakePos = (MoveBlock and MoveBlock.State.takePos) and string.format("%d,%d,%s", MoveBlock.State.takePos.x, MoveBlock.State.takePos.y, tostring(MoveBlock.State.takePos.world or "")) or "",
            mbDropPos = (MoveBlock and MoveBlock.State.dropPos) and string.format("%d,%d,%s", MoveBlock.State.dropPos.x, MoveBlock.State.dropPos.y, tostring(MoveBlock.State.dropPos.world or "")) or "",
        }

        local orderKeys = {
            "uiMinimized", "sysEnabled", "sysMode", "sysDiscordLog", "autoLvlTarget",
            "miscZoom", "miscSkipUpd", "miscSlowFall", "miscFly",
            "spamText", "spamRainbow", "spamPrefix", "spamDelay",
            "pnbBlockId", "pnbStorageBlock", "pnbStorageSafe", "pnbSpeedPct", "pnbAutoBuyKey", "pnbGrid5x5",
            "pabItemName", "pabBlockId", "pabSeedId", "pabSpeedPct", "pabBreakCnt", "pabSelectMode", "pabMapZoom",
            "dfQueue", "cwQueue", "dhUrl", "dhDelay", "dhEnabled", "prxP2p", "prxReme", "prxTax",
            "mbTakeWorld", "mbDropWorld", "mbMode", "mbCustomId", "mbAntiTake", "mbLockAnti", "mbSpeed", "mbDelay", "mbTakePos", "mbDropPos"
        }
        local lines = {}
        for _, k in ipairs(orderKeys) do
            lines[#lines + 1] = k .. "=" .. escVal(kv[k])
        end
        local raw = table.concat(lines, "\n")
        ed.settings = kv
        ed.dfQueue = dfList
        ed.cwQueue = cwList

        if not forceWrite and raw == SYT_Logic._lastSavedSettingsRaw then
            return false
        end
        SYT_Logic._lastSavedSettingsRaw = raw
        safeWriteStorage("syt_settings_v2.dat", raw)
        if Visual and Visual.SaveToEnv then pcall(Visual.SaveToEnv) end
        if ProxyCommands and ProxyCommands.SaveEnv then pcall(ProxyCommands.SaveEnv) end
        return true
    end

    function SYT_Logic.LoadAllSettings()
        local env = getEnv()
        local ed = env and env.__SYT_ENV_DATA
        local kv = (type(ed) == "table" and type(ed.settings) == "table") and ed.settings or nil
        if not kv then
            local raw = safeReadStorage("syt_settings_v2.dat")
            if type(raw) == "string" and raw ~= "" then
                kv = {}
                for line in (raw .. "\n"):gmatch("([^\r\n]*)\r?\n") do
                    local k, v = line:match("^([^=]+)=(.*)$")
                    if k then kv[k] = unescVal(v) end
                end
                SYT_Logic._lastSavedSettingsRaw = raw
            end
        end
        if type(kv) ~= "table" then return false end

        ed = ed or {}
        if env then env.__SYT_ENV_DATA = ed end
        if kv.uiMinimized ~= nil then ed.uiMinimized = (kv.uiMinimized ~= "0") end

        if SystemModule and SystemModule.State then
            if kv.sysEnabled ~= nil then SystemModule.State.enabled = (kv.sysEnabled ~= "0") end
            if kv.sysMode == "FREEZE" or kv.sysMode == "LEAVE" then SystemModule.State.mode = kv.sysMode end
            if kv.sysDiscordLog ~= nil then SystemModule.State.discordLog = (kv.sysDiscordLog == "1") end
        end
        if AutoLeveling and AutoLeveling.State then
            local tl = tonumber(kv.autoLvlTarget)
            if tl then AutoLeveling.State.targetLevel = math.clamp(math.floor(tl), 2, 100) end
        end
        if Misc and Misc.State then
            if kv.miscZoom ~= nil then Misc.State.zoom25x = (kv.miscZoom == "1") end
            if kv.miscSkipUpd ~= nil then Misc.State.skipUpdateItem = (kv.miscSkipUpd == "1") end
            if kv.miscSlowFall ~= nil then Misc.State.slowFall = (kv.miscSlowFall == "1") end
            if kv.miscFly ~= nil then Misc.State.fly = (kv.miscFly == "1") end
        end
        if Spam and Spam.State then
            if kv.spamText ~= nil then Spam.State.text = tostring(kv.spamText):sub(1, 85) end
            if kv.spamRainbow ~= nil then Spam.State.rainbowOn = (kv.spamRainbow == "1") end
            if kv.spamPrefix ~= nil then Spam.State.prefixOn = (kv.spamPrefix == "1") end
            if tonumber(kv.spamDelay) then Spam.State.delay = clamp(tonumber(kv.spamDelay), 3, 7) end
        end
        if PNB and PNB.State then
            if kv.pnbBlockId and tonumber(kv.pnbBlockId) then PNB.State.selectedBlockId = tonumber(kv.pnbBlockId) end
            if kv.pnbStorageBlock ~= nil then PNB.State.storageBlock = kv.pnbStorageBlock end
            if kv.pnbStorageSafe ~= nil then PNB.State.storageSafe = kv.pnbStorageSafe end
            if tonumber(kv.pnbSpeedPct) then PNB.State.speedPct = clamp(tonumber(kv.pnbSpeedPct), 0, 100) end
            if kv.pnbAutoBuyKey and kv.pnbAutoBuyKey ~= "" then PNB.State.autoBuyKey = kv.pnbAutoBuyKey end
            if kv.pnbGrid5x5 ~= nil then
                PNB.State.grid5x5 = {}
                for seg in kv.pnbGrid5x5:gmatch("[^;]+") do
                    if seg ~= "" then PNB.State.grid5x5[seg] = true end
                end
            end
        end
        if Pabrik and Pabrik.State then
            if kv.pabItemName ~= nil then Pabrik.State.itemName = kv.pabItemName end
            if kv.pabBlockId and tonumber(kv.pabBlockId) then Pabrik.State.blockId = tonumber(kv.pabBlockId) end
            if kv.pabSeedId and tonumber(kv.pabSeedId) then Pabrik.State.seedId = tonumber(kv.pabSeedId) end
            if tonumber(kv.pabSpeedPct) then Pabrik.State.speedPct = clamp(tonumber(kv.pabSpeedPct), 0, 100) end
            if tonumber(kv.pabBreakCnt) then Pabrik.State.breakTileCount = clamp(tonumber(kv.pabBreakCnt), 1, 3) end
            if kv.pabSelectMode == "DERET" or kv.pabSelectMode == "TILE" then Pabrik.State.selectMode = kv.pabSelectMode end
            if tonumber(kv.pabMapZoom) then Pabrik.State.mapZoom = clamp(tonumber(kv.pabMapZoom), 1.0, 5.0) end
        end
        if DirtFarm and DirtFarm.State and kv.dfQueue and kv.dfQueue ~= "" then
            local list = {}
            for w in kv.dfQueue:gmatch("[^,]+") do
                local cw = sanitizeWorldSpec(w, false)
                if cw ~= "" then list[#list + 1] = cw end
            end
            if #list > 0 then
                DirtFarm.State.rotationWorlds = list
                DirtFarm.State.rotationText = table.concat(list, ", ")
                ed.dfQueue = list
            end
        end
        if ClearWorld and ClearWorld.State and kv.cwQueue and kv.cwQueue ~= "" then
            local list = {}
            for w in kv.cwQueue:gmatch("[^,]+") do
                local cw = sanitizeWorldSpec(w, false)
                if cw ~= "" then list[#list + 1] = cw end
            end
            if #list > 0 then
                ClearWorld.State.worldList = list
                ed.cwQueue = list
            end
        end
        if DiscordHook and DiscordHook.State then
            if kv.dhUrl ~= nil then DiscordHook.State.url = tostring(kv.dhUrl):sub(1, 300) end
            if tonumber(kv.dhDelay) then DiscordHook.State.delay = clamp(tonumber(kv.dhDelay), 60, 300) end
            DiscordHook.State._wantResume = (kv.dhEnabled == "1")
        end
        if ProxyCommands and ProxyCommands.State then
            if kv.prxP2p ~= nil then ProxyCommands.State.p2pEnabled = (kv.prxP2p ~= "0") end
            if kv.prxReme ~= nil then ProxyCommands.State.remeEnabled = (kv.prxReme == "1") end
            if ProxyCommands.State.bj and tonumber(kv.prxTax) then
                ProxyCommands.State.bj.tax = clamp(math.floor(tonumber(kv.prxTax)), 0, 100)
            end
        end
        if MoveBlock and MoveBlock.State then
            if kv.mbTakeWorld ~= nil then MoveBlock.State.takeWorld = sanitizeWorldSpec(kv.mbTakeWorld, true) end
            if kv.mbDropWorld ~= nil then MoveBlock.State.dropWorld = sanitizeWorldSpec(kv.mbDropWorld, true) end
            if kv.mbMode and kv.mbMode ~= "" then MoveBlock.State.itemMode = kv.mbMode end
            if tonumber(kv.mbCustomId) then MoveBlock.State.customItemId = math.max(0, math.floor(tonumber(kv.mbCustomId))) end
            if kv.mbAntiTake ~= nil then MoveBlock.State.antiTakeDropTile = (kv.mbAntiTake ~= "0") end
            if kv.mbLockAnti ~= nil then MoveBlock.State.lockAntiTake = (kv.mbLockAnti == "1") end
            if tonumber(kv.mbSpeed) then MoveBlock.State.moveSpeed = clamp(tonumber(kv.mbSpeed), 6.0, 11.5) end
            if tonumber(kv.mbDelay) then MoveBlock.State.dropDelay = clamp(tonumber(kv.mbDelay), 0.04, 3.0) end
            if type(kv.mbTakePos) == "string" and kv.mbTakePos ~= "" then
                local tx, ty, tw = kv.mbTakePos:match("^(-?%d+),(-?%d+),(.*)$")
                if tx and ty then MoveBlock.State.takePos = { x = tonumber(tx), y = tonumber(ty), world = tw or "" } end
            end
            if type(kv.mbDropPos) == "string" and kv.mbDropPos ~= "" then
                local dx, dy, dw = kv.mbDropPos:match("^(-?%d+),(-?%d+),(.*)$")
                if dx and dy then MoveBlock.State.dropPos = { x = tonumber(dx), y = tonumber(dy), world = dw or "" } end
            end
        end
        return true
    end
end

