            if ProxyCommands.P2P.SendHello then pcall(ProxyCommands.P2P.SendHello, false) end
        end
    end)
end)

-- Auto-Resume dari Local Memory env (__SYT_ENV_DATA.rotSession + queue DF/CW) & AutoLeveling (level < 10) tanpa spam warp
task.spawn(function()
    local ed = getEnv().__SYT_ENV_DATA
    if type(ed) == "table" then
        if type(ed.dfQueue) == "table" and #ed.dfQueue > 0 then
            local q = {}
            for i, w in ipairs(ed.dfQueue) do q[i] = w end
            DirtFarm.State.rotationWorlds = q
            DirtFarm.State.rotationText = table.concat(q, ", ")
            if UIHooks.refreshDfList then pcall(UIHooks.refreshDfList) end
        end
        if type(ed.cwQueue) == "table" and #ed.cwQueue > 0 then
            local q = {}
            for i, w in ipairs(ed.cwQueue) do q[i] = w end
            ClearWorld.State.worldList = q
            if UIHooks.refreshCwList then pcall(UIHooks.refreshCwList) end
        end
    end

    local rot = type(ed) == "table" and ed.rotSession or nil
    local savedAutoLvl = safeReadStorage("syt_autolvl.dat")
    local hasRot = (type(rot) == "table" and rot.active == true and (type(rot.updatedAt) ~= "number" or (os.clock() - rot.updatedAt) <= 300))
    -- File lama syt_autolvl.dat tidak lagi auto-resume saat execute pertama (penyebab SC keluar world sendiri)
    local hasAutoFile = false
    if not hasRot and type(savedAutoLvl) == "string" and savedAutoLvl ~= "" then
        safeWriteStorage("syt_autolvl.dat", "")
    end
    H._pendingAutoLvlBoot = ((hasRot and rot.mode == "AutoLeveling") or hasAutoFile) == true
    if not hasRot and not hasAutoFile then H._pendingAutoLvlBoot = false; return end

    local dl = os.clock() + 14
    while os.clock() < dl do
        if getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then H._pendingAutoLvlBoot = false; return end
        pcall(SYT_Logic.Init, false)
        if H.gt and (H.gt.name or "") ~= "" and (H.gt.w or 0) > 0 and type(H.gt.fg) == "table" then break end
        task.wait(0.35)
    end
    if getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then H._pendingAutoLvlBoot = false; return end
    if not H.gt or (H.gt.name or "") == "" or type(H.gt.fg) ~= "table" then H._pendingAutoLvlBoot = false; return end

    if hasRot then
        if rot.mode == "DirtFarm" then
            if type(rot.worlds) == "table" and #rot.worlds > 0 then
                local q = {}
                for i, w in ipairs(rot.worlds) do q[i] = w end
                DirtFarm.State.rotationWorlds = q
                DirtFarm.State.rotationText = table.concat(q, ", ")
                if UIHooks.refreshDfList then pcall(UIHooks.refreshDfList) end
            end
            DirtFarm.Start()
            return
        elseif rot.mode == "ClearWorld" then
            if type(rot.worlds) == "table" and #rot.worlds > 0 then
                local q = {}
                for i, w in ipairs(rot.worlds) do q[i] = w end
                ClearWorld.State.worldList = q
                if UIHooks.refreshCwList then pcall(UIHooks.refreshCwList) end
            end
            ClearWorld.Start({ halfWorld = rot.halfWorld == true, noCollect = rot.noCollect == true })
            return
        elseif rot.mode == "MoveBlock" then
            if type(rot.takePos) == "table" then MoveBlock.State.takePos = rot.takePos end
            if type(rot.dropPos) == "table" then MoveBlock.State.dropPos = rot.dropPos end
            if type(rot.takeWorld) == "string" then MoveBlock.State.takeWorld = rot.takeWorld end
            if type(rot.dropWorld) == "string" then MoveBlock.State.dropWorld = rot.dropWorld end
            MoveBlock.Start()
            return
        elseif rot.mode == "AutoLeveling" then
            if AutoLeveling.GetLevel() < AutoLeveling.State.targetLevel then
                if type(rot.targetWorld) == "string" and rot.targetWorld ~= "" then
                    AutoLeveling.State.targetWorld = rot.targetWorld
                end
                if type(rot.completedWorlds) == "table" then
                    AutoLeveling.State.completedWorlds = rot.completedWorlds
                end
                if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SysAutoLevelToggle", true) end
                AutoLeveling.Start()
                return
            else
                H._pendingAutoLvlBoot = false
                ed.rotSession = nil
                safeWriteStorage("syt_autolvl.dat", "")
                return
            end
        end
    end

    if hasAutoFile then
        if AutoLeveling.GetLevel() < AutoLeveling.State.targetLevel then
            local savedW = string.sub(savedAutoLvl, 4)
            if savedW ~= "" then AutoLeveling.State.targetWorld = savedW end
            if UIHooks.syncRunToggle then UIHooks.syncRunToggle("SysAutoLevelToggle", true) end
            AutoLeveling.Start()
        else
            H._pendingAutoLvlBoot = false
            safeWriteStorage("syt_autolvl.dat", "")
        end
    end
end)

-- Runtime Watcher: Live Sync, World Change, Player/Mod Detection, Outfit Anti-Drop Self-Heal & Low-Heat Mode
local function computeInvHash()
    local slots = Core.GetBackpackSlots()
    if #slots == 0 then return "" end
    local sum, cnt = 0, 0
    for i, s in ipairs(slots) do
        cnt += 1
        sum += ((s.id or 0) * 13 + (s.n or 0)) * (i % 7 + 1)
    end
    return tostring(cnt) .. ":" .. tostring(sum)
end

local Watcher = {}
local lastFastTick, lastFxTick, lastSlowTick, lastInvCheckAt, lastInvHash = 0, 0, 0, 0, ""

function Watcher.isUiVisible()
    if not UI or UI.IsMinimized or not canAccessInst(UI.MainWindow) then return false end
    local okVis, vis = pcall(function() return UI.MainWindow.Visible == true end)
    return okVis and vis == true
end

function Watcher.syncLocalOutfit()
    if not (Visual and Visual.State) then return end
    if H._invOutfitHookedFor ~= H.inv or H._skRefreshHookedFor ~= H.skillsObj or (H.wornMod and H.wornModHookedFor ~= H.wornMod) then
        Visual.EnsureOutfitPersistenceHooks()
        Core.InstallGetgcBypassHooks()
    end
    local vs = Visual.State
    local hasFake = type(vs.fakeWorn) == "table" and next(vs.fakeWorn) ~= nil
    local hasCustomSkin = (vs.skinPreset and vs.skinPreset ~= "Real (Server Skin)") or vs.ghostSkin == true
    if not (hasFake or hasCustomSkin) then return end

    local drifted = false
    if hasFake and type(H.wornTbl) == "table" then
        for sl, fv in pairs(vs.fakeWorn) do
            if (fv > 0 and H.wornTbl[sl] ~= fv) or (fv == 0 and H.wornTbl[sl] ~= nil) then
                drifted = true
                break
            end
        end
    elseif not H.wornTbl then
        drifted = true
    end
    if not drifted and hasFake and type(H.wornSetTables) == "table" then
        local _, mergedSet = Core.BuildMergedLocalWorn(H.wornTbl)
        for wtSet, _ in pairs(H.wornSetTables) do
            if type(wtSet) == "table" then
                for id, _ in pairs(mergedSet) do
                    if not rawget(wtSet, id) then drifted = true; break end
                end
            end
            if drifted then break end
        end
    end
    if not drifted and hasFake and H.wornMod and H.wornModHookedFor == H.wornMod and type(H.playerSpriteObj) == "table" and type(Core.CollectLocalRigs) == "function" then
        local mergedSlots = Core.BuildMergedLocalWorn(H.wornTbl)
        local wantSig = Core.GetWornSignature(mergedSlots)
        if wantSig ~= "" then
            for _, rig in ipairs(Core.CollectLocalRigs(H.playerSpriteObj)) do
                if not rig.shade and rig._sytWornAppliedSig ~= wantSig then
                    drifted = true
                    break
                end
            end
        end
    end
    if drifted and Visual.ReapplyOutfitLocally then
        pcall(Visual.ReapplyOutfitLocally)
    end
end

function Watcher.handleWorldChanged(curWorld, intentionalWorldSwitch)
    local prev = Visual.State.lastWorldName
    Visual.State.lastWorldName = curWorld
    H._invDirty = true
    H._lastSidebarName = nil
    H._lastSidebarSub = nil
    H.stopMoveUntil = 0
    H.lastBlockedMoveToAt = 0
    H.blockedMoveToCount = 0
    H.autoMove = nil
    H.takingUids = {}
    if H.gt then
        H.gt.stuckAt = nil
        H.gt.portalGo = nil
    end
    pcall(Core.ClearStuckDropVisuals)
    if prev ~= "" and not intentionalWorldSwitch then
        if Misc and Misc.State and Misc.State.noClip then
            Misc.State.noClip = false
            Misc.State.noClipAnchor = nil
            pcall(RunService.UnbindFromRenderStep, RunService, "SYT_NoClipStep")
            if UI then pcall(UI.SetValue, UI, "MiscNoClipToggle", false, true) end
        end
        stopAllAutomationImpl("Pindah world -> Otomasi OFF")
    end
    if curWorld == "" then return end

    for idxW, waitSec in ipairs({ 0.15, 0.85, 2.0 }) do
        task.delay(waitSec, function()
            if getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then return end
            local wNow = H.gt and cleanWorldName(H.gt.name) or ""
            if wNow ~= curWorld then return end
            pcall(SYT_Logic.Init, false)
            if idxW == 1 then
                pcall(Core.InstallAntiBackGuard, true)
                pcall(hookIncomingNetGuard)
                pcall(ProxyCommands.Install, true)
                pcall(Core.RegisterGlobalAutoRerun)
                if ProxyCommands.State.remeEnabled then pcall(Misc.SetFastRoulette, true) end
                if Misc.State.skipUpdateItem then pcall(Misc.SetSkipUpdateItem, true) end
                if Misc.State.slowFall then pcall(Misc.SetSlowFall, true) end
                if Misc.State.fly then pcall(Misc.SetFly, true) end
                if SYT_Logic.SaveAllSettings then pcall(SYT_Logic.SaveAllSettings, false) end
            elseif idxW == 2 then
                pcall(ProxyCommands.Install, false)
            end
            if Visual.State.lockNames or Visual.HasActiveSpoof() or (Visual.State.customName or "") ~= "" or (Visual.State.role or "none") ~= "none" then
                pcall(Visual.OnWorldChanged)
            end
            if ProxyCommands.P2P then
                if ProxyCommands.P2P.SyncVisiblePeers then pcall(ProxyCommands.P2P.SyncVisiblePeers) end
                if ProxyCommands.P2P.SendHello then pcall(ProxyCommands.P2P.SendHello, idxW == 2) end
            end
            if idxW == 1 then
                if Misc.State.zoom25x then pcall(Misc.SetZoom25x, true) end
                if Watcher.isUiVisible() then
                    ensureExecCap()
                    if UIHooks.refreshBP then pcall(UIHooks.refreshBP) end
                    if UIHooks.refreshPabBP then pcall(UIHooks.refreshPabBP) end
                    if UIHooks.refreshMap then pcall(UIHooks.refreshMap, true) end
                    if UIHooks.refreshPad5x5 then pcall(UIHooks.refreshPad5x5) end
                end
            end
        end)
    end
end

function Watcher.syncEntrantsAndHeader(gt, uiVisible)
    if not gt or (gt.name or "") == "" then
        ProxyCommands.State.p2pLive = false
        return
    end
    local plrs = Core.GetInWorldPlayers(false)
    local peerCnt = (ProxyCommands.P2P and ProxyCommands.P2P.GetPeerCount) and ProxyCommands.P2P.GetPeerCount() or 0
    ProxyCommands.State.p2pLive = (ProxyCommands.State.p2pEnabled and (#plrs > 0 or peerCnt > 0)) == true
    pcall(SystemModule.CheckWorldEntrants, plrs)
    if uiVisible then
        ensureExecCap()
        local pos = Core.ReadPos()
        if canAccessInst(UIHooks.sidebarNameLbl) then
            local nmTxt = tostring(Core.GetInGameName(LP, true) or "")
            if nmTxt ~= H._lastSidebarName then
                H._lastSidebarName = nmTxt
                pcall(function() UIHooks.sidebarNameLbl.Text = nmTxt end)
            end
        end
        if canAccessInst(UIHooks.sidebarSubLbl) then
            local subTxt = string.format("%s (%d,%d)", tostring(gt.name), pos.sx, pos.sy)
            if subTxt ~= H._lastSidebarSub then
                H._lastSidebarSub = subTxt
                pcall(function() UIHooks.sidebarSubLbl.Text = subTxt end)
            end
        end
    end
end

function Watcher.syncSlowState(now, uiVisible)
    if not H.gt or not H.ItemDB or not H.Net or not H.inv then pcall(SYT_Logic.Init) end
    if not H.chatOnCmdHookedTbl or rawget(H.chatOnCmdHookedTbl, "onCommand") ~= H._sytOnCmdWrapper then
        pcall(ProxyCommands.Install, false)
    end
    if ProxyCommands.State.p2pEnabled and ProxyCommands.P2P and ProxyCommands.P2P.SyncVisiblePeers and next(ProxyCommands.P2P.Peers) ~= nil then
        pcall(ProxyCommands.P2P.SyncVisiblePeers)
    end
    if SYT_Logic.SaveAllSettings and (now - (SYT_Logic._lastPeriodicSaveAt or 0)) >= 3.0 then
        SYT_Logic._lastPeriodicSaveAt = now
        pcall(SYT_Logic.SaveAllSettings, false)
    end
    if not uiVisible then return end
    ensureExecCap()
    if not UIHooks.sidebarNameLbl or not UIHooks.sidebarSubLbl then
        pcall(UIHooks.scanResponsiveButtons)
    end
    if H._invDirty or (now - lastInvCheckAt) >= 2.5 then
        H._invDirty = false
        lastInvCheckAt = now
        local invHash = computeInvHash()
        if invHash ~= lastInvHash then
            lastInvHash = invHash
            if UIHooks.refreshBP then pcall(UIHooks.refreshBP) end
            if UIHooks.refreshPabBP then pcall(UIHooks.refreshPabBP) end
        end
    end
    if UIHooks.refreshMap then pcall(UIHooks.refreshMap, false) end
    if AutoLeveling and AutoLeveling.RefreshLevelUi then pcall(AutoLeveling.RefreshLevelUi) end
    if UI then
        local pCnt = (ProxyCommands.P2P and ProxyCommands.P2P.GetPeerCount) and ProxyCommands.P2P.GetPeerCount() or 0
        local p2pTxt = not ProxyCommands.State.p2pEnabled and "OFF (/p2p off)"
            or (pCnt > 0 and string.format("ON (%d Peer Sync)", pCnt)
            or (ProxyCommands.State.p2pLive and "ON (Multi-Player)" or "STANDBY (Alone)"))
        if p2pTxt ~= H._lastP2pStatusTxt then
            H._lastP2pStatusTxt = p2pTxt
            pcall(UI.SetValue, UI, "ProxyP2pStatus", p2pTxt)
        end
        local bj = ProxyCommands.State.bj
        local bjTxt = string.format("B1:%s B2:%s T1:%s T2:%s | TAX:%d%%",
            bj.b1 and (bj.b1.x .. "," .. bj.b1.y) or "-",
            bj.b2 and (bj.b2.x .. "," .. bj.b2.y) or "-",
            bj.t1 and (bj.t1.x .. "," .. bj.t1.y) or "-",
            bj.t2 and (bj.t2.x .. "," .. bj.t2.y) or "-",
            bj.tax or 0)
        if bjTxt ~= H._lastBjStatusTxt then
            H._lastBjStatusTxt = bjTxt
            pcall(UI.SetValue, UI, "ProxyBjStatus", bjTxt)
        end
    end
end

if H.watcherConn then H.watcherConn:Disconnect() end
H.watcherConn = RunService.Heartbeat:Connect(function()
    if getEnv().__SYT_SCRIPT_TOKEN ~= MY_SCRIPT_TOKEN then
        if H.watcherConn then H.watcherConn:Disconnect(); H.watcherConn = nil end
        return
    end
    local now = os.clock()
    if (now - lastFxTick) >= 0.03 then
        lastFxTick = now
        if Visual and Visual.State and ((type(Visual.State.fakeWorn) == "table" and next(Visual.State.fakeWorn) ~= nil) or (Visual.State.effect and Visual.State.effect ~= "" and Visual.State.effect ~= "None") or H._localFxState ~= nil) and type(Core.StepLocalWearVisualFX) == "function" then
            pcall(Core.StepLocalWearVisualFX, now)
        end
        if ProxyCommands and ProxyCommands.State and ProxyCommands.State.p2pEnabled ~= false and ProxyCommands.P2P and type(ProxyCommands.P2P.StepPeerEffects) == "function" then
            pcall(ProxyCommands.P2P.StepPeerEffects, now)
        end
    end
    if (now - lastFastTick) < 0.35 then return end
    lastFastTick = now
    if Misc.State.fastRoulette or ProxyCommands.State.remeEnabled then
        if H.wheelByteNetHookedFor ~= H.Net then Core.EnsureWheelHook() end
        if Misc.State.fastRoulette then Core.SkipWheelAnimations() end
    end
    if not H.chatOnCmdHookedTbl or rawget(H.chatOnCmdHookedTbl, "onCommand") ~= H._sytOnCmdWrapper or H._proxyWheelHookedFor ~= H.Net then
        pcall(ProxyCommands.Install, false)
    end
    Watcher.syncLocalOutfit()

    local uiVisible = Watcher.isUiVisible()
    local gt = H.gt
    local curWorld = gt and cleanWorldName(gt.name) or ""
    if H.Net and type(rawget(H.Net, "worldTag")) == "function" then
        local okW, wTag = pcall(H.Net.worldTag)
        if okW and type(wTag) == "string" and wTag ~= "" then
            local netClean = cleanWorldName(wTag)
            if netClean ~= "" and curWorld ~= "" and netClean ~= curWorld then
                H.gt = nil
                H.renderFn = nil
                pcall(SYT_Logic.Init, true)
                gt = H.gt
                curWorld = gt and cleanWorldName(gt.name) or netClean
            elseif curWorld == "" and netClean ~= "" then
                pcall(SYT_Logic.Init, false)
                gt = H.gt
                curWorld = gt and cleanWorldName(gt.name) or netClean
            end
        end
    end
    if curWorld ~= Visual.State.lastWorldName then
        local intentionalWorldSwitch = DirtFarm.State.switchingWorld
            or PNB.State.switchingWorld
            or ClearWorld.State.switchingWorld
            or MoveBlock.State.switchingWorld
            or AutoLeveling.State.switchingWorld
            or AutoLeveling.State.running
            or (now < (H.intentionalSwitchUntil or 0))
        Watcher.handleWorldChanged(curWorld, intentionalWorldSwitch)
    end

    Watcher.syncEntrantsAndHeader(gt, uiVisible)
    if (now - lastSlowTick) >= 1.2 then
        lastSlowTick = now
        Watcher.syncSlowState(now, uiVisible)
    end
end)
getEnv().__SYT_WATCHER_CONN = H.watcherConn
end)()
getEnv().SYT_Logic = SYT_Logic
return SYT_Logic
